with v(numero,viejo,nuevo,sec) as (values
(17,'207d083a22043fd15e668bc5aa55b941','42ec2ce7339b348099dff4fcb120466b',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀yẹ̀kú pide usar la inteligencia, la ofrenda y el consejo de Ifá en lugar de la fuerza o el pleito. Por grande que sea la persona —en poder, dinero o autoridad— necesita escuchar al babaláwo. Lo que se hace con fe en Ifá deja obras que no se destruyen."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Gasta mucha energía en ganancias rápidas que no duran.", "Se le abre una oportunidad, pero trabajar sin descanso o pelear sin necesidad puede cortarla.", "Tiene autoridad o dinero y cree que ya no necesita consejo.", "Le cuesta equilibrar trabajo, descanso y disfrute.", "Tiene una competencia o un obstáculo en un viaje y busca regresar bien (relato del camaleón Alàgemo y Olókun).", "No duerme bien o arrastra un conflicto que pasa de una persona a otra (relato de Olúkotún, Ọlọ́fin y el rey).", "Se pregunta por la muerte y el sentido de estar en la tierra (verso de la tierra como mercado y el cielo como hogar)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ifá favorece a la persona durante el año.", "Superar obstáculos y regresar bien de un viaje o de una competencia.", "Las obras que ha construido no serán destruidas y quedarán como testimonio.", "Una vida placentera para quien cumple su ofrenda."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto lleva a la terminación productiva. (Este odu expresa la idea del balance perfecto entre el esfuerzo relacionado al progreso y la habilidad para disfrutar el momento presente. Es saber cuando trabajar, cuando descansar, cuando jugar y cuando retirarse).", "origen_id": "24955feeea79873ce01a8ec6"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Gastar mucha energía en ganancias que duran poco.", "Pelear con alguien más poderoso sin preparación.", "Insomnio y riesgo de muerte repentina por no atender lo espiritual.", "Que otros le arrebaten lo que Ifá le había dado."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto lleva a las terminaciones prematuras. (Este odu previene a que un fallo para encontrar el balance pueda llevar a interrupción por espíritus elementales)", "origen_id": "9abaf517cf704fbd97ef4e3c"}]}, {"titulo": "Enseñanza principal", "texto": "La autoridad no exime de consultar. El rey que no podía dormir tuvo que entregar lo que se le pidió, y quien quiso quedarse con lo ajeno terminó pagando lo mismo. Con astucia y ofrenda, el pequeño camaleón le ganó a Olókun."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ogbè Yekú aconseja usar la inteligencia, el poder del sacrificio y seguir los consejos de Ifá, en vez de emplear la fuerza o la confrontación como vía para superar los obstáculos y los enemigos. No importa cuán importante sea el cliente (el poder, riqueza o autoridad que tenga), él o ella necesitan obtener y seguir los consejos del Babaláwo. La creencia firme y determinada en Ifá siempre le traerá recompensas y beneficios al creyente.", "origen_id": "58772fc5557462311884a7a5"}, {"titulo": "Características generales", "texto": "Otros nombres: Ogbè'Yẹkú; Orâculo 17.\nEn el Odù Ogbè Yekú, Ogbè está en la derecha, representando el principio masculino y Ọ̀yẹ̀kú está en la izquierda, representando el principio femenino. Cuando Ogbè va a visitar a Ọ̀yẹ̀kú, las transformaciones que resultan de este movimiento están simbolizadas por el Odù Ogbè Yèkú (como se expresó previamente, existen 256 Odù en el sistema de adivinación de Ifá, 16 Odù principales y 240 ramas o combinaciones de Odù. El Odù Ogbè Yèkú es el primero de las combinaciones de los 16 Odù principales y ocupa el décimo séptimo lugar en el Odù ajustado de Ọ̀rúnmìlà).", "origen_id": "dc6664b9a329abcbca21bd3b"}]}, {"titulo": "Relatos reunidos", "puntos": ["Olúkọ̀tún y la hija de Ọlọ́fin. A Olúkọ̀tún Ajamlolo le dijeron que ese año Ifá lo iba a favorecer mucho. Ọlọ́fin lo mandó llamar dos veces para que le consultara, y las dos veces respondió que no podía ir porque estaba adorando a su Ifá. Cuando por fin llegó, Ifá dijo que a Ọlọ́fin no le pasaba nada grave: solo que no podía dormir de noche. Como ofrenda debía entregar a Olúkọ̀tún a su hija mayor adornada con cuentas en muñecas y tobillos, dos chivas grandes y 4,400 cauríes. Ọlọ́fin cumplió. Pero la gente se burló de que una muchacha tan bella se fuera con un adivino pobre, se la quitaron en el camino y se la dieron a un rey. Entonces el rey tampoco pudo dormir, mandó llamar a Olúkọ̀tún, y Ifá le marcó lo mismo: entregar a su joven reina, dos chivas y 4,400 cauríes para evitar una muerte repentina. El rey cumplió, y Olúkọ̀tún se fue a su casa cantando: 'Así es como Ifá me favorece, así y siempre'.", "El camaleón y Olókun. Alàgemo, el camaleón, iba a la fiesta anual de Olókun y quería competir con él vistiendo la misma ropa. Le marcaron 20,000 cauríes, doscientas palomas y telas de muchos colores, y cumplió. En la fiesta, cada vez que Olókun cambiaba de ropa, Alàgemo cambiaba de color y lo igualaba. Olókun se enfureció y buscó a sabios y hechiceros para cerrarle el camino de regreso. Alàgemo volvió a consultar: le marcaron una estera de rafia, una jícara de ñame machacado y cosas variadas, y le enseñaron un canto: 'Que los hechiceros me dejen en paz, que las brujas me dejen en paz; cuando el buitre se coma la ofrenda, dejará la jícara aquí'. Le dijeron que tendiera la estera sobre el río y se sentara en ella. Lo hizo así, venció todos los obstáculos y llegó bien a su casa.", "El hombre blanco que viaja por el mar. Ogbèyèkú, el padre de todos los Àmùlú, consultó para el hombre blanco, hijo del clan que usa el océano como camino y la laguna para lavarse los pies. Le pidieron ofrecer, ofreció e hizo regalos a Èṣù, y le dijeron que las obras que construyera no serían destruidas y se recordarían por siempre.", "La Tierra y el Ẹ̀dan. El mismo Odù consultó para la Madre Tierra y para el Ẹ̀dan, el distintivo del babaláwo. Los dos preguntaron si la vida les sería placentera; los dos ofrendaron, y la vida les fue buena a ambos, igual que al hombre blanco."], "pasajes": [{"titulo": "Verso 17.1", "texto": "adivinó Ifá para Olükọ̀tún Ajamlolo, el padre de Oitolú.\nEl adivino dijo:\n\"este año él será muy favorecido por Ifa\".\nPoco después,\nỌlofin envió por Olúkotún\npara que viniera y adivinara Ifá para ÉI,\nOlúkotún les pidió que le dijeran a Ọlófin\nque él no podía ir inmediatamente\nporque estaba adorando\na su Ifá en aquel momento.\nỌlófin envió por Olúkotún por segunda vez.\nOlúkotún respondió repitiendo\nlo que había dicho antes.\nÉl aún estaba adorando a su Ifá,\nỌlofin preguntó:\n¿ cuál Ifá está adorando Olúkotún Ajamlolo?\n¿Ifá lo favoreció?\nMás tarde,\nOlúkotún Ajamlolọ llegó para ejecutar\nla adivinación para Ọlófin,\nIfá dijo que no había nada malo con Olófin.\nÉl sólo estaba pasando trabajo\npara dormir de noche\npor lo tanto como parte del sacrificio,\nEl debía entregar a Olúkotún su hija mayor\nadornada con cuentas en sus muñecas y en sus tobillos,\ndos chivas grande y 4400 cowries.\nỌlọ̀fin ejecutó el sacrificio.\nCuando Olúkotún se iba a casa\ncon los materiales del sacrificio,\nlas personas comenzaron a ridiculizarlo a él y a Ọlófin,\npreguntando: ¿ cómo es posible que Ọlófin\nentregue su hija a ese pobre Olúkotún?.\nEllos le arrebataron a Olúkotún la bella muchacha\ny se la dieron a un Ọba (rey).\nElla se convirtió en la esposa del rey.\nEl Oba tampoco pudo dormir bien\ny fue obligado a enviar por Olükọ̀tún Ajamlolo\npara que viniera y consultara Ifá para él,\nOlúkòtún vino y le dijo al Oba\nque no podía dormir profundamente de noche.\nPor lo tanto, si él deseaba evitar una muerte súbita,\nél tendría que dar al Babaláwo que adivinó Ifá para él,\nsu joven reina, dos chivas y 4400 cowries.\nEl Ọba ejecutó el sacrificio\nOlúkọ̀tún Ajamlolo\ntransportó los materiales del sacrificio a casa,\ncantando la siguiente canción:\nEkumini,\nEkumini,\nasí es como Ifá me favorece,\nasí y siempre.", "origen_id": "3cfda91f1c16c9dcc4150412"}, {"titulo": "Verso 17.2", "texto": "Awod'oro-awo-omodé,\nÌká-o-tan-bọro-awo-àgbalagbà\nEerẹtikekerepakẹse-ijam'ẹsẹ:\nadivinaron Ifá para Alàgemo (camaleón),\ncuando él iba a la celebración de las fiestas anuales con Olókun.\nLe fue aconsejado sacrificar:\n20000 cowries, doscientas palomas\ny varios tipos de ropas (telas de diferentes colores).\nÉl escuchó y sacrificó.\nLos adivinos prepararon la medicina de Ifá para él.\nAlàgemo entonces envió\nun mensaje a Olókun\ndiciendo que él iba a ir\npara participar en las festividades,\ny que a él le gustaría competir con Olókun\nen el uso de ropas idénticas,\nOlókun respondió:\n\"está bien\",\n¿cómo te atreves Alàgemo?\"\nél dijo: \"que aguardaría el arribo de Alàgẹmo\".\nAlàgemo vino en el día propuesto,\nOlókun comenzó la competencia.\nCualquier ropa que Olókun usara,\nAlàgemo debía usar la misma e igualarla\nDespués de un corto tiempo\nOlókun se encolerizó\ny decidió intentar bloquear el camino\npara que Alàgemo\nencontrara imposible regresar a casa.\nÉl fue a buscar la ayuda\nde los sabios y hechiceros\npara colocar obstáculos\nen el camino de Alàgemo.\nAlàgemo por su parte\nfue a consultar a los Babaláwos\nsobre qué debía hacer para evitar\ncualquier imprevisto en su camino a casa.\nLe aconsejaron sacrificar:\nẹni-agbafi (una estera de raffia),\nigbá ewo (igbá de ñames machacados)\ny variadas cosas (diferentes cosas).\nÉl escuchó el consejo y sacrificó.\nLa medicina de Ifá fue preparada para él,\ny le fue enseñada la siguiente canción:\nPermite que los hechiceros\nme dejen solo aquí,\nPermite que las brujas\nme dejen solo aquí.\nCuando un buitre se come el sacrificio,\nél dejará la calabaza aquí.\nSe le pidió después\nque extendiera la estera en el río\ny se sentara sobre ella.\nAlàgemo efectuó exactamente los consejos\nde sus Babaláwos,\npor tanto fue capaz de superar los obstáculos\ny regresar bien a su casa.", "origen_id": "d372cb8f15337711ecfe9e5d"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que las cosas maravillosas que esta persona\nha realizado o construido, no serán destruidas, y\nserán testificaciones exitosas en el presente y\nfuturo.\n\n       Ogbèyèkú ni bàbá Àmùlú\n                Orí Ogbó\n                 Orí Otó\n              Ợkợ Omidan\n            A dífá fún Èèbó\n           Ợmợ afòkun sède\n             A bú fún Èèbó\n            Ợmợ afòsà wèsẹ\n        Ệbợ n wón ní kí wón ó şé\n           Òyìnbó gbébo ńbè\n                 Ó rúbợ\n         Rírú ẹbợ èèrù àtùkèsù\n        Ệ wá bá níní jèbútú rere\n        Àrà tÉèbó ń dá ò le bàjé\n    Gbogbo ẹ ní ń gún rekete lójú omi\n\nOgbèyèkú es el padre de todos los Àmùlú\nPuede su cabeza ser vieja y estar firme\nEs aquel que es esposo de mujeres solitarias\nLanzó Ifá para el hombre blanco\nEl hijo del clan que usa el océano como su camino\nTambién lanzó Ifá para el hombre blanco que es hijo\ndel clan que usa a la laguna para lavar sus pies.\nSe les pidió que ofrendaran, y ellos lo hicieron.\nSacrificaron además de hacer los libres regalos a\nÈşù\nVen y únete a nosotros con buenas noticias.\n\nLas buenas obras conformadas por el hombre\nblanco, no serán destruidas y serán recordadas por\nlos tiempos de los tiempos.\n\n       Ogbèyèkú ni bàbá Àmùlú\n                Orí Ogbó\n                 Orí Otó\n              Ợkợ Omidan\n              A dífá fún Ilè\n             A bú fún Ệdan\n        Ayé le yẹ àwợn méjèèjì?\n          Wón ní kí wón ó rúbợ\n                Ilè rúbợ\n             Ệdan náà si rú\n           N ní wón wá ń jó\n            Ní wón wá ń yò\n       Wón ń yin àwợn babaláwo\n       Àwợn babaláwo ń yin Ifá\n  Wón ni béè làwợn babaláwo tàwón wi\n       Ogbèyèkú ni bàbá Àmùlú\n                Orí Ogbó\n                 Orí Otó\n              Ợkợ Omidan\n              A dífá fún Ilè\n             A bú fún Ệdan\n              Ayé yẹ Ệdan\n              Ayé si yẹ Ilè\n              Ayé tó yẹ Ilè\n              Yóó yẹ Ệdan\n              Ayé tó yẹ Ilè\n              Yóó yẹ Èèbó\n              Ayé tó yẹ Ilè\n              Yóó yẹ Ệdan\n\nOgbèyèkú es el padre de todos los Àmùlú\nPuede su cabeza ser vieja y estar firme\nEs aquel que es esposo de mujeres solitarias\nLanzó adivinación para la Madre Tierra\nY también profetizó Ifá para Ệdan\nEllos dos preguntaron: ¿La vida nos será placentera\na ambos?\nSe les pidió a ambos que sacrificasen.\nLa madre Tierra así lo hizo y Ệdan tampoco dejó de\nrealizarlo\nEllos bailaron y se regocijaron, alabaron a sus\nbabaláwo y estos alabaron a Ifá en prédicas y\nadoración.\nOgbèyèkú es el padre de todos los Àmùlú\nPuede su cabeza ser vieja y estar firme\nEs aquel que es esposo de mujeres solitarias\nLanzó adivinación para la Madre Tierra\nY también profetizó Ifá para Ệdan\nLa vida les fue placentera y exquisita a ambos\nY también para el hombre blanco\nLa vida le fue placentera a la Madre Tierra, a Ệdan y\nal hombre blanco", "origen_id": "37e7fde9deb38b501df70a9a"}, {"titulo": "Versión complementaria de los relatos", "texto": "En el Odu Ogbe Yeku nosotros hemos sido avisados de usar la\n     inteligencia en vez de la fuerza o la confrontación cuando sobrevenga\n     obstáculos o enemigos. Sin importar cuán importante es uno, él o ella\n\nnecesitan obetener y seguir los consejos del babalawo. Creer en Ifá\n                                              siempre traerá sus beneficios\n      WO - El cliente normalmente derrocha mucha energía en beneficios\n                temporales y necesita abrirse espiritual y emocionalmente.\n         En el Odu Ogbe Yeku, Ogbe está en la derecha, representando el\n       principio masculino y Oyeku está en la izquierda, representando el\n                 principio femenino. Cuando Ogbe va a visitar a Oyeku, las\ntransformaciones resultantes de este movimiento están simbolizadas por el\n   Odu Ogbe Yeku (como se expresó previamente, existen 256 Odu en el\n          sistema de adivinación de Ifá, 16 Odu principales y 240 ramas o\n               combinaciones de Odu. Odu Ogbe Yeku es el primero de las\n   combinaciones de Odu y éste ocupa el décimo séptimo lugar en el Odu\n                                                    ajustado de Orunmila).\n\n\n17.1 · Ekumini, Ekumini adivinó Ifá para Olukotun Ajambolo, el\n       padre de Oitolu. Fue predicho que él sería grandemente favorecido\n       por Ifá este año. Poco después Olofin envió por Olokutun para que\n        viniera y adivinara Ifá para Él, Olukofun les pidió que le dijeran a\n       Olofin que él no podía ir inmediatamente porque estaba adorando a\n        su Ifá en aquel momento. Olofin envió por Olukotun por segunda\n                                                                       vez.\n             Olukotun respondió repitiendo lo que había dicho antes. Él aún\n        estaba adorando a su Ifá, Olofin preguntó: ¿cuál Ifá está adorando\n               Olokotun Ajamlolo? ¿Ifá lo favoreció?. Más tarde, Olokotun\n\nAjamlolo arribó a ejecutar la adivinación para Olofin, Ifá dijo que no\n     había nada malo con Olofin. Él sólo estaba pasando trabajo para\n      dormir de noche por lo tanto como parte del sacrificio, Él debía\n       entregar a Olokotu su hija mayor adornada con cuentas en sus\n      muñecas y en sus tobillos, 1 chiva grande, 4400 cowrie. Olofin\n  ejecutó el sacrificio, como Olokotu se iba a casa con los materiales\ndel sacrificio, las personas comenzaron a ridiculizarlo a él y a Olofin,\n  preguntando ¿cómo puede ser posible que Olofin entregue su hija a\nese pobre Olokotun?. Ellos arrebataron a Olukotun la bella muchacha\n  y se la dieron a un Oba (rey). Ella se convirtió en la esposa del rey.\n       El Oba tampoco pudo dormir bien y fue obligado a enviar por\n         Olokotun Ajamlolo para que viniera y consultara Ifá para él,\n               Olokotun vino y le dijo al Oba que él no podía dormir\nprofundamente de noche. Por lo tanto, si él deseaba evitar una muerte\n     súbita, él tendría que dar al babalawo que adivinó Ifá para él, su\n    joven reina, 2 chivas y 4400 cowrie. El Oba ejecutó el sacrificio\n   Olokotun Ajamlolo transportó los materiales del sacrificio a casa,\n    cantando la siguiente canción: Ekumini, Ekumini, así es como Ifá\n                                     puede ser favorable y así y siempre.\n              De este Odu aprendemos como Olokotun Ajamlolo fue\n    recompensado y favorecido considerablemente debido a su firme\n                                                         creencia en Ifá.\n\n\n17.2 · Awod´oro-awo-omode, Ika-o-tan-boro-awo-agbalagba\n\nEeretikekerepakese-ijam´ese adivinó Ifá para Alagemo (camaleón),\n   cuando él iba a celebrar las festividades anuales con Olokun. Se le\n pidió sacrificar 20000 cowrie, 200 palomas y una variedad de ropas.\n  Él escuchó y sacrificó. Los adivinadores prepararon la medicina de\n  Ifá para él. Alagemo entonces envió un mensaje a Olokun diciendo\n                     que él iba a ir para participar en las festividades.\n   A él le gustaría competir con Olokun en el uso de ropas idénticas,\n  Olokun respondió “está bien”, ¿cómo te atreves Alagemo? , él dijo\n      “que aguardaría el arribo de Alagemo”. Alagemo vino en el día\n     propuesto, Olokun comenzó la competencia. Cualquier ropa que\n              Olokun usara, Alagemo debía usar la misma e igualarla\n Después de un corto tiempo Olokun se encolerizó y decidió intentar\nbloquear el camino para que Alagemo encontrara imposible regresar\n      a casa. Él fue a buscar la ayuda de los sabios y hechiceros para\n                        colocar obstáculos en el camino de Alagemo.\n     Alagemo por su parte fue a consultar a los Babalawos sobre qué\n debía hacer para evitar cualquier imprevisto en su camino a casa. Se\n     le aconsejó sacrificar eni agbafi (una estera raffia), iga ewo (una\n    calabaza de ñames asados machacados) y algunas otras cosas. Él\n  escuchó el consejo. La medicina de Ifá fue preparada para él le fue\n  enseñado la siguiente canción: “Oso Ibe e Jowo Mi, Aje Ibe e Jowo\n        Mi Bi Igun Ba J´ebo A Jooegba”, Permite que los sabios aquí\ndéjarme solo, permite a las hechiceras aquí dejarme solo. Si un buitre\n                    se come el sacrificio, éste dejará la calabaza aquí.\n\nSe le pidió después que extendiera la estera en el río y se sentara\n             sobre ella. Alagemo lo hizo como le dijeron los Babalawos y fue\n            capaz de volver a casa. Alagemo efectuó los sacrificios presciritos\n          por los Babalawos y fue por lo tanto capaz de superar los obstáculos\n                                que Olokun amenazó con poner en su camino.", "origen_id": "5dec9d66ccafda7f003ab467"}, {"titulo": "Relato en inglés 1", "texto": "Ogbe Qyeku, father of combinations. “He lives to a ripe old age,” the diviner\nof Rod,” was the one who cast-Ifa for Rod. Before Rod dies, the elders of Iworo\nwill nearly all be dead.\n\n“The one who circumcises the tortoise must not circumcise the snail” was\nthe one who cast Ifa for Lion, the child of “His urine captures the dense forest,”?\nwhen the other animals were taking advantage of him.\n\nIfa says he sees someone who owns neither a plate nor a calabash;4 everyone,\nincluding his own relatives, say he has a “bad head”® and are making fun of him.\nIfa says this person will become important in the near future and that he will have\nhis revenge.\n\nFrom the beginning of time all the animals took advantage of Lion. If he lay\nasleep on the ground, they climbed on top of him; they never showed him proper\nrespect. Lion got ready and went to the diviners; he asked them what he could\ndo to gain honor and glory among his associates. The diviners said that he should\nsacrifice one calabash of water, ashes, three clubs, and Ifa’s leaves (the “leaf of\nhonor”).® They said he should crush the leaves of Ifa in the water, add the ashes\nto it, and then drink it. And they told him that when he lay down\n\nanywhere, he should first make a circle of urine about the spot. After Lion had\nmade this sacrifice, when he wanted to sleep, he urinated around the place where\nhe was going to lie down, When the other animals wanted to climb on top of him,\nas in times past, if they stepped over his urine, they fell dead upon the ground.\nThus Lion came to be feared by the other animals; when they hear his voice,\nthey are frightened and tremble ‘riri.’? And since then, when Lion roars, he\nsays, Aside from man, aside from myself, aside from the Sky God, who else is\nthere?)", "comentario": "1. Ogbe Qyeku is regarded as the “oldest” and most powerful of these figures\nin which both halves are different. It ranks immediately after the “pairs” or double\n(meji) figures, and is therefore at the head of all the “mixtures” or combinations\n(amulu). See Chapter IV.\n\n2. A rod of brass or iron, such as is used by the Ogboni society and the wor-\nshipers of Qshun. A piece of metal, of course, can “outlive” even the elders of\nIworo, who seem to epitomize long life and old age. @\n\n3. The meaning of this name is explained later in the verse. One informant\nincluded “when the other animals were taking advantage of him” as part of the\nname.\n\n4. A common idiom indicating poverty.\n\n5. That is, that he has bad luck, and that he is therefore worthless.\n\n6. Brillantaisia patula, Note that in order to gain honor, a leaf known as\n“leaf of honor” is added to the concoction to be drunk.\n7. \"Riri\" describes the way in which a person trembles in fright.\n8, This verse explains why the Lion is the king of the animals and why all\nother animals fear him, and also what Lion says when he roars.", "origen_id": "c638d1421d9e8c8249f9f94d"}, {"titulo": "Relato en inglés 2", "texto": "“Stout Ogbe Qyeku”! was the one who cast Ifa f@ a king who had been de-\nthroned. Ifa says there is someone who has a title; he will be removed from of-\nfice and a person who stays in the corner will be chosen to fill his position. All\npeople will rub their hands? to the person of the corner, and pay homage to him.\nThere is also a deity that was once worshiped by all the people of a house; but\nthey do not worship him any more and the forest has overgrown his altar, We\nshould renovate the altar and tie young palm fronds at its entrance. The person\nof the corner is someone at whom young children and old people alike-are sneer-\ning; but he will leave his corner and come\n\nout into the open. There is a hen at the house of the person for whom this figure\nwas cast. This hen has chicks; we should take both the hen and its young to\nmake the sacrifice.", "comentario": "1, The name of the diviner is derived from the name of the figure.\n\n2. The palms of the hands are rubbed together as in a supplication, when\nasking to be excused from expressing an opinion during a trial or a discussion.\nThe gesture is made to those of higher rank to show that the matter is too dif-\nficult for you to decide, or that you have nothing significant to add to what has\nalready been said. The implication here is that everyone will defer to the client\nand look to him to make the important decisions, because of the position he will\noccupy.", "origen_id": "5a3fbf932069ec20e8773375"}, {"titulo": "Relato en inglés 3", "texto": "“The head that should not go naked will find a cloth seller when the market\nopens”! was the one who cast Ifa for “The King of Qfa who sells a box full of vel-\nvet,’? child of “One who coughs ‘gbinrin’® like the trumpeting of an elephant,”\nchild of “One who uses the top of a calabash to measure out beads for his mis-\ntresses,’4 child of “One who enjoys the world wet and soggy, like someone lick-\ning honey.\" Ifa says that a person who stays in the corner will come out into\nthe open; he will occupy an important position, and he will remain in office a\nlong time.\n\n“The King of Qfa who sells a box full of velvet” was an old man who owned\nneither a plate nor a calabash; but he had a large cloth hidden away. He never\nused this cloth himself, but others borrowed it from him to dress up to go out in.\nThe King of Qfa got ready, and he went to the diviners; he asked them what he\nmust do in order to gain importance, They said he should sacrifice one black\nhe-goat, two shillings six pence, and one large cloth which he had hidden away.\nHe heard and he sacrificed. Soon afterward the King of Qfa® died,-and the people\nof Qfa took “The King of Qfa who sells a box full of velvet” and\n\n°\n\nmade him king, expecting that it would not be long until he would die. But after\nhe took office, instead of dying, he continued in good health; and everything went\nwell for the people of QOfa and everything was easy for them. Then they did not\nwant him to die any more.\n\nIfa says that a person in the corner will come out into the open and will at-\n\ntain an important position, and he will stay in that position a long time before he\ndies.", "comentario": "1. The implication of this name, like that of a proverb, is much broader than\nits literal meaning. In this case the meaning is that class or nobility will be\nrecognized; and that each person will get his due, The allusion is to the fact that\nthe legendary character, though at first poor and of no importance, was made\nKing of Qfa.\n\n2, The legendary character is referred to as the King of Qfa even before he\nassumed that title. The name itself is an allusion to the large cloth mentioned\nlater in the verse, which he had hidden away. The velvet refers to the large cloth\nand the box (apoti) to the hiding place (odidi).\n\n3. This word is said to be the sound of a cough, or the sound made by iron\nstriking a stone anvil, The reference to elephant, which is associated with royalty,\nindicates that this is the name of an important person.\n\n4. The lid of a calabash is used in measuring small things of little value. It\nis not a standardized measure. And while it is appropriate for measuring some-\nthing like kernels of corn, it would never be used for anything as valuable as beads\nexcept by a person who did not have to worry about money. Thus the name implies\nthat the individual is very rich and generous, since he doesn’t stop to count out the\nbeads one by one.\n\n5. These are all names of individuals from whom the King of Qfa is descended.\n\n6. That is, the one who was king at the time of the divination; not the legendary\nclient, but his predecessor.", "origen_id": "07dc392fa0a96f2d1d46e3dd"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlọ́fin y el rey: la hija mayor con cuentas en muñecas y tobillos (después, la joven reina), dos chivas grandes y 4,400 cauríes.", "Alàgemo (primera consulta): 20,000 cauríes, doscientas palomas y telas de varios colores.", "Alàgemo (para el regreso): una estera de rafia, una jícara de ñame machacado y cosas variadas; tender la estera sobre el río y sentarse en ella.", "El hombre blanco, la Tierra y el Ẹ̀dan: ofrenda y regalos libres a Èṣù."], "pasajes": [{"titulo": "Ofrenda en el verso 17.1", "texto": "adivinó Ifá para Olükọ̀tún Ajamlolo, el padre de Oitolú.\nEl adivino dijo:\n\"este año él será muy favorecido por Ifa\".\nPoco después,\nỌlofin envió por Olúkotún\npara que viniera y adivinara Ifá para ÉI,\nOlúkotún les pidió que le dijeran a Ọlófin\nque él no podía ir inmediatamente\nporque estaba adorando\na su Ifá en aquel momento.\nỌlófin envió por Olúkotún por segunda vez.\nOlúkotún respondió repitiendo\nlo que había dicho antes.\nÉl aún estaba adorando a su Ifá,\nỌlofin preguntó:\n¿ cuál Ifá está adorando Olúkotún Ajamlolo?\n¿Ifá lo favoreció?\nMás tarde,\nOlúkotún Ajamlolọ llegó para ejecutar\nla adivinación para Ọlófin,\nIfá dijo que no había nada malo con Olófin.\nÉl sólo estaba pasando trabajo\npara dormir de noche\npor lo tanto como parte del sacrificio,\nEl debía entregar a Olúkotún su hija mayor\nadornada con cuentas en sus muñecas y en sus tobillos,\ndos chivas grande y 4400 cowries.\nỌlọ̀fin ejecutó el sacrificio.\nCuando Olúkotún se iba a casa\ncon los materiales del sacrificio,\nlas personas comenzaron a ridiculizarlo a él y a Ọlófin,\npreguntando: ¿ cómo es posible que Ọlófin\nentregue su hija a ese pobre Olúkotún?.\nEllos le arrebataron a Olúkotún la bella muchacha\ny se la dieron a un Ọba (rey).\nElla se convirtió en la esposa del rey.\nEl Oba tampoco pudo dormir bien\ny fue obligado a enviar por Olükọ̀tún Ajamlolo\npara que viniera y consultara Ifá para él,\nOlúkòtún vino y le dijo al Oba\nque no podía dormir profundamente de noche.\nPor lo tanto, si él deseaba evitar una muerte súbita,\nél tendría que dar al Babaláwo que adivinó Ifá para él,\nsu joven reina, dos chivas y 4400 cowries.\nEl Ọba ejecutó el sacrificio\nOlúkọ̀tún Ajamlolo\ntransportó los materiales del sacrificio a casa,\ncantando la siguiente canción:\nEkumini,\nEkumini,\nasí es como Ifá me favorece,\nasí y siempre.", "origen_id": "529a821bfa03e010cf1d023f"}, {"titulo": "Ofrenda en el verso 17.2", "texto": "Awod'oro-awo-omodé,\nÌká-o-tan-bọro-awo-àgbalagbà\nEerẹtikekerepakẹse-ijam'ẹsẹ:\nadivinaron Ifá para Alàgemo (camaleón),\ncuando él iba a la celebración de las fiestas anuales con Olókun.\nLe fue aconsejado sacrificar:\n20000 cowries, doscientas palomas\ny varios tipos de ropas (telas de diferentes colores).\nÉl escuchó y sacrificó.\nLos adivinos prepararon la medicina de Ifá para él.\nAlàgemo entonces envió\nun mensaje a Olókun\ndiciendo que él iba a ir\npara participar en las festividades,\ny que a él le gustaría competir con Olókun\nen el uso de ropas idénticas,\nOlókun respondió:\n\"está bien\",\n¿cómo te atreves Alàgemo?\"\nél dijo: \"que aguardaría el arribo de Alàgẹmo\".\nAlàgemo vino en el día propuesto,\nOlókun comenzó la competencia.\nCualquier ropa que Olókun usara,\nAlàgemo debía usar la misma e igualarla\nDespués de un corto tiempo\nOlókun se encolerizó\ny decidió intentar bloquear el camino\npara que Alàgemo\nencontrara imposible regresar a casa.\nÉl fue a buscar la ayuda\nde los sabios y hechiceros\npara colocar obstáculos\nen el camino de Alàgemo.\nAlàgemo por su parte\nfue a consultar a los Babaláwos\nsobre qué debía hacer para evitar\ncualquier imprevisto en su camino a casa.\nLe aconsejaron sacrificar:\nẹni-agbafi (una estera de raffia),\nigbá ewo (igbá de ñames machacados)\ny variadas cosas (diferentes cosas).\nÉl escuchó el consejo y sacrificó.\nLa medicina de Ifá fue preparada para él,\ny le fue enseñada la siguiente canción:\nPermite que los hechiceros\nme dejen solo aquí,\nPermite que las brujas\nme dejen solo aquí.\nCuando un buitre se come el sacrificio,\nél dejará la calabaza aquí.\nSe le pidió después\nque extendiera la estera en el río\ny se sentara sobre ella.\nAlàgemo efectuó exactamente los consejos\nde sus Babaláwos,\npor tanto fue capaz de superar los obstáculos\ny regresar bien a su casa.", "origen_id": "4fde2b5dfdb2f9f0cd41b181"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá favorece al que lo adora antes que a la autoridad. Olókun, dueño del mar, aparece como rival del camaleón. Èṣù recibe los regalos libres. El babaláwo y su Ẹ̀dan son protagonistas de uno de los versos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame machacado, estera de rafia, telas de colores, cuentas y cauríes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 17.1 (yorùbá): Ekumini, / Ekumini: / li o dífá f'Olúkptún Ajamlolą / ti ise baba Oitolú. / Wọ̀n ni: / \"nínú Qdún yi ni Ikin (Ifá) rè yoo gbee\" / O pẹ diẹ ṣa, / Ọlọ̀fin ranṣẹ si pe kiowa difá fún òun. / Ó niki wọ̀n lọ sọ fún Ọlọ̀fin / pe òun ṣi nbọ Ifá òun / ni lowọlową yi na o Ọlofin tun ranṣẹ / tọọ ni erinkeji pe kiomaa bọ / Òun si tun ranṣẹ pada si Ọlófin / gẹgẹbii ti iṣaaju pe òun ṣi nbọ / Ifá òun na. / Ọlọ̀fin dahun Ó ni: / Ifá kini Olúkotún Ajamlolọ mbọ to bayi, / Ifá naa gbee ndan? / Nigboose Olúkòtún Ajamlolo de o wó / Ifá fún Ọlọ̀fin / Ó ni: / Ọlofin, kosi ohun ti nṣé ọ̀, / o ni sisùn li o sùn ti o ko lee sün're l'oru / Nitorinaa ki ó rú: / Arẹmo rẹ, / kiofi ilẹkẹ owọ̀ ati ti ẹsẹ̀ rẹ sii l'ara, / ake-ewúrẹ Méjì / ati Eejilélógún owó. / Ó gbọ̀ ó rú. / Bi o ti nko àwọn ohun ebọ / ti a npe Eru re ilé, / àwọn èniyàn berẹ sii p'egan rẹ / ati Ọlófin pe: / Alaṣo kan yi ni Ọlófin fa pmọ fún? / Wọ̀n gba omobirin naa li qwọ̀ rẹ. / Wọ̀n muu lọ fún Ọba kan pe / ki o maa fẹẹ, / nitoripe ayába ni omobirin naa bamu. / Ọba tii wọ̀n fa omobirin naa lọ fún tun / sùn ko le sùn're l'oru / Ó ranṣẹ lọ pe Olükotún Ajamlçlo / pe ki owa wò Ifá fún oun. / Ó de, ó ni Ọba, / kosi ohun Méjì ti nṣe q, / sisùn li o sùn ti o ko lee sün're l'oru ni. / Nitorinaa bioba wipe ki o ma kú, / ki o yara mu Olorí (aya'ba) kan wa / àti ẹni-ajoji kan tio wa ni ilé rẹ / Kiofa wọ̀n fún Babaláwo / tiowa ni Orí-ite Ifá, / Ake-ewúrẹ Méjì / ati eejielógún owó. / Ọba gbọ ó rú. / Olúkọ̀tún Ajamlolo / ko inkan wọnyi losi ilé rè. / O de ilé tan o korin bayi: / Ekumini, / Ekumini, / bayi n'Ifá sẹ ngbéni ati bẹẹbẹẹ. / Ekumini, / Ekumini:", "Verso 17.2 (yorùbá): Awod'oro-awo-omodé, / Ìká-o-tan-boro-awo-àgbàlagbà / Eerẹtikekerepakẹsẹ-ijam'ẹsẹ: / a difa f'Alàgemo / nlọ b'Olókun pesi Odún / Wọ̀n niki ó rú: / Egbàáwa owó, igba eyẹlé / ati oniruuru aṣo. / Ó gbọ̀ ó rú. / Awon awo si ṣe ewé Ifá fún un. / Alágemo wa ranṣẹ si Olókun pe / Kiakii f'oun sẹ o, / Oun bowa baa pẹsi Odún, / kosi aṣọ ti Olókun maa lo ti / òun kò niilo iru rẹ gegẹ o. / Olókun ni: / Hẹn! Alágemo nilẹ-ẹlẹ? / Ó nì: / o di igbati o ba de ihin wa ba oun na. / Qjg ko, Alágemo de. / Olókun bẹrẹsii lo aṣo / Iru aṣo ti Olókun ba lo, Alágemo a loo / Wọ̀n jüjọ lo aṣo titi / Nigbooṣe Olókun wa binu. / Ó ni òun yoo di ona / ti Alágemo yoo gba pada si ilé rẹ̀. / Ó lọ bẹ àwọn Oṣó ati Ajé lowẹ tii, / kỉ wọ̀n ba òun ṣe idiwọ / fún un li ònà ajo si ilé rẹ̀. / Alágemo tun tọ Babaláwo lọ pe: / Kini òun iba ṣe / ki ọ̀nà-ajo òun silé le dára? / Wọ̀n niki ó rúbọ / Eni-agbafi, / igbá-ewo / ati oniruuru inkan miran. / Ó gbọ̀ ó rú. / Wọn ṣe ewé Ifá fún un wọ̀n si kọo / li orin ti oun yoo maa kọ bayi: / Oṣó ibe ẹ jowo mi. / Ajẹ ibe ẹ jowọ mi. / Bi Igún ba j'ẹbọ a jọọ'gbá. / Ati pe ki o na ẹni rẹ̀ si ojú omi / Kiogun le orí eni naa. / Alágemo ṣe gegẹbi imoran / àwọn Babaláwo rè. / O si bowalé.", "REZO: OGBE YEKU BABA OMOLU ABAKAKA BABA O AN ADIFAFUN AWANO IKIBE AKORA KEKE AWANO TIO PITO BIYE LEKE ERANKO ANDOBELASHI GBOGBO ERANKO LORUBO KEKE MEDILOGUN ERAN MALU, EKU, EYA, AWADO, OÑI, OPOLOPO OWO.", "SUYERE: EDAFON SHURO MI ORE, EDA EWE EDA EFUN AGAYU RAUN OSOMOBO MOBO SODOROMI YARE IYA LODE ABA.", "REZO: OGBE YEKUN NI BABA OMILU AGBA OLOYA NIRO DEMU, AGOGO NLA SHENU GBAGBA LONI NI PARIKOKO OTENU DUNDUN NI PARASIDI OTENU BATA JAD YEKUN ADIFAFUN OZAIN LODAFUN ORUNMILA KAFEREFUN OJUANI MEYI.", "REZO: AKUENO OLORI ASHUBO AWO KAKA ADO ADIFAFUN ORI KAFEREFUN ORUNMILA.", "REZO: OGBE YEKUN KUKUTU ADIFAFUN GUONITI AFITI BIYE LOGBU ORUNGAN.", "REZO: OGBE YEKUN BABA OMOLU ABAKAKA BARA ADAN ADIFAFUN KENE UN TIO PIO BIYE LOKE ERANKO ALUBODE LANSHI LORUBO.", "REZO: OGBE YEKUN BABA OMOLU BABA ADIFAFUN SHORO KOKO EPASIDA IKIBO OKARA KOKO ROKO OKO KOBERU OGBE.", "REZO: OGBE YEKUN OMOLU OBA KAKA EDAN ADIFAFUN YEBEKA OKA APEINDA IKIBO OSHOSI KAKARAKA OKO KOBORUN OGBE LOLA OGBE TEKE OUN KOYE KOBIN ADIFAFUN KENKUN TIO PIO EYELE LOWO ERANKO OLUBEBE GBOGBO ERANKO ETU LORUBO.", "REZO: OGBE YEKUN BABA OMOLU BABA ADIFAFUN SHERE KEKE EPISANDA IKIBO SHERU KEKE OKO KOBORU OGBE YEKU LO TOKE OUN KOSHE KOTIN ADIFAFUN OWUNKO ITA FIRE IYE REWE OLUBAMBA TOLI LEBO ETU KORUBO MEDILOGUN ERAN MALU, OÑI MEDILOGUN OWO ELEBO.", "REZO: OGBE YEKUN NI BABA OMULO AGBA OLOYA NIRO DEMU, AGOGO NLA SHENU GBAGBA LONI NI PARIKOKO OTENU DUN DUN NA LORI NI PARA OTENU BATA JAD OGBA YEKUN ADIFAFUN OZAIN, LODAFUN ORUNMILA. OJUANI MEYI.", "REZO: KUKUTO KUKO ADIFAFUN GUONITI AFITI BIYE LOUGBU ORUNGO."], "pasajes": [{"titulo": "Ogbe Yeku — rezo del signo que sale en la consulta", "texto_ritual": "Ogbe yeku baba amulu Aje ni baba teniteni Adifa fun ori Tinbe lohun nikan soso Ojuse keke oju bori duro Gbogbo ara se keke gbogbo ara bori duro", "traduccion": "Ogbe yeku, padre de los menores. Aje, padre de todos. Hicieron adivinación para la cabeza cuando estaba sola. Vino el ojo y se quedó. La cabeza se multiplicó. Vinieron todas las partes del cuerpo y se quedaron con la cabeza. La cabeza se multiplicó.", "origen_id": "4cc46f86f8ecef81a9dcfc93"}]}]$q$::jsonb),
(18,'cc65eb12b780e24be41d7a7fa970e393','95196bc30a9a99d49a5e425908f0fe43',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìwòrì habla de confusión emocional y de relaciones que se empiezan o se terminan, pero asegura un buen final cuando se aprende de lo vivido. Pide no contar los planes antes de tiempo, porque el que los deshace está cerca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Duda entre empezar o terminar una relación y debe separar la emoción del momento de lo que ya aprendió.", "Quiere que un proyecto llegue a buen fin sin perder lo ganado (relato de Ogbè visitando a Ìwòrì).", "Va a salir a un lugar nuevo y debe cuidar el camino y elegir bien dónde llegar (relato del cazador y el agricultor).", "Contó sus planes antes de tiempo y alguien cercano se los echó abajo (relato de Èbù Èyìn y Ògún).", "Una amistad se está enfriando por tacañería, enojo o desconfianza.", "Pregunta por un embarazo o por la responsabilidad de criar hijos.", "Se siente desordenado por dentro o teme quedarse sin apoyo (relato de la corneja Alukunrin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un final exitoso para lo que se emprendió.", "Riqueza que regresa a la persona y no se le escapa.", "Encontrar buen lugar en un camino o en una tierra nueva, si se ofrenda antes de salir."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto lleva a la resolución de conflicto y transformación espiritual. (Este odu habla de la virilidad y fertilidad y la necesidad para tomar responsabilidad para la concepción de niños. Volviéndose un padre tiene responsabilidades inherentes, el punto esta saliendo a la ocasión.)", "origen_id": "8f0fe6aefab6e533b1ee1a6c"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Contar los planes y que alguien cercano los deshaga.", "Tacañería que desacredita a la persona frente a sus amigos.", "Riesgo de perder el juicio por no cumplir la ofrenda.", "Enojarse al descubrir quién es el enemigo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El conflicto lleva a la arrogancia. (Este odu habla de las consecuencias negativas que vienen como resultado del fracaso a tomar responsabilidad para el desarrollo personal.)", "origen_id": "d90ef13da4a17fe0e6e1c4a9"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que se planea se cuida en silencio. Èbù Èyìn deshacía todo lo que Ògún hacía hasta que Ògún dejó de contar sus planes. Y la corneja que no quiso desprenderse de sus dos únicas ropas acabó perdiendo la cabeza."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè-Wẹhin habla de confusiones emocionales. También asegura tener conclusiones exitosas. Esto nos dice que debemos depender de las experiencias pasadas.", "origen_id": "20a977c95a339f2892e17310"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè visita a Ìwòrì. Antes de ir a ver a Ìwòrì, a Ogbè le marcaron tres chivos, tres gallos, la ropa que llevaba puesta y una rata de monte que debía quedarse siempre detrás de Èṣù, porque ese viaje le traería riquezas y había que asegurarse de que no se le escaparan. Cumplió. A quien le sale este Odù debe ofrecer para garantizar un final feliz.", "La corneja y sus dos ropas. Ogbèhofaafaa consultó para Alukunrin, la corneja, y le aconsejó ofrecer las dos únicas ropas que tenía, una negra y una blanca, con un chivo y un carnero, para no volverse loca, y dejarse atender con medicina de Ifá: un baño preparado con hojas contra la locura (masínwín), ọgbó y esùsù y la sangre del chivo. La corneja no quiso ofrecer.", "El cazador y el granjero. Ogbè miró hacia atrás para ver si su perro había matado a la rata. Así se consultó para el cazador que iba a siete bosques famosos y para el granjero que iba a escoger tierra nueva para su cosecha. A los dos les advirtieron que tuvieran cuidado en esos lugares y que ofrendaran antes de salir. Los dos cumplieron.", "Èbù Èyìn, el hermano de Ògún. Ògún era enérgico y siempre estaba planeando algo, pero todo lo que hacía amanecía deshecho al día siguiente. Fue a Ifá y le dijeron que ofrendara y que dejara de contar sus planes y sus viajes: que decidiera en el momento y no le avisara a nadie. El que lo deshacía todo era su propio hermano, Èbù Èyìn. Desde que Ògún dejó de contar, Èbù Èyìn ya no pudo arruinarle nada."], "pasajes": [{"titulo": "Verso 18.1", "texto": "Ogbèwẹhin-fuu-àlejò-mbọ,\nỌ̀gbàrà-ejimaketoto:\nadivinó Ifá para Ogbè\ncuando iba de visita a ver a lwòrì.\nLe fue aconsejado sacrificar:\ntres chivos, tres gallos,\nla ropa que él estaba usando\ny una rata de monte\n(la rata debe mantenerse\npermanente detrás de Eṣú),\nporque él traerá de regreso sus riquezas,\ny tiene que asegurar\nque las riquezas no lo evadan.\nEl hizo el sacrificio\nNota: Cualquiera a quien este Odù le sea adivinado, debe siempre\nofrecer sacrificios para garantizar un final exitoso o feliz.", "origen_id": "2e3e51fc77b103c1cfa15811"}, {"titulo": "Verso 18.2", "texto": "Ogbèhofaafaa:\nadivinó Ifá para Alukunrin (corneja, cuervo),\nle fue aconsejado sacrificar\nlas únicas dos ropas que poseia\n(una negra y una blanca),\njunto con un chivo y un carnero,\npara evitar la locura,\ny para que fuera atendido por los Babaláwos\ncon medicinas de Ifá.\nAlukunrin se negó a ejecutar el sacrificio.", "comentario": "58 masínwín: planta no identificada.\n59 ọgbó: NERVILIA UMBROSA (Rchb. f.) Schlt., Orchidaceae.; PARQUETINA NIGRESCENS (Afzel.) Bullock, Asclepiadaceae.\n60 esùsù: SACCHARUM SPONTANEUM L. var. aegyptiacum (Wildd.) Hark., Gramineae.", "origen_id": "fce11277a44060bce4c4f393"}, {"titulo": "Versos complementarios 1", "texto": "El cliente está considerando a menudo empezar o\nacabar una relación. La persona deberá mantener\nuna buena actitud con sus amigos, evitando ser\ntacaño, que sería una de las maneras de\ndesacreditarle. No se cuentan los planes futuros a\nnadie, el enemigo estará siempre muy cercano a la\npersona, pero no se deberá montar en cólera al\nsaber o descubrirlo.\n\n               Ogbè wèyin wò\n           Bájáà re o baà pa ikun\n          Awo Ợdẹ ló dífá fún Ợdẹ\n      Ợdẹ ni ń regbó méje èlùjù méje\n          Wón ní ki Ợdẹ ó sá káalè\n         Ệbợ ní ó şé kó tóó mợợ lợ\n           Ợdẹ gbébợ ńbè ó rúbợ\n               Ogbè wèyin wò\n           Bájáà re o baà pa ikun\n             A dífá fún Ònyagbè\n Èyí to ń lợ rèé ba wợn múlè oko àiròdùn\n  Wón ní ó sá káalè Ệbợ ní ó şé kó tóó lợ\n        Ònyagbè gbébợ ńbè ó rúbợ\n        Wón lòó ba wón múlè légàn\n                 Ợdẹ ń sợdẹ\n                Àgbè ń sàgbè\n      Wón wáá gbébợ ńbè wón rúbợ\n           Rírú Ệbợ èèrù àtùkèşù\n          Ệ wáá bá níní jèbútú ire\n    Jèbútú ire làá bá ni lésè ợba òrìşà\n       Ệ jé á móde mágbè kó lê yẹni\n              Àgbè ń tokoó bò\n           Ó mu Ìkókóró fún Ợdẹ\n               Ợdẹ ń tíjùú bò\n             Ó mu Ìkókóró ẹran\n                O si fún Àgbè\n    Ệ sàá jé á móde mágbè kó lê yẹni\n           Rírú Ệbợ èèrù àtùkèşù\n             Ayé wáá yẹ tùtúru!\n\nOgbè miró atrás\nPara ver si su perro había matado a la rata Ikun.\n\nEl adivino del cazador, lanzó adivinación para el\ncazador\nQue se dirigía hacía 7 renombrados arbustos en el\nbosque.\nLe pidieron que tuviese cuidado de esos parajes o\nlocaciones y que debía\nOfrendar antes de su partida\nÉl escuchó y ofrendó el sacrificio prescrito\nOgbè miro para atrás\nPara ver si su perro había matado a la rata Ikun\nAdivinó para el granjero que iba a escoger una\nnueva tierra para su cosecha anual. Se le dijo de\ncuidarse de esas locaciones y que sacrificase antes\nde su salida, cosa que realizó\n\n         Erín fi kúkú mợ inú ilé\n            Adìẹ fi títà mò ợjà\n           A dífá fún Èbù Èyìn\n          Eyí tíí sợmợ iya Ogun\n        Akíkanjú ènìyàn ni Ogun\n   Şùgbón bó bá pé òún ó şe nkan lóla\n        Èbù Èyìn ó ti lòó ba ibè jé\nTi ón bá pé lótùúnla làwón ó lòó şe nkan\n          Èbù Èyìn ó lòó ba á jé\n ¿Ogun wáá ní “Kín ní ń ba nnkan wònjí\n                     jé?\n               O ba tợ Ifá lợ\n               Ifá ní kó rúbợ\n              Kó si mó ẹnu è\n           Ifá pé ibi tí ó bàá lợ\n             Ki ó móợ pé ó yá\n         Àwón ó lợ ibi kan lónìí\n     Kó mó sợ ibi ti ń lợ fènikan mó\n             Ngbà ó dijó kan\n               Ogun bá nàró\n\n          O ní ìwo Èbù Èyìn ó yá\n            ¿Èbù Èyìn ní ńbo?\n        Ogun ní ngbà á bá de ibè\n                 Ó móợ mò\n     Wón ni Erin lo fi kúkú mợ inú ilé\n            Adìẹ fi títà mò ợjà\n           A dífá fún Èbù Èyìn\n          Eyí tíí sợmợ iya Ogun\n  Àşé Èbù Èyìn ni ti n bayé yìí jé njóhun!\n     Èbù Èyìn ò síí le bayé yìí jé mó o\n                 Èbù Èyìn!\n\nEl elefante usó la ventaja de su muerte para\nconocer el interior de una casa.\nY el pollo usó la ventaja de ser vendido para conocer\nel lugar del mercado.\nLanzó Ifá para Èbù Èyìn, el hermano de Ògún\nÒgún es una enérgica persona y cada vez que\nplaneaba realizar una acción, Èbù Èyìn se las\narreglaba para destruir el arreglo o conformación\nTodo lo hecho era deshecho al día siguiente\nY Ògún comenzó a preguntarse ¿Qué podría ser el\norigen de eso?\nY se fue a Ifá que le pidió sacrificar. Además de no\ncontar nada acerca de sus futuros planes o viajes a\nnadie, ni aún al más allegado familiar\nDonde quiera que vayas, toma tus decisiones\nespontáneas y no le cuentes a nadie, sobre tus\nplanes o rumbos a seguir\nDesde entonces Èbù Èyìn no pudo desbaratar más\nlos asuntos de su hermano Ògún\nEl elefante usó la ventaja de su muerte para\nconocer el interior de una casa\nY el pollo usó la ventaja de ser vendido para conocer\nel lugar del mercado\nLanzó Ifá para Èbù Èyìn, el hermano de Ògún\n\nÈbù Èyìn es aquel que destruye las cosas desde su\nprincipio, pero ya no podrá hacerlo más, pues no se\nenterará de lo que se va a realizar\nÈbù Èyìn!", "origen_id": "3e026f24236066b97400453e"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe Wehin habla de una confusión emocional, también\n     asegura conclusiones exitosas. Nos dice que confiemos en experiencias\n                                                          pasadas y recientes.\n          WO - El cliente está a menudo considerando el comienzo y final de\n                                                                   una relación\n\n\n18.1 · Ogbewehin-fuu-alejo-mbo, Ogbara-ejimaketoto profetizó Ifá para\n\nOgbe cuando iba a visitarlo con Iwori. Le fue preguntado sacrificar:\n            obuko meta, 3 gallos, la ropa que él estaba usando y jutía (la jutía\n              debe mantenerse permanente detrás de Eşu), porque él traerá de\n              regreso sus riquezas, él tuvo que asegurar que las riquezas no lo\n                                                evadieran. El hizo el sacrificio\n              Cualquiera que este marcado con este Odu debe siempre ofrecer\n                            sacrificios para garantizar un final exitoso o feliz.\n\n\n18.2 · Ogbehofaafaa profetizó Ifá para Alukunrin Kanna Kanna (la\n              corneja), le fue dicho sacrificar las únicas 2 ropas que poseía (1\n             negra, 1 blanca), 1 chivo, 1 carnero. Con el objetivo de no ir a la\n          locura y si él deseaba ser tratado por los Babalawos. La medicina de\n      Ifá (si él ejecuto el sacrificio), derramar la sangre del chivo dentro de\n      una maceta grande antes de ponerlo en el masinwin, hojas de ogbo y\n                  esusu dentro de la maceta y añadir agua para que él se lave.\n            Alukunrin se negó ejecutar el ebo. Aquellos nacidos por este Odu\n                                               generalmente se vuelven locos.", "origen_id": "30a575e5b3272faf382e1561"}, {"titulo": "Relato en inglés 1", "texto": "“After it is dead, we cut up an elephant; after it is dead, we cut up a buffalo; :\nafter it is prepared, we cut up a loaf of pounded yams,” child of Stark Naked,+ was\nthe one who cast Ifa for Odogbo when he was living in the midst of trouble.” Ifa\nsays that right now someone is in great trouble. Ifẹ̀tis mother is still alive on\nearth, he should sacrifice to her head; if she is dead, he should sacrifice to her\nat her grave.\n\nThey said that Odogbo's riches would be complete during that year. They\nsaid he should make a sacrifice; he sacrificed four pigeons, four beads (any kind\nof beads), two shillings, and 80 cowries. He made the sacrifice. They said when\nhe had\n\nfinished this sacrifice, he should sacrifice also to his mother.’ They said that\nhis blessing was to be found at home and that he must not go anywhere.\n\nWhen Odogbo had made the sacrifice and had sacrificed also to his mother,\nhe stayed at home for three days; but he did not see anything like a blessing.\nOn the fourth day he got ready and went to the farm to fetch wood, saying that he\nwas not going to starve to death. When he reached the farm, he chopped a good\npile of firewood and started back with as much as he could carry. As he was re-\nturning, carrying his load, his mother appeared as a bird, and she began to sing:\n\n“Odogbo, throw away your wood;\n“The blessing came to your house while you were gone.”\n\nWhen Odogbo heard this, he said that he would carry the wood home anyway.\nWhen he reached home and dumped the load of wood to the ground, its end broke\nthrough the ground into a pit of beads.® In this way money and wealth came to\nOdogbo, and he became a rich man.® Odogbo began to sing; he said it was just\nas the diviners had predicted when they said:\n\n“After it is dead we cut up an elephant;\n\n“After it is dead we cut up a buffalo;\n\n“After it is prepared we cut up a loaf of pounded yams,’\nchild of Stark Naked;\n\n“On the day that I, Odogbo, was living in the midst of trouble.\n“Odogbo, throw away your wood;\n“The blessing came to your house while you were gone.”", "comentario": "1. This refers to the yam loaf, which is completely naked in the sense that\nits surface is plain, undecorated, and uncovered.\n\n2, As explained later, Odogbo’s trouble was poverty.\n3. The first sacrifice goes to Eshu for the Sky God.\n\n4. Note that there is a difference between English and Yoruba in counting\ndays, The Yoruba count both the first and the last days, so that what we would\ncall three days they call four.\n\n5. Beads, especially valuable ones of the kind known as segi, are often\nfound in pits in the ground in this way. See n. 5, verse 1- 10, and n. 2, verse\n249-2, :\n\n6. In this case the outcome was successful even though Odogbo did not ob-\nserve the diviner's instruction that he must not leave his house or his mother’s\ncommand to throw away his wood. He made the sacrifice, however.", "origen_id": "b810b24d6e6db5616f91277e"}, {"titulo": "Relato en inglés 2", "texto": "\"After it is dead, we cut up an elephant; after it is dead we cut up a buffaJo;\nafter it is prepared, we cut up a loaf of pounded yams,\" child of Stark Naked, was\nthe one who cast Ifa for Odogbo! on the day that he was going to take Jand and set-\ntle in the farm. They said evil was waiting there for him; they said he must not\ngo. They said he should sacrifice one goat and three shillings. He said he would\ngo anyway, and that he would make the sacrifice when he came back. When he\nreached the farm, he met the Four Hundred Deities. They shoved him to the\nground and cut off his head. They took his head and stuck it in a young palm tree.\nThe people of his house waited for him, but he did not return; so they went to the\nfarm to look for him.\n\nWhen they got to the farm, they found his head where birds were chirping at\nit. When they saw it, they started back home, asking each other what they would\n\nreport when\n\"Y\n\nthey reached home. Not knowing what to do, they began to sing:\n\n“The birds are chirping at the corpse of a ‘dandy,’\n\n“The birds are chirping, oh, ‘gshereshere.”*\n\nIfa says an evil has pitched its tent in the farm and is waiting for someone.\nOr else someone wants to go somewhere, perhaps at a distance; evil awaits him\nwhere he is going. He should sacrifice before he goes.", "comentario": "1. The names of the diviner and of the legendary character are the same\nhere as in verse 3-1, but the circumstances are different.\n2, The sound of birds chirping.", "origen_id": "ef37745f331fe744e7ec3bac"}, {"titulo": "Relato en inglés 3", "texto": "“An elder who sits without leaning back gives the appearance of a person\nstanding” was the one who cast Ifa for “Wherever honor turns, it finds wealth,\"1\nthe child of “One who worships Oro and Qbalufgn.”*. She said that her strength\nwas no match for this world. They said her strength would be a match for this\nworld. They said she should sacrifice. She sacrificed two pangolins,’ the ring\nfrom her finger, and one shilling seven pence eight oginis. “Wherever honor\nturns, it finds wealth” is what we call witches; ever since she made the sacri-\nfice, witches have had power over human beings.*\n\nIfa says witches will seize someone right now unless he can beg them to\nchange their mind by sacrificing; then perhaps they will not take him away.", "comentario": "1, Wealth here is referred to as the cord or rope (okun) upon which cowries\nare strung.\n\n2. Oro and Qbalufgn are deities.\n\n3. Scaly anteaters (Uromanis longicaudata Briss). See Maupoil (1943: 280).\n\n4. This verse thus explains why witches can harm humans,", "origen_id": "ee3cdad1d2dfb17723057fa4"}, {"titulo": "Relato en inglés 4", "texto": "\"Ogbe, look back! and see if your dog will kill a squirrel\"? was the one who\ncast Ifa for Qrunmila when he was weeping because he had no wife. They said\nthat he should sacrifice that he might find a wife during that year. He sacrificed\na basket of peanuts, two hens, and one shilling, plus twenty cowries.?\n\nWhen he had finished sacrificing, the diviners put aside some of the peanuts\nfor him to plant. When these peanuts were ripe enough to harvest, Qrunmila\nnoticed that someone was stealing them. He thought that a squirrel was digging\nand eating them, and he began to keep watch over his peanut field.\n\nOne day as he was watching his peanuts, he saw two maidens. As they en-\ntered his peanut field and began to dig, Qrunmila came out from where he had\nbeen hiding and caught them in the act of stealing his peanuts. The maidens be-\ngan to beg him to spare them and not to take them as thieves.\n\nQrunmila replied that it was in order for him to get a wife that the diviners\nhad told him to plant these peanuts;* but if they came and stole them, how would\nhe ever be able to get married? They said that he should spare them; they would\nrather marry him than be taken as thieves. So Qrunmila married them both.\n\nThere are two maidens together; they are wives of Ifa;\" we should give them\nto Ifa so that they may not bring disgrace upon their family.\n\nAnd there is a man who wants to take a wife; he will marry her without giving\nbridewealth if he is able to sacrifice. And a woman should be careful lest she\nbe taken as a thief this year.\n\n4-1A\n\n“Ogbe closes very generously”! was the one who cast Ifa for Head, who had\nknelt and chosen his destiny,” and enemies prevented him from achieving it.\nIfa says he sees an evil-wisher who does not want us to succeed in what we are\ndoing. Ifa says he will aid us in conquering the evil-wisher. He says that we\nshould sacrifice three cocks and one shilling six pence, plus twenty cowries.", "comentario": "1, Ogbe-w(o)-ghin, an alternative name of the figure Ogbe-(I)wori, is in-\ncorporated into the diviner’s name.\n\n2. A squirrel is later suspected of digging up Qrunmila’s peanuts.\n\n3. Though in itself this is not a very convincing example, the sacrifice of\ntwenty cowries (oko) in a verse which involves a farm (oko) of peanuts follows\nthe pattern of word magic, See Chapter XII. e\n\n4. It is implied that Ọrunmila was to use the profit from the peanuts for\nbridewealth, Although this did not happen, Qrunmila nevertheless got two wives,\nwithout having to give bridewealth, through planting the peanuts.\n\n5. A woman who is told by a diviner that she is destined to be a “wife of Ifa”\nmust be given in marriage to a diviner without bridewealth being given for her\n(see Chapter IX).\n1, This name implies that whatever the client wishes will be granted. Note\nthe pun on the name of the figure, Ogbe-(E)di.\n\n2, Each soul, before leaving heaven to be born, is believed to kneel before\nthe Sky God to choose its destiny on earth (see Chapter XI).\n\n4-1B\n\n“Ogbe closes very generously” was the one who cast Ifa for Head, who had\nknelt and chosen his destiny, and enemies prevented him from achieving it.\n\nIfa says there is an evil-wisher who does not want us to succeed in what we are\ndoing. Ifa says he will aid us in conquering the evil-wisher. After Head had\nmade the sacrifice, everything that he was doing straightened out, and the way\n\nwas clear to success.'! Three cocks and one shilling six pence, plus twenty\ncowries,? is the sacrifice.\n\n1, The Yoruba idiom is “to have a road.” Aside from the addition of this\nsentence and minor differences in wording, this is the same as verse 4-1 A.\n2. Owo ẹyọ are the large cowries used as money.", "origen_id": "03740db9d6d69d3cfa5f401e"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: tres chivos, tres gallos, la ropa que llevaba puesta y una rata de monte que se deja detrás de Èṣù.", "Alukunrin (rechazado): sus dos ropas, negra y blanca, un chivo y un carnero; baño de masínwín, ọgbó y esùsù.", "El cazador y el granjero: ofrenda antes de salir.", "Ògún: ofrenda y no contar los planes."], "pasajes": [{"titulo": "Ofrenda en el verso 18.1", "texto": "Ogbèwẹhin-fuu-àlejò-mbọ,\nỌ̀gbàrà-ejimaketoto:\nadivinó Ifá para Ogbè\ncuando iba de visita a ver a lwòrì.\nLe fue aconsejado sacrificar:\ntres chivos, tres gallos,\nla ropa que él estaba usando\ny una rata de monte\n(la rata debe mantenerse\npermanente detrás de Eṣú),\nporque él traerá de regreso sus riquezas,\ny tiene que asegurar\nque las riquezas no lo evadan.\nEl hizo el sacrificio\nNota: Cualquiera a quien este Odù le sea adivinado, debe siempre\nofrecer sacrificios para garantizar un final exitoso o feliz.", "origen_id": "fd68fdfe96722cd51b96e46c"}, {"titulo": "Ofrenda en el verso 18.2", "texto": "Ogbèhofaafaa:\nadivinó Ifá para Alukunrin (corneja, cuervo),\nle fue aconsejado sacrificar\nlas únicas dos ropas que poseia\n(una negra y una blanca),\njunto con un chivo y un carnero,\npara evitar la locura,\ny para que fuera atendido por los Babaláwos\ncon medicinas de Ifá.\nAlukunrin se negó a ejecutar el sacrificio.", "origen_id": "47f7d4700786a95ec39d8374"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù guarda la riqueza que regresa. Ògún es protagonista del relato de los planes deshechos. Ifá y los babaláwo preparan la medicina."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Masínwín, ọgbó y esùsù (baño contra la locura); rata de monte."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 18.2", "texto": "(Si el cliente ejecuta el sacrificio) Colocar en un recipiente grande (ikoko) hojas contra la locura (masínwín), hojas de ọgbó y de esùsù. Sacrificar el chivo derramando sangre sobre las hojas, añadirle agua a la ikoko. Esto sirve para que el cliente se bañe.\nNota: Aquellos nacidos por este Odù tienen generalmente tendencia a padecer de locura.", "origen_id": "29719f4acb403f82a404d915"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 18.1 (yorùbá): Ogbèwẹ̀hin-fuu-àlejò-mbọ, / Ogbàrà-ejimaketoto: / a dífá f'Ogbè / nlọ s'ode lwòri. / Wọ̀n niki ò wa rùbọ: / Òbúkọ mẹta, / akuko-adiẹ mẹta, / aṣọ tiowa ni orùn rè / ati oridan eku kan / (kiamu eku naa si iduro lehin Èṣú). / Nitoripe o maa b'ọ̀rọ̀ de / ati pe ki prọ̀ naa ma baa foo. / Ó gbọ̀ ó rú.", "Verso 18.2 (yorùbá): Ogbèhofaafaa: / a difá fún Alukunrin (Kanna-Kanna) / Wọ̀n niki / ó wa ti aṣo Méjì kan bayi / (òkan dúdú, ekeji funfun) / tiowa lowọ rẹ rúbo / pẹlu Öbúko ati agbo / kioma baa sínwin / ati biobafẹ ki àwọn Awo / ṣe ewé Ifá fún oun. / Alukunrin kọ̀ kò rú.", "REZO: OGBE WEÑE MAFEREFUN OBATALA, OBATALA ALEYO UMBO INEDI IRE UMBO OMOFA EBE BODA KIMI IDERELE ADIFAFUN ASHEGUIDA ORUNMILA ADSHEKUE KII EYELE, AIKORDIE, EKU, EYA, EPO, AWADO, OPOLOPO OWO.", "SUYERE: MOÑU EKUE, MOÑU EKUE MOSARAO, OPOLO YAMI OPOLO YUMI MOÑU EKUE MOSARAO.", "REZO: LERIKAN ADIFAFUN AWO SARAKO BABA WELE AWO ABANITA AYE OBA ORUNMILA KOLADE OBE KAILEBO LEBO OGBE WEÑE SARAKO LAYE.", "REZO: OGBE WEÑE DOGUO ADAFA OMI BABALAWO ERA OLONA EWE AYA AYALORUN EWE EBOKARA OMI SIBA AKORDIE, EYELE, ETU.", "REZO: OGBE WEÑE KAFEREFUN SHANGO, OBATALA ALEYO UMBO IRE UMBO OMOFA UMBO, ALAFIA MANI LELU TOFE ORUNMILA AYE ORUNMILA FOMBO INTORI EURE ASHO ARA OJIBARA OMI OLE LUAYU OLUO ENCO UMBO LEÑO KOKOTO NILARA KOFEREBO EKU EYA, OPOLOPO OWO.", "REZO: OGBE IWERI IFANI GUENI GUENI GUATO ORUNMILA LODAFUN ALEYO LODAFUN SHANGO SHAQUITI NERBO OLUO ORA ADIFAFUN ORUNMILA ILE OLOKUN EURE LEBO SHAQUITI LEBO OLUO ARUN ADIFAFUN OSHORI QUINSHO LORO LORO LERI ORDA AKUKO LEBO KAREFUN OLOKUN, YALODE OBINI ORUNMILA QUINSHE ELEBO ADIFAFUN ABA LO OLEBO EKU, EYA, AYA, KONO ELEDE IKON KONI AYA OGRIAN TANKATE IYALE LO DRIAN OLO DE OGRION EBITIPAN Y AWO EMBEPAYA GRIO OBINI BORIO.", "REZO: OGBE WEÑE SILEDEO AWO SHOGOIKO AWO BABA SHERE.", "SUYERE PARA DAR CANDELA A ELEGBA: MALANGE IKU INAFE MALANGE IKU MALANGE IKU INAFE MALANGE IKU.", "SUYERE PARA OBATALA: ORISHA OBATALA BABAE PRISHA OSHANIA BABA EE.", "REZO: LERIKAN ADIFAFUN AWO SARAKO BABA WELE AWO ABANIA AYE BABA ORUNMILA KOLADE OGBE KAILEBO LEBO OGBE WEÑE SARAKO LAYE.", "REZO: ADIFAFUN OLOFIN OLOTORUN OMO AYE EGUGUN ORUN OKUARIBO", "ADAKE DAYE BABARIWO AWO OMITUNTUN AYEKALE ARUN SHE A BANI OFINTO OMO KEKE OBINI AYE LODAFUN ORUNMILA ABEBA-DAWINO IDELE OMO OLOFIN."], "pasajes": [{"titulo": "Rezo 7", "texto_ritual": "OGBE WEÑE SILEDEO AWO SHOGOIKO AWO BABA SHERE.\n\nSUYERE PARA DAR CANDELA A ELEGBA:\nMALANGE IKU INAFE MALANGE IKU MALANGE IKU INAFE MALANGE IKU.\n\nSUYERE PARA OBATALA:\nORISHA OBATALA BABAE PRISHA OSHANIA BABA EE.", "origen_id": "45b6bf575997bf1e799f6bd2"}]}]$q$::jsonb),
(19,'4ad76d9de2519ea413446db5123f1bbf','d6c1decf0b071d6d8aba192056621379',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìdí habla de hacer la ofrenda completa y a tiempo para no quedar atrapado, endeudado o en ridículo. Las presiones emocionales, muchas veces de pareja, frenan lo práctico mientras no se alivian. También anuncia hijos y amistades que vuelven de lejos con fortuna."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay presión en lo afectivo y, mientras no la atienda, le cuesta sacar adelante un proyecto.", "Va a una salida o expedición y debe medir el obstáculo antes de meterse (relato de Ogbè atrapado en el elefante).", "Quiere salir de una deuda, pero otros lo distraen con encargos (relato de Èṣù pescador).", "Alguien querido que está lejos puede volver con buenas noticias (relato de Baáyannì y Ṣàngó).", "Desea tener hijos (relato de Àjàgbé).", "Trabaja para ganar más y ampliar su círculo.", "Siente celos o interrupciones en su avance."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una persona querida que está lejos regresa con buenas cosas.", "Muchos hijos, tantos que se encuentran en todas partes.", "Fortuna compartida con el mejor amigo.", "Salir de una deuda o de un aprieto."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto lleva al renacimiento productivo. (Este odu habla de la transformación de la pobreza en abundancia a través del trabajo duro y optimismo, llevando al incremento en amigos y comunidad.)", "origen_id": "5a3be9eee75f133c13fa3fea"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Quedar encerrado o atorado en un lugar por no ofrecer antes de salir.", "Deudas que esclavizan.", "Que otros se aprovechen de lo que uno trabaja.", "Beber vino en exceso."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva al cambio sin sentido. (Este odu habla de la posibilidad de interrupción de los extraños que están celosos del potencial para el progreso.)", "origen_id": "a5adcd394a4a8ec7a3a2bbd8"}]}, {"titulo": "Enseñanza principal", "texto": "El que se niega a ofrecer termina en aprietos y el que cumple queda libre. Èṣù se volvió servidor de Ọ̀rúnmìlà por no hacer su ofrenda; Ogbè quedó atrapado dentro de un elefante hasta que su gente ofreció por él."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbédi habla de la necesidad de la ejecución correcta del sacrificio con el objetivo de evitar dificultades, apuros o hacer el ridículo.", "origen_id": "96e5725f6bfdbc93a942518f"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè dentro del elefante. Ogbè iba de cacería y le marcaron tres chivos, tres gallos y 6,000 cauríes para no quedar encerrado en el monte. Se negó. En el bosque empezó a llover; corrió a meterse en un hueco que creyó era un tronco hueco o un hormiguero, y era el ano de un elefante. El elefante lo cerró y Ogbè no pudo salir. Su gente lo buscó sin encontrarlo, y al final decidió hacer la ofrenda que él había dejado. Entonces el elefante lo expulsó. Por eso dijeron: 'al Ogbè que salió de un ano lo llamaremos Ogbèdi'.", "Cómo Èṣù quedó viviendo afuera de la casa de Ọ̀rúnmìlà. Èṣù debía mucho a Ọ̀rúnmìlà, a Òrìṣà-ńlá, a Òrìṣà-oko y a Ògún, y en ese tiempo era pescador. Le marcaron cáscaras de nuez de palma, nueve palomas y 18,000 cauríes para pagar sus deudas, y no quiso. Como su trampa sacaba mucho pescado, los irúnmọlẹ̀ temieron que pagara y se liberara, y el mismo día lo mandaron a lugares lejanos: Ọ̀rúnmìlà por su bolso y su batea a Oke-Biṣi, Òrìṣà-ńlá por su bastón a Ìrànjé, Òrìṣà-oko a Ode Irawẹ, Ògún por su machete largo a Ode-Ire. Ọ̀rúnmìlà consultó antes y le marcaron seis conejos, seis palomas y 12,000 cauríes; metió los conejos en su bolso y le dijeron que no lo soltara. Èṣù, en vez de viajar, conjuró todo desde el arbusto más cercano y regresó de inmediato: encontró a todos repartiéndose sus pescados, y ellos los escondieron en sus bolsas. En Ifẹ̀ estaba prohibido robar, así que los demás le perdonaron las deudas a cambio de que callara. Ọ̀rúnmìlà negó haber robado, y Èṣù lo acusó porque juraba ver narices de pescado saliendo de su bolso. En la corte de Ifẹ̀ abrieron el bolso y salieron los seis conejos. Avergonzado, Èṣù pidió perdón, ofreció empeñar su casa y sus bienes, y Ọ̀rúnmìlà no aceptó; entonces dijo que lo serviría para siempre. Ọ̀rúnmìlà no lo dejó entrar: le dijo que él comería adentro y le compartiría afuera. Desde ese día Èṣù vive fuera de la casa de Ọ̀rúnmìlà.", "Baáyannì regresa del bosque. Ifá consultó para Baáyannì cuando iba al bosque de Ìsèlè y le deseó mucha fortuna si ofrecía. Su compañero, el que se quedó en casa, era Ṣàngó. Baáyannì volvió con tanto dinero que le dio una parte a Ṣàngó, y Ṣàngó la ató a su ropa. Ifá le pide a quien saca este Odù que cuide mucho a su mejor amigo.", "Àjàgbé, la mosca. Àjàgbé lloraba porque no tenía hijos. Le pidieron ofrecer y lo hizo. A Àjàgbé lo conocemos como la mosca, y no hay ciudad en el mundo donde no se encuentren sus hijos. La gente se preguntaba cómo alguien podía tener tantos."], "pasajes": [{"titulo": "Verso 19.1", "texto": "Kukute-agbọn Korojiji:\nadivinó Ifá para Ogbè,\ncuando éste iba a una expedición de cacería.\nLe fue aconsejado hacer sacrificio\nasí no encontraría obstáculo allí\n(no verse encerrado o cercado allí):\ntres chivos,\ntres gallos\ny 6000 cowries.\nEl se negó a sacrificar.\ncuando llegó al bosque,\ncomenzó la lluvia,\nél se precipitó a correr,\nvio un hueco amplio,\ny supuso que era el hueco de un árbol\no el hueco del montículo de un hormiguero.\nÉl se metió por el hueco,\nsin saber que estaba dentro de un elefante\nque tenía abierto su ano.\nEl elefante cerró su ano,\npor lo tanto él no podía encontrar una salida.\nSu gente comenzó a buscarlo.\nDespués de un rato\ncuando ellos no pudieron encontrarlo,\nellos decidieron irse y ejecutar el sacrificio\nque él había abandonado,\nfue entonces que el elefante lo excretó.\nPor eso, todos decían:\n\"el Ogbè que salió de un ano\ndeberá ser llamado Ogbèdi\".", "origen_id": "cf8f85f726711a968724a4db"}, {"titulo": "Verso 19.2", "texto": "Ogbèdikaka,\nOgbèdilele:\nadivinó Ifá para Éṣú\ncuando él se estaba haciendo de sirviente\npor una deuda que tenía\ncon Ọ̀rúnmìlà, Oriṣà-ńlá, Oriṣà-oko y Ògún.\nA Epú le fue aconsejado ofrecer en sacrificio:\ncascarones de nuez de palma,\nnueve palomas y 18000 cowries,\npara preparar una medicina\nque le permitiera a él pagar sus deudas.\nEṣú negó sacrificar.", "comentario": "Eṣú quien tenía una gran deuda con los Irúnmalẹ, era un pescador en aquel momento. Cada vez que él capturaba una gran cantidad de peces con su trampa los Irúnmalè lo envidiaban. Ellos pensaron que Èṣú haría pronto demasiado dinero para pagar la fianza de sí mismo y salir así de sus apuros financieros. Por esta razón ellos decidieron enviarlo con recados hacia lugares distantes, en el mismo día.\nỌ̀rúnmìlà envió a Eṣú hacia Oke-Biṣi a traer su bolso y su batea.\nDespués de enviar el mensaje, Ọ̀rúnmìlà pensó en consultar con el oráculo de Ifá sobre el asunto, llamó a los Babaláwos quienes profetizaron Ifá y vieron el Odù Ogbèdíkaka.\nỌ̀rúnmìlà fue aconsejado a sacrificar: seis conejos, seis palomas, 12000 cowries.\nÉl escuchó y ejecutó el sacrificio.\nLa medicina de Ifá fue preparada para él, apretando los seis conejos en el bolso, ellos le advirtieron que siempre llevara el bolso con él, Oriṣà-ńlá le dijo a Eṣú para ir a Irànje para traerle su bastón (opa oṣoro) y un bolso, Òriṣà-oko envió a Èṣú a Ode Irawẹ. Ogún le dijo a Èṣú para ir a Ode-Ire para traer su Gbamdari (machete largo), rápidamente Èṣú se levantó y fue hasta el arbusto más cercano donde él conjuró y obtuvo todas las cosas pedidas. Inmediatamente después que Èṣú salió, todos los Irúnmalẹ comenzaron a cogerle el pescado de su trampa, sin embargo él estaba ya de regreso y los encontró repartiéndose sus pescados.\nComo él apareció inesperadamente todos echaron los pescados en sus bolsas. Él entregó todos los recados que le habían pedido a buscar.\nEṣú entonces comenzó a preguntarle a todos. De dónde sacaron el pescado que estaban compartiendo, algunos estaban disculpándose, otros no sabian que decir, aquellos rogaban su perdón. Decidieron darle sus demandas sobre el dinero que él les debía a cambio de no decir a nadie que ellos le habian robado.\nEra la costumbre en Ifè en aquel tiempo que nadie debía robar.\nỌ̀rúnmìlà decía que él no robó el pescado de Eṣú. Eṣú decía que Ọ̀rúnmìlà debía haber robado el pescado que estaba amarrado en el bolso y que él estaba agarrando. Eṣú pensó que las narices de los pescados estaban bombeado fuera del bolso. Ellos llevaron el asunto a la corte en la ciudad de Ifè. Ellos discutieron, la corte decidió preguntarle a Ọ̀rúnmìlà para descubrir el contenido del bolso. El aflojó el bolso y ellos vieron los seis conejos que él sacaba. Ellos comenzaron a culpar a Èṣú.\nEṣú le rogó a Ọ̀rúnmìlà por su perdón, Ọ̀rúnmìlà se negó a aceptar su súplica. Eṣú se adelantó en empeñar su casa y otras posesiones a Ọ̀rúnmìlà. Aún así Ọ̀rúnmìlà se negó a aceptar su ofrecimiento.\nEl Otù de lfè le preguntó a Éṣú que intentaba hacer, él respondió que iría a la casa con Ọ̀rúnmìlà y continuaría sirviéndole para siempre, ellos ayudaron a Eṣú por encima de Ọ̀rúnmìlà. Cuando todos llegaron a casa de Ọ̀rúnmìlà, Eṣú quería entrar con Ọ̀rúnmìlà a su casa, éste se negó y le dijo a Èṣú que se sentara afuera. Ọ̀rúnmìlà dijo que él comería dentro de la casa, y que compartiría con Eṣú fuera de la casa. Desde aquel día Èṣú ha estado viviendo fuera de la casa de Ọ̀rúnmilà.", "origen_id": "1955fa20ed99e881ff298061"}, {"titulo": "Versos complementarios 1", "texto": "La amistad o relación que está lejos se podrá atraer\na través de rezos y ceremonias y llegará con muy\nbuenas cosas para la persona. Este Odù habla de\ntener hijos que vivirán en el extranjero y que la\npersona deberá evitar consumir grandes cantidades\nde vino.\n\n              Kolálù lawo abé ợta\n        Ejò ló kó làngbà-làngbà wợ isà\n              A dífá fún Baáyannì\n                Ti nlo síjùu sèlé\n                 Wón ní ó rúbợ\n                Wón niré fún un\n           Eèkejì è làá pè ní Şàngó\n              Ńgbà ti Baáyannì dè\n                     Owó pó\n             Ó bá kó diè fún Şàngó\n          Şàngó bá so owó mó asợ è\n    Ifá pé kí eléyiun ó tójú èèyàn dáadáa\n              Ayé bá yẹ Baáyannì\n            N ní wá ń jó ní wá ń yò\n           Ní ń yin àwón babaláwo\n           Àwón babaláwo ń yin Ifá\n      Ó ní bèé làwón babaláwo tòún wí\n              Kolálù lawo abé ợta\n\n        Ejò ló kó làngbà-làngbà wợ isà\n              A dífá fún Baáyannì\n                Ti nlo síjùu sèlé\n          Wón ní ó sá káalè kó rúbợ\n               Kó lè baà múre dé\n             Dáda mó súnkun mó o\n              Dáda mó sèjè mó o\n               Èrò ìsèlè ń bò lonà\n         Yóó fùún ợ lóókan ợ so mórí.\n\nKolálù lawo abé ợta\nEs la serpiente que medrosa está en la madriguera\nLanzó Ifá para Baáyannì\nQue venía al bosque de sèlé\nSe le pidió sacrificar, ya que se le deseaba mucha\nfortuna\nSu compañero aún estaba en casa y es aquel llamado\nŞàngó\nA su regreso, Baáyannì tuvo tanto dinero, que le dio\nparte a Şàngó\nY él la ató a su ropaje.\nIfá le dice que cuide muchísimo a su mejor amigo\nLa vida le fue muy placentera a Baáyannì, quien se\nregocijó y bailó\nAlabó a sus babaláwo y estos alabaron a Ifá\nKolálù lawo abé ợta\nEs la serpiente que medrosa está en la madriguera\nLanzó Ifá para Baáyannì\nQue venía al bosque de sèlé\nSe le pidió sacrificar, ya que se le deseaba mucha\nfortuna\nQue tuviese cuidado de la tierra y que sacrificase para\nque pudiese regresar con mucha fortuna\nDàda no llore de nuevo, Dàda no llore de nuevo sangre\nEl pueblo del bosque de ìsèlè, regresará muy pronto\n\nY le darán a ud. un cowríe para atar en su cuerda o\ncinturón\n\n           Olúfón níí wofá Ogele\n          Alásìá níí wo Ifá Ògiyan\n       Òrìşàńlá ò jé ta ợmợ tié lópò\n             Ifá rere n logbedí\n             A dífá fún Àjàgbé\n     Àjàgbé tí ń fomi ojú sógbèré ợmợ\n        Òún le bímợ lópòlopò báyìí?\n               Wón ní kó rúbợ\n               Àjàgbé bá rúbợ\n             À á şé mợ Àjàgbé?\n               N làá pé Eesin\n           Kò si ilè tí Àjàgbé ó si\n                   Ayé yé é\n     Wón ní ợmợ Àjàgbé ló pò tó báyìí?\n                  Ijó ní ń jô\n                 Awo ní ń yò\n          N ń yin àwón Babaláwo\n          Àwón Babaláwo ń yin Ifá\n     Ó ní béè làwón Babaláwo tòún wí\n           Olúfón níí wofá Ogele\n          Alásìá níí wo Ifá Ògiyan\n       Òrìşàńlá ò jé ta ợmợ tié lópò\n             Ifá rere n logbedí\n             A dífá fún Àjàgbé\n     Àjàgbé tí ń fomi ojú sógbèré ợmợ\n                   Èrò Ipo!\n                   Èrò Òfà!\n        Bo lẹ gbé joyè tẹẹ Ràjàgbé?\n        Àjàgbé dé ò abợlà rẹbẹrẹbẹ\n\nEs Olúfón quien lanza Ifá para Ogele\nAlásìá lanza Ifá para Ògiyan\nÒrìşàńlá nunca vendería a sus propios hijos por\ncacahuetes\nOgbèdí es un buen Ifá\nLanzó adivinación para Àjàgbé, cuando lloraba por\ntener hijos\n¿Podré algún día tener descendencia?\nLe dijeron que ofrendase y así lo hizo\n¿Cómo nosotros reconocemos a Àjàgbé?\nEs aquel a quien se le llama “La Mosca”\nY no hay una sola ciudad o lugar en el mundo donde no\nse halle a la Mosca\nLa vida le fue placentera y la gente decía: Los hijos de\nla mosca son muchísimos!\nEs Olúfón quien lanzo Ifá para Ogele\nAlásìá lanzo Ifá para Ògiyan\nÒrìşàńlá nunca vendería a sus propios hijos por\ncacahuetes\nOgbèdí es un buen Ifá\nLanzó adivinación para Àjàgbé, cuando lloraba por\ntener hijos\nGente de Ìpò y de Òfà, ¿dónde se puede viajar sin\nencontrarse con la descendencia de Àjàgbé?\nÀjàgbe regresó con buena cantidad de riquezas.", "origen_id": "6e4a9bbc036439d404395028"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe Di habla de la necesidad de la ejecución correcta del\n           sacrificio con el objetivo de evitar dificultades o hacer el ridículo.\n            WO – El cliente está sintiendo o teme alguna presión emocional.\nPosibilidades prácticas no se pueden realizar hasta que esta presión no sea\n         aliviada. La presión a menudo proviene, producto de las relaciones.\n\n\n19.1 · Kukute-agbon Korojiji profetizó Ifá para Ogbe, cuando éste iba\n         a una expedición de caza o cacería. Le fue preguntado sacrificar, así\n     no encontraría obstáculo allí. Ebo: 3 chivos, 3 gallos, 6000 cowrie. Él\n      se negó a sacrificar, cuando llegó al bosque comenzó la lluvia, como\n         él estaba corriendo veía un hueco amplio que él pensaba que era un\n             árbol o un hormiguero. Él cayó dentro del hueco y no sabía que\n             estaba dentro de un elefante que tenía abierto su ano. El elefante\n         cerró su ano contra él, por lo tanto no podía encontrar una salida. Su\n              gente comenzó a buscarlo. Después de un rato cuando ellos no\n     pudieron encontrarlo, ellos decidieron irse y ejecutar el sacrificio que\n      él había abandonado, fue entonces excretado por el elefante. A pesar\n\nde eso, ellos decían: el Ogbe que salió de un ano deberá ser llamado\n                                                              (Ogbe Di).\n\n\n19.2 · Ogbedikaka, Ogbedilele profetizó Ifá para Eşu cuando él se estaba\n\n      sirviendo de una condena de esclavitud con Orunmila, Orişa Nlá,\n          Orişa Oko y Oguas. A Eşu le fue preguntado ofrecer como un\n  sacrificio cáscaras de almendras de palma, 9 palomas, 18000 cowrie.\n  La medicina de Ifá deberá ser preparada para permitirle a él pagar sus\n                                            deudas. Eşu negó sacrificar.\n   Eşu era un pescador en aquel momento. Cuando él capturó una gran\n       cantidad de pescados en su trampa el irunmale (400 deidades) lo\n     envidiaron. Ellos pensaron que Eşu haría pronto demasiado dinero\n     para pagar fianza de si mismo y salir así de sus apuros financieros.\n      Por esta razón ellos decidieron enviarlo con recados hacia lugares\n      distantes, en el mismo día. Orunmila envió a Eşu hacia Ke Bisi a\n           traer su jaba o saco y la batea o cubeta. Después de enviar el\n   mensaje, Orunmila pensó en consultar con el oráculo de Ifá sobre el\n      asunto, llamó a los Babalawos quienes profetizaron Ifá y vieron a\n                                                            Ogbedikaka.\n   Orunmila fue aconsejado para sacrificar. Ebo: 6 conejos, 6 palomas,\n   12000 cowrie. Él escuchó y ejecutó el sacrificio. La medicina de Ifá\n       fue preparada por él, apretando los 6 conejos en el bolso, ellos le\n     advirtieron que siempre llevara el bolso con él, Orişa Nlá le dijo a\n    Eşu para ir a Iranje y traerle su bastón (opa osoro) y un bolso, Orişa\n\nOko envió a Eşu a Ode Irawo. Oggún le dijo a Eşu para ir a Ode Ire y\ntraer su Gbamdari (machete largo), rápidamente Eşu se levantó y fue\n    hasta el arbusto más cercano donde él conjuró y obtuvo todas las\ncosas pedidas. Inmediatamente después que Eşu había salido, todo el\n   Irunmole fue a recogieron el pescado de su tampa, como él estaba\n regresando a casa los encontró repartiéndose sus pescados. Como él\napareció inesperadamente todos echaron el pescado en el bolsillo. Él\n             entregó todos los recados que le habían pedido a buscar.\n   Eşu entonces comenzó a preguntarle a todos. De dónde sacaron el\n  pescado que estaban compartiendo, algunos estaban disculpándose,\n   otros no sabian que decir, aquellos rogaban su perdón. Decidieron\n     darle sus demandas sobre el dinero que él les debía y él no haría\n     saber a nadie ellos le habían robado. Era la costumbre en Ife en\naquel tiempo que nadie debía robar. Orunmila decía que él no robó el\n       pescado de Eşu. Eşu decía que Orunmila debe haber robado el\n  pescado que estaba amarrado en el bolso y que él estaba agarrando.\n  Eşu pensó que las narices de los pescados estaban bombeado fuera\ndel bolso. Ellos llevaron el asunto a la corte en la ciudad de Ife. Ellos\ndiscutieron, la corte decidió preguntarle a Orunmila para descubrir el\n   contenido del bolso. Él aflojó el bolso y ellos vieron los 6 conejos\n       que él sacaba. Ellos comenzaron a culpar a Eşu. Eşu le rogó a\n Orunmila por su perdón, Orunmila se negó a aceptar su súplica. Eşu\n  se adelantó en empeñar su casa y otras posesiones a Orunmila. Aún\n        así Orunmila se negó a aceptar su ofrecimiento. El Otu de Ife\n\n(mayores de Ife) le preguntaron a Eşu que intentaba hacer, él\n          respondió que iría a la casa con Orunmila y continuaría sirviéndole\n      para siempre, ellos ayudaron a Eşu por encima de Orunmila. Cuando\n          todos llegaron a casa de Orunmila, Eşu quería entrar con Orunmila,\n      éste se negó y le dijo a Eşu que se sentara afuera. Orunmila decía que\n           él comió dentro de la casa, él compartiría con Eşu fuera de la casa.\n            Eşu ha estado viviendo fuera de la casa siempre, desde aquel día.", "origen_id": "c168cbd95cecf3725093fe9d"}, {"titulo": "Relato en inglés 2", "texto": "“Today Ogbe Edi’s fight, very hazily,! tomorrow Ogbe Edi’s fight, very hazi-\nly; the male bird is the one that does. . .2 with its wings; an old palm tree is the\none that has the omu plant’ in back” was the one who cast Ifa for Lukoun when he\nwas making war on the Town of Blood. They said one whole person would be\nbrought from there.‘ They said he should sacrifice two hens and one shilling,\nplus twenty cowries.®\n\nLukoun is the name that penis is called. Town of Blood is the name of vagina.\nSomeone is menstruating at this very moment; she should sacrifice that the dis-\ncharge may become a child® And a man wants to have an affair with a woman who\n\nis menstruating; they should sacrifice so that a complete person may emerge from\nit.", "comentario": "1. Described as being like fog or smoke; or as things appear when the eyes\nare opened and shut very rapidly. Ogbe Edi is the name of the figure.\n\n2. Informants could not translate the word ggan in this context.\n\n3. An unidentified plant that is said to sprout out of the base of old palm trees.\n\n4. The reference here is to the birth of a child.\n\n5. Cf. n. 2, verse 4-1B. Here twenty cowries (oko) are included in a verse\ninvolving penis (oko).\n\n6. The Yoruba believe that the menstrual fluid develops into the embryo and\nlater the child. Cf. verses 14-1, 86-3.", "origen_id": "521d66e33ca13272341d0340"}, {"titulo": "Relato en inglés 3", "texto": "“Tfa’s bell has a pointed mouth”? was the one who cast Ifa for the barren\nwoman who divined because she had no children, They said she would give birth\nto a child. Two rats, two fish, two hens, and one shilling, plus twenty cowries,\nwas the sacrifice, Ifa says a woman is seeking a child; she will give birth to a\ngirl whose name must not be changed. Dada? is what the child will be called.\nThe one for whom this figure was cast should complete the sacrifice\n\nand then go and sacrifice to the God of Thunder also. Ifa says he sees the bless-\ning of a daughter; a diviner will be her husband.", "comentario": "1. Cf. n. 1, verse 1-7,\n2, The name “Dada” is given to children born with prominent tufts of hair.\nSuch children are especially sacred to the God of Thunder. Note that the mother\n\nis told to sacrifice to the God of Thunder in addition to her sacrifice to the Sky\nGod.", "origen_id": "aa32a4a5e382b3d66f3002be"}, {"titulo": "Relato en inglés 4", "texto": "“Quietly I go, smoothly I return”! was the one who cast Ifa for Hook? when it\nwas waging war against a tangled snarl.’ They said it would not return empty-\nhanded. Two pigeons, two cocks, and one shilling was the sacrifice. He made the\nsacrifice. Since then, Hook does not return empty-handed when it reaches up to\npull anything down.‘\n\nIfa says we are stretching out our hands toward something.\" Ifa says we should\nsacrifice lest we draw a blank in that for which we are reaching, whether it is some\nwork or something else.", "comentario": "1. This seems to refer to the motions of the hook when it is used to pull some-\nthing down.\n\n2. A hook, also known as Ariwg or Arigggg, which is made from a forked stick\nand is shaped like a Yoruba hoe handle.\n\n3. As when someone uses a hook to pull down something snarled from a tree.\n\n4, The verse thus explains why hooks are useful implements for plucking fruit\nor pulling down things which are out of reach,\n5, Like Hook.", "origen_id": "92d9694d8ba039fd2deddc5a"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè en la cacería (rechazado): tres chivos, tres gallos y 6,000 cauríes.", "Èṣù (rechazado): cáscaras de nuez de palma, nueve palomas y 18,000 cauríes.", "Ọ̀rúnmìlà: seis conejos (guardados en su bolso), seis palomas y 12,000 cauríes.", "Baáyannì y Àjàgbé: ofrenda antes de salir y para tener hijos."], "pasajes": [{"titulo": "Ofrenda en el verso 19.1", "texto": "Kukute-agbọn Korojiji:\nadivinó Ifá para Ogbè,\ncuando éste iba a una expedición de cacería.\nLe fue aconsejado hacer sacrificio\nasí no encontraría obstáculo allí\n(no verse encerrado o cercado allí):\ntres chivos,\ntres gallos\ny 6000 cowries.\nEl se negó a sacrificar.\ncuando llegó al bosque,\ncomenzó la lluvia,\nél se precipitó a correr,\nvio un hueco amplio,\ny supuso que era el hueco de un árbol\no el hueco del montículo de un hormiguero.\nÉl se metió por el hueco,\nsin saber que estaba dentro de un elefante\nque tenía abierto su ano.\nEl elefante cerró su ano,\npor lo tanto él no podía encontrar una salida.\nSu gente comenzó a buscarlo.\nDespués de un rato\ncuando ellos no pudieron encontrarlo,\nellos decidieron irse y ejecutar el sacrificio\nque él había abandonado,\nfue entonces que el elefante lo excretó.\nPor eso, todos decían:\n\"el Ogbè que salió de un ano\ndeberá ser llamado Ogbèdi\".", "origen_id": "035499b74ad797596d050f4f"}, {"titulo": "Ofrenda en el verso 19.2", "texto": "Ogbèdikaka,\nOgbèdilele:\nadivinó Ifá para Éṣú\ncuando él se estaba haciendo de sirviente\npor una deuda que tenía\ncon Ọ̀rúnmìlà, Oriṣà-ńlá, Oriṣà-oko y Ògún.\nA Epú le fue aconsejado ofrecer en sacrificio:\ncascarones de nuez de palma,\nnueve palomas y 18000 cowries,\npara preparar una medicina\nque le permitiera a él pagar sus deudas.\nEṣú negó sacrificar.", "origen_id": "d3fb646341b2083949d8a934"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù vive afuera de la casa de Ọ̀rúnmìlà y se le comparte afuera. Ọ̀rúnmìlà, Òrìṣà-ńlá, Òrìṣà-oko y Ògún aparecen como acreedores en el relato de la deuda. Ṣàngó es el amigo de Baáyannì."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cáscaras de nuez de palma, pescado, conejos, palomas y cauríes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 19.1 (yorùbá): Kukute-agbọn Korojiji: / li o difá fOgbè, / Ogbè nlọ soko odẹ. / Wọ̀n niki ó wa ṣebọ / kioma ribi akamọ lohun: / Obúko méta, / akukọ mẹta / ati egbàá méta owó / Ogbè kọ̀ ko ru. / Ó de oko-odẹ tan, Ojo de, / bioti nsure lọ. / O ri iho kan ti o gboro. / O ṣebi iho-igi / tabi okiti kan ni, / O bosinu rẹ, / ko mọ pe Erin liofẹ Ìdí silẹ. / Erin pa Ìdí de mọọ / Bẹẹ ni oun kori ibiri yoo gba jade mọ. / Àwọn èniyàn rẹ̀ bẹrẹsii waa, / lẹhin igba-pipẹ ti wọ̀n ko rii, / wọn lọ ṣe ebọ ti oun Kosilẹ. / Erin wa yaa mọ igbẹ. / Njẹ wọ̀n ni: / \"Ogbè ti o ti Ìdí bọ, / ki a maa pee ni Ogbèdi\". / \"i ribi akamo: ver o vivir el mal de verse rodeado, cercado, sitiado.", "Verso 19.2 (yorùbá): Ogbèdikaka, / Ogbèdilele: / a dífá f'Èṣú / nigbi òun f'ara sọfa lọwọ Ọ̀rúnmìlà, / Oriṣà-ńlá, Oriṣà-oko ati Ògún. / Wọ̀n niki Èṣú rúbọ: / Eesan, / ẹyẹlé mẹsàn / ati egbàásan owó, / kiaṣe ewé Ifá fún un / kiobaa le san'gbese. / Èṣú kò rúbọ.", "REZO: OGBE DI KAKA OGBE DI LELE IYA LAMU BOROTITI OLITON OMO ABAN SHARAELA ADIFAFUN UNBATI ORUNMILA.", "SUYERE: OGBE DI KAKA, OGE DI LELE, OGBE DI LELE, OGBE DI KAKA.", "REZO: OGBE DI KAKA OGBE DI LELE OGBE DI ASUSE AFEFE AYERI OTA EYYE IYA LOMI BOROTITI IYA LAMEBERE TITI ADIFAFUN SHENIBUE BA UNLO EGUNGUN LANSHE.", "REZO: OGBE DI KAKA OGBE DI LELE ADIFAFUN BOROTITI IYA LOMI OLI OTORONSHELA WARA ELEBO.", "REZO: OGBE DI KAKA OGBE DI LELE ADA SHASHA OSIKO OBANA ADIFAFUN OSHUN ATI OGGUN TINSHE KOMADIE EYELE MARUN ELEBO.", "REZO: OGBE DI IFA NI ORISHA ADIFAFUN MOKOLU AWO BAROSIA BOROKATON JORO JORO EGGUN NILE LODAFUN ORUNMILA KAFEREFUN ORISHA ELEGBA.", "REZO: ORISHAOKO ABURE NI SHANGO ARO LESE KAN ATI OLOFIN UNLO SHON SHON OGGUN ORISHAOKO AFEFE IKU AROKO UNYEN SHANGO ARA UMBO NI SHANGO TIYA ONI YEMEYA OKU OKO KAFEREFUN OSHUN OMI DUN DUN SHIRI LODAFUN ORUNMILA.", "REZO: OGBE DI KAKA OGBE DI LELE, DEDELA BORU, DEDELA BOYE, DEDELA BORU.", "REZO: OGBE DI KAKA DI ADIFAYOKO BARABANIREGUN ADIFAFUN OSHUN ADIFAFUN OGGUN OBINI OGBE SA YEYE MATERO AFEFE LO SALU OBOLODE AWOLODA LO IKIN.ESTE ES EL REZO PARA DESPERTAR A ORUNMILA.", "SUYERE: OGBE DI KAKA, OGBE DI LELE. OGBE DI LELE OGBE DI KAKA.", "SUYERE: OMO IFA ODARA OMO ORISHAOKO OMO ODARA.", "REZO: OGBE DI KAKA OGBE DI LELE ADIFAYOKE BARABANIREGUN ADIFAFUN OSHUN, ADIFAFUN OGGUN OBINI OGBE SA YEYE MATEO AFEFE LO SALU OBOLODE AWALODA LO IKIN.", "REZO: OGBE DI OZAIN LEDO IBO IGBE AWO OGBE DI KAKA KUKU", "DIGAGA YAYEMUGAGA EYA AWO IYA IGAGAON IKUYA ELE ADAWO OGBE DI KAKA OGBE DI LELE OBORI ATAYE IYA GOBAMIABOROTITI ADIFAFUN ELUTENSHA MILA UOMA ABAN SHORUTAN UNKO WARANLA LODAFUN OSHUN LODAFUN IYA ADIFAFUN ORUNMILA.", "REZO: IFA NI ORISHA ADIFAFUN MOKELU AWO BOROKOTON KUTUN EGGUN NILE LODAFUN ORUNMILA KAFEREFUN ORISHA ELEGBA.", "REZO: ORISHAOKO ABURE NI SHANGO ARE LESE KAN ATI OLUFINA UNLO SHONSHON OGGUN ORISHAOKO AFEFE IKU UNRYN SHANGO ARA UMBO NI SHANGO TIYA TIYA ONI YEMAYA OKU KEFEREFUN OSHUN OMI DUN DUN ASHIRI LODAFUN ORUNMILA.", "SUYERE: OMO IFA ODARA OMO ORISHAOKO OMO ODARA."], "pasajes": [{"titulo": "Rezo 13", "texto_ritual": "OGBE DI OZAIN LEDO IBO IGBE AWO OGBE DI KAKA KUKU\n\nDIGAGA YAYEMUGAGA EYA AWO IYA IGAGAON IKUYA ELE ADAWO OGBE\nDI KAKA OGBE DI LELE OBORI ATAYE IYA GOBAMIABOROTITI\nADIFAFUN ELUTENSHA MILA UOMA ABAN SHORUTAN UNKO WARANLA\nLODAFUN OSHUN LODAFUN IYA ADIFAFUN ORUNMILA.", "origen_id": "2814e6f467abff9d2769b1b1"}]}]$q$::jsonb),
(20,'172f1702be265451a10749d5b51fe679','11507312ce4e6b615cf700447bdc5d96',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìrosùn es la salida para la amenaza de muerte, enfermedad, juicios, pérdidas y esterilidad. La persona parece vivir de problema en problema y solo lo espiritual le devuelve el equilibrio. La fortuna llega de lugares lejanos y se recoge poco a poco."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene varios problemas a la vez y busca recuperar orden y calma.", "Teme una pérdida, una enfermedad o un problema legal (relato de Àbàtí).", "La oportunidad de dinero viene de fuera o exige salir a buscarla (relato de Òdùkèkèèkè en el bosque).", "Pregunta por hijos o por un embarazo (canto de Òsìn Gàgààgà).", "Necesita avanzar poco a poco en lugar de exigir resultados inmediatos.", "Busca el respaldo de sus antepasados para continuar lo que empezó."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ni la muerte, ni la enfermedad, ni los juicios, ni las pérdidas lo vencerán.", "Fortuna que llega de fuera y se lleva a casa.", "Muchos hijos para quien los pide.", "Recuperar el equilibrio con trabajo espiritual."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto basado en soporte ancestral. (Este odu habla de la necesidad de hacer el progreso lento y estable hacia la satisfacción del destino.)", "origen_id": "c409923ab9c8e09a2b794b3d"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Dejar las cosas a medias o descuidarlas.", "Enredarse al cargar la fortuna por no ofrecer.", "Esterilidad cuando no se atiende la ofrenda.", "Apartarse de los principios de Ifá."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la inestabilidad basada en resistencia al soporte ancestral. (Este odu habla de la necesidad de hacer el progreso lento y estable hacia la satisfacción del destino.)", "origen_id": "07ba08d54da26b197a13c0f5"}]}, {"titulo": "Enseñanza principal", "texto": "El descuido atrae todos los males, pero con la ofrenda ninguno vence. Lo que se siembra en cantidad regresa en cantidad."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'Rosù provee la solución a la amenaza de muerte, enfermedad, casos judiciales, pérdidas e infertilidad.", "origen_id": "d37b4b837be6f7820cc052fc"}]}, {"titulo": "Relatos reunidos", "puntos": ["Àbàtí, el descuido. Ifá consultó para Àbàtí, que quiere decir descuido o tarea sin terminar, el hijo mayor de Aramfè, cuando todos los males se le venían encima. El adivino le aseguró que no lo vencería la muerte, ni la enfermedad, ni los juicios, ni las pérdidas, y le marcó un carnero y medicina de Ifá. Él cumplió.", "Òdùkèkèèkè carga la fortuna. Ifá consultó para Òdùkèkèèkè, que iba al bosque a cargar fortunas para llevarlas a su casa. Le pidieron ofrecer para que no se le complicara el camino de regreso. Ofreció, llevó todo lo bueno a su casa y cantó: '¿Quién trae la buena fortuna a mi casa? ¡Òdùkèkèèkè!'.", "Òsìn Gàgààgà y los muchos hijos. Los adivinos de las campanas Agogo y Àjìjà consultaron para Òsìn Gàgààgà, que deseaba hijos. Ofreció en abundancia y tuvo hijos en abundancia: 'Ofrecí en cantidad y di prueba de cantidad'."], "pasajes": [{"titulo": "Verso 20.1", "texto": "Ọ̀nàgbonrangondon-nti-lfẹ-wa:\nadivinó Ifá para el incumplimiento (descuido),\nel hijo primogénito de Aramfè\nquien se estaba enfrentando a todos los males.\nEl adivino le aseguró:\n\"la muerte (Ikú) no lo derrotará\"\n\"la enfermedad (Àrun) no lo derrotará\",\n\"los casos judiciales (ẹjó) no lo derrotarán\",\n\"las pérdidas (Ofo) no lo derrotarán\",\nle fue aconsejado sacrificar:\nun carnero y medicina de Ifá.\nEl obedeció y ejecutó el sacrificio.", "comentario": "62 Àbăti: incumplimiento, fallo, fracaso, descuido, una tarea sin terminar.", "origen_id": "69429e9b48356939fe9aac7a"}, {"titulo": "Versos complementarios 1", "texto": "Solo la acción espiritual puede restaurar el balance.\nLa fortuna llega de lugares extranjeros, se le deberá\nsacrificar a Odù con muchas babosas y huevos de\ngallina. La persona deberá comportarse dentro de\nlos principios ifistas. Ifá ve a una mujer estéril que\ndeberá ofrendar con 16 huevos para tener hijos.\n\n           Ogbè dáwò, òsùn telè\n          Ó ró jinngínni jinngínni\n           A dífá fún Òdùkèkèèkè\n     Èyí ti ń re inú ìgbé rèé kájé wálé\n       Òdùkèkèèkè ní ń re inú ìgbé\n               Wón ní kó rúbợ\n              Kó le baà kóre dé\n                  Ó bá rúbợ\n                Ayé bá yé Odù\n                 Ó kóre wálé\n            N ní wá ń jó ní wá ń yò\n            Ní ń yin àwón babaláwo\n           Àwón babaláwo ń yin Ifá\n     Ó ní bèé làwón babaláwo tòún wí\n           Ogbè dáwò, òsùn telè\n          Ó ró jinngínni jinngínni\n           A dífá fún Òdùkèkèèkè\n     Èyí ti ń re inú ìgbé rèé kájé wálé\n      Kín ní ń kórée bò wáá bá mi....\n                Òdùkèkèèkè!\n\nOgbè dáwò, òsùn telè\nÓ ró jinngínni jinngínni\nAdivinó Ifá para Òdùkèkèèkè\nQue venía al bosque a cargar las fortunas a su casa\nY se le pidió sacrificar, para que no se complicara\nllevando sus fortunas a casa. El sacrificó y la vida le\nfue placentera, pudiendo llevar las buenas cosas a\ncasa.\nEl bailó y se regocijó y alabó los babaláwo y ellos\nalabaron a Ifá\nOgbè dáwò, òsùn telè\nÓ ró jinngínni jinngínni\nAdivinó Ifá para Òdùkèkèèkè\n\nQue venía al bosque a cargar las fortunas a su casa\n¿Qué está trayendo buenas fortunas a mi casa?\n¡Òdùkèkèèkè!\nIfá dice que está trayendo buena fortuna a mi casa\n¡Òdùkèkèèkè!\n\n                  Òkan pó!\n    Babaláwo Agogo lo dífá fún Agogo\n          Eyì gbòngàn gbòngàn\n      Babaláwo Àjìjà lo dífá fún Àjìjà\n                Mo ru wẹẹrẹ\n                Ó dà wẹẹrẹ\n         A dífá fún Òsìn Gàgààgà\n         Eyì ti ó kómo dà sì àtàrí\n      Wón ní kó rúbợ kó le baà bimợ\n        Òsìn Gàgààgà ngbébo ńbè\n                   Ó rúbợ\n                Mo ru wẹẹrẹ\n                Ó dà wẹẹrẹ\n     Òsìn Gàgààgà ló bímợ báwònyì?\n                Mo ru wẹẹrẹ\n                Ó dà wẹẹrẹ\n\nÒkan pó!\nAdivino de la campana Agogo, adivinó Ifá para la\ncampana Agogo\nEyì gbòngàn gbòngàn\nAdivino de la campana Àjìjà, adivinó Ifá para la\ncampana Àjìjà\nYo sacrifiqué en cantidades\nY di muestra eficaz de cantidades\nEs Òsìn Gàgààgà aquel que ha tenido gran cantidad\nde hijos?\nYo sacrifiqué en cantidades\nY di muestra eficaz de cantidades", "origen_id": "a87d6b26f7e0d73d01a5c75e"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe´Rosu provee la solución a la amenaza de muerte,\n                           enfermedad, casos judiciales, pérdidas e infertilidad.\n                WO - El cliente siempre está en algún tipo de problema, sólo la\n                                  acción espiritual puede restablecer su balance.\n\n\n20.1 · Onagbonrangondon-nti-Ife-wa profetizó Ifá para Abati, el hijo\n          de Aranfe quien se estaba enfrentando a todos los malos. Él estaba\n     seguro de que la muerte (Ikú) no lo derrotaría, enfermedad (Arun) no\n         lo derrotaría, casos judiciales (Ejo) no lo derrotarían, pérdidas (Ofo)\n     no lo derrotarían, le fue preguntado un sacrificio 1 carnero y hojas de\n                                       Ifá. El obedeció y ejecutó el sacrificio.", "origen_id": "49f0e94d35a491c3d64c75a9"}, {"titulo": "Relato en inglés 1", "texto": "\"Ogbe sees Camwood;! Camwood sees the priest\" was the one who cast Ifa\nfor Rascal when he was dreaming about his father.\n\n\"I saw my father today; e\n\n“Father of leopard,\n\n“Father of cat,\n\n“Father of panther,”\n\n“Father come from heaven to help me;\n\n“The child’s father does not refuse to help his child,\n“The child’s father.”\n\nIfa says someone has forgotten his father and that if he does not take care\nof his father there will be no one on earth to take care of him. One ram and\nthree shillings six pence is the sacrifice. When this sacrifice has been made,\nthis person should go and sacrifice the ram to his father; but if the father is\nstill alive, he should sacrifice the ram to his father’s head so that the way to\nsuccess may be clear for him. Something of the person concerned will spoil\n\ncompletely if he does not take care of his father, whether he is on earth or in\nheaven.", "comentario": "1. Ogbe and Camwood appear here as names of people. Note the pun on the\nname of the figure, Ogbe-(I)rosun.\n\n2. Amgkigitekun is a title of a feline identified as a panther by informants\nand described as about the size of a dog. Its meaning could not be analyzed, but\nit is also known as a-mg-t(o)-ekun (one:who-know-equal-leopard), meaning “The\none who knows as much as leopard.” Note that all the animals mentioned are\nfelines.", "origen_id": "fe8e5227afea691739d69c0b"}, {"titulo": "Relato en inglés 2", "texto": "“Pebbles have tiny eyes”! was the one who cast Ifa for Ọrunmila when he was\ngoing to take “She is coy when she sees her mother”? as his wife. Ifa says this is\na wife of Ifa;? if she is not given to Ifa, she will die. And then there is a woman\nwho will bear many children if she is able to sacrifice.\n\n“She is coy when she sees her mother will bear.tiny children;\n\n“She is coy when she sees her mother will bear tiny children;\n\n“Qrunmila is the one who took She is coy when she sees her mother\nas his wife;\n\n“She is coy when she sees her mother will bear tiny children.”\n\nThis is a woman who is a wife of Ifa; she will bear children if she is able to\nsacrifice five hens and two shillings six pence. When she has completed the sac-\nrifice, she should begin to rub the house of Ifa;* then things will be easy for her.", "comentario": "1. Informants said that this meant only that they “come in small pieces,”\nbut tara refers to pebbles of laterite (yangi), which has a pitted surface.\n2. This name, carries the meaning that as a girl she turns and shuffles shy-\n\nly, trying to get her mother to do something or to give her something that she\nhas been denied.\n\n3. See n. 5, verse 3-4.\n4. The walls and floor of the room in which the Ifa paraphernalia are kept\n\nare rubbed regularly with dung by the women worshipers of Ifa and those who\ncome to Ifa for children.", "origen_id": "062d12f7f4ec33513383337d"}, {"titulo": "Relato en inglés 3", "texto": "“Vulture’s feathers reach to his thighs; for the rest! he wears trousers” was\nthe one who cast Ifa for Ojugbẹdẹ? on the day that the God of Iron taught him his\nhandicraft. They said he should sacrifice two pigeons and seven pence two oninis.\n\nIfa says that we will find a blessing in the thing for which we cast this figure.\nIfa says that during this year the God of Iron will show us the way to make a prof-\nit. That year Ojugbede planted ochra, and he made a big profit on the ochra.", "comentario": "1. That is, for the rest of his leg, which is not covered with feathers.\n\n2. Ojugbede is the head of the Ifẹ blacksmiths and the God of Iron is their\npatron.", "origen_id": "c1e0da697a25f0e59d6f7d7e"}, {"titulo": "Relato en inglés 4", "texto": "Adepeju leaf, the diviner of “The one who owns velvet”; Okoromu, the diviner\nof the town of Esa; and Itamgj¢, the diviner of Itamgpo were the ones who cast Ifa\nfor “Strong but stupid elder”! who was so poor that he ground cornstarch porridge\nat the river without a calabash. They said, “Why ar® you grinding cornstarch por-\nridge at the river without a calabash?” He said he was suffering because he had\nnobody.”\n\nIfa says he sees the blessing of people and the blessing of wives for the per-\nson who cast this figure. Two hens, ten kola nuts, and nine pence six oninis® is\nthe sacrifice. We will wrap the kola nuts in “hoe” leaves; we will sacrifice one\neach day, at dawn, to his head.", "comentario": "1, An old person who has brawn, but not brains.\n2. That is, because he had no relatives or friends to help him financially,\n\neven in buying a calabash. Not having a calabash or a plate is a euphemism for\npoverty. Cf. n. 4, verse 2-1; and n. 4, verse 18-11.\n\n3. Egberindilogun is a shortened form of Egberindinlogun.", "origen_id": "8c7415a24d7107eca148dd74"}, {"titulo": "Relato en inglés 5", "texto": "“Bald headed one,” the diviner of the Egba;! “ Pointed beard,” the diviner of\nthe town of Esa; and “Too big a tuft of hair? on the head,” the diviner of the town\nof Ijẹbu Ode were the ones who cast Ifa for “Quavering voice,' who was engaged\nto be married.4 They said that “Quavering voice” should sacrifice lest his bride-\nto-be should die and all the work and the difficulties he had been through because\nof her? be lost. One full-grown he-goat, three shillings, the cutlass from his hand,\nand the cloth from his body was the sacrifice. Ifa says this person should make\na sacrifice because of his bride-to-be, that death should not come to her just as\nshe is about to become his wife, and the money he has given as bridewealth be\nlost.\n\nWhen “Quavering voice” heard the sacrifice, he did not make it. Shortly after-\nward his bride-to-be took her calabashes and went to the river to wash them; she\ndid not know that on that very day the Four Hundred Deities and the Egungun® were\n\ncoming to the earth from heaven. When they met her at the river, they began to\ngreet her thus:\n\n“Bride, greetings of the river,”\n\n“Make your breasts quiver, make your breasts quiver;\n\n“Dip me some water with your calabash,\n\n“Make your breasts quiver, make your breasts quiver;\n“With your calabash, with your calabash, ‘gbunrun ngundun,’®\n\n“Make your breasts quiver, make your breasts quiver.”\n\nSo she began to dip water with her calabashes for each one of the Egungun, .\nand the Egungun were drinking the water and swallowing the calabashes with it\nuntil all the calabashes that the girl had brought to the river to wash were gone.\nWhen it became the turn of the chief of the Egungun, whose heads numbered al-\nmost two hundred, he began to say:\n\n“Bride, greetings of the river,\n\n“Make your breasts quiver, make your breasts quiver;\n\n“Dip me some water with your calabash,\n\n“Make your breasts quiver, make your breasts quiver;\n“With your calabash, with your calabash, ‘gbunrun ngundun,’\n“Make your breasts quiver, make your breasts quiver.”\n\nThe girl said that the calabashes were gone; the Egungun answered:\n\n“Dip me some water with your hands,\n\n“Make your breasts quiver, make your breasts quiver;\n“With your hands, with your hands, ‘gbunrun ngundun,”\n\n“Make your breasts quiver, make your breasts quiver.”\n\nAs the girl dipped water for the Egungun with her hands, he swallowed her,\nand the Egungun went on their way. When the girl’s mother at home heard what\nhad happened, she took the sword? from her loom and set out after the\n\nEgungun. When she caught up with them she began to sing:\n\n\"You are the ones who took my chi1d and ate her,\n“And ate her, who ate the child of Ọrangun.\"\n\nEach one that she came to answered:\n\n“We are not the ones who took your child,\n“Who ate the child of Ọrangun.\"\n\nThus she questioned all the Egungun that she came to and killed them one by one,\nuntil she came to their chief. When she met him, she asked him the same ques-\ntion; the chief of the Egungun answered:\n\n\"I am the one who took your child,\n“Who ate the child of Qrangun.”\n\nThey fought and fought until the woman had cut off all the heads of the chief\nEgungun, and he fell to the ground. But when:this.Egungun was cut open, they\nfound that the child was already dead.\n\nIfa says a man should sacrifice that his bride-to-be should not die and the\nmoney that he has spent upon her become a loss, And then we should sacrifice\nfor a girl lest she die during this very year.", "comentario": "1. A Yoruba subgroup.\n\n2. A type of hairdress in which the hair is tied into a tuft or knot. The mes-\nsengers (Ilari) of the chief of the town of Igana, for example, dress their hair in\nthis fashion. kẹ\n\n3. Ololo is the sound that this man made when he tried to talk.\n\n4. After an agreement of marriage has been made, and until the groom has\nfulfilled his obligations to the prospective father-in-law and the bride comes to\nlive with him, the bride is known commonly as iyaw(o)-gna, or junior:wife-(of)-\nroad, indicating that she does not yet live with her husband. In this verse the\nterms gbuntun, wundia ita, and aya a-f¢-s(i)-gna appear, all of which mean the\nsame thing.\n\n5. This refers primarily to the work done by a man for his prospective\nfather-in-law, and his difficulties in raising the bridewealth.\n\n6. The Egungun are a group of deities represented by costumes which com-\npletely conceal the body of the wearer. Often referred to as “masquerades,” some\ntypes of Egungun costumes have masks; others do not, One type of Egungun\n(alagg) is made in honor of a relative who has recently died. (See Bascom, 1944:\n48-59). Like other deities, the Egungun receive sacrifices and they can grant\nchildren. Cf. verse 52-4.\n\n7. The Yoruba have a large number of similar greetings: greetings of the\n\nhouse, greetings of the farm, greetings of work. These mean, I greet you at the\nriver, at home, at the farm, at your work, etc.\n\n8. This represents the sound made when swallowing the water.\n9. The wooden piece used to beat up the weft threads on the vertical looms\non which women weave.\n\n\"\n10. The title of the king of the town of Na, which is about 60 miles north-\neast of Ifẹ.\n\n11. This is reminiscent of many African tales in which a monster is cut\nopen, and the persons he has swallowed are released. While in this case his\nvictim is dead, it is significant that they looked to see. With the tale ending in\nthis way, the prediction of the diviners is fulfilled. e", "origen_id": "758496a114dfe8ec74d573fa"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Àbàtí: un carnero y medicina de Ifá.", "Para la fortuna de fuera: babosas (caracoles) y huevos de gallina a Odù.", "Para una mujer que no ha tenido hijos: dieciséis huevos.", "Òdùkèkèèkè y Òsìn Gàgààgà: ofrenda abundante."], "pasajes": [{"titulo": "Ofrenda en el verso 20.1", "texto": "Ọ̀nàgbonrangondon-nti-lfẹ-wa:\nadivinó Ifá para el incumplimiento (descuido),\nel hijo primogénito de Aramfè\nquien se estaba enfrentando a todos los males.\nEl adivino le aseguró:\n\"la muerte (Ikú) no lo derrotará\"\n\"la enfermedad (Àrun) no lo derrotará\",\n\"los casos judiciales (ẹjó) no lo derrotarán\",\n\"las pérdidas (Ofo) no lo derrotarán\",\nle fue aconsejado sacrificar:\nun carnero y medicina de Ifá.\nEl obedeció y ejecutó el sacrificio.", "origen_id": "2a2e2ca8122f04f5ba2513c4"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Odù reciben la ofrenda. La persona debe vivir conforme a los principios de Ifá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Babosas, huevos de gallina, carnero."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 20.1 (yorùbá): Onàgbonrangọndon-nti-Ife-wa: / li o dífá fÀbàti / tiiṣe aremo Aramfẹ / eniti gbogbo ibi nkoriti. / Wọ̀n ni: / Ikú a gbee ti, / Àrùn a gbee ti, / Ejo a gbee ti, / Ofo a gbee ti. / Wọ̀n niki o rú. / Agbo kan ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: OGBE ROSO UNTELE ASHE EBBO ASHE TO ARIKU BABAWA ORUNMILA AKUALOSIÑA AKUA EBBO RERA ORUNMILA ISOTA OGBE ROSO UNTELE ASHE ATIE DEKU ATIE, ATIE DEYA DEYA ATIE, ATIE AKUKO ATIE, ATIE ADIE ATIE, ATIE ASHE ASHE ADIE.", "SUYERE: OGBE ROSO UNTELE, ATIE KUN ATIE JA ORUNMILA HURUN HURUN MOLE PIN HURUN MOLE PIN HURUN. BOBO BO MI ERAN BOBO BO MI EJE.", "REZO: OGBE ROSO UNTELE ENABORO ADIFAFUN EBBO TINIBELE ELOSO ARUN ABO ELEBO.", "REZO: OGBE ROSO ADIFAFUN OKURIN ODE, OPIPO OBIRIN ORO INDOKO OFIKALE PECULO OPOLOPO OKUNI.", "REZO: OGBE ROSO ADIFAFUN AYAN ASHE LODUN ASHOKO SHOBO AJOGUN LEFA ANAYO ADEDI NILE LODAFUN OLODO.", "REZO: OGBE ROSO MONI OSHA AHEREBO MONI OSHA AHEREBO MONI OSHA ADASHELE.", "REZO: OGBE ROSO KORO AWO OKO ALIA AWO ILE OLOFUN ADIFAFUN AGUNDARE ADIFAFUN SHEKORDA.", "SUYERE: MONI OSHA SESEREBO, MONI OSHA SESEREBO, MONI OLOFUN ORISHA MONI OSHA SESEREBO.", "SUYERE: OGBE ROSO UNTELE, ATIE KUN, ATIE JA, ORUNMILA RURUN RURUN, MOLPIN, RURUN MOLE PIN RURUN. BOBO MI ERAN BOBO BO MI EJE.", "REZO: OGBA ROSO UNTELE ISHIN AWO ORISHOIPKUO OKUN ISHI NI IWIN ORISHA ABANIDIYE AFI YEBA EGOWORO ESAYO OLORUN NI ADIFAFUN ORUNMILA, ADIFAFUN SHANGO, ATI EGGUN.", "REZO: OFA ERI OBA ASHESHE NI ORUN AGBO NAWO OSA OBASHO ERI PERI AWO ODA IYE BU ADIFAFUN OLOFIN TINSHE OKO ABUTUN WO NIGUI OLOLE LEJUN PARUGO KI AYEBE WUNDIA IFA MABA EKUKI GBOGBO ISHE ATI WAHALA ELERI LEYI OBINI NOGBA BO IGUIRIPA DUNKO LEBO ADA LEFE GARUBO KELOPO AYA KOIGBA EDE ODOLOPO KOSI MOPE NOJO MASAN NI AWO IRUN OMOTE ATI AWON EGGUN NITU URUMBO WARIVE IGBA BU OMI OMI OKAN NIMU AWON DIGUN WOYITI EGGUN MOSI OMU OMITI OSI NIBE IBANI POLU TITI", "GBOGBO IGBA OMO BIBIN NIGBA OMO BIRIN OMIFUN EGGUN OBA AGBA BEYIN BORE KAFEREFUN ORUNMILA.", "1ER. SUYERE: OGBATUN OMAKA ODARA INSHE OMU LODE IGBA FIGBA ISHE KOMI ASHE OMOLODE ASHE OMOLODE.", "2DO. SUYERE: (PARA DARLE AGUA A EGGUN). OBA FI OMO ISHE OMI KOBI OSHE OMOLODE ASHE OMOLODE.", "3ER. SUYERE: (PARA DESPEDIR A EGGUN). OYILE IGBE EMO NIJE IJE ORAGUN.", "REZO: OGBE ROSO AFIDI KUE OSORIBENLEKUI OLELE OLELE BABA BIALE OMO OBA LELE OLELE BABA BIALE OMO OBA LALA OLELE OKUA SURE OLELE LAKUA ODA AUN ANIYA BAYAKUNLO SILE ELELE SILE ELELE AUN MAFUFU KETE AUN MALAKUI OROBO.", "REZO: OGBE ROSO, ADIKANKUN, OBININ, OSHISHA UMBO, ALE ODARA, ORUNMILA PELURE, OYA ATI, OSHUN OBIRIN. ODARA LODAFUN OLOFIN."]}]$q$::jsonb),
(21,'6eca2d24acf776ef54f000a405ffc437','9b684da358aa5bced5678b4c5f4281ea',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀wọ́nrín es un gran momento, en los negocios y en lo emocional, para atraer gente. Habla de escoger bien entre varios pretendientes, de buena compañía y de bendiciones que llegan a la persona de muchos lados cuando sabe reunir y alimentar a otros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene que escoger entre opciones de pareja o ver si una unión les conviene a los dos (relato de Koko, Apata y Àkùrò).", "Quiere atraer clientes o fortalecer sus relaciones.", "Hace cosas por otros y nadie se lo agradece (relato de Ṣeşeeşe kò lórí yìn).", "Busca buena compañía y cariño (relato de Ọlọ́fin y Ogbè).", "Se acerca un viaje y puede haber un imprevisto en el camino.", "Algo que parecía mala suerte puede abrirle una salida si actúa con flexibilidad."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Escoger la pareja correcta y tener un matrimonio próspero.", "Atraer clientes, seguidores y afecto.", "Bendiciones de dinero, esposas, hijos, casa y salud.", "Que el mundo entero lo reconozca y alabe."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto. Encuentra caos inesperado. Espera lo inesperado. (Este odu habla de la posibilidad de regresar la mala suerte en buena suerte.)", "origen_id": "323c8654fa5781fb42d07506"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Hacer el bien a otros sin que lo agradezcan.", "Andar por caminos desconocidos que hacen sentir extranjero.", "Escoger pareja sin pensar en el bienestar de los dos."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto es bloqueado por caos inesperado. (Este odu habla de la posibilidad de un accidente serio y la necesidad a ser cauteloso cuando se viaja).", "origen_id": "c753928e3e5b72868a6b5429"}]}, {"titulo": "Enseñanza principal", "texto": "Hay que arreglar bien la propia casa y pisar bien el propio camino. Quien reúne y alimenta a los demás termina rodeado de ellos."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbèwọ́nrín dice que el cliente necesita realizar la elección adecuada entre potenciales esposos o esposas. Los sacrificios asegurarán la elección correcta y un matrimonio próspero.", "origen_id": "aa15cb540dba96f6e34b09dc"}]}, {"titulo": "Relatos reunidos", "puntos": ["Koko escoge esposo. Koko, el tubérculo, iba a casarse con Àpáta, la roca, o con Àkùrọ̀, la tierra de cultivo. Le marcaron cuatro palomas y cuatro telas anudadas, y cumplió. El adivino le dijo que Àkùrọ̀ sería su esposo favorito: si Koko prospera, la tierra de cultivo prospera con ella.", "Ọlọ́fin y la buena compañía. Okiti-bamba-tiipẹkun-opopo consultó para Ọlọ́fin para que Ogbè fuera su buena compañía, alguien que lo entendiera y le diera cariño. Le marcaron tres gallos y tres recipientes de ñame machacado con sopa. Cumplió.", "El hijo de Àgbọnnìrègún que no era reconocido. Ogbè húnlé: la casa propia es la que se arregla, el camino propio es el que se pisa. Un hijo de Àgbọnnìrègún había probado de todo y nadie le agradecía nada. Le dijeron que consiguiera semillas de palma, las cocinara, reuniera a todos los babaláwo que pudiera y preparara mucha comida para comerla con ellos. Lo hizo, y el mundo entero se levantó a alabarlo; sus asuntos marcharon sin fallar. Cantó: 'Cientos son las hojas de eréyìn; rezaré por riqueza, por mis hijos y por todo lo bueno'.", "Kórewátì y el montón de huesos. Kórewátì, también hijo de Àgbọnnìrègún, preguntó si le llegarían bendiciones. Ofreció, y le llegaron riqueza, hijos, esposas, casas y propiedades, tantas que exclamó sorprendido: '¿A mí?'. El canto compara la llegada de bendiciones con los huesos que se van amontonando en el basurero: así se juntan la riqueza, las esposas, los hijos y la salud."], "pasajes": [{"titulo": "Verso 21.1", "texto": "adivinó Ifá para Koko (el tubérculo),\ncuando ella iba a casarse con Apata (la roca),\no casarse con Àkùrò (granja de cultivos).\nA ella se le aconsejó ofrecer un sacrificio:\ncuatro palomas,\ncuatro piezas de telas anudadas.\nElla escuchó el consejo y sacrificó.\nEl adivino dijo:\n\"Akuro será su esposo favorito\".\n\"Si Koko tiene éxito (es saludable),\nAkurọ lo tendrá también\"", "comentario": "Apata: roca solida.\n4 Akùrọ̀: tierra cultivable, prado.", "origen_id": "e8c737eb7980134019a1f66e"}, {"titulo": "Verso 21.2", "texto": "Okiti-bamba-tiipẹkun-opopo:\nadivinó Ifá para Ọlófin.\nSe le aconsejó ofrecer sacrificio\npara que Ogbè le fuera una excelente compañía\n(para que lo entienda, le de afecto y cariño):\ntres gallos,\ntres recipientes de ñame machacado\ny sopa deben ser ofrecidos.\nÉl realizó el sacrificio.", "origen_id": "09d97a2125114db6075082cf"}, {"titulo": "Versos complementarios 1", "texto": "A la persona no le agradecen las acciones realizadas\na favor de otros y deberá ofrecer semillas de aceite\nde palma y varias palomas para ser reconocido\nentre sus seguidores y familiares. Deberá recolectar\nvarios y diferentes tipos de huesos animales y\nponerlos en una cazuela, para así ofrendar para la\nafluencia de buenas cosas que le llegarán del\nexterior.\n\n                 Ogbè húnlé\n               Ilé ẹni làá hún\n               Ònà ẹni làá tò\n   Ònà tàà tợ rí níí şeni sìbálá sìbolo\n      A dífá fún Şeşeeşe kò lórí yìn\n   Èyì tíí sợmợ bíbí inú Àgbợnnìrègún\nGbogbo nnkan lòún ń şe ti wón ò yìn òún\n         Wón wá le yìn òún báyìí?\n     Wón ní ợpợlợpợ ẹyin ni kó tójú\n             Kí wón ó wáá sè é\n            Kó kó àwón Awo jợ\n                 Kó şe oúnjẹ\nBí ón bá tí ń jẹun kí wón ó móợ mú ẹyin\n                   òhún jẹ\n                  Ó bá rúbợ\n              Layé bá ń yin ní\n                Nnkan è dára\n                 Kó bàjé mợ\n            N ní wá ń jó ní wá ń yò\n           Ní ń yin àwón babaláwo\n           Àwón babaláwo ń yin Ifá\n\n     Ó ní bèé làwón babaláwo tòún wí\n                  Ogbè húnlé\n                Ilé ẹni làá hún\n                 Ònà ẹni làá tò\n    Ònà tàà tợ rí níí şeni sìbálá sìbolo\n       A dífá fún Şeşeeşe kò lórí yìn\n    Èyì tíí sợmợ bíbí inú Àgbợnnìrègún\n              N ó lòórí ẹyin Ajé\n               Igba lewé eréyìn\n              N ó lòórí ẹyin Aya\n               Igba lewé eréyìn\n       N ó mợmợ lòórí ẹyin ni tèmi ò\n               Igba lewé eréyìn\n              N ó lòórí ẹyin Ợmợ\n               Igba lewé eréyìn\n       N ó mợmợ lòórí ẹyin ni tèmi ò\n               Igba lewé eréyìn\n     N ó lòórí ẹyin ire gbogbo nilé ayé\n               Igba lewé eréyìn\n       N ó mợmợ lòórí ẹyin ni tèmi ò\n               Igba lewé eréyìn\n\nEs la casa de uno la que de deberá arreglar bien\nEs el sendero de uno el que se debe pisar bien\nEl camino que nunca se ha tomado podrá hacernos\nsentir extranjeros\nLanzaron Ifá para Şeşeeşe kò lórí yìn\nEl hijo de las entrañas de Àgbợnnìrègún\nHe probado todo tipo de suertes y no he sido\nalabado ni exaltado, ¿Cómo podría lograrlo?\nEllos le dijeron que obtuviese semillas de aceite de\npalma y debía cocinarlas\nY que reuniese tantos babaláwo como le fuese\nposible y que preparase también bastante comida.\n\nEllos tomarán junto con los alimentos las semillas de\naceite de palma y las comerán\nEl realizó el sacrificio y el mundo entero se levantó a\nalabarle\nSus asuntos marcharon de forma inmejorable y no\nfracasaban\nEl alabó a sus babaláwo y ellos alabaron a Ifá\nOgbè húnlé\nIlé ẹni làá hún\nÒnà ẹni làá tò\nÒnà tàà tợ rí níí şeni sìbálá sìbolo\nA dífá fún Şeşeeşe kò lórí yìn\nÈyì tíí sợmợ bíbí inú Àgbợnnìrègún\nRezaré por riquezas\nCientos son las hojas de eréyìn\nTendré definitivamente el Orí de mis prédicas\nCientos son las hojas de eréyìn\nRezaré por mis hijos\nCientos son las hojas de eréyìn\nRezaré por las buenas cosas y bendiciones de este\nmundo\nCientos son las hojas de eréyìn\nTendré definitivamente el Orí de mis prédicas\nCientos son las hojas de eréyìn\n\n           Kukuuku léékú léékú\n           Kukuuku léékú léékú\n            A dífá fún Kórewátì\n   Èyì tíí sợmợ bíbí inú Àgbợnnìrègún\n  Wón ní wón le kójú ire gbogbo da òún\n                    báyìí?\n  Wón ni kó rúbợ kó le ríre gbámú láyé\n             Kórewátì bá rúbợ\n      Wón bá kójú ire gbogbo dà á\n            Bí ti ń lájé ní ń láya\n            Ní ń kólé ní ń bímợ\n\n                  Òún náà?\n         Ó ní Kukuuku léékú léékú\n            Kukuuku léékú léékú\n             A dífá fún Kórewátì\n    Èyì tíí sợmợ bíbí inú Àgbợnnìrègún\n    Èwí Adó ń kóre Ajéé bò wáá bá mi\n                   Jànnjàn\n         N làá kégunguún kàkìtàn\n    Èwí Adó ń kóre Ayaá bò wáá bá mi\n                   Jànnjàn\n         N làá kégunguún kàkìtàn\nIfá mợ ń kóre ợmợợ bò wáá bá mi Jànnjàn\n         N làá kégunguún kàkìtàn\n     Gbogbo ire ilé, àlàáfià ire gbogbo\n Ifá ń kó gbogbo è bò wáá bá mi Jànnjàn\n         N làá kégunguún kàkìtàn\n                   Jànnjàn\n\nKukuuku léékú léékú\nKukuuku léékú léékú\n\nLanzó Ifá para Kórewátì\nEl hijo de las entrañas de Àgbợnnìrègún\nQue se preguntaba: ¿Seré favorecido por ellos con\nbuenas bendiciones?\nLe fue pedido sacrificar y así lo hizo\nFue favorecido con muchas buenas bendiciones\nAsí como tenía riquezas, tenía hijos, esposas, casas,\npropiedades, etc.\nSorprendido, exclamó: ¡Yo!\nKukuuku léékú léékú\nKukuuku léékú léékú\nLanzó Ifá para Kórewátì\nEl hijo de las entrañas de Àgbợnnìrègún\n\nEl rey Èwí de Adó, está llegando con múltiples\nbendiciones de riquezas Jànnjàn\nEs la apilación de huesos de un vertedero de\ndesechos\nEl rey Èwí de Adó, está llegando con múltiples\nbendiciones de esposas Jànnjàn\nEs la apilación de huesos de un vertedero de\ndesechos\nIfá está trayéndome la bendición de hijos, Jànnjàn\nEs la apilación de huesos de un vertedero de\ndesechos\nIfá está trayéndome la bendición de casas, salud,\nJànnjàn\nEs la apilación de huesos de un vertedero de\ndesechos", "origen_id": "55169fb8b5d331774167c4da"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbewonri habla de la selección de esposos o esposas\n          potenciales. Los sacrificios asegurarán una elección correcta y una\n                                                           próspera sociedad.\n            WO - Un gran momento para ser aprovechado tanto en negocios\n            como emocionalmente, en la atracción de los clientes para otros.\n\n\n21.1 · Ajaje adivinó Ifá para Koko, cuando ella estaba contemplando\n             casarse con Apata o con Akoro. A ella se le aconsejó ofrecer un\n          sacrificio. 4 palomas, 4 pedazos de ropa anudadas. Ella escuchó el\n         consejo y sacrificó. Se le dijo que Akoro sería su esposo favorito. Si\n\nKoko tenía éxito, Akoro lo tendría también.\n\n\n21.2 · Okiti-bamba-tiipekun-opopo adivinó Ifá para Olofin. A él se le\n              aconsejó ofrecer un sacrificio para que Ogbe le brinde a él buena\n           compañía. 3 gallos, 3 palanganas de ñame machacado y sopa deben\n                                                                   ser ofrecidos.\n                                                         Él realizó el sacrificio.", "origen_id": "c3137fc9920db9d610a924de"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Koko: cuatro palomas y cuatro telas anudadas.", "Ọlọ́fin: tres gallos y tres recipientes de ñame machacado con sopa.", "Para ser reconocido: semillas de palma cocinadas y comida abundante para los babaláwo, más varias palomas.", "Para que lleguen bienes de fuera: juntar distintos huesos de animales en una cazuela y ofrecerlos."], "pasajes": [{"titulo": "Ofrenda en el verso 21.1", "texto": "adivinó Ifá para Koko (el tubérculo),\ncuando ella iba a casarse con Apata (la roca),\no casarse con Àkùrò (granja de cultivos).\nA ella se le aconsejó ofrecer un sacrificio:\ncuatro palomas,\ncuatro piezas de telas anudadas.\nElla escuchó el consejo y sacrificó.\nEl adivino dijo:\n\"Akuro será su esposo favorito\".\n\"Si Koko tiene éxito (es saludable),\nAkurọ lo tendrá también\"", "origen_id": "de36fa99e6f32a44972768ed"}, {"titulo": "Ofrenda en el verso 21.2", "texto": "Okiti-bamba-tiipẹkun-opopo:\nadivinó Ifá para Ọlófin.\nSe le aconsejó ofrecer sacrificio\npara que Ogbè le fuera una excelente compañía\n(para que lo entienda, le de afecto y cariño):\ntres gallos,\ntres recipientes de ñame machacado\ny sopa deben ser ofrecidos.\nÉl realizó el sacrificio.", "origen_id": "8a72d8587d6d6888aa8fbc17"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá y los babaláwo reunidos reciben la comida. Àgbọnnìrègún es el padre de los consultantes de dos relatos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Koko (tubérculo), semillas de palma, ñame machacado, hojas de eréyìn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 21.1 (yorùbá): Ajaje: / li o dífá fún Koko / nigbi Koko nlọ ṣe obirin Apata, / nlọ ṣe obirin Àkùrọ̀. / Wọ̀n niki ki ó rú: / Eyẹlé mẹrin / ati aṣo onikoko mẹrin. / Ó gbọ̀ ó rú. / Wọ̀n ni: Akuro ni'le Koko. / Bi orí ba san Koko o san Akurọ. / Ajaje:", "Verso 21.2 (yorùbá): Okiti-bamba-tiipẹkun-opopo: / li o difá fOlófin. / A niki o wa rúbo / ki Ogbè le ye oriwiwọn lọdọ rẹ. / Akuko mẹta, / arabà lyán mọ̀ta / ati obọ ni pbọ. / Ô gbọ̀ ô rú.", "REZO: OGBE WALW ADIFAFUN ADIE YARAKO UNBOWA SILE EÑI ADIE, EKUEKUEYE NI OMO KEKERE ADIRE OROMODIO FUN FUN ARERE LAWA ADIE ERE TASHE ADIE. ADIE WIWO NI OKU LERI ADIFAFUN OGBE WALE KETE WALERI ADIFAIA NI ASIWERE LODAFUN ELEGBA.", "SUYERE: ALA OLE OMO MAYO, MADE ISERE NI MAYO.", "REZO: OGBE WALE OGBE WANIKU OGBE WALE KETO WALE WA NILE ONI BABALAWO ADIFAKOKO KANFUN ORUNMILA OBARABANIREGUN ORUNBO GBOGBO TENUYEN ADIE MEYI, AIKORDIE, EKO, EYA, EPO, AWADO, OPOLOPO OWO.", "REZO: OGBE WALE ITE ADIFAFUN AGUTAN ADIE LEBO, AIKORDIE LEBO GBOGBO YEKU, OBETA OWO, EKU, EYA, OPO, AWADO, EYA TUTU FIFESHU, ORUNMILA LORUGBO.", "REZO: OGBE WANIMU OWUNKO KARIRA ABIMIKU ABERIN OUNKO OKO IFA MORA IFA RAKANSE EMU AJUAN IDI LUARO KOTOWO ADIFAFUN EKUTE.", "REZO: OGBE WANIMU AGO EÑI IBOBORU KO OKUNI PAWO AYAWALA OTO AYAMAWALA OSI MOKUNLE MOKUNLE WALE KETO WALE TO OUN BELONA OTO ETA. ALA OLE OMO MAYE ISERE MI MAYE. AKERE KENKON GBOGBO NISHE OLEDE ATANIGBE ATAMIDA FEKO GBOGBO KOGBO.", "REZO: OGBE WALE KOTOWALE EKINI ENJE AYA OFO ISESHENI ARUN INU AWO ADOFA LOBO KAFEREFUN ORUNMILA LODAFUN AYA.", "REZO: OGBE WALE AMEGO AMONA OREGUN, ELEDA NI AWO OGBE WALE BABARE NI IFA BABARE NI BURUKU, OFONA ILE OGBE WALE, IBETI LESE IGI, OPARALDO OYALORI AWO. KAFEREFUN ORUNMILA LODAFUN IBEYIS.", "REZO: OGBE WALE ELEGBA META, ESHU LAREYE, ALAWANA, EKUTE OKOLEGBANA, AWADO KUKUNDUKUN MARIBO OGU ABITI ABURE MEYI.", "REZO: OGBE WALE AGO ENI IBEBORU KE OKUNI PAWO AYAWALA OTO AYAMAWALA OSI MOKUNLE MOKUNLE WALE KOTOWALE TO UN BELONA TO TO.", "REZO: OGBE WALE IWAKUMA IR IKUNI OMO LODE OSHA AGUANA ORI TOMI AYA IFA UNLE OGBE ILEKUNA ABALIKA OZAIN AGBA BURU OLOKUE BABA OMI TIYA OMO AKEKE OYOKUN OMO OBO IYA IYAO IYA", "OREKUN EYO MEYI OTA SHE OYANLO MOBI OBIA OMO AYAMI ORGUN OMO MIKABAMI TEFA OKOKAN OYO YEGUERE BURE ADIFAFUN KO LOKO IFA BIRE BERE OLONSHE ABANI TEFA ASHOMA DUN DUN AWO ORI OBE OFO BOGANI OSHAWANI IFA LODAFUN OLOFIN.", "SUYERE: ALO ALO OMO MAYE, MADE ISERE NI MAYO.", "SUYERE: ARERE KE KEN BOBONISHE, OLODO ATANIBO ATIMIDA FOKE GBOGBO KO GBO.", "REZO: ELEGBA META, ESHU LAROYE, ALAGWANA, EKUTE, OKELAGBANA AWADO, KUKUNDUKUN ISHUGARA MANIGBE OGU ABITI ABURE MEYI, LODAFUN ORUNMILA.", "REZO: OGBE WARINU, OWUNKO KO RI BA ABIMEKU, AYA, ABERIN, OWUNKO SHE INFANORA INFARAKAN SA EMU, AJUU. IDI LARO YOTOGUO, ADIFAFUN EKUTE.", "REZO: OGBE WALE KETE KETE WENDE GBOGBO FEREKUN KOKO ATEFA IBIGAN LOLOEMI NERE LODAFUN OSHANLA OPOLOPO OWO BURAKATA AGOGO FUN FUN, KAFEREFUN ELEGBA, OSHUN.", "REZO: ADIFAFUN OBATALA ONA SUARE OGBE WALE INLE INLE EYITE AKEKE MARUN OMOKORIN KEKE IBINU TOKU LERI OMODE OGBE WALE INLE, MARUN OMO. IKA ATAPAKO, IFA BELA OBA ARUN ASHO MONGBE OMO DINRIN LODAFUN AMONA ORE.", "REZO: ADIFAFUN ADIE YORAKE UMBO WASILE EÑI ADIE KUEKUEYE NI OMO KEKERE ADIRE ORODIE FUN FUN KO MO ARARE ADIE ORE TASHE ADIE WIWE NI OKU ORO LERI ADIFAFUN OGBE WALE KOTO ADIFAFUN ADIE NI ASIWERO LODAFUN ELEGBA."]}]$q$::jsonb),
(22,'6947a54444cac5e4a2cac2f28b0a5708','b4e1d041d1d222e077a2157c3063c936',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀bàrà habla de enfermedades que vuelven con las estaciones y de una persona que se exige demasiado en el trabajo. Pide calma, cuidar a la pareja —porque por ella llegan las bendiciones— y vigilar a una amistad cercana que puede volverse peligrosa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se exige demasiado en el trabajo y necesita descansar o avanzar de forma más sostenible.", "Tiene molestias que vuelven cada temporada (relato de las aves en la sequía).", "Busca paz mental y apoyo en su pareja, y no debe tratarla con mezquindad.", "Una amistad cercana se volvió peligrosa (relato de Àfòn e Ìtí).", "Desea formar familia (relato de Ebè y el melón Bàrà).", "Teme una pérdida importante (relato de Ọ̀rúnmìlà ante la visita de Ikú).", "Quiere conocerse mejor y cambiar hábitos que le hacen daño."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Librarse de la muerte que viene a buscar a la casa.", "Muchos hijos de una buena unión.", "Un hijo que ayudará a vencer a los enemigos.", "Paz mental."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la transformación misma y al descubrimiento mismo. (Este Odu habla de la necesidad para mejorar la salud para asegurar la satisfacción del destino)", "origen_id": "b3c1d5f2f7bd391eed078363"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedades de temporada, como gripes y alergias; conviene atenderse a tiempo.", "Ser tacaño con la pareja.", "Una amiga o amigo, pequeño de estatura, que se enreda alrededor de uno para hacerle daño.", "Agotarse trabajando."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la decepción misma. (Este Odu habla de la posibilidad de una enfermedad seria para esos que resisten la necesidad para mejorar su salud).", "origen_id": "2c3323732629e5be2e7cc5af"}]}, {"titulo": "Enseñanza principal", "texto": "Quien cuida a su pareja recibe a través de ella. Y la falsa amistad se vence con lo que uno sembró: los hijos de Àfòn la defendieron de quien decía ser su amiga."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'bàrà habla de enfermedades que ocurren según las estaciones del año, como las alergias, gripes, resfriados, etc.", "origen_id": "72a6d231a4d0a11edddf63b7"}]}, {"titulo": "Relatos reunidos", "puntos": ["Las gallinas en la sequía. Ifá consultó para las gallinas y les aconsejó ofrecer diez nueces de kola y 20,000 cauríes para no enfermarse en la temporada seca. Algunas cumplieron y otras no.", "La muerte viene por Ọ̀rúnmìlà. Cuando la muerte venía del cielo a visitar a Ọ̀rúnmìlà, le marcaron una chiva y dieciséis ikin. La chiva se sacrificó a Ifá afuera de la casa para que la muerte no pudiera llevárselo a él ni a los suyos. Ọ̀rúnmìlà cumplió.", "Àfòn y su falsa amiga Ìtí. Àfòn e Ìtí siempre fueron amigas, aunque Ìtí era más bajita. Un día Ìtí mostró su verdadero color: se enredó alrededor de Àfòn y la apretó hasta dejarla en agonía, burlándose de si había ofrecido. Àfòn sí había ofrecido. Sus hijos la desenredaron, tiraron a Ìtí al suelo con fuerza y así su madre venció a la falsa amiga. Ìtí nunca volvió a atacarla.", "El Espinazo y el Melón. Ebè, el espinazo, iba a casarse con Bàrà, el melón. Le dijeron que tendría esposa si ofrecía, pero que no fuera tacaño con ella. Se casó con el melón, y cuando ella empezó a dar hijos tuvo tantos que llenaron todo el suelo."], "pasajes": [{"titulo": "Verso 22.1", "texto": "adivinó Ifá para las aves de gallina (adiyẹ).\nLes fue aconsejado hacer sacrificio\npara evitar las enfermedades que ocurren\ndurante la estación de sequía.\ndiez nueces de kola\ny 20000 cowries serían el sacrificio.\nAlgunos de ellos hicieron el sacrificio, otros no.", "origen_id": "fd69255f1aeddecb7e92daf9"}, {"titulo": "Verso 22.2", "texto": "Ipalẹro-ab'ẹnúmogimogimamo'nilowọ:\nadivinó Ifá para Ọ̀rúnmìlà,\ncuando la muerte venía a visitarlo desde el cielo.\nLe fue aconsejado hacer sacrificio:\nuna chiva y dieciséis ikines de Ifá.\nLa chiva debía ser sacrificada a Ifá afuera\nde modo que la muerte no fuera capaz\nde capturarlo a él, ni a los otros.\nỌ̀rúnmìlà oyó y sacrificó.", "comentario": "65 kawokawo: La muerte.", "origen_id": "de7521d1fc61b9f6d4902243"}, {"titulo": "Versos complementarios 1", "texto": "La persona necesita calma mental, cuidar mucho a\nsu esposa, pues obtendrá bendiciones a través de\nella, no ser miserable con ella y deberá sacrificar\ncon un garrote o estaca de madera. Existe un amigo\n(bajito de estatura) muy cercano del cual se deberá\nestar muy atento, para que detractores no le\ndesvíen del buen camino. Se tendrá un hijo que\nayudará a sobrepasar a los enemigos.\n\n                Òfòkisi Òfòkisi\n                A dífá fún Àfòn\n                 Èyí tìí sòré Ìtí\n             Òré ní Àfòn òún Ìtí\n              Ìtí ò si ga tó Àfòn\n               Wón ń báyéé lợ\n  Ìtí bá ni ó ku bí Àfòn ó ti gbé gíga ẹ lợ\n\n            Ní ń bá ló mó Àfòn\n          Ní ń ló mó bíì kó pa á\n              Èşù ní ìwo Àfòn\n               Şe bóo rúbợ?\n              Àfòn lòún rúbợ!\n    Èşù ní: “Si jàn án ní gbóńgbó ò”\n         Nígbà ti Ìtí bá si ló lóó ló\n           Ợmợ Àfòn a si gbé e\n                A nà á mólè\n      Ợmợ Àfòn bá bá ìyá şégun Ìtí\n          Ìtí ò bá le bá Àfòn mó\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwón babaláwo\n          Àwón babaláwo ń yin Ifá\n   Ó ní bèé làwón babaláwo tòún wí\n               Òfòkisi Òfòkisi\n              A dífá fún Àfòn\n               Èyí tìí sòré Ìtí\n             Ệbợ n wón ní ó şe\n              Àfòn gbébợ ńbè\n                   Ó rúbợ\n   Ìtí kan ó mòmò lórí à á gbàfòón si\nÀfòn ní ń bẹ léyìn to şẹgun gbogboo wón\n\nÒfòkisi Òfòkisi\nLanzó Ifá para Àfòn, la amiga de Ìtí\nSiempre habían sido amigas, aunque Ìtí era más\nbajita que Àfòn\nHasta que un día Ìtí demostró su verdadero color\nElla comenzó a retorcerse delante de Àfòn,\nbuscando apretarla hasta matarle, hasta que Èşù\ndijo: ¿Sacrificaste Àfòn? y ella dijo: ¡Si, respondió\nÀfòn ya en agonía\n\n¿Entonces que esperas para pegarle con tu garrote?\nDijo Èşù\nCuando Ìtí se había enredado alrededor de Àfòn, los\nhijos de esta última, desenredaron las manos y el\ncuerpo de Ìtí de su madre y la lanzaron al suelo con\nfuerza, ayudando así a su madre a vencer a su falsa\namiga\nÌtí nunca sopló contra Àfòn otra vez\nElla y sus hijos alabaron a sus babaláwo, ellos\nalabaron a Ifá\nÒfòkisi Òfòkisi\nLanzó Ifá para Àfòn, la amiga de Ìtí\nSe le dijo de ofrendar y ella escuchó y lo realizó\nNingún bramante llamada Ìtí tendrá cabeza para\nsoportar el garrote de Àfòn\nÀfòn, llega por detrás para vencerlos a todos ellos,\njunto a sus hijos\n\n            Obìnrín sowó Kokoro\n               Ó móko è làhun\n                A dífá fún Ebè\n      Èyí ti ń lợ rèé gbé Bàrà níyàwó\n           Òún lé lóbìnrín báyìí?\n           Ebè bá mééjì kún ẹèta\n              Ó bá roko Aláwo\n            Wón ní “O ó níyàwó”\n               Wón ní kó rúbợ\n        Şùgbón o ò gbợdò sahún o\n             Nígbà ti Ebè ó gbèé\n             Bàrà ló gbé níyàwó\n        Ńgbà ti Bàrà bèrè síí bímợ\n             Ló bá bí ợmợ dàálè\n                 Ợmợ kun ilè\n            Obìnrín sowó Kokoro\n               Ó móko è làhun\n\n                A dífá fún Ebè\n      Èyí ti ń lợ rèé gbé Bàrà níyàwó\n       Taa ló bímợ báwònyí bẹẹrẹ?\n                     Bàrà\n       Bàrà ló bímợ báwònyí bẹẹrẹ\n                     Bàrà\n\nLa mujer obstinadamente curvó sus manos\nElla tenía a su esposo como un ser muy avaro y\ntacaño\nLanzó adivinación para el Espinazo.\nQuien iba a tomar al Melón como esposa\n¿Cómo podría tener una esposa?\nY combinó tres cowríes con dos, llegando a la casa\ndel babaláwo y repitió la pregunta acerca de la\nesposa\nSe le dijo que para obtenerla debía sacrificar y que\nno debía ser miserable ni tacaño\nÉl se casó con el Melón y cuando llegó la etapa de\nproducir hijos, ella parió muchos que llenaron todos\nlos espacios disponibles\nLa mujer obstinadamente curvó sus manos\nElla tenía a su esposo como un ser muy avaro y\ntacaño\nLanzó adivinación para el Espinazo\nQuien iba a tomar al Melón como esposa\n¿Quién ha tenido tantos hijos?..... El Melón", "origen_id": "887c93bf120e317f6ab4ff8f"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe Bara habla de enfermedades tanto como de alergías\n                                                                  estacionales.\n\nWO – El cliente ha estado empujado por sí mismo a un trabajo muy\n                                                                         fuerte.\n\n\n22.1 · Kuomi adivinó Ifá para aves (adiye), había pedido a ellos\n     ofrecer sacrificio para evitar las enfermedades que ocurren durante la\n         estación de sequía. 10 nueces de kola (coco) y 20000 cowrie serían\n          para el sacrificio. Algunos de ellos hicieron el sacrificio, otros no.\n\n\n22.2 · Ipalero-ab´enumogimogimamo´nilowo adivinó Ifá para\n         Orunmila. Cuando la muerte (kawo-kawo) vino a visitarlo desde el\n          cielo. Él había sido advertido para sacrificar 1 chiva, 16 ikines. La\n         cabra sería matada afuera de modo que la muerte no fuera capaz de\n                         capturarlo a él con otros. Orunmila oyó y sacrificó.", "origen_id": "ed3af177a36204d0393b8d3b"}, {"titulo": "Relato en inglés 1", "texto": "“Noise-making is the task of birds, trembling is ghat of invalids;! an invalid\nis the one who knows what witches can do at night; welcome, goodbye”® was the one\nwho cast Ifa for the God of Whiteness* when he was about to trade in the flax mar-\nket* and do just as well as if he were to receive a blessing of money. They said he\nshould sacrifice two rats, two fish, two snails, two tortoises,> two chickens—one a\ncock and the other a hen—and one shilling one pence two oninis. The God of White-\nness made the sacrifice.\n\nIfa says that we are going to do some business or that we want to do some\nwork; we should sacrifice that the Sky God may lead us to money.", "comentario": "1, The reference is to a person shivering with chills and fever.\n\n2, Ma re-wa is a salutation used when a person is going away for a short time.\nIt means “come back soon,” or “until you return,” and should be compared with o-d(i)-\nabọ (it-become- arrival) and e-rin-wa-o (you-walk-come-oh).\n\n3. Orishala, or Orishanla the “big deity,” or Qbatala the “King that has a white\ncloth” heads a pantheon of “white deities” (orisha funfun) associated with snails, shea\nbutter, white beads, white cloths, and other white things (see Chapter XI). Informants\ncould not translate “Qsher¢gbo,” but presumably it is a praise-name of Orishala, be-\ncause in verse 241-3 Orishala Qsh¢regbo states that he was the one who “created\nboth slaves and freeborn” (cf. n. 3, verse 9-1). Epega (n.d.: XII, 2) and Lijadu (1923:\n9) cite verses mentioning Qbatala Qshere-Igbo, and Beyioku (1940; 5) gives Qbatala\nQshere Majigbo in the same verse cited by Lijadu.\n\n4. Qgbg is the name for both European flax and linen and for a local plant\n(Omphalogonus nigritanus) whose fibers are used in making cord.\n\n5. Referred to here by his title, “Miser.”", "origen_id": "d0ea40fd26d1b1bd8afe6613"}, {"titulo": "Relato en inglés 2", "texto": "“Lightning flashes; it touches earth; it touches heaven”! was the one who\ncast Ifa for Feathered Vulture, the diviner of Ilode ward? on the day that he was\ncoming to earth. They said that he would not be disgraced; they said that when\nhe was in disgrace and dying of hunger there would be a disaster.2 They said he\nshould sacrifice one he-goat, one shilling three pence, a pot of palm oil, and the\ncloth from his body. They said that we will hear of the day that Vulture came to\nthe earth, but we will never hear of his death,4 and that on the day when he is dy-\ning of hunger a disaster will occur.\n\nIfa says there is someone; he says he will not allow him to be disgraced. He\nsays that if he should be disgraced, his spiritual double® in heaven will aid him,\n\nand the secret which he has brought from the presence of Sky God will remain\ncovered,", "comentario": "1. This appears to be an adaptation of a Yoruba riddle, “A slender staff\ntouches earth; it touches heaven” [Qpa tere kan-(i)le; o kan-(9)run], the answer\nto which is “Rain.” See Bascom, 1949: 10.\n\n2. One of the five major divisions of the city of If¢.\n3. Since Vulture feeds off the sacrifices that Are made and the animals that\n\ndie, any disaster is to Vulture’s advantage. Cf. verses 241-1, 248-1. It is under-\nstood that Vulture made the sacrifice.\n\n4. Informants explained that the bodies of dead vultures are never found. Cf.\nverse 248-1.\n\n5. The ancestral guardian soul. See also verses 241-1, 241-4, 248-1.", "origen_id": "99504bd85a6da6afd9096bbf"}, {"titulo": "Relato en inglés 3", "texto": "“A hassock has a hard chest”! was the only one who cast Ifa for “The one\nwith endurance arrives” when she was weeping and moaning because she had no\n\nchildren. They said she should sacrifice. They said that if she did not sacrifice,\nshe would bear children; but that lest\n\nher children become enemies, she should sacrifice one black she-goat, the under-\ngarment? from her waist, eleven shillings,’ and three cocks. She sacrificed the\nshe-goat, the undergarment from her waist, and the eleven shillings, but not the\nthree cocks; she said she just wanted to bear children, When she gave birth, she\ngave birth to Horse and Breadfruit.\n\nThe desire for children troubled Horse, and it troubled Breadfruit just as it\nhad their mother. They both consulted the diviners. The diviners named for them\nthe same sacrifice that had been prescribed for their mother, and they offered the\nsame part of it that their mother had sacrificed before them.‘\n\nWhile Horse was pregnant, Breadfruit gave birth to her child. Eshu said,\n“These are the children of ‘The one with endurance arrives’ whose mother was\ntold to make a sacrifice but did not do so.\" He caused a fight between them, and\nwhile they were fighting Horse- trampled on the child of Breadfruit and killed him.\nBreadfruit was very angry. When Horse gave birth to her child, Breadfruit\nbrought water for it, and when Horse's child had drunk the poisoned water, it\ndied.5 Ever since that day Horse and Breadfruit have been enemies.\n\nIfa says this is someone who will bear a child, but she should sacrifice lest\nher children become enemies soon afterwards.", "comentario": "1. Yoruba hassocks are similar to those made by the Hausa; they are thought\nof as sticking out their chests as if they were very brave.\n2, This is the general term for the garments worn by women under their\nclothing; it includes both the tobi of the old women, and the yeri or ilaburu of the\nmaidens.\n\n3. Ejielogun is a shortened form of ejilelogun.\n\n4. They did not sacrifice the three cocks so that their children would not be\nenemies.\n\n5. This refers to the belief that the African Breadfruit (Treculia africana)\nis poisonous to horses. See Dalziel (1937: 286). The®erse thus explains why\nthis is true.", "origen_id": "fc0a34fab85cd8b90bf51508"}, {"titulo": "Relato en inglés 4", "texto": "\"Ogbe Qbara! cast Ifa that the critic? remains; Ifa does all things everywhere”\nwas the one who cast Ifa for Qrunmila when he was going to the shore of the ocean,\nto the middle of the lagoon, at Iwgnran where fish perform tricks on the surface\nof the water. They said he should sacrifice four rats, four fish, some loose beans,\nfour white pigeons, and four shillings six pence.\n\nWe will take some ela (efunlg) leaf. We will grind it with a small piece of\npalm leaf. We will kill one of the pigeons. We will mix its blood with this. We\nwill cut any number of incisions on the head, and rub this mixture into them.\n\nIfa says he sees a blessing for someone from beyond the town wall. He says\nlots of money will come to this person from there. Because while the tree may\nshed its leaves, and the liana may shed its leaves, for the palm tree to shed its\nleaves is very difficult4", "comentario": "1. Note the reference to the name of the figure.\n\n2. One who criticises everything and has contempt for everything.\n\n3, Efunle may refer to one of the many kinds of epiphytic Orchidaceae which\nare known as ela.\n\n4. Note that a piece of a palm leaf is included as one of the ingredients of\nthe medicine that is to be made.", "origen_id": "2b74845b02445e36a9fda196"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Las gallinas: diez nueces de kola y 20,000 cauríes.", "Ọ̀rúnmìlà: una chiva y dieciséis ikin; la chiva se sacrifica a Ifá afuera.", "Àfòn: un garrote o estaca de madera.", "Ebè: ofrenda para la esposa y no ser tacaño con ella."], "pasajes": [{"titulo": "Ofrenda en el verso 22.1", "texto": "adivinó Ifá para las aves de gallina (adiyẹ).\nLes fue aconsejado hacer sacrificio\npara evitar las enfermedades que ocurren\ndurante la estación de sequía.\ndiez nueces de kola\ny 20000 cowries serían el sacrificio.\nAlgunos de ellos hicieron el sacrificio, otros no.", "origen_id": "07f4cd31ec6aeb454ef6a954"}, {"titulo": "Ofrenda en el verso 22.2", "texto": "Ipalẹro-ab'ẹnúmogimogimamo'nilowọ:\nadivinó Ifá para Ọ̀rúnmìlà,\ncuando la muerte venía a visitarlo desde el cielo.\nLe fue aconsejado hacer sacrificio:\nuna chiva y dieciséis ikines de Ifá.\nLa chiva debía ser sacrificada a Ifá afuera\nde modo que la muerte no fuera capaz\nde capturarlo a él, ni a los otros.\nỌ̀rúnmìlà oyó y sacrificó.", "origen_id": "f237bcfe1cef9a78c3a40486"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá protege la casa frente a Ikú, la muerte. Los hijos son la defensa de la madre en el relato de Àfòn."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nueces de kola, ikin (nueces de palma de Ifá), melón (bàrà), garrote de madera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 22.1 (yorùbá): Kuọmi: / a dífá f'Adiye. / A niki wọ̀n wa rúbọ / ki àrùn kan ma baa de / ba wọ̀n nigba oworẹ. / Obi méwà / ati egbáàwa owó li ebọ. / Apakon wọn li ó rúbọ. / Kuọmi:", "Verso 22.2 (yorùbá): Ipalẹro-ab'ẹnúmogimogimamg'nilowọ: / li o difá f'Ọ̀rúnmìlà / nigbi kawokawo óde Orun de. / Wọ̀n niki ó rú: / Ewúrẹ ati Ifá (Ikin) mẹrindilógún. / Pa ewúrẹ fún Ifá ni Ata-nde / ki kawokawo Öde-orun ma baa koo mọ wọn. / Ọ̀rúnmìlà gbọ̀ ó rú.", "REZO: OGBE BARA BI BARA TEREE ADIFAFUN SESE BI ABERE BABA TERERE ADIFAFUN SHANGO BI ABERE BABA TERERE ALORDOFUN OLOFIN BABA YEKU KOLADEE EYO UNLO AGUERE NI ORUNMILA TO IBAN ESHU BI BABA TERE ADIFAFUN OLOFIN.", "SUYERE: ISHONSHON ABE ISHONSHON ABE ODARA KOLORI EYO ISHONSHON ABE", "REZO: OGBE BARA TEMU TEMU PILO ADIFAFUN OLOKUN NI EJE TIOFIN OKUN OJENSHO IRAJON EWE NWENI KI ORUBO KEREUBE YIOBI OMO SHAGBONKI AWO OMOBE MABA MABA ARA SHE OTA NIKI ORUBO, EURE DUN DUN LEBO ASHO ITELERI LEBO AKUKO META LEBO EYILEGUN OWO LEBO KERUN, AKUKO META LEBO OMIKI ENSHABI OMO MOGBATI OMABI OBI SENIN OSIBI AFON.", "REZO: OGBE BARA ORIKOYE AWO AGUARO OMO SHABI OBARALA BALA OGBE BARA ONIKOYE AWO KOKEREY TORI SHEGUA EGGUN BORUN OBA AWO LORUN BABA TOBI SHANGO UN SORO OGBE BARA ORI-KOYE AWO OYORUNLEWA BAGUN IFA OYORUNLEWA OLOFIN KOROÑIRE OYU TISHE ELEGBA ORIYOKE AWO AGBANI SHANGO OBARA-LA BAYABIFA.", "REZO: OGBE BARA ADIFAFUN OBATALA ORIKOSUN ORE OBORISA EYELE ETU ELEGBA OGGUN OSHOSIS EKINI ORISHA FUN FUN BABA KAFEREFUN OLUFON.", "SUYERE: ISHONSHEN ABO ISHONSHEN ABO, ODARA KOLORI EYO ISHONSHEN ABO.", "SUYERE DE EGGUN: MOLERE IKU OBARA BARA MELAYE EGGUN IKU OBA MOLAYE IKU SHANGO MOLAYE EGGUN.", "SUYERE DEL OPARALDO: SARAYEYE EGGUN BOLEKUN LOWA. EGGUN MAWA MORIYEYE BELEKUN OLONA EGGUN IKU SARAYEYE", "SUYERE PARA EBBO MISI Y BAWE LERI: SHOKUIN KUEKUE EWE MOFI YANLAO. SHANGO MOFI YANLAO LORI MOI LANYAO.", "SUYERE: ALAMANA FUNI LALA MOSUKO, ALAMANA FUNI LALA MOSUKO.", "SUYERE: ALAGUANA FUMI LOLA MUSOKO.", "REZO: EYELE ADIFAFUN EYELE LORDAFUN OLOFIN MAFEREFUN ELEGBA KE KONUYA GBOGBO OFO LOKO ISHU.", "REZO: LEKE LEKE LEKEBE AWO AWERE ANILERE BIYE ABRUN MOFUE OYE KUANKUAN LIMIDIO LU ALOMOYE ABERUN FUO EMAWODRUN MAKUO EIYE ABORUN AKODE LODAFUN ORUNMILA APARO ALEBO.", "REZO: BABA TIRIBU ABIRI BABA BALAYA BISHIKO OU ADIFAFUN SESE MERAN EYELE LEBO AYAPA AKUKO LEBO KAFEREFUN SHANGO.", "REZO: OGBE BARA TIELOGAN LEKUN IFASHO BOFO OJUN MIOUN ADIFA-FUN ORUNMILA TIONLE SIAPA OKUN ILAJE ESA MI IWORAN NIBITE EJAGO INSHE GBOGBO LEJU EMI NIWON NIKI ERU LEBO EYA LOBO EYO ERE LOBO EYELE FUN FUN MERIN LOBO MEYOLA OWO LOBO. AYI EMU OWO BA ELA OFUNLO AYIOLE PELU IME OSHO DIE AYIGBA EYELE EKUN AYIOFI SINGBERE OYEKU OYO SIERI. IFA NI ONIRE LEJIN ADIFAFUN ORO OKAN ENIYE LOWO PIPE TIBE BENITO RETOBI IGE BA EWE OKUN OSI WO EWE SHUGBON ATIWO OWO MASHERE.", "REZO: OGBE BARA IKOYO LODAFUN ORIKA MOGAN ODA NILE EGGUN LORUBO AKUKO LEBO BATE AYA ESHU ETA META AKUKO ELEBO OGGUN LORUBO ELEBO ESHU FORUN ORUNMILA UNLO ILE IFE INLE OGGUN LODAFUN ELEGBA.", "REZO: AGBA DIGBO OLEWO LAKU ERU MEDI OSIRIKIKI BAJE KONO KARAN OMO ANABI KOSHEMIBI TANYI KOBO TOKOSO KOLEBO OJUMO KOLA GERI ODUDUWA ALAWANA ENI ETI EGUNGUN ALALA SHENA APA MATA OPE LERI MARIWO ORUNMILA AFURI BI OYE ADABIBARE LODAFUN EGGUN MEYI NI ODARA.", "SUYERE: ALAWANA FUMI LALA MUSOKO.", "SUYERE: EMI OBA OMOLOYUMI EMI OBA OMOLOYUMI AKORIKOBA OMOLOYUMI EMI OBA OMOLOYUMI."]}]$q$::jsonb),
(23,'bc6ec6b6235e800f6e94a5298b0ef80d','7def634f58733efdb73b47591f2e1637',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀kànràn habla de perder lo ganado por hacer las cosas a medias. La persona anda con prisa y necesita ir más despacio. Al mismo tiempo, anuncia logros inesperados: alguien puede llegar a donde nadie imaginaba y una mujer puede dar a luz a un futuro jefe."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se apresuró y dejó algo a medias, y eso pone en riesgo lo que ya tenía.", "Su manera de hacer las cosas ya no funciona; necesita cambiar de método, no solo esforzarse más.", "Busca dinero, pareja o hijos, pero cumplió solo una parte de lo que le pidieron (relato de Ogbè y Otuufe).", "Tiene recursos pero sufre por no tener hijos o por las burlas de otros (relato de Sièjidé).", "Puede lograr algo que nadie esperaba (relato de Lábógundé, que llega a ser Èwí).", "Piensa mudarse o establecerse en otro lugar (relato de Bikibi en el bosque de Ògún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero, pareja e hijos que salen al paso cuando se cumple.", "Lograr algo que nadie esperaba, incluso una posición muy alta.", "Hijos para una mujer que era objeto de burla.", "Un lugar agradable para establecerse."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto lleva a una nueva dirección. (Este Odu habla de la necesidad para cambiar procedimientos, a persona está haciendo las cosas muy difíciles un cambio en el método hace fácil el proceso)", "origen_id": "9b0d1fba25093b852afab8b5"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Ofrecer a medias y luego querer más: lo ganado se pierde y llegan los juicios y las pérdidas.", "La prisa.", "Burlas por no tener hijos.", "Que una mujer de piel clara pierda su buena suerte si no ofrece."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a una falsa dirección. (Este Odu habla de las consecuencias del fracaso a tomar responsabilidad.)", "origen_id": "ae6a6e58cd97221afac19df9"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que se da incompleto se cobra completo. Ogbè quiso recuperar lo que no había ofrecido y se quedó con las heridas; Sièjidé, en cambio, cumplió y recibió el hijo que le negaban."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'Kànrán habla de la posible pérdida de las ganancias previas por fallar en no completar los sacrificios. Las acciones a media y las cosas incompletas acaban siempre trayendo pérdidas.", "origen_id": "c741b245b8302448b123b5f8"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè y las cuatro garras. Ogbè iba a ver a Otuufe y le marcaron cuatro garras y 8,000 cauríes; solo dio tres garras y 6,000 cauríes. El babaláwo le dijo que en el camino real clavara las garras en la tierra una por una. Con la primera brotó un montón de dinero; con la segunda aparecieron mujeres hermosas bailando a su alrededor; con la tercera, muchos niños. Entonces pensó que con la cuarta habría obtenido más, regresó y arrancó la primera garra, que le rasgó la frente. Aparecieron los malos espíritus: juicios, pérdidas y todo tipo de problemas. Desde ese día lo llamaron Ogbè Kànràn, 'Ogbè golpeado por los problemas'.", "Bikibi en el bosque de Ògún. Bikibi iba a establecerse en el bosque de Ògún, y el adivino le dijo que ahí estaría bien. Le marcaron un perro; cumplió.", "Sièjidé, la rica sin hijos. Sièjidé era muy generosa y gastaba en todos, pero no tenía hijos. En una fiesta, mientras repartía dinero bailando, la gente le cantaba burlándose: '¿Dónde están tus hijos? Eres rica pero tienes seco el vientre'. Llorando, fue a ver a Ọ̀rúnmìlà. Los adivinos le prepararon medicina de Ifá y le dijeron que al año, en la misma fecha, sería feliz. En el siguiente festival llegó con su hijo a la espalda, y los que se habían burlado se quedaron callados.", "Lábógundé llega a rey. Lábógundé lloraba porque no le llegaba ninguna bendición. Ofreció sin saber que le tocaba el turno de reinar, y fue coronado Èwí de Adó. Nadie supo nunca cómo llegó a ser rey."], "pasajes": [{"titulo": "Verso 23.1", "texto": "Okitibamba-tii-pẹkun-opopo:\nadivinó Ifá para Ogbè,\ncuando Ogbè fue a ver Otuufe.\nLe fue aconsejado hacer sacrificio:\ncuatro garras (Ṣẹrin) y 8000 cowries.\nÉl solo sacrificó tres garras y 6000 cowries.\nEl Babaláwo le dijo\nque en el camino principal,\nfuera clavando las garras\nen la tierra una cada vez.\nÉl fue al camino principal\ny clavó la primera en la tierra.\nUn montón de dinero salió del hueco,\nel cual él recogió.\nContinúo el camino,\ncuando clavó la segunda garra,\nmuchas mujeres hermosas aparecieron\nbailando alrededor de él,\ncon la tercera uña hizo lo mismo\ny muchos niños aparecieron rodeándole.\nEl dijo entonces:\n\"de haber sacrificado\nlas cuatro uñas de una vez,\nseguro que hubiera obtenido más\".\nÉl volvió hacia atrás y extrajo la primera uña\nla cual le arañó la frente y le provocó heridas.\nLos espiritus malignos aparecieron ante él,\nlos caso judiciales (Ejó), las pérdidas (ofo), etc.\nDesde el día en que Ogbè\ntuvo muchas dificultades,\neste Odù fue llamado\nOgbè Kànràn (Ogbè kan ràn).\n67 Ogbè kan oràn: Ogbè fue afectado (golpeado) por grandes problemas (litigios,\npérdidas, etc.).", "comentario": "8® Serin: Esta palabra se investigó por su importancia como material a sacrificar en este Esè Ifá. Ṣerin no aparece en los diccionarios yoruba consultados. La traducción al inglés de este libro lo hace como: nail, que tiene los siguientes significados: uña, pesuña, garra, clavo, tachón. Para esta traducción significa garra, como las uñas corvas y fuertes de algunas fieras y aves rapaces.", "origen_id": "6e424876d27736ec3b51f197"}, {"titulo": "Verso 23.2", "texto": "Çerindilógún-agbon-koseekodabi-Ifá\nadivinó Ifá para Bikibi,\ncuando estaba yendo a establecerse\nen el bosque de Ogún.\nEl adivino dijo:\n\"ese será un lugar agradable para él\".\nUn perro debió sacrificar.\nBikibi escuchó y realizó el sacrificio.", "origen_id": "e58e041930aedffa92573e88"}, {"titulo": "Versos complementarios 1", "texto": "La persona podrá realizar algo que podría no\nesperarse de ella (él) que podría tener connotación\nmundial. Hay una mujer que parirá un niño que será\n\ncoronado jefe de clan o tribu y originará una familia\ncoronada. Se ofrendará para recibir bendiciones y\nfortunas que no se esperan. Hay una mujer clara\nque deberá ofrendar para no perder su buena\nsuerte.\n\n             Orí níí şe wón báyìí\n               Awo Ògúnníkin\n                 Àsòwòò jèrè\n            Ó dà bí alàí mợjàá na\n              A dífá fún Sièjidé\nSièjidé tí ón ní ó sẹbợ ợlà kó si sẹbợ ợmợ\n            Sièjidé ni ó rí ợmợ bí\n               Şùgbón ó yawó\n                 A móợ náwó\n       Ńgbòó yá, wón bá ń sèninì ẹ\n         Ní ón jẹ tán ni ón mu tán\n       Ní ón bá bó si gbangba ìşèrè\n              Sièjidé bá bóójó\n             Wón ń da owó bò ó\n              Wón lómợợ rẹ dà\n                 Ợmợợ rè dà\n         Sièjidé ợmợợ rè dà lágbo\n    Sièjidé bá búẹkún lòòdò Òrúnmìlà\nÀwón Orí níí şe wón báyìí Awo Ògúnníkin\n   Àwón Àsòwòò jèrè bí alàí mợjàá na\n          Wón bá sefá fún Sièjidé\n           Wón ni bó bá di èèmìín\n            Wón ni ínúù rẹó dùn\n   Wón níwợợ wón lẹé jợ şehun to dáa\n             Ńgbà ó dợdun kejì\n                 Bódún ti pé\n                Ợmợ ló pợn lợ\n              Oşù tí ón wí òhún\n\n                  Kò mú u jẹ\n                 Ló bá bímợ\n      Wón dágbo ìşèrè bíì tàtèyìnwá\n        Àwón ti ón şìrègún è léşìín\n               Ojú bá ń ti wón\n           Sièjidé bá ń jó ní bá ń yò\n            Èşù ní: “Ệ dárin fún un\n       Bẹẹ şe dárin fún un lójó kìínní\n                 Ệ dárin fún un\n       Ệ sá lómợ è dà lágbo lójó kìínní\n         Ệ tún dá a béèè tí dá lérò yìí\n         Wón bá lórí níí şe wón báyìí\n             Orí níí şe wón báyìí\n               Awo Ògúnníkin\n                 Àsòwòò jèrè\n            Ó dà bí alàí mợjàá na\n              A dífá fún Sièjidé\nSièjidé tí ón ní ó sẹbợ ợlà kó si sẹbợ ợmợ\n               Ợmợợ rẹ rèé o\n                   Sièjidé o\n             Ợmợợ rẹ rèé lágbo\n                 O lówó lówó\n            O wáá rómợ pòn wá\n       Sièjidé o. Ợmợợ rẹ rèé lágbo\n\nOrí níí şe wón báyìí\nEl babaláwo de Ògúnníkin\nLa práctica comercial improductiva\nEs como uno que no sabe negociar\nLanzó adivinación para Sièjidé\nA quien se le pidió ofrendar por riquezas e hijos\nElla no tenía hijos, pero era muy generosa y gastaba\nbastante en las personas\n\nSucedió que algunas personas, comenzaron a\nmofarse de ella, a causa de ser estéril. En una\ncelebración, un día ellos se fueron al estado\ndanzario y ella repartió dinero y útiles caseros,\nmientras bailaba, pero la canción, le insultaba:\n¿Dónde están tus hijos……eres rica, pero no pares\nhijos?\n¿Sièjidé, estás seca del vientre…..dónde están tus\nhijos?\nY llorando fuertes lágrimas se fue a encontrar con\nÒrúnmìlà\nEl sacerdote Orí níí şe wón báyìí\n Awo de Ògúnníkin\nY el sacerdote Àsòwòò jèrè\nBabaláwo de Ó dà bí alàí mợjàá na,\nPrepararon una poción de Ifá para ella y le\npredijeron:\n¡El próximo año, a esta misma fecha, serás muy\nfeliz!\nEllos y tú compartirán algo muy bueno, concluyeron\nlos babaláwo\nLa próxima temporada, al llegar el festival anual,\nella cargaba su hijo a sus espaldas. La predicción\nfue exacta y ella lucía su esbeltez de madre\nY aquellos que se mofaron de ella quedaron\nestupefactos y remordidos en si mismos, al verla tan\nfeliz\nElla bailó y se regocijó y alabó a sus babaláwo, ellos\nalabaron a Ifá\nOrí níí şe wón báyìí\nEl babaláwo de Ògúnníkin\nLa práctica comercial improductiva\nEs como uno que no sabe negociar\nLanzó adivinación para Sièjidé\nA quien se le pidió ofrendar por riquezas e hijos\n¡Aquí está tu hijo, Sièjidé!\n¡Eres rica y en fase, eres también madre, Sièjidé!\n\n    Akókóró èlùbó níí sodó gbànkoko\n                  gbànkoko\n            A dífá fún Lábógundé\n   Níjó ti ń fomi ojú şògbérè ire gbogbo\n                Wón ní ó rúbợ\n                  Ó ba rúbợ\n          Àşé Lábógundé lợbá kàn\n          Àşé Lábógundé ní ó joyè\n        Lábógundé ba jợba Èwí lÁdó\n              Àwón èèyàn ò mò\n            Pé Lábógundé lè jợba\n             N ní wá ń jó ní wá ń yò\n            Ní ń yin àwón babaláwo\n            Àwón babaláwo ń yin Ifá\n     Ó ní bèé làwón babaláwo tòún wí\n    Akókóró èlùbó níí sodó gbànkoko\n                  gbànkoko\n            A dífá fún Lábógundé\n     Tí wón ó mùú jợba lóde Èwí lÁdó\n               Ệnikan ò gbòn o\n                 Ệnikan ò mò\n       A ò mò pé Lábógundé lè jợba\n    Àşé Lábógundé ní ó jợba Èwí lado\n               Ệnikan ò gbòn o\n                 Ệnikan ò mò\n\nAkókóró èlùbó níí sodó gbànkoko\nAdivinó Ifá para Lábógundé\nCuando lloraba por la carencia de buenas\nbendiciones\nSe le pidió sacrificar y así lo hizo, sin saber que era\nsu turno para convertirse en rey\n\nAhora sabemos que fue Lábógundé quien fue\ncoronado rey y fue Èwí de la ciudad de Ádó\nLas personas nunca supieron de qué manera se\nconvirtió él en rey\nÉl bailó y se regocijó y alabó a sus babaláwo y ellos\nalabaron a Ifá\nAkókóró èlùbó níí sodó gbànkoko gbànkoko\nAdivinó Ifá para Lábógundé\nCuando lloraba por la carencia de buenas\nbendiciones\nAhora sabemos que fue Lábógundé quien fue\ncoronado rey y fue Èwí de la ciudad de Ádó\nLas personas nunca supieron de qué manera se\nconvirtió él en rey\nNadie fue lo bastante sabio para saberlo\nLas personas nunca supieron de qué manera se\nconvirtió él en rey\nNadie fue lo bastante sabio para saberlo", "origen_id": "644f3b6093840c193a435f37"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe´Kanran habla de una pérdida posible de previas ganancias\n     por la falla de no completar los sacrificios. Medias acciones siempren\n                                                      terminarán en pérdidas.\n                WO – El cliente está muy apurado, él o ella necesitan ir más\n                                                 despacio y con más cuidado.\n\n\n23.1 · Okitibamba-tii-pekun-opopo adivinó Ifá para Ogbe cuando\n           Ogbe fue a ver Otufe. Él habló de sacrificar 4 uñas (serin) y 8000\n      cowrie. Él sacrificó sólo 3 uñas y 6000 cowrie. El Babalawo le dijo a\n          él que en el camino principal, él debía comenzar a enterrar las uñas\n                                                      en la tierra una por vez.\n              Él fue al camino principal y tiró una uña dentro de la tierra. Un\n\nmontón de dinero salió del hueco, el cual él recogió. Cuando lanzó la\n                segunda uña, muchas hermosas mujeres aparecieron bailando\n             alrededor de él, con la tercera uña hizo lo mismo y muchos niños\n      aparecieron rodeándole. El dijo entonces, ya de haber sacrificados las\n                        4 uñas de una vez, seguro que hubiera obtenido más.\n      Él volvió hacia atrás y extrajo la primera uña la cual le arañó la frente\n             y le provocó heridas. Los espíritus malignos aparecieron ante él.\n               Desde el día que Ogbe tuvo muchas dificultades, este Odu fue\n                                                       llamado Ogbe Kanran.\n\n\n23.2 · Eerindilogun-agbon-koseekodabi-Ifá adivinó Ifá para Bikibi,\n       quien fue a establecerse en los terrenos de Ogún. Él le dijo que aquel\n             lugar sería muy agradable. 1 perro debió sacrificar. Bikibi oyó el\n                                                  aviso y realizó el sacrificio.", "origen_id": "e3a278dbebd6828d7329a966"}, {"titulo": "Relato en inglés 1", "texto": "Agbgnniregun! says Ogbe should touch? you; I say Ogbe should touch you; he\nsays that when Ogbe stopped at the house of the King of Ara for just a moment, he\nbecame wealthy and began to spend money lavishly® in the streets; he says that\nthat which stops at the house of his apprentice‘ is wealth.\n\nIfa says he sees the blessing of wealth. Two pigeons, two hens, and one shil-\nling plus 20 cowries is the sacrifice. Ifa says wealth is coming.", "comentario": "1. Qrunmila or Ifa.\n2. Note the pun on the name of the figure, Ogbe-(Q)kanran.\n3. The figure of speech used here is “to burst open like a bud.”\n\n4. An apprentice carries his master’s bag and runs errands for him (see\nChapter IX).", "origen_id": "c5d0214750a401334f341595"}, {"titulo": "Relato en inglés 2", "texto": "\"It is not long before the ẹkikun leaf! belongs to the elephant,”? “It is not long\nbefore mud belongs to the buffalo,”* and “It is not long before the street belongs to\nthe girl from the town of Ilaun”* they were the ones who cast Ifa for the people of\nMọrẹ Agbada ward® on the day that something evil was forcing them to heaven®\nagainst their will. They said they should sacrifice a pot of boiled corn and beans,”\na hen, and two shillings six pence. They said each person should cook his own\ncorn and beans.\n\nIfa says something is causing someone a loss, but that the Sky God will put a\nstop to it. Someone should make a sacrifice lest something come from heaven\nand carry him and his family away. A group of people should sacrifice because\nof evil spirits.\n\nOnce upon a time evil spirits were coming from heaven and carrying the peo-\nple of Mọrẹ ward back with them. They consulted the diviners. The diviners said\nthey should sacrifice, and they sacrificed. They took the chickens they had sacri-\nficed and killed them. They cooked them and placed everything on the boiled corn\nand beans in a potsherd. They said they should take the sacrifice into the grove\nof trees that faced their house and which we call the grove of Qlgshe.® When the\nevil spirits arrived at the grove and saw the food, they began to eat it. When they\nhad finished eating it, Eshu told them that the people of Mọrẹ were the ones who\nhad cooked it, and that they should go back to heaven. They replied, “Death does\nnot eat a person's food and then kill him.\"\n\nIfa says we should prepare food for evil spirits. Since that time death has not\n\ntaken the people of Mọrẹ away any more. And every year the people of Mọrẹ\ncook this kind of food and take it to the grove of Qlgshe® Ifa says that this is a\ngroup of people who live together in a compound;” they should sacrifice lest evil\nspirits enter their compound,", "comentario": "1. The leaf of a tall tree, like a palm tree, which is used in weaving atinrin\nmats. li e\n\n2. It is not long after they have appeared before elephants eat them.\n\n3. It is not long before “bushcows” or African buffalos are wallowing in the\nmud.\n\n4. Cf. verses 6-5, 6-6. Because these names are followed by the plural\nawọn it is clear that several diviners are mentioned. [aun could not be identi-\nfied.\n\n5. Mọrẹ is the name of a ward of the town of Ifẹ, one of its five major divi-\nsions. Agbada is a title of that quarter, the meaning of which could not be given\nby informants,\n\n6. That is, causing them to die.\n\n7, A dish of food made of boiled corn or boiled corn and beans.\n\n8. The name of a deity worshiped particularly by the people of Mọrẹ ward in\nIfe.\n9. This verse thus explains why the people of More ward carry boiled corn\nand beans to the grove of Qlgsh¢ during the Coconut Festival (ọdun agbọn).\n10, A compound is known as a “flock of houses” (agbo ile).", "origen_id": "5221b98c2aa9e8ce97b37428"}, {"titulo": "Relato en inglés 3", "texto": "“The water of the forest is like indigo dye;! the water of the grassland is\nlike palm kernel oil;? palm nuts embedded in the path are like the palm nuts of\nIfa, but they do not drink blood like Ifa’s palm nuts” was the one who cast Ifa\nfor “He beats palm nuts and knows the future” when he was going to buy Ẹda?\nas his slave. They said he must serve his Ẹda. He said he would serve it. Ẹda\nis what we call the palm nuts of Ifa. \"He beats palm nuts and knows the future”\nis what we call Qrunmila.\n\nIfa says this is a boy; he is a diviner; he was serving Ifa when he came from\nheaven. The rising or setting sun must not find him in the farm, and his feet\nmust not brush the dew from the farm road.\"\n\nAnd Ifa says we want to buy something. The person in question should not *\nbe deterred from buying it. If there is not enough money, he should add to it.\nThis thing he wants to buy will benefit him. This. is the day he is buying his set\nof palm nuts. °\n\n“Well then, I cannot go to the farm,\n“He beats palm nuts and knows the future;\n\n“Won’t you come and see what Eda is doing for me?®\n“He beats palm nuts and knows the future.\n\n\"I cannot go to the river,\n\n“He beats palm nuts and knows the future;\n\n“Won't you come and see what Ẹda is doing for me?\n“He beats palm nuts and knows the future.\n\n“I cannot go to market,\n\n“He beats palm nuts and knows the future;\n\n“Won’t you come and see what Eda is doing for me?\n“He beats palm nuts and knows the future.\n\n“I cannot go to distant places,\n\n“He beats palm nuts and knows the future;\n\n“Won't you come and see what Eda is doing for me?\n“He beats palm nuts and knows the future.”\n\nIfa says the destiny of someone is to do nothing more than Ifa. He must not\nwork in the farm but inside the town. This person should return to what he had\nbeen doing,” and either divine or recite the verses of Ifa. He should sacrifice\none she-goat and five shillings, no less, and then he should go and sacrifice one\nshe-goat to his own Ifa also.", "comentario": "1. The water which gathers in the forest is colored by the rotting leaves so\nthat it resembles the very dark blue of indigo.\n\n2. The oil (adi or adin) made from the white palm kernels is to be distin-\nguished from the orange palm oil (epo) made from the pericarp. Palm kernel\noil is used in making soap and in rubbing the body after bathing.\n\n3. Palm nuts embedded in the road and the sixteen palm nuts (ikin) used in\ndivining are both polished through use, but only the ones used in divining receive\nthe blood of sacrifices. Cf. verse 247-4,\n\n4. Eda is usually translated as “creature” or “that which has been created,”\nand refers to the ancestral guardian soul. Here, however, it is specifically\nequated with the set of palm nuts used in divining.\n\n5. He is supposed to devote himself to divining, as is spelled out below.\n6. Since Eda here means the palm nuts of Ifa, the request is for people to\ncome and see how he is prospering through divining.\n\n7. It is explained earlier in the verse that he was worshiping Ifa before he\nwas born.", "origen_id": "b45cf31f87d7273653029644"}, {"titulo": "Relato en inglés 4", "texto": "“The open square belongs to foreigners”? was the one who cast Ifa for Cac-\ntus® when she was going to move to the field of Igango because she had no chil-\ndren. They said that one she-goat and five shillings, no less, was the sacrifice.\nThey said that witches would not drink her menstrual blood to keep her from hav-\ning children. Cactus sacrificed one she-goat, five shillings, and Ifa’s leaf.\n\nSmall incisions were made on the body of Cactus and medicine was rubbed\ninto them, The scars of these cuts are the thorns that Cactus has until this very\nday. From that time on, the blood of Cactus cannot be drunk.4\n\nIfa says a woman should sacrifice so that witches will not reach into her\nwomb to destroy the embryo, and so that she will not menstruate every month.)", "comentario": "1. That is, it is public property. The word “foreigner” or “stranger” (elu)\nrefers to Yoruba who are not native to a given town.\n\n2, Euphorbia kamerunica.\n\n3. Cactus was going to leave her compound and build her own house in hopes\nthat she might bear children.\n\n4. This verse explains how cactus came to have thorns,’ why it has so many\nchildren, and why the “blood” or sap (oje) of cactus is bitter, and can be used as\nfish poison, Dalziel reports that it is highly purgative and is used as an ordeal\nand in arrow poison.\n\n5. That is, so that she may conceive,", "origen_id": "0bf949aec0aba172db47e7c9"}, {"titulo": "Relato en inglés 5", "texto": "“It is not long before the river belongs to the ¢kikun leaf,” “It is not long be-\nfore the field belongs to the leopard,” and \"It is not long before the open street\nbelongs to the child from the town of Ilaun”! were the ones who cast Ifa for the\npeople of Mọrẹ Agbada ward where they had cast Ifa because they had no children.\nThey said they would bear children. Ten calabashes of boiled corn and beans, ten\nhens, and five shillings* was the sacrifice.\n\nThey said each of them would have a child. When the year had\n\nrun its course, they all bore children. From that day on they have not missed\neating boiled corn and beans at More ward; they have done it every year The\nnext year they began to dance, and to sing:\n\n“Qsara,* brings us children, oh,\n\n“Hin, hin, hin, hin!®\n\n“I will bear children with the others, oh,\n\n“Hin, hin, hin, hin!\n\n“Greetings of children, you who have children, oh,\n“Hin, hin, hin, hin!”\n\nIfa says a woman is troubled by the desire for children. She should sacri-\nfice ten calabashes of boiled corn and beans, ten hens, and five shillings. If she\nis able to make this sacrifice, by this time next year she will be carrying a child\non her back.)", "comentario": "1. Because these names are so similar to those in verse 6-2, they have also\nbeen interpreted as referring to several individuals. Note that this verse and 6-2\nand 6-6 all have several points of similarity. Aside from the names of the divin-\ners, they all refer to Morg ward and to the worship of Qsara and Ọlọshẹ.\n\n2. Since cowries are counted by the two thousand, there are ten units of cow-\nries required, as there are ten hens and ten calabashes of boiled corn and beans.\n3. This verse, like 6-2, explains why the dish of boiled corn and beans is\nsacrificed every year by the people of Mọrẹ ward.\n\n4. Qsara is a deity who was the husband of Qlọshẹ (see verse 6-2). He is\nidentified with a body of water in Qlgshe’s grove, opposite Mgre ward along the\nIlesha road in Ifẹ.\n\n5. These sounds have no meaning, but are added to the song simply to make\nit “sound sweet.”\n\n6. Note the pun on “carry on back” (pọn) and “be red” (pọn).", "origen_id": "fea9344abd99ac753517331d"}, {"titulo": "Relato en inglés 6", "texto": "“It is not long before the river belongs to the ekikun leaf,” “It is not long be-\nfore the field belongs to the leopard,” and “It is not long before the open street\nbelongs to the child from the town of Ilaun”! were the ones who cast Ifa for the\npeople of Mọrẹ Agbada ward where they were dancing the egemgpati? because\nthey had no children. Ifa says someone is not well; he should make a sacrifice\nso that he may be able to eat. Or a babe in arms\n\nis ill and cannot eat anything; we should sacrifice so it will be able to eat. One\nhe-goat, 120 lumps of cornstarch porridge, and three shillings is the sacrifice.\nWhen they had made the sacrifice and carried it out behind the house where\n\nthe child was lying ill, his companions finished eating it and they came back sing-\ning:\n\n“Eat, oh, egemgpati.”\nH\n\nAs his companions finish eating the food, the child who is not well will eat some-\nthing.", "comentario": "1. Cf. n. 1, verse 6-5, and nn. 1 to 3, verse 6-2.\n\n2. A drum rhythm used at the Coconut Festival (ọdun agbọn), which is per-\nformed by the people of More ward in honor of Qsara and Qlgshe.", "origen_id": "b4d088a1f7bb9c4c8e2981d8"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: cuatro garras y 8,000 cauríes (solo dio tres y 6,000).", "Bikibi: un perro.", "Sièjidé: ofrenda por riqueza e hijos y medicina de Ifá.", "Lábógundé: ofrenda por buenas bendiciones."], "pasajes": [{"titulo": "Ofrenda en el verso 23.1", "texto": "Okitibamba-tii-pẹkun-opopo:\nadivinó Ifá para Ogbè,\ncuando Ogbè fue a ver Otuufe.\nLe fue aconsejado hacer sacrificio:\ncuatro garras (Ṣẹrin) y 8000 cowries.\nÉl solo sacrificó tres garras y 6000 cowries.\nEl Babaláwo le dijo\nque en el camino principal,\nfuera clavando las garras\nen la tierra una cada vez.\nÉl fue al camino principal\ny clavó la primera en la tierra.\nUn montón de dinero salió del hueco,\nel cual él recogió.\nContinúo el camino,\ncuando clavó la segunda garra,\nmuchas mujeres hermosas aparecieron\nbailando alrededor de él,\ncon la tercera uña hizo lo mismo\ny muchos niños aparecieron rodeándole.\nEl dijo entonces:\n\"de haber sacrificado\nlas cuatro uñas de una vez,\nseguro que hubiera obtenido más\".\nÉl volvió hacia atrás y extrajo la primera uña\nla cual le arañó la frente y le provocó heridas.\nLos espiritus malignos aparecieron ante él,\nlos caso judiciales (Ejó), las pérdidas (ofo), etc.\nDesde el día en que Ogbè\ntuvo muchas dificultades,\neste Odù fue llamado\nOgbè Kànràn (Ogbè kan ràn).\n67 Ogbè kan oràn: Ogbè fue afectado (golpeado) por grandes problemas (litigios,\npérdidas, etc.).", "origen_id": "ebbe429ed48b25d79b857f78"}, {"titulo": "Ofrenda en el verso 23.2", "texto": "Çerindilógún-agbon-koseekodabi-Ifá\nadivinó Ifá para Bikibi,\ncuando estaba yendo a establecerse\nen el bosque de Ogún.\nEl adivino dijo:\n\"ese será un lugar agradable para él\".\nUn perro debió sacrificar.\nBikibi escuchó y realizó el sacrificio.", "origen_id": "9167def6672aa71eeb059513"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà atiende a Sièjidé. Ògún es dueño del bosque donde se establece Bikibi."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Garras, perro, cauríes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 23.1 (yorùbá): Okitibamba-tii-pẹkun-opopo: / li o difa fOgbe, / Ogbè nlọ si Otuufẹ̀. / Wọ̀n niki ó rú: / Ṣẹrin mẹrin ati egbàá mẹrin owó. / Ṣẹrin mẹta ati ẹgbàá méta owó liọrú. / Babaláwo ti sọ fún un pe: / Nigbati o ba tide ojú-orere (ni popo) / niki o ti bẹrẹsiikan ṣerin naa / mọ'le ni okookan titi lọ. / O de ojú-orere, / ó kan ṣerin kan mọ'lẹ, / owó yẹjade sii, o koo. / Ó tun rin siwájú diẹ, / ó kan ekeji mo'lẹ, / Obirin yojade sii. / Ó ko wọn mọ'ra. / O tun ṣi'sẹ siwájú diẹ, / ó kan ṣerin kẹta mọ'lẹ, / Ọmp seyọ sii. / O ko wọn mọ'ra. / O ni: / Ha! ibaṣepe mo ru ṣerin mẹrin pe, / nba ni ohun pupẹ ju àwọn wọnyi lọ. / Ó pada s'ẹhin o lọ hu ṣerin ekini, / ó wa kan an siwájú. / Ejó, ofo ati bẹebeẹ wa yo sii. / Nje ojo li Ogbè kan ràn / ki a maa pee ni Ogbè'Kànràn.", "Verso 23.2 (yorùbá): Eerindilógún-agbon-koseekodabi-Ifá: / a difá fún Bikibi / nhọ mư lẹ̀ nigbo Ogún. / Wọ̀n ni: / \"ilè ibẹ a gbee\" / Aja kan ni ebo. / Bikibi gbọ̀ ọ rú.", "REZO: OGBE KANA LODAFUN OBATALA ATI SHANGO NI MOTI EWEFA OMODE KOBO ORI OUYEN IYARE ATI BABARE. SHANGO IYEDE BIRINIWA MOFA ADA ELEBO.", "SUYERE: OGOMOLOSHE BIRERE IRU LODAFUN MAYAWAL.", "REZO: OGBA KANA LODAFUN OBATALA ODAFUN SHANGO NI MOTI ALAMO-NI ALAKOSI MONI YEUN EGGUN BABARE ORUNMILA LERUGBO.", "REZO: OGBE KIKANA KOMASE ADIFAFUN OGGUN.", "REZO: ERI KIPE DI ERIKIKAN ELUYU KIPE DI ELUYU EKUN ODE IGBANGBA KIPE DI ODE OMODE ILAUN ADIFAFUN OMO.", "REZO: OGBE KANA AWO NI BEBE NI LORUN AWO NI BONI BOSHE ABE- LEKUN LORUN INLE GANGA NI LODE ASAMI LAYE INLE BORELO ENI OTOTOMI ILO NI SHANGO OMO AWO MONI BOSHEOLORUN SHANGO OGBE KANA OLORUN KOLOYE SHANGO ODARA.", "REZO: EKIKUN KIPO DIN EKIKUN ERIN ABATA KIPE DI ABATA EFON ORERE KIPE OMO ILAUN AWEN ADIFAFUN AWO NI MORE AGBADA NI EJITEBON SI ORUN NI OFUN SHUGBON OLORUN", "SUYERE: OGOLOSHE BIRERE IRU LOFUN KAYAWALE.", "SUYERE: KUDU AKOGBA, EKO, LAYE KOTO ONIKO.", "SUYERE: OSARA MA KOME BEO.", "REZO: OGBE KANA AWO NI BOBE NI LORUN AWO NI MONI BOSHE ABE- LEKUN LORUN INLE GANGA NI LODE ASANI LAYE INLE BORELE ENI OTOTOMI TO NI SHANGO OMO AWO MONI BOSHE LORUN SHANGO OGBE KANA OLORUN KOYELE SHANGO ODARA.", "REZO PARA DARLE EL EYA TUTU Y KLA LERI JUNTO CON SHANGO: ZALARA OREO NI IFA AWO MONI BOSHE EBEYENI IFA KORI BO WO AYE ORI LORUN AGBA NI SHANGO AWO MONI BOSHE ARAGBA NI OBANI LORUN ODUA ORUNMILA AWO IFA MOYARE ODARA, IFA SHANGO AGUANI LORUN.", "SUYERE DEL EYE EN LA LERI: “EYE EYENI YERE ARAGBA FELEGUEGUE FELEGUEGUE AGBA OEREO.”", "REZO: ERIN LAFIAKU ORO LEGEN LABAOWO OROLOWUOKO ORO TIOSHEGI ERIN ABIKUNLO OYEKU OLOFIN ERIN PEREBI AJANAKU TINE-LUIKARA ONI MOWA ERIN OKE MOFOYU LABUTA LABUTA BI OLO- WU KUDU AKOGBA OKE ERI SOFOBU LABATA BI OLUWO KUDU AKOGBA OKE ERIN OTOKU AJANAKU KOTO SILE ADE ERIN LARI ERIN KOLARUN ADIFAFUN ERIN OKO LAYE KOTE NIKO LOJOMO ELOJIN GBRO AFI ORI KUNLO FOKO LODAFUN ORUNMILA.", "SUYERE: KUDU AKOGBA EKE, LAYE KOTE ONIKO."]}]$q$::jsonb),
(24,'0cb438b543097f00ab6f5559a0e50d92','06dff7278cdcb54b714a8b03d8a91fa1',$q$[{"titulo": "Idea central", "texto": "Ogbè Ògúndá anuncia un éxito material cercano. Se presenta una oportunidad que a primera vista parece poca cosa y la persona querrá rechazarla: hay que mirarla con calma. También pide no separarse de sus mayores religiosos ni de quien lo inició."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le llega una oportunidad o un regalo que por fuera no convence, pero por dentro vale mucho (relato del paquete de hojas de koko).", "Espera la recompensa de un trabajo anterior y no ve que ya se le abrió el camino.", "Busca riqueza y estabilidad familiar (relato de la gente de Egún Majo).", "Se alejó de quien antes lo ayudaba y desde entonces no le va bien (relato de Àyìnnipinpin y Ẹlẹ́gùdumòró).", "Siente que ayudar le sale caro y no valora lo que gana con eso.", "Desea pareja o hijos.", "Se siente mal recibido o menospreciado al intentar una relación (relato de Ọ̀rúnmìlà en Ìwó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Gran riqueza para quien recibe lo que le llega.", "Esposa y dinero ofreciendo kola a Ifá.", "Bendiciones que regresan a la casa cuando vuelve el babaláwo de siempre.", "Llegada sin aviso de esposas, riqueza, hijos y casas."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto requiere el removimiento de obstáculos. (Este Odu habla de la posibilidad de recibir riqueza de un esfuerzo anterior).", "origen_id": "e5296e42de3bbd9cf8c505c1"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Despreciar un regalo por cómo viene envuelto.", "Cambiar al babaláwo que siempre funcionó por ahorrar.", "Separarse de quien lo inició en Ifá."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Un camino abierto se encuentra con conflicto. (Este Odu habla de los problemas que se puedan desarrollar como resultado de un fracaso al ser generoso.)", "origen_id": "0f996f90fe44ea7ec3017d62"}]}, {"titulo": "Enseñanza principal", "texto": "No se juzga por el envoltorio. Alárá y Ajerò rechazaron lo que su madre mandaba en hojas secas, y Ọràngún, que lo aceptó, se hizo rico vendiéndoles a ellos mismos las cuentas que habían despreciado."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbèyónú habla de un inminente éxito monetario o material.", "origen_id": "72c7e8e0f092d5691b6b423d"}]}, {"titulo": "Relatos reunidos", "puntos": ["La gente de Egún Majo. Kuku-ndukun y Pẹtẹ-inoki consultaron para la gente de Egún Majo y les dijeron que podían llegar a ser muy ricos. Les marcaron cuatro cerdos, 80,000 cauríes y cuatro barriles de vino. Cumplieron.", "Las cuentas envueltas en hojas secas. Los adivinos de Alárá, de Ajerò y de Ọràngún les advirtieron a los tres que iban a recibir algo y que no lo rechazaran. Poco después, la madre de Alárá le mandó un regalo envuelto en hojas secas de koko. Alárá se ofendió y lo rechazó; se lo mandaron a Ajerò, que también lo rechazó; molestos, se lo pasaron a Ọràngún, que lo aceptó. Al desenvolverlo encontró cuentas. Ọràngún hizo su ofrenda —tela de pintas, una paloma y 16,000 cauríes—, ensartó una quinta parte de las cuentas en un collar y se lo mandó a Alárá para que se lo comprara, porque le quedaba bien; Alárá lo compró. Hizo otro con otra quinta parte para Ajerò, y Ajerò también lo compró. Con lo demás se cubrió todo el cuerpo.", "Àyìnnipinpin, el babaláwo de la casa. Àyìnnipinpin era el babaláwo de la casa de Ẹlẹ́gùdumòró. Cada vez que llegaba pedía una botella grande de vino, y con él la casa se llenó de bendiciones. Un día Ẹlẹ́gùdumòró se preguntó por qué tenía que darle tanto vino y llamó a otros sacerdotes, que no le dieron resultado. La gente le dijo: 'Mejor que te pida vino y se resuelvan tus cosas, que no te pida poco y no veas nada'. Volvió a llamar a Àyìnnipinpin, le dio su vino, y la casa se llenó otra vez de bendiciones.", "Ọ̀rúnmìlà y Somúgàgà. Ọ̀rúnmìlà iba a casarse con Somúgàgà. Le dijeron que una rata siempre es pareja de otra rata, un pájaro de otro pájaro y un pez de otro pez. Ofreció dos ratas, dos pájaros y dos peces, compró kola en el mercado y se lo ofreció todo a Ifá. Al poco tiempo, sin aviso, le llegaron esposas, riqueza, hijos y casas. Cantó: 'Somúgàgà, ven a ser esposa de un awo'."], "pasajes": [{"titulo": "Verso 24.1", "texto": "Kuku-ndukun,\nPẹtẹ-inoki:\nadivinaron Ifá para la gente de Egún Majo.\nSe les dijo que ellos podrían ser muy ricos.\nCuatro puercos, 80,000 cowries\ny cuatro barriles de vino deben ser sacrificados.\nEllos escucharon y realizaron el sacrificio.", "origen_id": "96c9d798656e0d6432dacb0b"}, {"titulo": "Verso 24.2", "texto": "Ibinu el adivino de Alárá:\nadivinó Ifá para Alárá.\nEdofufu el adivinó de Ajerò:\nadivinó Ifá para Ajerò.\nPeleturu el adivino de Oràngún:\nadivinó Ifá para ràngún.\nIfá les alertó a todos\nque recibirian alguna cosa\ny que no debian rechazarla.\nPoco tiempo después,\nsu madre le envió a Alárá un regalo\nenvuelto en hojas secas de koko.\nAlárá se sorprendió e irritó (molestó)\nporque su madre le enviara\nuna cosa envuelta\nen hojas secas de koko.\nEl rechazó aceptarlo.\nSu madre envió lo mismo a Ajerò\nquien lo rechazó también.\nLos dos molestos lo tomaron\ny se lo enviaron a Ọràngún quien lo aceptó.\nEl lo desenvolvió y halló cuentas.\nOràngún tenía listo para realizar el sacrificio\nprescrito por su Babalawo.\nỌràngún ofreció:\ntela de pintas (como la guinea).\nuna paloma\ny 16000 cowries.\nOràngún ensartó\nun quinto de las cuentas que recibió\ny envió un collar a Alárá para que lo comprara\nporque sentía que a Alárá le quedaba bien.\nAlárá compró el collar.\nÉl se lo pagó (dio dinero a Oràngún).\nOràngún ensartó\nun segundo quinto de las cuentas\nen otro collar y se lo envió a Ajerò\npara que lo comprara.\nAjerò compró el collar.\nÉl pagó a Ọ̀ràngún por su collar.\nComo Ọràngún\nenvolvió las cosas elegantemente\nfue capaz de vender los collares.\nỌ̀ràngún se quedó con las cuentas restantes\npara cubrir todo su cuerpo.", "origen_id": "f4dc019149b7a0865903e5c8"}, {"titulo": "Versos complementarios 1", "texto": "Aquí no se deberá separar de sus líderes religiosos y\nmenos de quien le inició en Ifá. Deberá reunir a\nvarios babaláwo y festejarles con vino y alimentos.\nSe le sacrifica a Ifá nuez de kolá, para la bendición\nde esposa y dinero.\n\n               A ro gbódo léfòó\n              Èrò wèsì ni tebòlò\n            Ara ò níí ni ni kákááká\n            Kó níí ni ni kukuunkun\n         Ká mó leè dá kàkà dífá ẹni\n            A dífá fún Àyìnnipinpin\n        Tíí sawo ilé Ệlẹgùdumòró tán\n                    Tí ón jẹ\n\n                Tí ón mu tán\n          Ệlẹgùdumòró bá ń lájé\n                  Ó ń bímợ\n          Bó bá tún dé ńjợ miiin\n        A tún ni lágàńgà ợti ńkó?\n   Gbogbo ire ti Ệlẹgùdumòró ń wá\n               Gbogbo è ló rí\n              Ńgbà ó dijó kan\n Ệlẹgùdumòró bá ní: “Gbogbo igbà n\n      leléyìí ó móoó bèèree ợti ní”\nYóó şe á móợ bèèree ợti ń gbogbo igbà\n Ệlẹgùdumòró bá lòó ké si àwón “Igiri\n                 Ệgbárá igi”\nÓ ní kí wón ó móợ bá òún şe nnkan òun\n            Wón ń şe é fun un\n                Kò rójútùú è\n   Ó tún lợòdò àwón Igiri Ệgbárá igi\n        Ệ wáá bóun şe nnkan òun\n               Wón tún şe é\n                   Kò dáa\nÓ tún lợòdò àwón À jó fórí sòpó òdèdè\n              Wón tún ń şe é\n                   Kó wúlò\nWón ní Àyìnnipinpin rẹ ti ń ba ợ şe é ńjó\n                 kìínní ńkó?\n  Ó ní Lágàńgà ợti níí móoó bèèree!\n Wón ní bó ba bèèrè Lágàńgà ợti ńkó\nŃgbà ti Àyìnnipinpin ń bèèree Lágàńgà\n                     ợti\n   Gbogbo nnkan tí àwón ń bèèree\n                 Àwón ń ri i\n         Àwón táwòón lòó pé yí\n Wón ón bèèree nnkankan lówó àwón\n\n  Şùgbón gbogbo nnkan ti àwón ń wá\n                  Àwón ò ri\n      Ló ba tún ké si Àyìnnipinpin\n                 Bó ti tún dé\n       Lágàńgà ợti ló tún bèèree\n                    Ợti dá?\n                  Ệ gbợti wá\n         Wón bá tún gbợti kalè\nÀyìnnipinpin tún şe Ifá fún Ệlẹgùdumòró\n                Ilé è tún kún\n                   Òún náà\n          Àşé òún ti sợnù lợ ni?\n        Ayé wáá yẹ Ệlẹgùdumòró\n     Ló wáá fa Àyìnnipinpin móra è\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwón babaláwo\n          Àwón babaláwo ń yin Ifá\n   Ó ní bèé làwón babaláwo tòún wí\n              A ro gbódo léfòó\n             Èrò wèsì ni tebòlò\n         Ara ò níí ni ni kákááká\n         Kó níí ni ni kukuunkun\n       Ká mó leè dá kàkà dífá ẹni\n         A dífá fún Àyìnnipinpin\n        Tíí sawo ilé Ệlẹgùdumòró\n       Èyí ti ó bèèree lágàńgà ợti\n         Àwón “Igiri Ệgbárá igi”\n    Òtò lẹni wón ń wo Ifáa wóón fún\n         Àwón “Igiri Ệgbárá igi”\n    Òtò lẹni wón ń wo Ifáa wóón fún\n       Àwón À-jó-fórí-sòpó-òdèdè\n    Òtò lẹni wón ń wo Ifáa wóón fún\n Àyìnnipinpin níí sawo ilé Ệlẹgùdumòró\n\n           Ệ jé n bÓgbèyónú mumi\n                   Ệrú ń mu\n                   Ợsin ń mu\n                 Àyìnnipinpin\n           Ệ jé n bÓgbèyónú mumi\n                 Àyìnnipinpin\n\nA ro gbódo léfòó\nÈrò wèsì ni tebòlò\nUno no se siente tan enfermizo\nPero si está cabizbajo\nY no es capaz de postrarse para lanzar adivinación\nAdivinó para Àyìnnipinpin, sacerdote de la casa de\nỆlẹgùdumòró\nY que al llegar a la casa de Ệlẹgùdumòró, pidió una\ngran botella de vino\nỆlẹgùdumòró se la brindó, después de que le fuese\npreparada su porción de Ifá\nEllos comieron y bebieron juntos\nỆlẹgùdumòró comenzó a tener riquezas, hijos y\nbuenas bendiciones, mientras le brindaba siempre\nbotellas de vino al sacerdote\nPero un día se preguntó, el por qué debía darle\nbotellas de vino al Awo\nY se fue a llamar entonces al sacerdote “Igiri Ệgbárá\nigi”\nPero no le fue beneficioso y llamó a otros como À-jó-\nfórí-sòpó-òdèdè, pero tampoco le fue bien y las\ngentes le decían que donde estaba el Awo de sus\nprimeros éxitos\nEl pide siempre grandes botellas de vino por las\ncosas que yo le pido a Ifá\nEs mejor que pida botellas de vino y que se\nresuelvan los asuntos tuyos y no que te pida otras\n\ncosas menos costosas y que no se vean los\nresultados\nỆlẹgùdumòró volvió a llamar a Àyìnnipinpin\nY cuando él llegó, lo primero que pidió fue una gran\nbotella de vino, que le fue entregada, junto a otras\nmás\nDe nuevo la casa de Ệlẹgùdumòró, se llenó de\nbuenas bendiciones y él dijo\n¡Si! Y bailó y alabó a su babaláwo y el sacerdote\nalabó a Ifá\nA ro gbódo léfòó\nÈrò wèsì ni tebòlò\nUno no se siente tan enfermizo\nPero si está cabizbajo\nY no es capaz de postrarse para lanzar adivinación\nAdivinó para Àyìnnipinpin, sacerdote de la casa de\nỆlẹgùdumòró\nY que al llegar a la casa de Ệlẹgùdumòró, pidió una\ngran botella de vino\nLos sacerdotes Igiri Ệgbárá igi y À-jó-fórí-sòpó-\nòdèdè, practican su sacerdocio para otras personas\nEl sacerdote de la casa de Ệlẹgùdumòró es y será\nÀyìnnipinpin\nDéjenme beber agua con Ogbèyónú\nLos esclavos y sirvientes beben\nDéjenme beber agua con Ogbèyónú\nÀyìnnipinpin\n\n    Wón ń lú bínní bínní lójúdé Ìbínní\n   Wón ń lú pàkùà pàkùà lóde Ìwợnràn\n  Wón ń lú jògbòdò-rúkú-n-jợgbò lójúdé\n                 Ìjợgbò\n         Àwón Ìbààbà òkè Ògún\n           Wón ti kárà mìín dé\n         Wón ń lú gbádágbádá\n     Wón ń lú gbudugbudu lójú omi\n\n          A dífá fún Òrúnmìlà\n   Ifá ń lợ rèé Sợmúgàgà sobìnrín\n      Wón ní kí Òrúnmìlà ó rúbợ\n   Ńgbà ti wón ó móợ kẹbợ fun un\n       Wón ni eku ni saya eku\n      Kí Òrúnmìlà ò fi eku rúbợ\n            Ệyẹ níí saya ẹyẹ\n      Kí Òrúnmìlà ò fi ẹyẹ rúbợ\n            Ệja níí saya ẹja\n      Kí Òrúnmìlà ò fi ẹja rúbợ\n  Òrúnmìlà bá rú eku méjì Olúwéré\n      Ó rú ẹja méjì abiwè gbàdà\n    Ó rú ẹyẹ méjì abèdò lùké lùké\n         Wón ní kó ra obì lójà\n          Kó fi bợ òkè ìpòrí ẹ\n           Òrúnmìlà şe béè\n            Ńgbà ó dèèkan\n               Ajé bá dé\n                 Ayá dé\n           Gbogbo ire bá dé\n      Gbogbo wón bá ń jò mó ợ\nÓ ní wón ń lú bínní bínní lójúdé Ìbínní\n Wón ń lú pàkùà pàkùà lóde Ìwợnràn\nWón ń lú jògbòdò-rúkú-n-jợgbò lójúdé\n                 Ìjợgbò\n        Àwón Ìbààbà òkè Ògún\n          Wón ti kárà mìín dé\n        Wón ń lú gbádágbádá\n   Wón ń lú gbudugbudu lójú omi\n          A dífá fún Òrúnmìlà\n   Ifá ń lợ rèé Sợmúgàgà sobìnrín\n          Sợmúgàgà súré wá\n          Kóo wáá saya Awo\n\n                 Béku bá jí\n              Ệja níí saya ẹja\n            Sợmúgàgà súré wá\n            Kóo wáá saya Awo\n                 Béyẹ bá jí\n              Ệyẹ níí saya ẹyẹ\n            Sợmúgàgà súré wá\n            Kóo wáá saya Awo\n                Béran bá jí\n             Ệran ni saya ẹran\n            Sợmúgàgà súré wá\n            Kóo wáá saya Awo\n             Àtòkèèrè féfééfé\n       Léwé ợkợ ti wáá saya obì lójà\n          Ệ súré wá ẹ wáà fé wa!\n\n    Wón ń lú bínní bínní lójúdé Ìbínní\n   Wón ń lú pàkùà pàkùà lóde Ìwợnràn\n  Wón ń lú jògbòdò-rúkú-n-jợgbò lójúdé\n                 Ìjợgbò\n\nLas tribus Ìbààbà de la parte alta del río Ogun,\nhabían importado otra práctica maravillosa; ellos\nbatían el gbádágbádá\nY batían el gbudugbudu en la superficie del agua\nLanzaron adivinación para Òrúnmìlà\nQue venía a casarse con Somúgàgà\nFue prevenido de ofrendar. Mientras ellos\npreparaban los objetos del sacrificio, le dijeron que\nuna rata siempre sería la esposa de otra rata\nQue un pájaro y un pez siempre serían las esposas\nde otros pájaros y peces\nÒrúnmìlà ofreció 2 ratas, 2 pájaros y 2 peces.\nTambién compró nuez de kolá en el mercado y se lo\n\nofreció todo a Ifá. Hizo según le instruyeron que\nhiciera\nLuego de un corto período de tiempo y sin previo\naviso, las buenas bendiciones llegaron a él. Esposas,\nriquezas, hijos, casas, etc. Llegaron sin límites a su\nhogar\nWón ń lú bínní bínní lójúdé Ìbínní\nWón ń lú pàkùà pàkùà lóde Ìwợnràn\nWón ń lú jògbòdò-rúkú-n-jợgbò lójúdé Ìjợgbò\nLas tribus Ìbààbà de la parte alta del río Ogun,\nhabían importado otra práctica maravillosa; ellos\nbatían el gbádágbádá\nY batían el gbudugbudu en la superficie del agua\nLanzaron adivinación para Òrúnmìlà\nQue venía a casarse con Somúgàgà\nSomúgàgà, ven aquí para que seas la esposa de un\nAwo\nCuando una rata se levanta, siempre será la esposa\nde otra rata\nSomúgàgà, ven aquí para que seas la esposa de un\nAwo\nCuando un pájaro se levanta, siempre será la\nesposa de otro pájaro\nSomúgàgà, ven aquí para que seas la esposa de un\nAwo\nCuando un pez se levanta, siempre será la esposa\nde otro pez\nSomúgàgà, ven aquí para que seas la esposa de un\nAwo\nCuando un animal se levanta, siempre será la\nesposa de otro animal\nSomúgàgà, ven aquí para que seas la esposa de un\nAwo\nDesde muy lejos, las hojas de la planta de Ợkợ\nserán la esposa de la nuez de kolá en el mercado.\nQue corran aquí todas las mujeres para casarnos", "origen_id": "7b7260411f8f516ebfedbc0d"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbeyonu habla de un inminente éxito monetario o material.\n        WO – Una oportunidad de negocios se le presentará por sí misma. Al\n                 principio el cliente desechará esto, como si no valiera la pena.\n     Consideraciones serias de las oportunidades lo llevarán a grandes éxitos.\n\n\n24.1 · Kuku-ndukun, Pete-inoki fueron quienes adivinaron Ifá para el\n              pueblo de Egun majo. Fue profetizado que ellos podrían ser muy\n\nricos. 4 puercos, 80,000 cowrie y 4 barriles de vino deben ser\n                    sacrificados. Ellos escucharon y realizaron el sacrificio.\n\n\n24.2 · Ibinu, el adivino de Alara profetizó Ifá para Alara. Edofufu, el\n           adivino de Ajero profetizó Ifá para Ajero. Peleturu, el adivino de\n    Orangun, profetizó Ifá para Orangun. Ifá alertó que alguna cosa sería\n    enviada a ellos y que ellos no debían rechazarla. Después de un corto\n         tiempo, sus madres le enviaron a Alara un regalo envuelto en hojas\n     secas de koko. Alara estaba molesto y extrañado de cómo su madre\n     podría enviarle a él alguna cosa envuelta en hojas secas de koko. El\n           rechazó aceptarlo. Sus madres enviaron lo mismo a Ajero y él lo\n          rechazó también. Ya molestos ellos lo tomaron y se lo enviaron a\n    Orangun quien lo aceptó. Él lo desenvolvió y halló cuentas. Orangun\n             tenía listo para realizar el sacrificio prescrito por su Babalawo\n    Orangun ofreció: tela de pintas (como la guinea), 1 paloma y 16000\n   cowries. Orangun ensartó 5 de las cuentas y le envió un collar a Alara\n             porque él sintió que era a Alara a quien le quedaba bien. Alara\n                                    compró el collar de Orangun. Orangun\n\n\n24.3 · ensartó otro collar y se lo envio a Ajero quien también le pagó\n          a Orangun por el collar. Orangun fue capaz de vender los collares\n             porque los envolvió elegantemente. Orangun se quedó con las\n                                            cuentas restantes para sí mismo.", "origen_id": "34d9aff1e315f6eef874cd51"}, {"titulo": "Relato en inglés 1", "texto": "Hero, child of the king; Unassuming,’ child of the king. Hero was fighting\nwith Unassuming, and he pulled off his penis. Afterward when they made Hero\nking, he chased Unassuming to the farm. When he drove him away, he sent a\nwoman with a constricted vagina? to him. They both lived in the forest, working\nand eating in the farm.\n\nOne day the God of Whiteness was going from Iranje of the house to Iranje®\nof the farm, and he was hungry. As he walked along, he heard these two talking\nwhere they were getting ready to pound yams. The God of Whiteness clapped his\nhands 'popo.? When they looked behind them and saw the God of Whiteness, they\nkept their mouths closed until they had finished pounding the yams. In this way\nthe God of Whiteness had ‘speechless yams” to eat.\n\nWhen they had finished pounding the yams, they gave them to the God of\nWhiteness and he ate until he was satisfied. When he had eaten his fill, he asked\nthem what they were doing in the middle of the forest. Unassuming explained\nthat when they were fighting, his younger brother had pulled off his penis and had\ndriven him to the forest and had sent him this woman with the constricted vagina.\n\nThe God of Whiteness told them that he was going away, but that they should each\nfind a snail and keep it until he returned.\n\nWhen the God of Whiteness came back, he took one of the snails. He told the\nman to take off his clothes and spread his legs. When the man had done this, the”\nGod of Whiteness said “Ha!” to the snail. It came out of its shell, and he threw it\nagainst the man’s groin. Then he did the same for the woman, and her snail stuck\nto her groin. He told them to go and sleep together as they had done before.\n\nWhen night fell and they were asleep, the snail from the man’s groin fastened\nitself against the woman’s snail, which had opened its mouth, and it entered the\nwoman's belly. Soon afterward the woman’s belly began to swell; she became\npregnant. The people who saw these two came and told the king that this woman\nwas pregnant, but he contradicted them, saying it could not be so. When she gave\nbirth to her child, they came and told him again, but he would not believe them.\nWhen she became pregnant for a second time, they again came to tell him. He\nreplied that if he should ever see this happen, they should drag him from the\nthrone® upon which he was sitting and cut off his head. The townspeople sent\nword to this woman and to Unassuming to come. When they arrived, the whole\ntown assembled and sat down before the king. When Hero, the king, saw this wom-\nan get up to go to urinate, he saw that she was pregnant; he got up, too, and tried\nto run into the house. But the people\n\nof his town pulled him to the ground and cut off his head.\n\n“What we hear is the sound of people doing things loudly;”\n\n“We do not hear the sound of people who do things quietly;\n\n“We drag the one who does things loudly to Unassuming’s door;®\n\n“Qrunmila says he does things quietly when he gives someone his destiny.\"?\n\nIfa says we must not fight. A man should sacrifice so that his relatives will\nnot injure him during a fight. And someone’s penis is setting his dates for him,”\nand he is troubled because he has no children. He should sacrifice to a deity so\nthat the deity may give hima child. The sacrifice is a full-grown he-goat and a\ncock (for a man); and a she-goat and eight shillings” (for a woman).", "comentario": "1. Awurg is an abbreviation of Awuretete, which appears later in the verse.\nIt means a man who goes about his work quietly without making a fuss and with-\nout boasting about what he is doing, but who nevertheless does his work surely\nand well. Others may call him a lazy man, a fool, or ‘a farmer,’ but he is really\nthe wisest and most competent of them all.\n\nNote that the form of this verse is unusual in that it starts directly by nam-\ning the characters of the tale. There is no dialogue with Qrunmila, and no citing\nof a precedent divination. e\n\n2. A woman described as being able to urinate, but not to have sexual inter-\ncourse, possibly because of excessive scar tissue forming after clitoridectomy.\n\n3. The meaning of Iranje could not be explained by informants, but it is\nnamed in another verse as the place Qbatala Qshere-Igbo came from (Epega, n.d.:\nXII, 2). Although identified only as Orisha, it is to be understood that this deity\nis Orishala or Qbatala, the God of Whiteness, who fashions the human form with-\nin the mother’s womb by opening the eyes, mouth, nose, and ears, and by separat-\ning the arms, legs, toes, and fingers much as a woodcarver does when making a\nfigurine. He is also credited with fashioning the first humans, male and female,\nin a similar manner, Albinos, hunchbacks, cripples, children with six toes or\nsix fingers, and individuals with other deformities are sacred to him. Cf. Chap-\nter XI and n. 3, verse 5-1. Snails and one of his tabus are mentioned in this\nverse,\n\n4. Popo is the sound made when the hands are clapped.\n\n5. It is a tabu for Orishala to eat yams which have not been prepared in\nsilence.\n6. A raised platform of mud, or dais, upon which a chief or a king sits. The\nraised mud sleeping platforms are the same in construction, and are known by\nthe same name.\n7. The word “gbi” was said to mean the sound of someone doing something.\n\n8. To have him pronounce judgment on his offense. The meaning of this,\nlike that of a proverb, is extended far beyond the literal meaning of the words\nthemselves. The implication is that the unassuming man may be committing the\nsame offense as the man whose case he is called upon to judge; but that since he\ndoes it quietly without boasting and publicity, others do not know about it and do\nnot attempt to interfere,\n\n9. That is, a person may receive aid from Qrunmila without even knowing\nwhat has happened,\n\n10. He cannot have sexual relations regularly. Cf. verse 20-2.\n\n11. Erindilogun is a shortened form of grindinlogun.", "origen_id": "086d5913ce90c8490e54a43f"}, {"titulo": "Relato en inglés 2", "texto": "“Yam; petenleki;! two pence four oninis worth of corn; 800 kernels of corn”\nwas the one who cast Ifa for Oluogodo, the child of “Ekunlempe? who chased the\nforeigner into the Niger River,” child of “He uses the other end of his spear as a\nwalking stick ‘mgraganniganni’”> They said he should come and make a sacrifice.\nThey said his body was not healing; they said it would heal during that year. The\nsacrifice was six cocks and three shillings; Oluogodo made the sacrifice.\n\n“Oluogodo did arrive, child of Ekunlempe, oh,\n\n“Wood breaks ‘gba,’* his body is healing.”\n\nIfa says someone’s body will heal if he can make a sacrifice.", "comentario": "1. Informants suggested that this may be the name or title of a type of yam.\n\n2.. The informant could not explain or identify Oluogodo or Ekunlempe. How-\never, later work with worshipers of Bgrgmun and $gpgna made it clear that Olu\nOgodo means “Lord of Yaws” and refers to Bgrgmun, the Goddess of Yaws. Ẹkun-\n1(i)-Empe, meaning “Leopard at Empe” refers to $gpgna, the God of Smallpox,\nwhose town is said to be Empe.\n\n3. Mgraganniganni describes the motion of a person using a walking stick.\n4. Gba is the sound made when wood breaks. This is said to mean that the\nperson will get well as quickly as wood breaks.", "origen_id": "c1c15545d8cfcc36672aa23b"}, {"titulo": "Relato en inglés 3", "texto": "“I go around the world,” the diviner of the Ẹgba, and “I walk and walk and\nwalk along the road until I come to remote Ijgbu,! broad at sword” (were the\nones who cast Ifa for them)? where they were weeping every day because they\ndid not have money. They said they would have money. Four pigeons, lots of\nchalk from Benin, and two shillings was the sacrifice. They made the sacri-\nfice; and they began to have money.\n\nIfa says this person will have lots of money. Money is coming, but he\nshould make a sacrifice.", "comentario": "1, The Ẹgba and Ijẹbu are Yoruba subgroups.\n2. This is omitted from the Yoruba text, and the people are not identified.\nThis would seem to indicate that the verse is incomplete.", "origen_id": "e0be46d5b258307f81963cd2"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Egún Majo: cuatro cerdos, 80,000 cauríes y cuatro barriles de vino.", "Ọràngún: tela de pintas, una paloma y 16,000 cauríes.", "Àyìnnipinpin: botellas grandes de vino para el babaláwo.", "Ọ̀rúnmìlà: dos ratas, dos pájaros, dos peces y nueces de kola a Ifá.", "Festejar a varios babaláwo con vino y comida, y kola a Ifá para esposa y dinero."], "pasajes": [{"titulo": "Ofrenda en el verso 24.1", "texto": "Kuku-ndukun,\nPẹtẹ-inoki:\nadivinaron Ifá para la gente de Egún Majo.\nSe les dijo que ellos podrían ser muy ricos.\nCuatro puercos, 80,000 cowries\ny cuatro barriles de vino deben ser sacrificados.\nEllos escucharon y realizaron el sacrificio.", "origen_id": "9e3a0482e177249a4ce6dadc"}, {"titulo": "Ofrenda en el verso 24.2", "texto": "Ibinu el adivino de Alárá:\nadivinó Ifá para Alárá.\nEdofufu el adivinó de Ajerò:\nadivinó Ifá para Ajerò.\nPeleturu el adivino de Oràngún:\nadivinó Ifá para ràngún.\nIfá les alertó a todos\nque recibirian alguna cosa\ny que no debian rechazarla.\nPoco tiempo después,\nsu madre le envió a Alárá un regalo\nenvuelto en hojas secas de koko.\nAlárá se sorprendió e irritó (molestó)\nporque su madre le enviara\nuna cosa envuelta\nen hojas secas de koko.\nEl rechazó aceptarlo.\nSu madre envió lo mismo a Ajerò\nquien lo rechazó también.\nLos dos molestos lo tomaron\ny se lo enviaron a Ọràngún quien lo aceptó.\nEl lo desenvolvió y halló cuentas.\nOràngún tenía listo para realizar el sacrificio\nprescrito por su Babalawo.\nỌràngún ofreció:\ntela de pintas (como la guinea).\nuna paloma\ny 16000 cowries.\nOràngún ensartó\nun quinto de las cuentas que recibió\ny envió un collar a Alárá para que lo comprara\nporque sentía que a Alárá le quedaba bien.\nAlárá compró el collar.\nÉl se lo pagó (dio dinero a Oràngún).\nOràngún ensartó\nun segundo quinto de las cuentas\nen otro collar y se lo envió a Ajerò\npara que lo comprara.\nAjerò compró el collar.\nÉl pagó a Ọ̀ràngún por su collar.\nComo Ọràngún\nenvolvió las cosas elegantemente\nfue capaz de vender los collares.\nỌ̀ràngún se quedó con las cuentas restantes\npara cubrir todo su cuerpo.", "origen_id": "fe3731d80cd858f529b5c04f"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá recibe la kola. El babaláwo de la casa y quien inició a la persona son vínculos que no se deben cortar. Alárá, Ajerò y Ọràngún son tres reyes yoruba hermanos en el relato de las cuentas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas secas de koko, cuentas, nuez de kola, vino."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 24.1 (yorùbá): Kuku-ndukun, / Pẹtẹ-inoki: / a dífá fún wọn l'Egún Majo. / I wọ̀n a n'ọrọ yeye. / Elẹdẹ mẹrin, okẹ mẹrin owó / ati agba oti mẹrin ni ebọ. / Wọ̀n gbọ̀ wọ̀n rú.", "Verso 24.2 (yorùbá): Ibinu awo Alára: / li o dífá f'Alárá, / Edofufu awo Ajerò: / li o dífá f'Ajerò, / Pẹlẹturu awo Ọ̀ràngún: / li o difá fOràngún, / Ifá I wọ̀n maa fi inkan / kan ransẹ si wọn ki wọ̀n mama kọ ọ. / Ó pẹ diẹ lẹhin eyi, / iya wọn fi eepa koko / (ewé koko tiotigbẹ) / ti a di ranṣẹ si Aláára. / Alárá binu ó ni: / Eepa koko ni iya oun / ri fi ranṣẹ si oun ninu / gbogbo inkan ti o wa l'ayé yi? / O kọọ. / lya wọ̀n si tun fi ranṣẹ si Ajeró. / Ajeró tun kọo. / Ni ibinu wọn muulọ si ọdọ Ọ̀ràngún. / Ọràngún gbaa. Otuu wo. / O ba ilẹkẹ ninu re. / Oràngún sa ti rúbọ / ti Babaláwo rẹ yan fún un. / Ọràngún ti rú: / Aṣo ẹtu, ẹyẹlé / ati egbàájo owó. / Ọràngún sin ikarun kan ninu wọn o / fi ranṣẹ si Alárá pe ki o raa / nitoripe oun rii pe o baa mu. / Alárá raa. O sanwo. / Otun sin ikarun ekeji o / fi ranṣẹ si Ajerò pe ki o raa. / Ajerò raa. O sanwo. / Nitoripe Oràngún fi ohun / didára dii ni wọ̀n ṣe raa. / O si fi àwọn ilẹkẹ iyokun pamg / fún ilo ti ara rẹ̀.", "REZO: OGBE YONO OBOSORBO OBOKONO ADIFAFUN SHONA.", "SUYERE: ATIPONLA IFA BORU, ATIPONLA IFA BORU. IFA OWE, IFA OMA, IFA IRE. ATIPONLA IFA BORU.", "SUYERE: IYO MALERO IYO MALERO AJALA IYO MALERO. (PARA LA SAL). EPO MALERO EPO MALERO AJALA EPO MALERO. (PARA LA MANTECA DE COROJO). ORI NALERO ORI MALERO AJALA ORI MALERO. (PARA LA MANTECA DE CACAO). EFUN MALERO EFUN MALERO AJALA EFUN MALERO. (PARA LA CASCARILLA).", "REZO: OGBE YONO AYE ADE MOWAYE EREÑI LAYE ADIFAFUN ODUDUWA WANEMI OFA OWAYE ODUDUWA IKU SEGUERE, ARUN SEGUERE, OFE SEGUERE,EYE SEGUERE, OGU SEGUERE, EYU ARAYE SEGUERE ELEMU SEGUERE.", "REZO: ADDE YENI MOWA YENI EWE YENI ADOPE MI LADDE OLUWO POPO IRE ARIKU, IRA OMO, IRE OMA, IRE OWO, IRE ASHEGUN OTA.", "REZO: OGBE YONO, EBOMISI OBASALE OBIMISI NI AGBENIYA ADIFA- FUN OTAPOKON UMBATI ORUBO OMODE.", "REZO: OGBE YONO YONO OKUYEYE, OKUKUYERU ADIFAFUN ORUNMILA OBINI.", "REZO: OGBE YONO IFA OLANLA OBA BINI OBALOLO.", "REZO: OGBE YONO KIRIPUEKE AKITIPOKE KUKUTEKU LODAFUN ABUAN ABUAN LORUBE.", "REZO: OGBE YONO PANRERE OFONAMI FONAKITI ADIFAFUN SIEGUIADO EBUESAN KARASHETE.", "SUYERE: SEDEME DE KAE KENEDEME MADO KAE SHEGUERE NIWA KAO BODEME KAE MADO KE.", "SUYERE: YAE YAE MASHE YAE YAE PAE TAKUARA MAYAKUA KERE YAE YAE.", "SUYERE: BONAN SEBERE IKU, IKU SEBERE, ARUN SEBERE, OFO SEBERE.", "SUYERE: SHEBERE OKUN ABO EKUN, SHEBERE OKUN ABO EKUN.", "REZO: OGBE YONO KUKUNDUKU LAYANI LEKE BEBELEKE ILEKE YOSHE OSHA AUN BABALAWO ADIFAFUN YOKAN ONIFA EGUI MAYO OLOWONO AYO ELEGBA GBOGBO YEYE OTONIFA IDA ILU GBOGBO INSHEGUI AGGUN LOYENI AGGUN.", "GBOGBO OSHE ILEKE LABO ABAYEIFA OMOLOYO ILEKE AGGUN OBONLAYA OYU ARINLA BEBE ILEKE IÑAFA FOROLOYU, IÑAFA KOFERU BOYU FURAWA OTONIBOSHE ERE IKUTASHE NARA NARA JUN ADIFAFUN.", "OLUYEBE OBI ORUN AWO OBI INA AWO OLUYEBE LOBI IKU JUN AWO OLUYEBE LOBI ARON JUN AWO OLUYEBE LOBI EYO JUN AWO OLUYEBE LOBI OFO JUN OKOLOYO YEYE ENIFA ILOKE LOYEYE AWO ILEKE, BEBE ORUNMILA ANIFEKUN GBOGBO OSHA WA GBOGBO OSHA ANU ADIFAFUN ORUNMILA.", "LE REZO A EGGUN ASI: INALE EGGUN KUELE, AWO BELELO IÑAFA KUELE ORUN OTONIBOSHE.", "SUYERE: SHEBERE BOKOMO ABE IKU SHEBERE BOKOMO SOKU", "REZO: BITI EBOKO NIYEDI CUCO ADIFAFUN ORISHAOKO OMO OGGUN ADIFAFUN ORILOMORE OMO YO ORUN ADIFAFUN OFUWAPO TINSHOMO ORUNMILA HIJO TIWO LERE OLODUMARE LORE YERIN AWO MEMOTA TODARUKO WONYI OKENIWO NIGRATODOJE KAN NIWORA OHIMO KERE KAWO OLESILE AYE WONIBI AWO BADE LE AYE BOYA IBALOSAN AWO JU ORUN NA LO AGBALAGBA SUJUWO WON NILATIKOKO LOBI ODO AJACA LOTI IKUIN NIBO EWE KANANIE KILATI SA MEBANLO ILE AJACA NIKI OMA LO SARATA BABARI LONA NIKI WON OTOKON SEDA OSALAIYE ODILA AJACA AJAMO TOMON OSEI BIWON BARINDE NIWE BABE IBIKAN, BOTIWO OPOTUNSU RUN OGBE YONO NI WORI NIGBATI AWO BABALAWO ILE ORUNMILA AWO IFA NA OSUN KOMONA SHERENIKUIN KEKE MINIBE OMIBOPI A KOKO AJALA LEMERE KUILE AJACA JIRASI JEN MIMON BABIN KURE LODARE NIBA TI WUN DELE AJACA JIRASI WUN OBANILE AJACA BADUKUE KURO LODARE NIBA TI WUN DELE AJACA JIRASI IWUN OBANILE AJACA BADUKUE LOWO OTUWARE AJACA NI ORI EYENIDA YORE NI ORI TODELEAYE KODARA KUERI.", "REZO: OGBE YONO OBO NILO OSABO OGBE YONO OBO NILO SABE ABONI LARA AGUO FECHE IRE BOBO LERI OMO LARA YIRE AGUO IFA UNLO YEBA YENILARA LAYO BOBO NI YERE OBARA DADA IFA LADE TINCHE ME AGUO NI LARA OGBE YONO OBAKI OBO IFA LAYE NIFA OMO LALA NIFA OGBE YONO IFA NIYA LE ASHEKUN OTA IFA OMO LADE KEFEREFUN ORUNMILA IFA KAFEREFUN OBA TALA KAFEREFUN OGGUN IFA KAFEREFUN SHANGO."]}]$q$::jsonb),
(25,'4c621b637d1c7327b9cea910c78f24ca','3d9e0131a20343b3f0880542c56afc10',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀sá habla de engaños y mentiras de amigos que pueden llevar a pérdidas, y de terminar lo que se empezó. La persona pasa por una etapa áspera, pero si no se rinde triunfa al final. Las bendiciones le pasan cerca sin tocarla mientras no ofrece."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Lo que está haciendo se puso difícil y piensa dejarlo antes de terminar.", "Va a viajar por trabajo y allá puede encontrar con qué prosperar (relato de Ogbè en Alahusa).", "Un amigo o una propuesta le da desconfianza, o parece demasiado buena (relato de Iki y el carnero Agbo).", "Busca recursos fuera de su entorno y debe evaluar bien el viaje.", "Teme perder por confiar sin revisar los hechos.", "El obstáculo principal puede ser una expectativa propia o una decisión apresurada."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Prosperar en un viaje de trabajo.", "Escapar de la trampa de un falso amigo.", "Que las fortunas dejen de esquivarlo y se le junten.", "Salir con vida de una persecución."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la abundancia. (Este Odu habla del viaje para encontrar la buena fortuna y la abundancia).", "origen_id": "3cd463a63ee2d619f1bc32b7"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Un amigo grande y fuerte, como un carnero, que planea su muerte.", "Ser encarcelado o encerrado.", "Que la buena suerte pase a su lado sin tocarlo.", "Rendirse antes de terminar."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la decepción de uno mismo. (Este Odu habla del peligro de la decepción de amigos).", "origen_id": "f26ffbb6f3a311047c6909dd"}]}, {"titulo": "Enseñanza principal", "texto": "No todo juego de un amigo es inocente. Iki sobrevivió porque ofreció y cantó lo que le enseñaron; el carnero, que lo engañó, terminó ofrecido en su lugar."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbèsá habla del engaño y mentiras de los amigos que pueden llevar al cliente a las pérdidas, y de la necesidad de finalizar de cualquier forma lo que se ha comenzado.", "origen_id": "7c64a27afceb1f30352dc57b"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè en Alahusa. Lekeleke, el adivino de Ogbè, le dijo que prosperaría mucho en su viaje de adivinación a Alahusa. Le marcaron dieciséis palomas y 32,000 cauríes. Cumplió.", "Iki y el carnero. Los adivinos de la Tierra, del Cielo y del borde de la Tierra le advirtieron a Iki que se cuidara de un amigo grande como un carnero, que planeaba traicionarlo. Le marcaron una jícara con muchas nueces de kola, pulseras de hierro, 22,000 cauríes y un cuenco grande de madera con tapa. Cumplió. Un día el carnero visitó a Ọlọ́fin, vio limpio el lugar de Egúngún y supo que lo habían adorado con kola; se rió y prometió traerle a Iki como ofrenda. Fue con Iki y le habló de un juego que, según él, jugaban con su padre: turnarse para cargarse el uno al otro cuarenta pasos dentro del cuenco tapado. Cuando le tocó a Iki estar adentro, el carnero no lo bajó y siguió caminando. Iki cantó lo que el babaláwo le había enseñado: 'Adivinos de la tierra, del cielo y de abajo, el carnero me lleva a Ọlọ́fin para sacrificarme; vengan a sacar a Iki del cuenco'. Al llegar, el carnero sacudió el cuenco, oyó las pulseras de hierro y creyó que Iki seguía dentro. En el patio de Ọlọ́fin lo abrieron y estaba vacío. Ọlọ́fin sentenció que, por tramposo, el carnero sería el sacrificado a Egúngún. Desde entonces a Egúngún se le da carnero.", "Ifánírègún y las fortunas que se cruzan. Ifánírègún había andado mucho sin encontrar fortuna. Le pidieron ofrecer para encontrarse con ella; cumplió, y pronto le llegaron riqueza, esposas e hijos. Cantó: 'Que no me esquive la fortuna; las fortunas que se cruzan conmigo las voy a juntar'.", "El venado que ladró. Àgbọ̀nrín gàgàlà, hijo de Olúugbó, supo que sus enemigos querían atraparlo. Le dijeron que ofreciera ẹ̀kuru a la Tierra y lo hizo. Lo persiguieron largo tiempo y nunca pudieron agarrarlo; al final el venado ladró, y dijeron que una vez que había ladrado, el día de su muerte había cambiado. Salió con vida frente al cazador y frente al leopardo."], "pasajes": [{"titulo": "Verso 25.1", "texto": "Lekeleke el adivino de Ogbè:\nadivinó Ifá para Ogbè,\ncuando iba en un viaje de adivinación a Alahusa.\nEl adivino dijo:\n\"Ogbè progresará abundantemente allí\".\nPor tanto él debe sacrificar:\ndieciséis palomas y 32000 cowries.\nÉl escuchó el consejo y efectuó el sacrificio.", "origen_id": "b8ca654ab9d6919cc33f5623"}, {"titulo": "Verso 25.2", "texto": "Afefelegelẹgẹ el adivino de la Tierra,\nẸfufulẹlẹ el adivino del Cielo,\nKukuteku el adivino del límite de la Tierra:\nadivinaron Ifá para Iki,\nEllos le aconsejaron:\n\"Iki tiene que cuidarse de un amigo\ntan enorme como el carnero (Agbo)\".\nLe fue aconsejado hacer sacrificio\npara evitar que su amigo lo traicionara\ny preparara su muerte.\nRecipiente con bastantes nueces de kola,\npulseras de hierro, 22000 cowries\ny un cuenco grande de madera con tapa eran las ofrendas.\nIki hizo el sacrificio.", "comentario": "Un día, el carnero fue a visitar a Ọlófin y observó que el lugar sagrado Egungun estaba limpio. Él le preguntó a Olófin que había usado en su adoración del Egungun. Ọlófin le respondió que había utilizado nueces de kola como sacrificio. El carnero se rió y dijo que aunque eso estaba bien, él le traería a Iki para un sacrificio, Ọlófin le dio las gracias.\nUn día el carnero fue a visitar a Iki. El carnero le preguntó a Iki, si su padre alguna vez le había hablado acerca de un juego que él y el carnero solían jugar juntos. Iki deseó conocer qué juego era. El carnero le dijo a Iki que el juego consistía en turnarse llevando el uno al otro por 40 pies, mientras uno estaba escondido dentro del cuenco de madera. Iki dijo que su padre nunca le había hablado del juego, pero que éste sonaba divertido.\nEl carnero puso el cuenco de madera en el suelo y se metió dentro. Le pidió a Iki tapar el cuenco y transportarlo 40 pies, después que lki caminó 40 pies, el carnero dijo que era su turno. El carnero entonces transportó a Iki por 40 pies y lo puso en el suelo y entonces le tocó su turno dentro del cuenco. Era el turno de estar Iki dentro del cuenco, el carnero lo transportó por 40 pies, pero cuando Iki le pidió que lo bajara, el carnero lo ignoró y continuó caminando, Iki le suplicó pero el carnero se hizo el sordo para no oírlo. Iki comenzó a cantar la canción que el Babaláwo le había enseñado cuando él hizo su sacrificio.\nAfẹfẹlegelẹgẹ adivino de la tierra Efufulelẹ adivino del cielo Kukuteku adivino de bajo tierra El carnero me está llevando a Ọlófin para sacrificarme Yo no sabía que el carnero estaba jugando el juego de la muerte conmigo Afẹfẹlẹgelegẹ adivino de la tierra Efufulelẹ adivino del cielo Vengan y liberen a Iki del cuenco.\nDespués de un rato, el carnero agitó el cuenco de madera y escuchó los brazaletes de hierro moviéndose y pensó que Iki estaba dentro del cuenco. Cuando llegó a donde Ọlófin, le fue ofrecida la ayuda pero la rechazó y dijo para pasar al patio interior. Cuando estaban en el patio, ayudaron al carnero con el cuenco. Al abrirlo, se dieron cuenta de que Iki no estaba adentro. Ọlófin sentenció que porque el carnero lo engaño, el carnero debia ser sacrificado a eegun. Desde ese día un carnero siempre es dado a eegun como sacrificio.", "origen_id": "6723a46bedf9ce0286437f18"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe Sa habla del engaño de los amigos y de la necesidad de\n                     finalizar de cualquier forma lo que se ha comenzado.\n         WO – Todo está siendo áspero y rudo ahora, mas si usted no se da\n                                             por vencido, triunfará al final.\n\n\n25.1 · Lekeleke adivono de Ogbe, adivinó Ifá para Ogbe, quien iba en\n            un viaje de adivinación a Alahusa. Fue predecido que él podría\n           prosperar allí. Por lo tanto él debía ofrendar 16 palomas, 32000\n\ncowrie. Él escuchó el consejo y efectuó el sacrificio.\n\n\n25.2 · Afefelegelege, adivino de la tierra, Efufulele adivino del cielo,\n         Kukoteku adivino bajo tierra. El oráculo de Ifá fue consultado para\n            Iki, quien fue advertido acerca de un amigo tan enorme como el\n     carnero (agbo). Se le aconsejó ofrendar sacrificio para evitar que su\n               amigo lo traicionara y preparara su muerte. semillas de kola,\n   brazaletes de hierro, 22000 cowrie y un cuenco grande de madera con\n                                 tapa eran las ofrendas, Iki hizo el sacrificio.\n             Un día, el carnero fue a visitar a Olofin y observó que su lugar\n          sagrado Egungun estaba limpio. Él le preguntó a Olofin que había\n         usado en su adoración del Egungun. Olofin le respondió que había\n    utilizado nueces de kola como sacrificio. El carnero se rió y dejó que\n         aunque esto estaba bien, él traería a Iki para un sacrificio, Olofin le\n                                                               dio las gracias.\n    Un día el carnero fue a visitar a Iki. El carnero le preguntó a Iki, si su\n            padre alguna vez le había hablado acerca de un juego que él y el\n             carnero solían jugar juntos. Iki deseó conocer qué juego era. El\n         carnero le dijo a Iki que el juego consistía en truncarse llevando el\n           uno al otro por 40 pies, mientras uno estaba escondido dentro del\n         cuenco de madera. Iki dijo que su padre nunca le había hablado del\n                                       juego, pero que éste sonaba divertido.\n         El carnero puso el cuenco de madera en el suelo y se metió dentro.\n    Le pidió a Iki tapar el cuenco y transportarlo 40 pies, después que iki\n\ncaminó 40 pies, el carnero padre dijo que era su turno. El carnero\nentonces transportó a Iki por 40 pies y lo puso en el suelo y entonces\nle tocó su turno dentro del cuenco. Era el turno de estar Iki dentro del\n cuenco, el carnero lo transportó por 40 pies, pero cuando Iki le pidió\n      que lo bajara, el carnero lo ignoró y continuó caminando, Iki le\n suplicó pero el carnero se hizo el sordo para no oirlo. Iki comenzó a\n  cantar la canción que el babalawo le había enseñado cuando él hizo\n                                                          su sacrificio.\n                                     Afefelegelege adivino de la tierra\n                                            Efufulele adivino del cielo\n                                       Kukuteku adivino de bajo tierra\n               El carnero me está llevando a Olofin para sacrificarme\n     Yo no sabía que el carnero estaba jugando el juego de la muerte\n                                                              conmigo\n                                     Afefelegelege adivino de la tierra\n                                            Efufulele adivino del cielo\n                                     Vengan y liberen a Iki del cuenco.\n  Después de un rato, el carnero agitó el cuenco de madera y escuchó\nlos brazaletes de hierro moviéndose y pensó que Iki estaba dentro del\ncuenco. Cuando llegó a donde Olofin, le fue ofrecida la ayuda pero la\n     rechazó y dijo para pasar al patio interior. Cuando estaban en el\npatio, ayudaron al carnero con el cuenco. Al abrirlo, se dieron cuenta\n de que Iki no estaba adentro. Olofin sentenció que porque el carnero\n  lo emgaño, el carnero debía ser sacrificado a Eegun. Desde ese día\n\nun carnero siempre es dado a Eegun como sacrificio.", "origen_id": "b2f1de1cf41bd18f0504668a"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: dieciséis palomas y 32,000 cauríes.", "Iki: jícara con nueces de kola, pulseras de hierro, 22,000 cauríes y un cuenco de madera con tapa.", "Ifánírègún: ofrenda completa; piel de hiena.", "Àgbọ̀nrín y para no ser encarcelado: ẹ̀kuru espolvoreado con iyẹ̀rosùn y enterrado en la tierra."], "pasajes": [{"titulo": "Ofrenda en el verso 25.1", "texto": "Lekeleke el adivino de Ogbè:\nadivinó Ifá para Ogbè,\ncuando iba en un viaje de adivinación a Alahusa.\nEl adivino dijo:\n\"Ogbè progresará abundantemente allí\".\nPor tanto él debe sacrificar:\ndieciséis palomas y 32000 cowries.\nÉl escuchó el consejo y efectuó el sacrificio.", "origen_id": "7782925d4d302d3c5e0ab709"}, {"titulo": "Ofrenda en el verso 25.2", "texto": "Afefelegelẹgẹ el adivino de la Tierra,\nẸfufulẹlẹ el adivino del Cielo,\nKukuteku el adivino del límite de la Tierra:\nadivinaron Ifá para Iki,\nEllos le aconsejaron:\n\"Iki tiene que cuidarse de un amigo\ntan enorme como el carnero (Agbo)\".\nLe fue aconsejado hacer sacrificio\npara evitar que su amigo lo traicionara\ny preparara su muerte.\nRecipiente con bastantes nueces de kola,\npulseras de hierro, 22000 cowries\ny un cuenco grande de madera con tapa eran las ofrendas.\nIki hizo el sacrificio.", "origen_id": "2e051746c544fc1fb188df8c"}]}, {"titulo": "Relaciones espirituales", "texto": "Egúngún recibe el carnero desde este relato. Ọlọ́fin es el juez. Olúugbó, el dueño del bosque profundo, es padre del venado. La Tierra recibe el ẹ̀kuru."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nueces de kola, ẹ̀kuru (pastel de frijol), iyẹ̀rosùn, pulseras de hierro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 25.1 (yorùbá): Lekeleke awo Ogbè: / li o dífá f'Ogbè / nṣawo lo sile Alahusa. / Wọ̀n ni: / \"a rire lohun papoju\". / Nitorinaa kiorúbo. / Ẹyẹlé mẹrindilógún ati egbàá mẹrindilógún owó. / Ó gbọ̀ ó rú.", "Verso 25.2 (yorùbá): Afẹfelẹgẹlẹgẹ awo ayé, / Efufulẹlẹ awo òde orun, / Kukuteku awo aja-ilẹ: / a difá fún Iki. / Wọ̀n ni: / \"ẹnikan giriṣigiriṣi bi Agbo nbaaṣ'orẹ\". / Wọ̀n niki ó rúbọ / kiomabaa tan an lọ pa. / Apipo-obi, / pawa (egbà-ṣẹrin), ẹgbàá mokanla owó, / ppọ̀n tidetiṣi. / tki gbọ ó rú.", "REZO: OGBE SA YEYEMATERO AFEFE SALU AYE, AFETE SALU OLORUN ADIFAFUN EWE BANA AWAYANI ABO, AWAYENI ORUNMILA AFEFE LONA SHANGO ADIFAFUN EWE BANA. OGBE SA ADIFAFUN ORUNMILA ISHONSHON NABE GBOGBO SIYE INLEOBA OLOFIN ARUYE KAFEREFUN BARAPETU LODAFUN OZAIN ERU WAMALE WAMALE ORISHAOKO AYE AFEFE.", "SUYERE: EKUE MORE SALU EKUE, BABATATA EKUE MOLOBOLO UN YERE DUN.", "REZO: ERU WAN ERU MALE ORISHAOKO AYE AFEFE.", "REZO: SHEBELO KUE ABO KU SHEBELO MEDE LE MEKU SHEBELO KUSHESHEBELE KUE ABO KU SHEBELE ABO MELE SHIKU. JOBO SATOLE MOEKU EGGUN.", "SUYERE: KUSHENE ABO KUNE SHEBOLE ABO JUE SHEBELE.", "REZO: SHANGO LONGO ARAO FILANI OGBE SA BILARI EKOSI LARIO OGBE SA AFEFE INTO AFEFE LAO SALU AYE. OGBE SA AFEFE INTO AFEFE LAO LAO AWO SALU OLORUN APONTE PEKITA LORUBO EBBO OBO ORUN OGBE SA YEYEMETERO AFEFE OMO OLOFIN ILU FULEYE OMI IYAYE IKU BONILO LIJI LOMA.", "SUYERE: ABONSA ABONIYA AWO LODA IWI (SE REPITE).", "REZO: OGBE SA OGBERIKUSA OLOFIN NIYIN KUTUN ESADO ORI OASNI OLOFIN IWI EBATE ABE ONIONIONI IWI OMIGA ILE OLOFIN AFEFE LEGUE GUEGUE AWO OGUI OGALONLO AWE ESHURA MEYI LOQUITISIA OUPA.", "SUYERE: EKUE MORE SALU EKUE, BABATATA EKUE MOLOBORO UN YEREDUN.", "REZO: OGBE SA OYA BORI BOKUN LAROYE IYA IYA TOKU ORU OSHE ABOYERE OGBA IFA GRELOKO LORE ONI OGBE SA OSI YEYELINA.", "SUYERE: AWO KALEBO AWO OBA MOYOYE IKU EGGUN OBONIYE IKU AWO BOSIKEO AWO.", "REZO: ADIFAFUN ORUNMILA ISHONSHON NABE GBOGBO AIYE INLE OBA OLOFIN ARUYE KAFEREFUN BARAPETU LODAFUN OZAIN.", "REZO: OGBESA OGBERIKUSA OLOFIN NIYIN KUTUN ORI OAMI OLOFIN", "IKI OBATE ABO ONIONIONI IKI OMIGA ULE OLOFIN AFEFE LEKE KEKE. AWO OWI OGALONLO AWO IWI OSHERA MEYI LOKITISA OSHUPA.", "REZO: OGBE SA, OGBE YONO, OTI IKU, ANSI ALABO IKU, ATILA BIYA, OGBE SA PARA OBASAKUASA, KUASA OKIKAN KI DUBULO IKU, BORO OMOSHUBUN, BORO OMO DIDE.", "REZO: OGBE SA ATEMOLETA OSHU AWO NANIO. OGBE SA ORI AFEFE-LORUN AFEFE MAWA ORUN OÑI LEKAN IGUEDE FIERUBAYE AWO OGBE SA. OMO OLOFIN ENEFA ELEGBA ATEMOLETA SHANGO MEYERI ODDUN. TENTE ABURE OKANA GIO, ABURE OKANA SA. ORI NIFA TENTE MONI LAYE, ABURE OKANA YEKUN OLOWO ORUN ABURE OGBE TUA KATIYEBE NIFA AYEWARA, TONTI ABURE, ODI KAKA OGUERE ORI ORONI LAYE OKUN TENTE ORI LAYE NIFA, OJUANI SHOGBE IMBELARIO ORI OGBE SA ATEMOLETA ORI BAWA ORUN MAYENI IFA AGBANI BOSHE ADELE NIFA OGBE SA AGBA- NILE OSHUN IKAYO ADELE OLERIFA OMO TONIGBASHE UNTEFA ORUN LADEYE ORUN LADEYE NIFA ORI OGBE SA AWO ODARA BORI OLOFIN OMOKIO IFA ORUN LAYE IFA ODARA AWO DANIO."]}]$q$::jsonb),
(26,'6ba12452f376d7e5b216e4aabcd37ffc','580c5321e5433b135ebe51ecffca044e',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìká habla de vencer los celos, la desconfianza y la envidia para llegar a la fama y al respeto. Una fortuna salió de la casa y está regresando; lo que es de uno vuelve a uno. Pide más sentido común y menos imaginación en el día a día."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Imagina ofensas o desconfía sin pruebas; debe revisar los hechos antes de reaccionar.", "Quiere que respeten su trabajo, sus derechos o su lugar.", "Una fortuna o una oportunidad salió de su casa y espera que vuelva.", "Una pareja se separó y alguno piensa en regresar (relato de Ìtipónọlá y Ahoro).", "Desea reconocimiento en su profesión (relato del médico Arinwaka).", "Se siente arrastrado por lo que otros le piden (relato de la corriente Ogbàrá-ojo).", "Necesita parar, aceptar consejo y no perder amistades por orgullo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fama en todo el mundo para quien ejerce bien su oficio.", "Respeto a sus derechos, que nadie le podrá quitar en vida.", "La fortuna que se fue regresa, y quien se fue de la casa vuelve.", "Recuperar lo que siempre fue suyo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a un tiempo de contemplación. (Este Odu habla de la necesidad para seguir el consejo del Espíritu y seguir los tabú del Espíritu, considera nuevas posibilidades).", "origen_id": "19d19b9753344e3eafe8c00f"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Dejarse arrastrar por lo que otros quieren.", "Imaginar ofensas que no existen.", "Perder la casa o la pareja por no ofrecer completo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La arrogancia lleva al comportamiento impropio. (Este Odu habla d la necesidad a hacer más cauteloso o correr el riesgo de alienar a amigos)", "origen_id": "36656979e6abb4f066aaada1"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que es de uno termina regresando. La tortuga recuperó su caparazón sin pelear; solo esperó, porque siempre había sido suyo."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'Ká habla de sobreponerse a los celos, la desconfianza y la envidia para lograr alcanzar la fama y el respeto.", "origen_id": "5f89407b541095e9ca5247c4"}]}, {"titulo": "Relatos reunidos", "puntos": ["La corriente de agua. Èṣùmàrè, el arcoíris, consultó para Ọ̀gbàrá-ojo, la corriente que deja la lluvia, y le aconsejó ofrecer un azadón, un machete y un chivo para que nadie la guiara dentro del bosque. Ella se negó, y mucha gente empezó a dirigir su curso. Cuando por fin ofreció, con el tiempo empezaron a respetarla.", "Arinwaka, el médico. Los adivinos le dijeron a Arinwaka, médico del Ọwọni, que su nombre sería famoso en todo el mundo. Le marcaron una rata, un pescado y una gallina. Cumplió.", "Ìtipónọlá vuelve con Ahoro. Ìtipónọlá se había divorciado de Ahoro. Ifá le dijo: 'La casa que dejaste, a ella tendrás que volver'. Ella ofreció, y Ahoro dijo lo mismo que los babaláwo: de donde te vayas, ahí regresarás. Volvió y formalizó con su primer esposo.", "El caracol y el caparazón de la tortuga. El caparazón era de la tortuga, pero el caracol se lo quedó. A la tortuga le aconsejaron dejárselo y le dijeron que con el tiempo volvería a ella. La tortuga se buscó otra casa. Mucho después, la gente atrapó al caracol, le sacó la carne y tiró la concha, y desde entonces ya no la llamaron 'concha del caracol' sino 'caparazón de la tortuga'. Siempre le había pertenecido."], "pasajes": [{"titulo": "Verso 26.1", "texto": "Arcoíris (Èṣùmàrè) con una bella cola:\nfue quien adivinó Ifá para Ogbàrá-ojo\n(la inundación por la lluvia, torrente de agua).\nLe fue aconsejado hacer sacrificio:\nun azadón, un machete y un chivo\npara evitar que la guiaran (controlaran)\ndentro del bosque.\nElla oyó pero rechazó hacer el sacrificio.\nPor eso un gran gentío\ncomenzó a guiar su curso dentro del bosque.\nCuando ella finalmente fue a hacer el sacrificio\nla gente comenzó a respetarla con el tiempo.", "origen_id": "5ad41874d07aaee66bd28557"}, {"titulo": "Verso 26.2", "texto": "Qwọ̀ ni pẹbẹ,\nEsẹ̀ ni pẹbẹ:\nadivinaron Ifá para Arinwaka,\nquien era el médico de Qwọni.\nEllos le dijeron que su nombre\nsería famoso en todo el mundo.\nPor eso él debía sacrificar:\nrata, pescado y una gallina.\nÉl oyó y realizó el sacrificio.", "origen_id": "b86791cabbef752311e32804"}, {"titulo": "Versos complementarios 1", "texto": "Una cierta fortuna dejó la casa de esta persona que\nestá muy triste.\nLa buena fortuna está regresando. Si ofrendamos de\nmanera completa, las buenas bendiciones no se\nalejarán de esta casa nunca más, incluso si la\nesposa decide divorciarse, ella regresará pidiendo\nclemencia.\nAl igual que se ofrendará para que los derechos\nsean respetados a esta persona y solo con la muerte\nse perderán esos derechos que serán inalienables.\n\n                Ogbè ká relé\n                  Ợmợ Ợsìn\n                Ogbè ká relé\n                  Ợmợ Ợrà\n                Ogbè ká relé\n         Ợmợ Ògún lè lèè lè alèdé\n       A dífá fún Ìtipónợlá aya Ahoro\n               Wón ní kó rúbợ\n\n  Agbà ó yá ó bá lóun ò saya Ahoro mợ\n            Wón nilé tò ti kúò\n            Mó yáa padà sibè\n            Ìtipónợlá ba rúbợ\n                   O şe é\n              Níbi ó ti sa kúò\n             Mó ba padà sibè\n  Ahoró ni béè làwợn Babaláwo tòún wí\n               Ogbè ká relé\n                 Ợmợ Ợsìn\n               Ogbè ká relé\n                 Ợmợ Ợrà\n               Ogbè ká relé\n        Ợmợ Ògún lè lèè lè alèdé\n     A dífá fún Ìtipónợlá aya Ahoro\n                Ìtipónợlá o\n                Aya Ahoro\n         O ó tùún délé ợkợ àárò\n           O ó tợkợ àtijợ un fé!\n\nOgbè ká relé\nHijo de Ợsìn\nOgbè ká relé\nHijo de Ợrà\nOgbè ká relé\nHijo de Ògún lè lèè lè alèdé\nLanzaron adivinación para Ìtipónợlá esposa de\nAhoro\nA quien se le pidió sacrificar\nY esto sucedía después de haberse divorciado de\nAhoro\n¡La casa que ud. ha dejado…. Tendrá que regresar\nde nuevo…!\nEllos le dijeron\nElla consideró el sacrificio y así lo realizó\n\n“De donde te vayas o escapes, allí regresarás”\nAsí exclamó Ahoro, de la misma manera que dijeron\nsus Babaláwo\nOgbè ká relé\nHijo de Ợsìn\nOgbè ká relé\nHijo de Ợrà\nOgbè ká relé\nHijo de Ògún lè lèè lè alèdé\nLanzaron adivinación para Ìtipónợlá esposa de\nAhoro\nYo te lo advertí Ìtipónợlá, que eres la esposa de\nAhoro\nQue regresarías y te formalizarías con tu primer\nesposo\n\n          Ogbè ká re káà ká bò dé\n               A dífá fún Ìgbín\n    Ti ń lợ rèé gba káà lợwợ Alábahun\n            Ahun ló ni káà télè rì\n            Ìgbín bá gbà á lợwợ è\n                 Ó mú káà lợ\n                Wón ní ó fíí lè\n             Wón ní ńgbà ó bá yá\n           “Yóó fíí káà sílè fún ợ”\n            Ahun bá mú káà míìn\n               Wón ń báyéé lợ\n                 Ńgbà ó bá yá\n              Ti ợn bá mú Ìgbín\n      Wón ó bàá yợ Ìgbín kúò ńnú è\n           Wón ó ju kòròòfo è nù\n    Wón ò bá níí pè é ní káà Ìgbín mợ\n       Káà Ahun ni wón ó mợợ pè é\n              Ó bá di káà Ahun\n             “Wón ni ńgbà ó kú”\n\n             Ợ ò gba nnkaàn rẹ?\n             Ahun gba nnkàn è\n          Ogbè ká re káà ká bò dé\n               A dífá fún Ìgbín\n    Ti ń lợ rèé gba káà lợwợ Alábahun\n              Ìgbín wáá kú tán\n         Ahun gba káà lợwợợ wợn\n         Wón a ní káà Ahun níí şe!\n\nOgbè ká re káà ká bò dé\nLanzó adivinación para el Caracol (babosa)\nQue venía a asirse a la casa de la Tortuga\nInicialmente fue la Tortuga la dueña del carapacho\nPero el Caracol, se hizo con ello y se marchó con el\nEllos aconsejaron a la Tortuga que dejase el\ncarapacho para el caracol\nEllos le predijeron que pasado algún tiempo, ella le\ndejaría la concha\nLa Tortuga consiguió otra casa para si misma\nY la vida continuó\nLuego de un largo tiempo, el hombre levantó el\ncaracol y separó la carne de la concha, botando esta\núltima y quedándose con la carne\nY ya no fue llamado “El Carapacho del Caracol”, sino\nde la Tortuga\nAsí fue como regresó la concha a la Tortuga.\n“Cuando él muere”\nEllos dijeron: ¿No recobraste tu carapacho?\nOgbè ká re káà ká bò dé\nLanzó adivinación para el Caracol (Babosa)\nQue venía a asirse a la casa de la Tortuga\nEl Caracol entonces murió\nLa Tortuga recobró su carapacho\nEllos dijeron: ¡Siempre perteneció a la Tortuga!", "origen_id": "08da651f3001bfc41bfece17"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbeka habla de sobreponerse a los celos y la envidia para\n                                                            lograr fama y respeto.\n                WO - El cliente necesita inyectar más sentido común y menos\n                                           imaginación en las actividades diarias.\n\n\n26.1 · Arcoiris (esumare) con una bella cola adivinó Ifá para un\n       torrente de lluvia. Ella habló de ofrecer como sacrificio 1 azadón, un\n           machete, 1 chivo para evitar que la gente penetre dentro del bosque.\n      Ella oyó pero rechazó hacer el sacrificio. Por eso un gran gentío entró\n      en su bosque. Cuando ella finalmente fue a hacer el sacrificio la gente\n                                                  comenzó a tratarla con cuidado.\n\n\n26.2 · Owon ni pebe, Ese ni pebe adivinó Ifá para Arinwaka, quien\n                    era el doctor de Owoni. Él le dijo que sería famoso en todo el\n            mundo. Por eso él debía sacrificar 1 jutía, 1 pescado y 1 gallina. Él\n                                                       oyó y realizó el sacrificio.", "origen_id": "c1f8afea7ee90a8bd9789151"}, {"titulo": "Relato en inglés 1", "texto": "“Night falls and we spread our sleeping mats, day breaks and we roll them:\nup; one who lays the warp threads must walk back and forth;! when someone\ndies, we dig a hole that is very, very deep in the eyes of a coward” was the one\nwho cast Ifa for Qrunmila when he was going to Ika? to divine. They said he\nshould sacrifice one gbaguda knife’ with its sheath, some fallen kola? still in the\npod, two hens, two rats, two fish, and one shilling one penny two oninis\n\nso that he would not be taken as a thief at the place to which he was going. Qrun-\nmila said he would not make the sacrifice until he returned. Ifa says someone is\ngoing to a distant place; he should sacrifice lest he be taken as a thief at the\nplace to which he is going.\n\nWhen Qrunmila was going to the town of Ika, he consulted the diviners. They\nsaid that he should make a sacrifice, but he said that he would not make the sacri-\nfice until he came back. On his way, when he approached the town gate, he saw a\nkola tree that bore fruit, and he longed to have some. He pulled the gbaguda knife\nhe had in his hand out of its sheath and with it cut off one of the pods of kola.®\nJust as he had cut it down, the owner of the kola came along, and he tried to catch\nQrunmila as a thief; but while they were wrestling with each other, and Qrunmila\nwas trying to run away, the knife that he held cut Qrunmila on the palm of his\nhand, and he escaped, After Qrunmila had run away, the owner of the kola came\nhome from the farm. He went to the king of Ika and told him that someone had\nstolen his kola, but that when he tried to catch him, he had run away; therefore,\nthe king should please summon the people of the town, including both the foreign-\ners and the townspeople, because the thief was somewhere in town,\n\nWhen Qrunmila heard about this, he was frightened, and he again consulted\nthe diviners. They told him that he should make the sacrifice\n\nthat he had not made before he left home; but that this time he must make it two-\nfold. Qrunmila made the sacrifice just as the diviners had told him. When he\nhad finished, they said that he should stick the gbaguda knife® into the base of\nEshu; and he did so.\n\nBefore daybreak Eshu had taken the knife’ and with it cut the hands of all\nthe people who were in the town, including even the unborn embryos and the chil-\ndren still unconceived.® When dawn came and all the people of the town had as-\nsembled, the King of Ika told them that a man had been stealing kola; and that the\nowner of the kola said he would recognize him because his hand had been cut by\na knife. The king told the owner of the kola to look for the thief among the peo-\nple who were gathered there. As he walked about through the people, he saw\nQrunmila among them and pointed his finger at him, saying, “This is the man.”\nWhen Qrunmila heard this, he asked how the owner of the kola could identify him.\nHe answered that he could identify him because the knife had cut his hand. Qrun-\nmila said, “Well then, let everyone open his hands, including the king and the\nowner of the owner of the kola as well.” When they opened their hands, there\nwere scars on the hands of each and every one of them.\n\nWhen the owner of the kola saw this, he was frightened,” and Qrunmila be-\ngan to cry that they had accused him of being a thief and had been telling lies\nabout him. While Qrunmila was weeping, Eshu told the King of Ika that he must\nnot let Qrunmila weep; therefore, he should hasten\n\nto beg him to stop. All the townspeople begged and begged him to stop, but he\nwould not listen. Then they asked Qrunmila what he would take to forget what\nhad happened, Ọrunmila said he would take two hundred of every kind of goods\nfrom them, and in addition ten boys and ten girls. The King of Ika gathered all\nthese things together and gave them to Ọrunmila.1? When he had received them\nall, and had carried them home, he began to dance, rejoicing and singing:\n\n“Oooooh shoko.” “Bani.”\n\n“The dawn will break good for the diviner, oh!\n\n“The dawn will break good for the diviner;\n\n“When we wake up and come to find something, we find scars on the hand, oh!\n“The dawn will break good for the diviner.”", "comentario": "1. The warp threads for the men’s horizontal looms are laid out by running\nthem around stakes stuck into the ground in two parallel lines in a manner that\nmakes it possible to lay a warp several hundred yards long in a fairly small\narea. The weaver must walk back and forth between the lines of stakes, winding\nthe warp thread about two adjacent stakes in each line each time.\n\n2. Ika here is the name of a town; note the reference to the name of. the\nfigure, Ogbe Ika.\n\n3. A small knife with a straight blade.\n\n4, Kola nuts which had not been picked from the tree, but which had become\nripe enough to fall to the ground by themselves.\n5. Note that Qrunmila, who was told to sacrifice a gbaguda knife in its\nsheath and fallen kola lest he be caught in the act of stealing, gets into trouble\nwhen cutting kola from the tree (before it was ripe enough to fall) with a gbaguda\nknife that had a sheath.\n6. There is an inconsistency here. Since the sacrifice was doubled by the\ndiviners because of the postponement, there should be two gbaguda knives; but\nonly one is mentioned.\n\n7. The knife which Qrunmila sacrificed is thus instrumental in extricating\nhim from his difficulties. e\n\n8. To ensure that all the people to be born in the future will have lines on\ntheir palms. Note the reference in the text to the Yoruba belief that the menstru-\nal fluid develops into the embryo.\n\n9. This verse thus explains how people came to have lines on the palms of\ntheir hands.\n\n10. Because he could be charged with having accused someone falsely.\n11. Cf. n. 7, verse 1-10,\n12. Cf. the similar tale recorded by Frobenius (1926: 287-288) in which\nTortoise, who replaces Qrunmila, is caught and killed.", "origen_id": "ef36f203556cb567b3142acf"}, {"titulo": "Relato en inglés 2", "texto": "“A horse carries his head high in battle” was the one who cast Ifa for “Divin-\ner chooses his houses carefully,” the child of Qrunmila, when he was farming,\nhunting, and trading in merchandise.\n\nIfa says there is someone whom, when he stretches his hands to do something,*\nIfa does not allow to see his work come to a successful conclusion. Ifa is fighting\nwith this person, therefore he should sacrifice to the Ifa and also take care of a\nset of palm nuts, Ifa says that he will spoil everything that this person puts his\nhand\n\nto; he will break the string and clog up the beads? unless this person takes care\nof the Ifa. If he does so, then his affairs will be set in order and will reach a\nsuccessful conclusion, After all the children born to him have died, Ifa will set\nhis destiny in order, if he is able to take care of the Ifa and to sacrifice to it.", "comentario": "1, That is, when he tries to do anything. Cf. verse 4-4.\n2, A metaphor for spoiling everything, based on the way in which beads are\nspoiled when their string breaks and sticks in the openings so that they cannot be\nrestrung, or a pipe is spoiled when a match breaks in cleaning it, clogging up the\nhole so that it cannot be smoked. Cf. n. 4, verse 244-1.", "origen_id": "e0b9f35a5dd40eb69db05599"}, {"titulo": "Relato en inglés 3", "texto": "\"Ogbe that we go home,”! King’s child, Altar’s child, the child of “He wor-\nships the God of Iron beneath a low, wide-spreading tree” was the one who cast\nIfa for Qrunmila on the day that he was going home to Qlomg Qfẹ ward in the\ntown of Ijero.? Ifa says someone wants to go to a distant place; at that place the\nSky God will give him many possessions and he will be king over the people\nthere. Both the slaves and the townspeople will prostrate themselves before him\nand bow down before him. But he should sacrifice four pigeons and two shillings.®", "comentario": "1. It is possible that this is an alternative name for the figure Ogbe-(I)ka.\nNote that it is a pun on the name of this figure, and also that it implies that the\nclient, like Qrunmila, is about to go home.\n\n2. Informants were not certain of the meaning of either Ọlọmọ Qf¢ or Ijero,\nbut pointed out that the former is the name of a ward in the town of Ilesha, about\ntwenty miles away. Ijero is a town east of Nesha.\n\n3. Since cowries are counted by the two thousand, there are four units of\ncowries as well as four pigeons.", "origen_id": "b25c251961feb0efed78ad7d"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀gbàrá-ojo: un azadón, un machete y un chivo.", "Arinwaka: una rata, un pescado y una gallina.", "Ìtipónọlá y la casa: ofrenda completa para que las bendiciones no vuelvan a salir."], "pasajes": [{"titulo": "Ofrenda en el verso 26.1", "texto": "Arcoíris (Èṣùmàrè) con una bella cola:\nfue quien adivinó Ifá para Ogbàrá-ojo\n(la inundación por la lluvia, torrente de agua).\nLe fue aconsejado hacer sacrificio:\nun azadón, un machete y un chivo\npara evitar que la guiaran (controlaran)\ndentro del bosque.\nElla oyó pero rechazó hacer el sacrificio.\nPor eso un gran gentío\ncomenzó a guiar su curso dentro del bosque.\nCuando ella finalmente fue a hacer el sacrificio\nla gente comenzó a respetarla con el tiempo.", "origen_id": "d1628af0d7e200095b40c49c"}, {"titulo": "Ofrenda en el verso 26.2", "texto": "Qwọ̀ ni pẹbẹ,\nEsẹ̀ ni pẹbẹ:\nadivinaron Ifá para Arinwaka,\nquien era el médico de Qwọni.\nEllos le dijeron que su nombre\nsería famoso en todo el mundo.\nPor eso él debía sacrificar:\nrata, pescado y una gallina.\nÉl oyó y realizó el sacrificio.", "origen_id": "866a15ee0b89b9069f692da2"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣùmàrè, el arcoíris, es el adivino de la corriente. Ọwọni es el rey al que sirve el médico."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Azadón, machete, rata, pescado, gallina."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 26.1 (yorùbá): Èṣumàrè abidi-dododo: / li o dífá f'Ogbàrá-ojo / A niki ó wa rú: / oką, àdá ati òbúko / ki àwọn ọmọ aráyé / ma ba maa dari rẹ sinu ígbó. / O gbọ̀ ebọ ko mama rú. / Oun ni ọmo aráyé / bẹrẹsii dari rẹ sinu ígbó. / Nigbati o wa rúbo / ni ikẹhin ni àwọn omọ aráyé too / bẹrẹsii maa tún iwa rẹ ṣe diẹdiẹ.", "Verso 26.2 (yorùbá): Qwą ni pẹbẹ, / Esẹ̀ ni pẹbẹ: / li o dífá fún Arinwaka / ti iṣe Oniṣègùn Qwọni. / Wọ̀n ni kaakiri ayé / ni wọ̀n maagbọ orukọ rẹ. / Nitorinaa kiorú: / Eku, ẹja ati abo-adiyẹ. / Ó gbọ̀ ó rú.", "REZO: OGBE KA LAFILA AWO OGBE LOSHUDE ELEGBA IBA FILA ASIA AKETEFUN OMO SHEREGUN IFA LAYENI FILA AWO.", "SUYERE: LASHEWA LASHEWA OMO SEMEWA.", "REZO: OGBE KA ADIFAYOKO KAFUN ASHEBEREBERE OMO OLOFIN OBA.", "REZO: OGBE OKALA OKOE OKONURE AWO OKAMBA OMO OLOFIN BARA BARA ARAWE NIREGUN AGRI KUALONUBE OWUNKO OPA AKUKO EWE EYA OPO EWEYEWO OGBE KA ABABIKO ADIFAFUN IYA OYUPAN ADIE.", "REZO: OGBE KANLA LASHEBANA ADIFAFUN PEISHEBA OMA ESHU AMEGUN", "REZO: OGBE KA ORUNMILA, OGGUN Y OSHOSI, OGBE KA ADIFAFUN ASHIBEROBRE OMO OLOFIN.", "REZO: OGBE IKA EBBO YEKU TU ANARE ANANA EKUTALE YEKE ABEREKU YEKU IYELA KUTALO NANA.", "SUYERE: NANA OKUNAYE EKUTALE, NANA ANANIYO, KUTALE NANA.", "SUYERE: LASHEWA LASHEWA OMO SEMOWA.", "SUYERE: OWENE WENE ABIGBO, OWENE WENE ABIGBO, OFO TANSHE SHEMISHE ABIGBO, OWENE WENE ABIGBO.", "SUYERE: KINI WANILE NNILEKE, AWO KINI WANILE AWO.", "SUYERE: OWUENE WENE ABIGBO, AFETAN SHEMENI ORUNMILA ABIGBO OKERE KERE, ABIGBO AFETAN SHEMENI.", "SUYERE: OJUMO AWO AWO RIREO, OJUMO AWO AWO RIRE AJIBOWA, BALA BALA LOWO, OJUMO AWO AWO RIRE.", "REZO: ORUNMILA ADIFAFUN KANFU ASHEREBEREBE OMO OLOFIN.", "REZO : AILELE ATENI OJUMO MOKONI ADAWU NIPOYIRERE KOLA OKU LOKUNI AGBELE LOOJIN BUMBUN OPI OJO ADAFUN ORUNMILA OJO INSHE AWO OGBE IKA WEN NIKI ORUTO OGBE BAGUNDA KANTI OWA MUNU AKE IWOOBI ADA ABEBO ADIE MEYI, EKU, EYA, NITORI KIWON NABA NUÑELE NIBRIN TINLO OSI TUNIBO AWON BABALAWO LOWON SISE LEMPE KI OTUN WA NI EBBO", "AIKONU KONKOLE SHUGBON ONILATE MONI ILOPO MEYI ORUN-MILA OLOFIN GBOGBO IMALO ORANO OLORUN KALE ERIN A WARA BAWOS IRAWE OLOKUN OLARE OSUPA GBOGBO IMALE AINA EMI OLORI OKAN IPIN IMPORI GBOGBO ONONLO FI OGBO BAGUNDA MAGUN IDI ESHU LORDAFUN GBOGBO ORUNALE ESHU.", "SUYERE: OJUMO AWO AWO RIREO, OJUNMO AWO AWO RIRE AJILOWA, BALA BALA LOWO, OJUMO AWO AWO RIRE.", "SUYERE: AWENE WENE ABIBO ORUNMILA. ADEFE ITANAE ABIBO ORUNMILA. AWENE WENE ABIBO ORUNMILA.", "REZO: ADIFAFUN BARA PETU KOBORI OLE YEWA ONILU OPALYE ORUNMILA OGBE IKA KEFEREFUN ELEGBA.", "REZO: OGBE IKA EBBO YEKU TU AMARE ANANA EKUTALE YEKE ABEREKU IYELA KUTALE NANA.", "SUYERE: OKUNAYE OKUTALE NANA, OKUNAYE OKUTALE NANA, ANANAYE ARA NAYE KUTALE NANA."]}]$q$::jsonb),
(27,'2bdb7b229c94f4d13a37bac7dffccaa5','6db15de99b8e19a05b8b6bdda3b8cf4e',$q$[{"titulo": "Idea central", "texto": "Ogbè Òtúrúpọ̀n habla de competencia: la persona puede quedarse atrás y gana con la ofrenda. Un nuevo vínculo con el Òrìṣà le trae un despertar espiritual. Pide obedecer a los padres, no malgastar la herencia y cuidar el buen nombre que dejaron los antepasados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se compara con otros y teme perder su lugar (relato de la vaca y el caballo).", "Desea hijos o busca guía espiritual (relato de Alaworo-Oriṣà).", "Pregunta a la vez por dinero, pareja e hijos (relato de Sèkèrè).", "Recibió un nombre o una herencia familiar y debe cuidarla sin malgastar.", "Quiere dejar un buen nombre que la gente recuerde (relato del árbol Ìrókò).", "Un problema de salud o un plan frustrado necesita atención práctica.", "Debe escuchar a sus padres o mayores antes de una decisión importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ganar un estatus que antes era de otro.", "Hijos para quien los busca, y riqueza inesperada.", "Un nombre respetado que se recuerda aun cuando uno ya no está.", "Bendiciones a través del Òrìṣà."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la buena salud. (Este Odu habla de la necesidad de desarrollar un buen carácter como la fundación de crecimiento espiritual y vida larga.)", "origen_id": "9d2e9aee38477fa50b842f65"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Desobedecer a los padres.", "Despilfarrar la herencia de los antepasados.", "Perder un lugar por no ofrecer."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto es bloqueado por enfermedad. (Este Odu habla de la necesidad de protección en contra de la posibilidad de planes echados a perder o salud echada a perder.)", "origen_id": "4fea52b259c3a7aeb9f6bf2d"}]}, {"titulo": "Enseñanza principal", "texto": "El rango se gana cumpliendo. La vaca tenía más estatus que el caballo, pero el caballo ofreció y ella no; desde entonces el caballo va adornado."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'Túrúpòn habla que el cliente puede perder o quedar atrás en una situación de competitividad. Él o ella pueden ganar a través del sacrificio.", "origen_id": "860a6cbc19c7770e5c1c51f2"}]}, {"titulo": "Relatos reunidos", "puntos": ["La vaca y el caballo. Antes la vaca tenía más estatus que el caballo. A los dos les marcaron tres azadones y 66,000 cauríes para tener el lugar del otro. La vaca no quiso; el caballo cumplió. Èṣù convenció a la gente de tratar al caballo como compañero, porque siempre favorece a quien cumple. Desde entonces el adorno de honor va en el cuello del caballo.", "La sacerdotisa sin hijos. Alaworo-Òrìṣà sufría porque no tenía hijos y andaba de un lado a otro como el buitre. Le marcaron una tela blanca para poner sobre el Òrìṣà, 32,000 cauríes y dos gallinas. Cumplió.", "Sèkèrè, hijo de Àlákòlé. Sèkèrè preguntó si tendría riqueza, esposas, hijos y una vida mejor. Le pidieron ofrecer una buena cantidad de dinero para que bailara de gusto el resto de su vida. Cumplió, y la riqueza llegó de golpe; no tenía dónde guardarla y se la ató al cuerpo. La gente decía: '¿Tanto dinero tiene Sèkèrè?'. El canto dice: 'Tu ropa está hecha de cuentas; en tu cuerpo germina la riqueza'.", "El nombre del Ìrókò. Uno que preguntaba si tendría un buen nombre como el de su padre ofreció, y resultó ser el árbol Ìrókò. Aunque lo corten y ya no esté, la gente sigue diciendo 'junto al Ìrókò' para señalar el lugar. Su nombre se proclamó en todas partes con respeto."], "pasajes": [{"titulo": "Verso 27.1", "texto": "Jigbinni (estatus simbólico):\nadivinó Ifá para el caballo (Eṣin)\ny también para la vaca (Eranla).\nLa vaca fue advertida para ofrecer sacrificio,\nasí le sería dado el estatus del caballo.\nTres azadones\ny 66.000 cowries serían el sacrificio.\nLa vaca escuchó pero se negó a sacrificar.\nEl caballo escuchó y realizó el sacrificio.\nAntiguamente, la vaca tenía un estatus superior al del caballo.\nÈṣú persuadió a la gente a tratar al caballo\ncomo un buen acompañante\nporque Eṣú favorece siempre\na cualquiera que realizara sus sacrificios.\nCanto de Ifá:\nJigbinini o,\nestá ahora en el cuello del caballo,\nJigbinini o,\nestá ahora en el cuello del caballo.", "origen_id": "27bb9a808830309ca72a2a3d"}, {"titulo": "Verso 27.2", "texto": "Ogbètúnmopòn-Sunmosi,\nBi-omo-ba-nke-iyá-rẹ-ni-aagbefun:\nadivinaron Ifá para Alaworo-Oriṣà\nquien estaba sufriendo por la carencia de hijos\ny estaba yendo de un sitio a otro como el buitre.\nElla fue advertida para ofrecer en sacrificio:\nponer una pieza de tela blanca sobre el Oriṣà,\n32.000 cowries y dos gallinas.\nElla oyó y realizó el sacrificio.", "origen_id": "fe5ec6421045ca459a91e6eb"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que las buenas bendiciones vendrán a esta\npersona. Deberá ofrendar una buena cantidad de\ndinero y la vida le será placentera.\nIfá dice que el buen nombre implantado por sus\nancestros no podrá ser difamado. Estará avisado de\nno desobedecer a sus padres. Se le aconseja no\ndespilfarrar la herencia recibida ancestralmente,\npara que sus ancestros celestiales no lo lamenten\nen el cielo.\n\n             Ogbè tợmợ pòn\n           Abiamợ súmmợ sí\n             Àgbàpòn ó lérè\n           Bợmợ bá ń sunkún\n              Ìyá làá kéé sí\n            A dífá fún Sèkèrè\n        Sèkèrè tíí sợmợ Àlákòlé\n              Òún leé lájé?\n               Òún le láya?\n                Òún bímợ?\n              Ayé oún dáa?\n        Wón ní kí Sèkèrè ó rúbợ\n         Wón ni ijó ní ó móợ jó\n             Ayò n layée rè\n     Wón ní ợpợlợpợ owó ni ó fi rúbợ\n            Sèkèrè rúbợ tán\n                  Ajé dé\n           Kò ribi kó ó si mó\n          Ó bá sowó mó ara è\n    Wón ń pé Sèkèrè ló lówó tó báyìí?\n        N ní wá ń jó ní wá ń yò\n\n          Ní ń yìn àwợn Babaláwo\n         Àwợn Babaláwo ń yìn Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n              Ogbè tợmợ pòn\n             Abiamợ súmmợ sí\n               Àgbàpòn ó lérè\n             Bợmợ bá ń sunkún\n                Ìyá làá kéé sí\n  A dífá fún Sèkèrè èyí tíí sợmợ Àlákòlé\n           Sèkèrè araà rẹ lokùn\n       Sèkèrè araà rẹ lájé gbé ń so\n        Ajé wáá rí rẹrẹ báwònyí o\n           Sèkèrè araà rẹ lokùn\n       Sèkèrè araà rẹ lájé gbé ń so\n\nOgbè tợmợ pòn\nAbiamợ súmmợ sí\nAl igual que el portador del bebé no tiene beneficios\nEs la madre quien calma al niño, cuando éste llora\nLanzaron Ifá para Sèkèrè, el hijo de Àlákòlé\nCuando él preguntó: ¿Tendré riquezas, esposas, e\nhijos?\n¿Será mejor mi vida futura?\nEllos le pidieron a Sèkèrè que sacrificara con una\nbuena cantidad de dinero para que pudiese bailar\nde júbilo y gozo en su vida futura\nSèkèrè sacrificó y de manera inesperada llegó a\ncaudales la riqueza\nNo tuvo lugar donde guardarlo todo y se llenó sus\nbolsillos\nLa gente se preguntaba: ¿Tiene tanto dinero ese\nSèkèrè?\nEl bailó y regocijó a sus adivinos\nEllos regocijaron a Ifá\nEl hizo y dijo lo que ellos dijeron que dijera e hiciera\n\nOgbè tợmợ pòn\nAbiamợ súmmợ sí\nAl igual que el portador del bebé no tiene beneficios\nEs la madre quien calma al niño, cuando éste llora\nLanzaron Ifá para Sèkèrè, el hijo de Àlákòlé\nTú corpiño está hecho de cuentas bellas\nEs en tu cuerpo donde germina la riqueza\nLa riqueza está abundante entre nosotros ahora\nTú corpiño está hecho de cuentas bellas\nEs en tu cuerpo donde germina la riqueza\n\n                Şeguí sóòrúpa\n             Òkèrè n kerenbètè\n            Ìyà àlà larugbòn ikú\n     A dífá fún Ợlợmợ a ji foókợ sára\n    Òún lê lóókợ to dáa láyé òun báyìí?\n              Bàbá òún tí lóókợ\n               Wón ní kó rúbợ\n     À á séé mợ Ợlợmợ a ji foókợ sara\n                 Làá pé Ìrókò\n            Bí ợn bá ge Ìrókò tán\n                Tí ò si ńbè mợ\n        Wón ó túún móợ fibè júwe\n             Wón a pé ńdíí Ìrókò\n          Ifá pé ki eléyìun ó rúbợ\n                Ìrókò ba rúbợ\n        Ni ợn ba ń ki gbé è kárí ayé\n                 Ayé yẹ Ìrókò\n                Şeguí sóòrúpa\n             Òkèrè n kerenbètè\n            Ìyà àlà larugbòn ikú\n     A dífá fún Ợlợmợ a ji foókợ sára\n     Ợlợmợ a ji foókợ sára nìrókòó jẹ\n       Ifá jé á jợ lóókợ rere ńlé ayé\n\n                  Porongodo!\nŞeguí sóòrúpa\nÒkèrè n kerenbètè\nEs una carga pesada para el portador del cesto de la\nmuerte\nLanzó adivinación para Ợlợmợ a ji foókợ sára\nQuien se preguntaba ¿si tendría un buen nombre en\nla Tierra?\n“Mi Padre tuvo un nombre distinguido”\nSe le pidió sacrificar\n¿Cómo reconoceremos nosotros a Ợlợmợ a ji foókợ\nsára?\nPues es aquél a quien llamamos “Árbol del Ìrókò”\nIncluso sabiendo que ha existido uno de esos\nárboles en un lugar determinado, aunque ya no esté\npresente, se seguirá diciendo:\n- Al lado del árbol del Ìrókò -\nÌrókò sacrificó\nY ellos proclamaron su nombre en todas partes\ncomo algo majestuoso y muy importante, así como\nde mucho respeto y honra\nY la vida le fue muy placentera al árbol de Ìrókò\nY el dijo Şeguí sóòrúpa\nÒkèrè n kerenbètè\nEs una carga pesada para el portador del cesto de la\nmuerte\nLanzó adivinación para Ợlợmợ a ji foókợ sára\nỢlợmợ a ji foókợ sára es el sobrenombre del árbol\nde Ìrókò\nPor favor, Ifá deja que nuestros nombres sean\nilustres y respetados en la Tierra\nPorongodo!", "origen_id": "50dfce932dde421e7f27edd3"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbeturupon habla del cliente que queda atrás o pierde terreno\n\nen una situación de competitividad. Él o ella pueden ganar a través del\n                                                                      sacrificio.\n     WO – Una nueva relación o un despertar espiritual, mitigará el actual\n                                                             enfoque temporal.\n\n\n27.1 · Jigbinni adivinó Ifá para el caballo (esin) y también para la vaca\n\n            (eranla). La vaca fue advertida para ofrecer sacrificio, así le sería\n     dado el estatus del caballo. 3 azadones y 66.000 cowrie serían usados\n     como sacrificio. La vaca oyó pero se negó a sacrificar. El caballo oyó\n           y realizó el sacrificio. Anteriormente, la vaca estaba en un estatus\n           superior al del caballo. Eşu persuadió a la gente a tratar al caballo\n                como una buena compañía porque Eşu favorecería siempre a\n                                       cualquiera que realizara sus sacrificios.\n          Canto de Ifá: Jigbinini o (status simbólico) esto está sobre el cuello\n                del caballo, Jigbinini o, esto está sobre el cuello del caballo.\n\n\n27.2 · Ogbetunmopon-Sunmosi, Bi-omo-ba-nke-iya-re-ni-aagbefun,\n     adivinó Ifá para Alaworo-Orişa quien estaba sufriendo por la carencia\n           de hijos y estaba yendo de un sitio para otro con el buitre. Ella fue\n          advertida para ofrecer en sacrificio 1 pieza de tela blanca puesto de\n            Orişa, 32.000 cowrie y 2 gallinas. Ella oyó y realizó el sacrificio.", "origen_id": "3ada7f1ce9af3f3f8eff5efa"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El caballo: tres azadones y 66,000 cauríes.", "Alaworo-Òrìṣà: tela blanca sobre el Òrìṣà, 32,000 cauríes y dos gallinas.", "Sèkèrè: una buena cantidad de dinero.", "Ìrókò: ofrenda por el buen nombre."], "pasajes": [{"titulo": "Ofrenda en el verso 27.1", "texto": "Jigbinni (estatus simbólico):\nadivinó Ifá para el caballo (Eṣin)\ny también para la vaca (Eranla).\nLa vaca fue advertida para ofrecer sacrificio,\nasí le sería dado el estatus del caballo.\nTres azadones\ny 66.000 cowries serían el sacrificio.\nLa vaca escuchó pero se negó a sacrificar.\nEl caballo escuchó y realizó el sacrificio.\nAntiguamente, la vaca tenía un estatus superior al del caballo.\nÈṣú persuadió a la gente a tratar al caballo\ncomo un buen acompañante\nporque Eṣú favorece siempre\na cualquiera que realizara sus sacrificios.\nCanto de Ifá:\nJigbinini o,\nestá ahora en el cuello del caballo,\nJigbinini o,\nestá ahora en el cuello del caballo.", "origen_id": "be893130650c382e7650581a"}, {"titulo": "Ofrenda en el verso 27.2", "texto": "Ogbètúnmopòn-Sunmosi,\nBi-omo-ba-nke-iyá-rẹ-ni-aagbefun:\nadivinaron Ifá para Alaworo-Oriṣà\nquien estaba sufriendo por la carencia de hijos\ny estaba yendo de un sitio a otro como el buitre.\nElla fue advertida para ofrecer en sacrificio:\nponer una pieza de tela blanca sobre el Oriṣà,\n32.000 cowries y dos gallinas.\nElla oyó y realizó el sacrificio.", "origen_id": "89336227c054c813a1819fbe"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù favorece a quien cumple. El Òrìṣà recibe la tela blanca. Los antepasados cuidan el nombre de la familia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Árbol Ìrókò, tela blanca, azadones, cuentas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 27.1 (yorùbá): Jigbinni: / li o difá fẸṣin, / o dífá f'Eranla. / Wọn niki Ẹranla wa rúbọ / ki iwa rẹ ma baar'ẹhin sit'Ẹṣin. / Qkọ méta / ati ẹgbẹtalélọgbọ̀n owó ni ẹbọ. / Eranla gbọ ẹbọ ko ma rú o. / Eṣin gbọ̀ ebọ, ó ruu. / Eranla li o tijẹ ègbọ̀n Eṣin tẹlẹ ri / Èṣú wa sọ fún ẹ̀niyàn / pe kiwọn fa Ẹṣin mọra / nitori eniti ó rúbọ ni Eṣú ngbe. / Orin Ifá naa: / Jigbinni o, / O wa l'orùn Eṣin / Jigbinni o, / O wa l'orùn Eṣin.", "Verso 27.2 (yorùbá): AP / Ogbètúnmopon-Sunmosi, / Bi-omo-ba-nke-iyá-rẹ-ni-aagbefun: / li o difá f'Alaworo-Oriṣà / ti kor'omọgbepòn tio nba igún kiri. / Wọ̀n niki ó rú. / Aṣọ funfun kan / bayi tiowa lori Oriṣà l'ẹbọ, / egberindilógún owó ati abo adiyẹ Méjì. / Ô gbó ó rú.", "REZO: OGBE TUMAKO KUKUYE AYA KUKUYE AYU ARUN ATANA YUBARA KUMISAYA ADELEWA ORUNMILA AGBANI IBA, ABO LEBO. ORUN IRE NIRA KILODA FUN ESHU.", "SUYERE: KUYE KUYE IKU KUYE BINI, KUYE KUYE BERE AWO ATA MAYURU ILU BERE AWO ELEGBA OMODE.", "REZO: OGBE TUMAKO IKU YEYE NISHE OBINI IKUKU NISHE OBINI AMU ATAMU OBINI NISHE OMO ODUDUWA ADIFAFUN ALA ORUMILA AGBANIROGUN TAMALA MALA BALANSHE IWI ESHU NI OKUTE KULALEKE IWI BALELE IFA OMOKEKERE OFA MEYA GBOGBO ARAYE TOKU OSODE IFA LODAFUN ELEGBA.", "REZO: OGBE TUMAKO KAKUYE AYA KUKUYE AYA ARUN ATANA YUBARA KUMISAYA ADELEWA ORUNMILA ABUANI LEBO ABO LEBO ORUN IRE NIRA KEFEREFUN ESHU.", "SUYERE: KUYE KUYE IKU BINI ATA MAYARU IKU BERE ELEGBA ABA- LONKA.", "SUYERE: KUELKE KUTE IKUMBILE KUYE IKU BERE UNLO ATA MAYARU IKU BERE UNLO ELEGBA OMODE.", "SUYERE: OZAIN SHIWIRI KUI KUI, OZAIN SHIWIRI KUI KUI OUN FERE MOLE EÑI ORUN EÑI ORUN, OZAIN SHIWIRI KUI KUI.", "REZO: OGBE TUMAKO IKU YEYE NISHO OBINI IKU KUKU NISHE OBINI AMU ATANU OBININISHO OMO ODUDUWA ADIFAFUN ALA ORUNMILA AGBONIREGUN TOMALA BELANSHE IGI ESHU NI OKUTA KULA-LALEKE IGI BELELE IFA OMOKEKE OFA MEYI GBOGBO ARAYE TOKU OSODE IFA LODAFUN ELEGBA."]}]$q$::jsonb),
(28,'ba5eecb4378d4784b71e6e5cffeff2dd','3fdd5ebd93f2d9177ebc67face06d84c',$q$[{"titulo": "Idea central", "texto": "Ogbè Òtúrá habla de ofrecer para tener paz, tranquilidad y felicidad. Un conflicto de trabajo se resolverá a favor de la persona. La fortuna puede llegarle tarde en la vida, y no debe entristecerse por eso: le toca trabajar en la juventud y ofrecer por larga vida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un conflicto en el trabajo y quiere resolverlo sin perder la calma.", "Desea adquirir bienes o que le lleguen oportunidades a casa (relato de Ọlomo-Agbeti).", "Se impacienta porque el éxito material tarda; puede llegar en una etapa más avanzada de la vida.", "Debe repartir bien su esfuerzo entre la juventud y la madurez (relato del Amanecer y el Crepúsculo).", "Busca paz o dirección espiritual (relato de Ọ̀rúnmìlà al llegar al mundo).", "Está tan cómodo con lo que tiene ahora que puede descuidar el futuro."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["El conflicto en el trabajo se resuelve a su favor.", "Que los bienes lleguen solos hasta su puerta.", "Paz, felicidad y que nunca caiga en desgracia.", "Hijos y paz mental."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la visión mística. (Este Odu habla de la claridad, especialmente referente a la evitación de la posibilidad de comportamiento de destrucción misma).", "origen_id": "efda9a024d6858cdd03376ec"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Descuidar la juventud y llegar sin nada a la vejez.", "Vivir sin ofrecer: no hay paz sin ofrenda.", "Perder la calma."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva al delirio del mismo. (Este Odu habla de la posibilidad de satisfacción creando la perdida).", "origen_id": "a9c38fc755f446ecab49a7bf"}]}, {"titulo": "Enseñanza principal", "texto": "Ni siquiera Ọ̀rúnmìlà tiene paz sin ofrecer. Quien hace el bien, sobre todo a los pobres, siempre tendrá felicidad; y quien trabaja en su amanecer tiene un buen atardecer."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbètúrá habla de hacer sacrificios para garantizar tener paz, tranquilidad y felicidad.", "origen_id": "d739d6389657860f83f486ba"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà nunca cae en desgracia. Cuando Ọ̀rúnmìlà venía a este mundo, le dijeron que nunca caería en desgracia si ofrecía una chiva, una rata y un pescado. Ofreció, y desde la creación no ha caído. Él creó la tierra, fue el primero en pisarla, formó a los adivinos y puso a cada Odù en su lugar, y aun así nunca dejó de hacer sus ofrendas: demostró que nadie tiene paz sin ofrecer.", "Ọlomo-Agbeti. Ajiwoye-odẹdẹ le dijo a Ọlomo-Agbeti que todo lo que adquiriera le llegaría fácil, hasta la puerta de su casa. Le marcaron una rata, un pescado y dos imágenes. Cumplió.", "El Amanecer y el Crepúsculo. Ifá consultó para el Amanecer y para el Crepúsculo y les pidió ofrecer a los dos. El Amanecer cumplió y el Crepúsculo no. Por eso, quien está en el amanecer de su vida debe trabajar y formar su hogar, y eso le dura hasta sus últimos días. Canto: 'Este es mi amanecer; si mi atardecer es bueno, tendré muchas bendiciones'.", "Oníjùmu y los muchos niños. La esposa de la casa vale más que la amante. Oníjùmu preguntó si tendría hijos; ofreció, tuvo paz y exclamó sorprendido: '¡Ando con muchos niños!'."], "pasajes": [{"titulo": "Verso 28.1", "texto": "fueron quienes adivinaron Ifá para Ọ̀rúnmìlà,\ncuando él venía a este mundo,\nEllos dijeron: \"él nunca estará en desgracia\"\nUna chiva, una rata y un pescado\ndebian ser el sacrificio.\nỌ̀rúnmìlà escuchó el ẹbo y lo ejecutó,\npor lo tanto desde la creación del mundo,\nỌ̀rúnmìlà nunca ha estado en desgracia\nhasta hoy día.\nỌ̀rúnmìlà creó la tierra,\nfue el primero que la pisó,\nentrenó a los adivinos de Ifá\ny situó los Odù en sus respectivas posiciones\na pesar de todas esas cosas,\nél nunca se volvería sordo\nhacia los sacrificios prescritos por él,\nporque él ha demostrado\na todos los seres humanos\n\"que no pueden tener paz sin hacer sacrificio\".\nEsto ha sido claramente expresado\nen muchas lecciones de Ifá,\nque los seres humanos\nno pueden vivir pacíficamente sin ofrecer \"sacrificios\".\nAdemás, pequeños sacrificios\npreviene de la muerte prematura.\nCualquiera que desee tener una buena fortuna\ndeberá siempre ofrecer sacrificios.\nCualquiera que cultive el hábito de hacer bien,\nespecialmente a los pobres, siempre tendrá felicidad.", "origen_id": "b712b99d539a32cdcf8c4869"}, {"titulo": "Verso 28.2", "texto": "Ajiwoye-odẹdẹ:\nadivinó Ifá para Ọlomo-Agbeti.\nEl adivino dijo:\n\"todas sus adquisiciones\nvendrán fácilmente a él, a su portal (balcón)\".\nRata, pescado y dos imágenes son el sacrificio.\nEl escuchó y ejecutó el sacrificio.", "origen_id": "1984b6f688fbb48891ac311c"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que muy buenas cosas vienen al encuentro\nde esta persona. Siempre y cuando esta persona\nestá destinada a tener fortuna casi al final de su\nexistencia, asunto que no deberá entristecerlo,\nporque deberá ofrendar solo para una larga vida\n(longevidad).\nIfá le pide ser una persona tranquila y de mucha\ncalma, que deberá sacrificar en pos de su Ệgbérun,\nasí como congregar y alimentar a niños muy\npequeños.\n\n        Ệmợ níí forí gbón nini jáko\n        Òyà níí kò rùmùrùmù wợdò\n              A dífá fún Ààrò\n                A bu fún Alè\n           Wón ní kí Ààrò rúbợ\n          Wón ní kí Alè náà ó rú\n                 Ààrò rúbợ\n             Alè náà ò gbéyìn\n        Béèyán bá wà ni oko ààrò\n                  Yóó şişé\n                Yóó lòbínrin\n             Níí dalé kokooko\n                   Wón ní\n        Ệmợ níí forí gbón nini jáko\n        Òyà níí kò rùmùrùmù wợdò\n              A dífá fún Ààrò\n                A bu fún Alè\n                 Ààrò rèé o\n                Alè ni ń tợrợ\n             Bálé bá sunwợn\n                  N ó sajé\n\nEs la rata Ệmợ quien usa su cabeza para sacudir el\ncésped húmedo en la granja\nEs el cortador de césped quien entra al río con\ntorpeza\nLanzaron Ifá para el amanecer y para el crepúsculo\nLes dijeron a ambos que sacrificaran\nAmanecer lo realizó. Crepúsculo lo omitió\nSi uno está en los albores de su vida, se deberá\nlaborar, para poder contraer matrimonio\nY esto le durará hasta sus sombríos días\nEs la rata Ệmợ quien usa su cabeza para sacudir el\ncésped húmedo en la granja\nEs el cortador de césped quien entra al río con\ntorpeza\nLanzaron Ifá para el amanecer y para el crepúsculo\nEste es mi amanecer, porque estoy comenzando mi\ncrepúsculo\nSi mi crepúsculo es perfecto, tendré muchas\nbendiciones\n\n        Ìdérí Apó ò sunwòn sunwòn\n                  Kó ju Apó\n       Ợgbợgbợ Àgbợnyín ò sunwòn\n             Ò sunwòn ju Ekùn\n           Àgbélé ilé yìí sunwòn\n               Ò ju Omidan lợ\n          A dífá fún Oníjùmu nàkí\n       Ợmợ Ajợká nahín nahín bímợ\n             Òun le bímợ láyé?\n                  Ó bá rúbợ\n               Ợkaàn rè balè\n                 Ó ní Ìsinmi\n                   Òun náà\n       Lòún ń kó ợmợ wẹẹrẹ kiri yìí?\n          N ní wá ń jó ní wá ń yò\n\n          Ní ń yìn àwợn Babaláwo\n          Àwợn Babaláwo ń yìn Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n        Ìdérí Apó ò sunwòn sunwòn\n                  Kó ju Apó\n       Ợgbợgbợ Àgbợnyín ò sunwòn\n              Ò sunwòn ju Ekùn\n            Àgbélé ilé yìí sunwòn\n               Ò ju Omidan lợ\n          A dífá fún Oníjùmu nàkí\n       Ợmợ Ajợká nahín nahín bímợ\n           Èyin ẹ wòmùdúun Kókò\n          Ệ wáá wợmợ ekin yááyo!\n\nLa tapa de la mochila no se desea tan bonita\nPara ser mejor que la tapa de la mochila\nEl exterior mejor de la selección de los antílopes\nPodría no ser mejor que el de los leopardos\nLa esposa en la casa es mejor, mucho mejor que la\nconcubina\nLanzaron Ifá para Oníjùmu nàkí\nEl hijo de Ajợká nahín nahín bímợ\n¿Tendré hijos en la Tierra?\nEntonces él realizó los sacrificios prescritos por Ifá\nY tuvo paz mental (Irorun)\nY sorprendido exclamó: ¡Yo!\nEstoy yendo con muchos niños.\nY comenzó a bailar y regocijarse y alabó a sus\nbabaláwo\nEllos alabaron a Ifá\nEl hizo y dijo lo mismo que los babaláwo le dijeron\nque dijera e hiciera\nLa tapa de la mochila no se desea tan bonita\nPara ser mejor que la tapa de la mochila\nEl exterior mejor de la selección de los antílopes\n\nPodría no ser mejor que el de los leopardos\nLa esposa en la casa es mejor, mucho mejor que la\nconcubina\nLanzaron Ifá para Oníjùmu nàkí\nEl hijo de Ajợká nahín nahín bímợ\nÈyin ẹ wòmùdúun Kókò\nỆ wáá wợmợ ekin yááyo!", "origen_id": "a892bbcbb69afee82cf69a17"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbetura habla de sacrificios garantizando la paz y la felicidad.\n             WO - Conflictos en el trabajo serán llevados a favor del cliente.\n\n\n28.1 · Para, el amigo del azadón (Oko) y Adede, el amigo del machete\n         (ada) adivinaron Ifá para Orunmila, mientras él venía a este mundo,\n             le fue dicho que él nunca estaría en desgracia. 1 chiva, 1 jutía, 1\n            pescado deberán ser sacrificados. Orunmila escuchó el ebbo y lo\n     ejecutó, por lo tanto desde la creación del mundo, Orunmila nunca ha\n                                            estado en desgracia hasta hoy día.\n             Orunmila creó la tierra, fue el primero que la pisó, entrenó a los\n           adivinadores de Ifá y situó los Odu en sus respectivas posiciones a\n\npesar de todas esas cosas, él nunca se volvería sordo hacia los\n    sacrificios prescritos por él, porque él ha demostrado a todos los seres\n     humanos “que no pueden tener paz sin hacer sacrificio”. Esto ha sido\n            claramente expresado en muchas lecciones de Ifá, que los seres\n           humanos no pueden vivir pacíficamente sin ofrecer “sacrificios”.\n            Además, pequeños sacrificios previene de la muerte prematura.\n     Cualquiera que desee tener una buena fortuna deberá siempre ofrecer\n                 sacrificios. Cualquiera que cultive el hábito de hacer bien,\n                     especialmente a los pobres, siempre tendrán felicidad.\n\n\n28.2 · Ajiwoye-odede adivinó Ifá para el Olomo-Agbeti. Le fue\n           profetizado que todas sus adquisiciones vendrían fácilmente a él\n                  desde su balcón. 1 jutía, 1 pescado, 2 imágenes deben ser\n                            sacrificadas. Él escuchó y ejecutó el sacrificio.", "origen_id": "77bc52fc8abce79fb781d4a8"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: una chiva, una rata y un pescado.", "Ọlomo-Agbeti: una rata, un pescado y dos imágenes.", "Larga vida: ofrenda a su Ẹgbẹ́ (compañeros espirituales) y dar de comer a niños pequeños."], "pasajes": [{"titulo": "Ofrenda en el verso 28.1", "texto": "fueron quienes adivinaron Ifá para Ọ̀rúnmìlà,\ncuando él venía a este mundo,\nEllos dijeron: \"él nunca estará en desgracia\"\nUna chiva, una rata y un pescado\ndebian ser el sacrificio.\nỌ̀rúnmìlà escuchó el ẹbo y lo ejecutó,\npor lo tanto desde la creación del mundo,\nỌ̀rúnmìlà nunca ha estado en desgracia\nhasta hoy día.\nỌ̀rúnmìlà creó la tierra,\nfue el primero que la pisó,\nentrenó a los adivinos de Ifá\ny situó los Odù en sus respectivas posiciones\na pesar de todas esas cosas,\nél nunca se volvería sordo\nhacia los sacrificios prescritos por él,\nporque él ha demostrado\na todos los seres humanos\n\"que no pueden tener paz sin hacer sacrificio\".\nEsto ha sido claramente expresado\nen muchas lecciones de Ifá,\nque los seres humanos\nno pueden vivir pacíficamente sin ofrecer \"sacrificios\".\nAdemás, pequeños sacrificios\npreviene de la muerte prematura.\nCualquiera que desee tener una buena fortuna\ndeberá siempre ofrecer sacrificios.\nCualquiera que cultive el hábito de hacer bien,\nespecialmente a los pobres, siempre tendrá felicidad.", "origen_id": "8bf9fdea0235f5cc4d49dd07"}, {"titulo": "Ofrenda en el verso 28.2", "texto": "Ajiwoye-odẹdẹ:\nadivinó Ifá para Ọlomo-Agbeti.\nEl adivino dijo:\n\"todas sus adquisiciones\nvendrán fácilmente a él, a su portal (balcón)\".\nRata, pescado y dos imágenes son el sacrificio.\nEl escuchó y ejecutó el sacrificio.", "origen_id": "1c74908dfd789545f4440e10"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es el modelo de quien ofrece siempre. El Ẹgbẹ́, los compañeros del cielo, reciben ofrenda para la larga vida."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Rata, pescado, chiva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 28.1 (yorùbá): Para Oluku oko, / Odẹdẹ Oluku Àdá: / li o difá f'Ọ̀rúnmìlà / nigbi oun mi bowa si òde Ayé. / Wọn ni: \"koniitẹ titi\" / Ewúrẹ, eku ati ẹja li ebọ. / Ọ̀rúnmìlà gbọ̀ ebọ ó rú. / Nitorinaa lati igbati a ti da Ayé, / Ọ̀rúnmìlà ko tẹ titi o fidi ònì olóni yi. / Ọ̀rúnmìlà li o da llẹ̀, Ôun li o kọ tẹ̀ẹ̀. / Òun li o kọ àwọn awo ni Ẹkọ Ifá / tio si fi àwọn Odù si ayé wọn. / Sibẹsibẹ oun kiikọ eti didi si ebo / tiaba yan fún un, / nitori ti oun ti fihan / gbogbo ẹda alaayé pe: / A kiigbaiṣẹbọ ki ara kioro'ni. / Nibi pupo ninu Ẹkọ Ifá / li a si nri apẹẹrẹ rere rẹ pe: / Ọmọ èniyàn ko le gbaiṣẹbọ / ki ara ki o rọọ. / Ati pe: / Ẹbọ kekeke ni nigba alàikú la. / Ẹniti o ba si nwa ire liomaa nṣ'ẹbọ. / Eniti o ba si fẹran iwà ooreṣiṣe paapaa / fún àwọn alaini oun paapaa / ko niiye ni idunnu. / Para, el amigo del azadón (oko) / Odẹdẹ, el amigo del machete (Àdá):", "Verso 28.2 (yorùbá): Ajiwoye-odẹdẹ: / li o difá fQlọmo-Agbeti. / Wọ̀n ni: / \"Gbogbo inkan ti o maa ni, / odẹdẹ ni wón o maa wa baa\". / Eku, ẹja, ati aworan Méjì li ebọ. / Ô gbọ̀ ó rú.", "REZO: OGBE TUANILARA MOFOU SESI ONIBARABANIRE AYEGUE OLUWOPOPO FUYERE ADDE KUE BAYAMI ARAGBA KALEKUN ABEKUN MOFOU SESI AYERE NI IFA OLOFIN ADIFAFUN OLUWO-POPO.", "SUYERE: AWO OBA YEMILO ORUNMILA AWO YEMILO ASHEBO ASHETE ASHE LOMO ASHE LOWO ARIKU BABAWA.", "REZO: OGBE TUA MOFEU SESI ADIFAFUN OLUWO ALADE MOFEU SESI ADIFAFUN AYAPA TIROKO LELE NIFA EYEGUE ODUDUWA MOWALE YERE OLOFIN.", "REZO: OGBE TUA GUA GUA AWOSOYU ADIFAYOKE KONDUN OYA IBON MERUN ADIFAFUN AYA UMBATOLO IYA META GBOGBO IGI INYA OMA ORUNMILA LORUBO.", "REZO: OGBE TUA LARA KATIYERE EKU OGDABA ARO SHAROMODO LARO SHARO OBATALA EDUN SHEPO EKUTE INA KAFEREFUN OBATALA KAFEREFUN OZAIN ADIFAFUN ORUNMILA LODAFUN ELEGBA.", "REZO: OGBE TUA ADIFAFUN AWONI MERIDILOGUN OBGADO IFA ODDUN OGIDE EWINI ODDUN IYASI EDUN POKON LADO EJEPA OKOTASHE INLE OGBE TUAMORO OYA IFE OBA LODAFUN OLOFIN, KAFERE-FUN ODUDUWA, ADIFAFUN ORUNMILA.", "REZO: OGBE TUA NIKO TINSHOMO GUAYE ADIFAFUN OBA YEBE UN KAHIN ALE OMO SHANGO LORUBO.", "REZO: OGBE TUALARA ADIFAFUN AWO LARERE ILOBAYE NI OBALUMA ADIFAYOKO OLOFIN LADE ABAYE ONI BABALAWO LARRE AYE BARABO NIREGUN OLUO SIWAYU LODAFUN ORUNMILA SHANGO Y OGGUN.", "REZO: OGBE TUANILARA OBANI SHANGO ONI IRE IYA OBOYENI IFA ORUNMILA ILE YENYO SHANGO OBANI OKUE JEKUE OZAIN ORUPUE OBA YENTE OKO EWO NI SHANGO OBANI LORUN OBEBUFUN EYELE MEDILOGUN APARO MEDILOGUN BEYEKU IFA.", "REZO: ADIFAFUN IYABAFUN IYA OGIEDAY OMO BI OBA MAKASHE BABA OSAWANI IYA NI OBONO IYABAFUN IYA NI OBONO IYABAFUN IYA OLONO LELE INLE OGUNDAY IWA METETA LERI ASANI OMOLOGO OGUNDAY BABAWA IYABAFUN IYA KERE OGUNDAY IYA IWE METETA LERI OBALELE ODARA BI EGGUN BABA OSAWANI ARUBO YAKON LALE OSA RA BIEMESAN ODDUN MESAN ODDUN MESAN IYABAFUN ASHE ALO OMO OGUEDAY NIWAGUE ALAKAN SHOSHO AYO LERI OGBE TUANILARA OSAWANI SATAMASIA AWO OSHENBOKO LELU LELE KAFERFUN ORUNMILA LODAFUN OLOFIN.", "SUYERE: AWO OBA YEMILO ORUNMILA AWO YEMILO, ASHEBO ASHETO ASHE LOMO ASHE LOWO ARIKU BABAWA.", "SUYERE: AWO TENIYO NI EBBO GUNUGUN ASHE NI EBBO GUNUGUN ASHE NI OLORUN GUNUGUN ASHE NI ASHE GUNUGUN ASHE ORISHA OLORUN.", "SUYERE: OGUEDAY ASHE OMO FUN WAWAO OMO KEKE ODARA NI LAYE.", "SUYERE: ORUGBA LELE OMO INLE SHEPE OMO LELE ENI BONSI EUN NI KAYE.", "SUYERE: INLE OGUERE AWO LOYA ADIE, ADIE BABA OGBE TUANILARA,BABA AWO MOREYA, AWO LOYA ADIE, ADIE BABA.", "SUYERE: ODUDUWA AREMO SOKUN LOMASHE MUDARE ODARA EMIDARA.", "SUYERE: AJA BEKUN BELO KOIÑA, AJA BELE KOIÑA KOIÑA APUANIYE.", "REZO: ADIFAFUN AWONI ERIDILOGUN OBAGDO IFE AWO ODDUN OGIDE EWENI ODDUN IYASI EDUN POKON LADE EJEPA OKOTASHE INLE OGBE TUAMORA OYA OBA LODAFUN OLOFIN, KAFEREFUN ORUNMILA, KAFEREFUN ODUDUWA."]}]$q$::jsonb),
(29,'29622926d008cf377960ea8920334c70','eb17c9a31864f3c7ee2d78381521ffc3',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìrẹtẹ̀ habla de evitar problemas y de viajes prometedores. Hay riesgo de perder un trabajo o una relación. Tres personas que no son hermanas de sangre pueden unir esfuerzos y hacerse ricas; la fortuna llega desde otra ciudad o del campo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder un empleo o una relación y debe ver qué cuidar y qué cambiar.", "Planea un viaje y debe saber si es una oportunidad real o un movimiento sin propósito.", "Personas que no son familia pueden unirse y salir ganando (relato de Erin, Ẹfọn y Eṣinṣin).", "Un negocio en otra ciudad o un trabajo de campo puede traer dinero a casa (verso de Ọ̀rúnmìlà).", "No quiere escuchar una advertencia concreta (relato de Ewọn, Iro e Ìgèdè).", "Se siente estancado y la terquedad no le deja cambiar el plan."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riquezas que llegan por los caminos, desde la ciudad.", "Una sociedad entre personas que no son familia que da mucho fruto.", "Influencia, honor y riqueza.", "Vencer en una disputa por algo deseado."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto requiere determinación. (Este Odu habla de la necesidad de evitar viajes innecesarios).", "origen_id": "78f8917f53d940f1a7072d5d"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder el trabajo o la pareja.", "Ir a donde Ifá prohibió ir.", "Que los enemigos deseen que caiga en manos de los ajogun."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la testarudez (Este Odu habla de la posible pérdida a través de accidente u enfermedad.)", "origen_id": "1d9eabb59a49745c954bf827"}]}, {"titulo": "Enseñanza principal", "texto": "Cuando Ifá dice que no se vaya, no se va. Ewọn e Iro desobedecieron y murieron en la granja; solo Ìgèdè volvió, gracias a la ofrenda de Àgbọnnìrègún."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè-Ate habla de evitar los problemas y de esforzarse en crear el potencial necesario para efectuar viajes prometedores (hacer los sacrificios).", "origen_id": "cf30590e3de4d75984fe7005"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ewọn, Iro e Ìgèdè en la granja. Iyalẹtajaja consultó para Ewọn (la cadena), para Iro (la opinión) y para Ìgèdè (el encantamiento), descendiente de Àgbọnnìrègún, y les advirtió que no fueran a la granja porque ahí encontrarían a la muerte. No hicieron caso. A la mañana siguiente fueron, y Ikú mató a Ewọn y a Iro y se tragó a Ìgèdè. Àgbọnnìrègún fue a ver a su babaláwo, que le marcó una pluma de loro, cuentas tutu-opon, tres recipientes de ñame machacado y siete palomas, para ofrecerlos en la granja al amanecer. Al llegar encontró los cuerpos de Ewọn y de Iro en el suelo. Ikú lo llamó, vomitó a Ìgèdè en su mano y le pidió que se lo tragara, diciéndole: 'Àgbọnnìrègún, tú siempre lo devolverás cada vez que haya grandes problemas'.", "Los caminos traen riqueza. Asanigboro, Arinnigboro y Oburin-burin consultaron para Ọ̀rúnmìlà y le dijeron que los caminos le traerían riquezas desde la ciudad. Le marcaron una rata, un pescado y una gallina, y con ellos se apaciguó a Ifá.", "El elefante, el búfalo y la mosca. 'El gallo que cantó ayer cantó de buen agüero.' Así consultaron para el elefante, que lloraba porque no tenía influencia; para el búfalo, que lloraba porque no tenía honor; y para la mosca, que iba a escoger tierra virgen para la cosecha. Los tres ofrecieron. El elefante se volvió influyente, el búfalo honorable y la mosca regresó del campo inmensamente rica.", "La pata solitaria de Ogbè. Le deseaban la muerte a uno que construía una mansión tras otra pero dormía en el suelo, vestía harapos y no tenía con quién jugar. Era la pata solitaria de Ogbè, que iba a pelear por conseguir a Ìrẹtẹ̀. Ofreció y ganó."], "pasajes": [{"titulo": "Verso 29.1", "texto": "lyalẹtajaja:\nadivinó Ifa para Ewon (cadena, prisión),\nlyalẹtajaja:\nadivinó Ifá para Iro (opinión, idea),\nlyalẹtajaja:\nadivinó Ifá para igèdè (encantamiento),\nel descendiente de Àgbọnnìrègún.\nEllos fueron advertidos a no ir a la granja.\nSi ellos iban a la granja,\nellos encontrarían la muerte (Ikú).\nEllos no escucharon.\nA la mañana siguiente fueron a la granja\ny encontraron a (Ikú) quien mató a Ewon y a Iro.\nÉl se tragó a lgèdé, el hijo de Àgbọnnìrègún.\nCuando Àgbọnnìrègún oyó la noticia,\nfue a ver al Babaláwo que adivinó Ifá para él.\nEl Babaláwo dijo que sacrificara:\nuna pluma de loro,\ncuentas de tutu-opon,\ntres recipientes grandes de ñame machacado\ny siete palomas.\nEl adivino dijo\n\"que sacrificara en la granja al amanecer\".\nÉl escuchó el sacrificio y lo hizo.\nAl llegar a la granja,\nse encontró el cadáver de Ewon en la tierra,\nel de Iro también estaba sobre la tierra.\nLa muerte (Ikú) llamó a Àgbọnnìrègún\ny vomitó a lgèdè sobre su mano\n(sobre la mano de Àgbọnnìrègún)\ny le pidió que se lo tragara.\nEl dijo:\n\"Àgbọnnìrègún,\ntú siempre vomitarás esto (lgèdè)\ncada vez que existan grandes problemas\".", "comentario": "Ewọn: cadena, significa: prisión, encadenamiento, pérdida de la libertad, encierro.", "origen_id": "b31e5a4a6bc82bfbb9e95084"}, {"titulo": "Verso 29.2", "texto": "Asanigboro,\nArinnigboro,\nOburin-burin bu-omi igboro bọ'jú:\nadivinaron Ifá para Ọ̀rúnmìlà.\nEllos dijeron:\n\"los caminos traerán las riquezas\na Ọ̀rúnmìlà desde la ciudad\".\nPor lo tanto él debe sacrificar:\nrata, pescado y una gallina.\nÉl escuchó y realizó el sacrificio.\nLa rata, el pescado y la gallina\nfueron usados para apaciguar Ifá.", "origen_id": "8c28f1f1cece6057789362ad"}, {"titulo": "Versos complementarios 1", "texto": "Ifá se refiere a tres personas que deberán combinar\nesfuerzos para crear riquezas o ganancias. Ifá dice\nque ellos no son hermanos de sangre. Si es una\npersona que realiza negocios, se le dirá que es de\notra ciudad o pueblo de donde él hará su fortuna. Si\nes campesino, regresará rico del campo. Ifá dice\nque sus enemigos desean que sea capturado por los\najogun, pero no sucederá. Ifá desea que sacrifique.\n\n             Àkùkợ tó kợ lanàá\n                Ìkợ ire ló kợ\n               A dífá fún Erin\n        Erin ń sunkúun póun ò lólá\n             Ệbợ n wón ní ó şe\n             Àkùkợ tó kợ lanàá\n                Ìkợ ire ló kợ\n              A dífá fún Ệfợn\n        Ệfợn ń sunkúun òún ò níyì\n             Ệbợ n wón ní ó şe\n             Àkùkợ tó kợ lanàá\n                Ìkợ ire ló kợ\n             A dífá fún Eşinşin\n    Ń lợ rèé bá wón múlẹ oko àì ródún\n             Ệbợ n wón ní ó şe\n\n        Àwợn mètééta bá rúbợ\n                Erin rúbợ\n             Ệfợn náà rúbợ\n          Eeşin náà ò gbéyin\n          Àwợn mètééta bá là\n Wón bá bèrè síí yin àwợn babaláwo\n       Wón ní Àkùkợ tó kợ lanàá\n              Ìkợ ire ló kợ\n             A dífá fún Erin\n      Erin ń sunkúun póun ò lólá\n           Ệbợ n wón ní ó şe\n                Erin rúbợ\n                 Erin lola\n           Àkùkợ tó kợ lanàá\n              Ìkợ ire ló kợ\n             A dífá fún Ệfợn\n      Ệfợn ń sunkúun òún ò níyì\n           Ệbợ n wón ní ó şe\n             Kó le baà níyì\n                Ệfợn rúbợ\n               Ệfợợn níyì\n           Àkùkợ tó kợ lanàá\n              Ìkợ ire ló kợ\nA dífá fún Eşinşin tíí sợmợ ìkéyìín wợn\n               leńje-leńje\n Wón ní ó rúbợ kó lè baà toko là wálé\n            Eeşin gbébợ ńbè\n                  Ó rúbợ\n     Eeşin wáá toko là wá inú ilé\n               Erin lola o\n                Ệfợn níyì\n          Eeşin nikàn ló roko\n                 Lòó lá o\n\n         Ifá póun pé ire fún eléyiun.\n\nEl gallo que canto ayer\nCantar es de buen agüero\nLanzó adivinación para el elefante\nQue gemía por no poseer influencias\nEl gallo que canto ayer\nCantar es de buen agüero\nLanzó adivinación para el búfalo\nQue gemía por no tener honor\nEl gallo que canto ayer\nCantar es de buen agüero\nLanzó adivinación para la mosca\nQue venía a escoger una tierra virgen en la cosecha\nanual\nA los tres se les pidió que ofrendasen y así lo\nhicieron\nLos tres se convirtieron en personas excesivamente\nricas\nEllos alabaron a sus babaláwo y dijeron:\nEl gallo que canto ayer\nCantar es de buen agüero\nLanzó adivinación para el elefante\nQue gemía por no poseer influencias\nEl elefante sacrificó y se llenó de fuertes influencias\nEl gallo que canto ayer\nCantar es de buen agüero\nLanzó adivinación para el búfalo\nQue gemía por no tener honor\nEl búfalo ofrendó y es ahora una persona altamente\nhonorable\nEl gallo que canto ayer\nCantar es de buen agüero\nLanzó adivinación para la mosca\nQue venía a escoger una tierra virgen en la cosecha\nanual\n\nSacrificó    y    regresó     del    campo,    siendo\ninmensamente rico\nEl elefante es influyente, el búfalo es honorable y la\nmosca es ahora riquísima\nIfá desea que esta persona sea o esté lleno de\nriquezas\n\n          Ogun n wón ni ó pá a\n            Ilé ni ń moó kún ilé\n          Okè èèpè ni à sàì sun\n           Akànpò èwù ni ń kàn\n       Kó níí rénìkan à á báá şeré\nOrí akợ ẹşin orí abo ẹşin ni wón tí ń bá a\n      A dífá fún ẹsẹ kan şoşo Ogbè\n        Ti ń lợ rèé bá Ìrètè şégun\n                 Ayé yẹ wón\n          N ní wá ń jó ní wá ń yò\n         Ní ń yìn àwợn Babaláwo\n         Àwợn Babaláwo ń yìn Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n          Ogun n wón ni ó pá a\n            Ilé ni ń moó kún ilé\n          Okè èèpè ni à sàì sun\n           Akànpò èwù ni ń kàn\n       Kó níí rénìkan à á báá şeré\nOrí akợ ẹşin orí abo ẹşin ni wón tí ń bá a\n      A dífá fún ẹsẹ kan şoşo Ogbè\n        Ti ń lợ rèé bá Ìrètè şégun\n            A şégun nígbà yí ò\n                   A şégun\n            Ệsẹ kan şoşo Ogbè\n         Ó ti bá Ìrètè şégun láyé\n\nEllos desean que la muerte lo asesine a él\n\nÉl estuvo construyendo una mansión después de la\notra\nEstuvo deseando dormir desnudo sobre el firme\nsuelo\nMás bien usaba harapos en vez de ropas\nNo hallaba a nadie con quien jugar\nEn cambio, él se encontró ya ensillados a las yeguas\ny a los sementales\nLanzó Ifá para la pata solitaria de Ogbè\nQue venía a pelear por obtener a Ìrètè\nSe le pidió ofrendar y así lo realizó\nLa vida, les fue placentera a ambos\nEllos danzaron y alabaron a sus babaláwo\nLos babaláwo alabaron a Ifá\nEllos hicieron lo que los babaláwo le dijeron que\nhicieran\nEllos desean que la muerte lo asesine a él\nÉl estuvo construyendo una mansión después de la\notra\nEstuvo deseando dormir desnudo sobre el firme\nsuelo\nMás bien usaba harapos en vez de ropas\nNo hallaba a nadie con quien jugar\nEn cambio, él se encontró ya ensillados a las yeguas\ny a los sementales\nLanzó Ifá para la pata solitaria de Ogbè\nQue venía a pelear por obtener a Ìrètè\nA partir de ahora hemos salido y somos victoriosos\nHemos ganado\nLa pata solitaria de Ogbè ha ganado la guerra por\nobtener a Ìrètè", "origen_id": "6b2e19e25502e1947c4e331f"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe Ate habla de la prevención de problemas y la creación de\n                              un potencial de prometedores viajes y esfuerzos.\n            WO - Pérdida potencial de un trabajo o de una relación del cliente.\n\n\n29.1 · Iyaletajaja adivinó Ifá para Ewon, Iyaletajaja adivinó Ifá para\n   Iro, Iyaletajaja adivinó Ifá para Igede, el hijo de Agbonniregun. Ellos\n         fueron advertidos a no ir a la granja. Si ellos iban a la granja, ellos\n            encontrarían la muerte (Ikú). Ellos no escucharon. A la mañana\n   siguiente fueron a la granja y encontraron a (Ikú) quien mató a Ewon\n             y a Iro, él se tragó a Aiyede, el hijo de Agbonniregun. Cuando\n   Agbonniregun oyó la noticia, fue a ver a su Babalawo que adivinó Ifá\n           para él. El Babalawo dijo que sacrificara. 1 pluma de papagayo,\n    semillas de tutu upon, 3 grandes palanganas de ñame machacado y 7\n          palomas. Le fue advertido que hiciera el sacrificio en la granja al\n                                                                    amanecer.\n                                           Él escuchó el sacrificio y lo hizo.\n          Al llegar a la granja, él se encontró con el cadáver de Ewon en la\n   tierra, el de Iro también estaba sobre la tierra. La muerte (Ikú) llama a\n   Agobnniregun y vomitó a Igede sobre la mano de Agbonniregun y le\n               pidió que se lo tragara, él dijo: Agobnniregun, tú siempre lo\n                          vomitarás (Igede) en los días terriblemente tristes.\n\n\n29.2 · Asanigboro, Arinnigboro, Obunrin-burin bu-omi igboro bo´ju\n     adivinó Ifá para Orunmila. Él predijo que Orunmila se enriquecería\n                                                                 en la ciudad.\n         Por lo tanto él debía ofrecer 1 jutía, 1 pescado, 1 gallina. Él oyó el\n         aviso y ejecutó el sacrificio. La jutía, el pescado, la gallina fueron\n                                                    usados para apaciguar Ifá.", "origen_id": "7e8b88f86ccca00fdb7e2765"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Àgbọnnìrègún: una pluma de loro, cuentas tutu-opon, tres recipientes de ñame machacado y siete palomas, en la granja al amanecer.", "Ọ̀rúnmìlà: una rata, un pescado y una gallina a Ifá.", "El elefante, el búfalo y la mosca: ofrenda por influencia, honor y riqueza."], "pasajes": [{"titulo": "Ofrenda en el verso 29.1", "texto": "lyalẹtajaja:\nadivinó Ifa para Ewon (cadena, prisión),\nlyalẹtajaja:\nadivinó Ifá para Iro (opinión, idea),\nlyalẹtajaja:\nadivinó Ifá para igèdè (encantamiento),\nel descendiente de Àgbọnnìrègún.\nEllos fueron advertidos a no ir a la granja.\nSi ellos iban a la granja,\nellos encontrarían la muerte (Ikú).\nEllos no escucharon.\nA la mañana siguiente fueron a la granja\ny encontraron a (Ikú) quien mató a Ewon y a Iro.\nÉl se tragó a lgèdé, el hijo de Àgbọnnìrègún.\nCuando Àgbọnnìrègún oyó la noticia,\nfue a ver al Babaláwo que adivinó Ifá para él.\nEl Babaláwo dijo que sacrificara:\nuna pluma de loro,\ncuentas de tutu-opon,\ntres recipientes grandes de ñame machacado\ny siete palomas.\nEl adivino dijo\n\"que sacrificara en la granja al amanecer\".\nÉl escuchó el sacrificio y lo hizo.\nAl llegar a la granja,\nse encontró el cadáver de Ewon en la tierra,\nel de Iro también estaba sobre la tierra.\nLa muerte (Ikú) llamó a Àgbọnnìrègún\ny vomitó a lgèdè sobre su mano\n(sobre la mano de Àgbọnnìrègún)\ny le pidió que se lo tragara.\nEl dijo:\n\"Àgbọnnìrègún,\ntú siempre vomitarás esto (lgèdè)\ncada vez que existan grandes problemas\".", "origen_id": "5155bf8aaea8f46dcecd68b6"}, {"titulo": "Ofrenda en el verso 29.2", "texto": "Asanigboro,\nArinnigboro,\nOburin-burin bu-omi igboro bọ'jú:\nadivinaron Ifá para Ọ̀rúnmìlà.\nEllos dijeron:\n\"los caminos traerán las riquezas\na Ọ̀rúnmìlà desde la ciudad\".\nPor lo tanto él debe sacrificar:\nrata, pescado y una gallina.\nÉl escuchó y realizó el sacrificio.\nLa rata, el pescado y la gallina\nfueron usados para apaciguar Ifá.", "origen_id": "2e133857e424dbe344eaa7c6"}]}, {"titulo": "Relaciones espirituales", "texto": "Ikú, la muerte, devuelve a Ìgèdè por la ofrenda. Àgbọnnìrègún (Ọ̀rúnmìlà) es quien rescata. Ifá recibe la rata, el pescado y la gallina."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pluma de loro, cuentas tutu-opon, ñame machacado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 29.1 (yorùbá): lyalẹtajaja: / li o difá f'Ẹwọn6a, / Iyalẹtajaja: / li o difá fún Iro, / lyalẹtajaja: / li o difá fún lgèdè / ti nṣe qmọ Àgbọnnìrègún. / A niki wọ̀n ma dẹ ṣi yun oko. / Wọ̀n nì: / \"Bi wọn ba lọ si oko naa / wọn a ba ikú pade\". / Wọ̀n ko gbọ̀. / llẹ mo wọ̀n lọ si oko. / Wọn si ba ikú pade. / Ikú pa Ewọn, o pa Iro, / o gbe İgèdè qmọ Àgbọnnìrègún mi. / Àgbọnnìrègún gbọ̀, / O tọ Babaláwo lọ wọn difá fún un / wọn niki ó rúbọ: / Ikoodẹ, / llẹkẹ tutu-opon, / àràbà-iyán mẹta / ati eyẹlé méje, / wọ̀n ni: / \"ki o gbe ẹbọ naa lẹsi oko ni iyalẹta\" / Ó gbọ̀ ó rú. / O d'oko o ba oku Ẹwọn nilẹ. / O ba oku Iro nilẹ. / Ikú pe Àgbọnnìrègún / o pọ lgèdè lee lọwọ o niki o gbee mi. / O ni: / \"ọjọ ti ọràn ba dun un niki O maa pọo\".", "Verso 29.2 (yorùbá): Asanigboro, / Arinnigboro, / Oburin-burin bu-omi igboro bọ'jú: / li o difá f'Ọ̀rúnmìlà. / Wọ̀n ni: / \"igboro ni Ọ̀rúnmìlà ma laa si\". / Nitorinaa ki ó wa rúbọ: / eku, ẹja, ati abo-adiyẹ. / Ó gbọ̀ ó rú. / Wọ̀n fi eku, eja ati abo-adiyẹ bo Ifá.", "REZO: OGBEREKUNTELE ODANDE IFA MAFEREFUN OGGUN. OGBEREKUNTELE ADDE IFA OBARABANIREGUN ORISHA WANEYI IFA MORI YEYEO ADIFAFUN ORUNMILA AKUALOSIÑA OMO IFA.", "SUYERE: OBAIKU BABA YERERE OMO OBOKOYE IKU SEWERE, ARUN SEWERE, OFO SEWERE, EYO SEWERE, BERELADE OBENIRE OBAYE.", "REZO: OGBE ATE OSADE ODANDE MERI YEYEO APETEBI WADA MAIBERU,APETEBI WADA MAIYOBA, APETEBI WADA MAIBOSHESHE. OSHUN MORI YEYEO IFA AYE MOWA EYE EYIDE EYERI OLOFIN BABA ORUN. ORUN LOYEBONI IFA OMO LAYE IKU AYEÑI IFEI ODEDE ORUN LAYE.", "REZO: OGBEREKUNTELE OSODE ODANDE ODANDE LAYE ODANDE ORISHA ODANDE ELA. ORUNMILA OMO IFA OLOFIN AGUENO AWETE ASHE OLOFIN, ASHE OGGUN OBAYE IFA EBBO SHANGO OBA KOSO OBAYE ORUNMILA OGBEREKUNTELE LETE OZAIN LAYE OBI KUALARA LAYE.", "REZO: OGBE ATE OGBE MATA ALUMEMATA OMO AWOSHE MAFITARUN ADIFAFUN OMO OBANISHE AIKORDIE, ADIE, EKU, EYA, ILA, EFUN, OU, OBATALA OWO MESAN.", "REZO: OGBE DANDE ADIFAYOKO ADIFAFUN ORUNMILA IFA FOTOLUSHO ADIFAFUN YALORDE.", "REZO: OGBE ATE OBA OBE IKUN ABURE IFA BEYE IDARE OBOKOYE.", "REZO: OKPELE EBEYEKUN WA EUMINIYO IYALORDE OWA NILORUN SUNINIYE OGGUN, OGGUN ARERE OWO OKPELE BANIYEKUN ORUNMILA APALOSIÑA OWO YEKUN OWONU ODARA AWENA WEÑA YEYEKUN OKPELE NISHABO IYALORDE OBEYARI OLORUN OKPELE MEYI AWANIEBANIWA ALA ALABOYARI ORUNMILA OKPELE NIKE YIRIKA OKUEBA BUKERE OBA BOKARE ONI OLORUN EYERE EGGUN OKPELE OGGUN ODARA.", "REZO: OGBE ATE AWO NIFA OSHAWA OGBONI OTORUN IFA OBADAWO OMO AWONI EMIMOLE BUBURU OSHA MAWO TOMBU IJERI OGBETE OMO- NI FAUNSODE NIFA OGBEATE TOKU ESHU BELU BELEBU OJO AWO GUNUGUN UMBO WAIYE BI AWO TINLU AWO DI OKE BELEBU KOMOPE IJERIJKU ANAIRERI OFELOSODE AWO LODAFUN IMOLE ORUN KAFEREFUN ORUNMILA.", "REZO: OGBE ATE ADIFAFUN OMOBIRIN ATOLE SHAWO EGUNGUN LAISUN ORUN EFE AKARE LODAFUN OSANYIN OMODERE OLOBINU ONI OLOSA.", "REZO: ORUN KAWADO OGBE ATE ARUN KOWADO OGBE ATE OMOLOGU,OGBE ATE ADAFORI ADI FAYOKO OSHUN ADIFAJOKO LODAFUN SHANGO OBANIREGUN ORUNMILA.", "SUYERE: ARERE OGGUN LAYEO OGGUN LAYE, BABA OGGUN LAYEO OGGUN LAYE.", "SUYERE DE EGGUN: EUERE WERE NITO WERE, AFARAMOYO KOTO FADILAMA OMO IKU WAMBE WAMBE FADILAMA FABAMANBE FADILAMA, EBBO EBBO FEREYE EÑI EBBO FEREYE UNYEN OLOYU WERE IKOKO.", "SUYERE DE EGGUN: EGGUN EKUN FEYU TANA ELUKEREKUN BEKUNSUN EGGUN LELE.", "SUYERE: OBOIKUN BABA YEYERE OWO OBOKOYE IKU SEWERE ORUN SHEWERE OFO SHEWERE EYO SHEWERE BERELADE ABENIRE ABOKOYE.", "SUYERE: EYE EYA LORIDEO OGGUN ALAGUEDE OGGUN LAYABA NILEO OGGUN OKPELE.", "SUYERE ARABA: EJU NIKOO O NANKO ESOFA MIKUO OMANKO AFA YOIBE MEDI LETE.", "REZO: ADIFAFUN OBERU KUNTELE YEDO AWO OBEDANDE ABERU OBERY TASHERE QUERE INLE TINWANILLE PAYA WE INTIVA AKUELE AWO OTOKAN ESON AKUELERI OBEDANDE OBERE KUNTELE LODAFUN YEMAYA KAFEREFUN AGOTEKU KAFEREFUN YALORDE.", "SUYERE: OBERU KUNTELE EYE MOKUE ENENKO ORISHA MIJUE OMANKO IFA EJIOGBE AWENDA IRETE.", "REZO: OGBE ATE AWO NIFA OSHAWO OGBONI OGBONI OTORUN EFA OBADAWO OMO AWONI EMIMOLE BUBURU OSHA MAWO TOMBU IJERI OGBE ATE OMONI EAUSODE NIFA OGBE ATE TOKU ESHU BELU BELEBU OJO AWO GUNUGUN UMBO WAIYE BI AWO TINLU AWO DI OKE BELEBU KOMOPE IJERIKU OFELOSODE AWO LODAFUN IMOLE ORUN KAFEREFUN ORUNMILA.", "SUYERE: LAMI LAMI OLORI AWO ALAWO IKU ONISHEGUN A ORUN OGBEDANDE AWO ODARA."], "pasajes": [{"titulo": "Sigidi ogbé irete — para la prosperidad", "texto_ritual": "Won ni yio lo nilkr ilé ni n món kun ilé Oke erupe ni kó sai sun akanpo ewu meji meji Ni n wo ni n wo bábá kio rere koní sun rere Orí ako esun loti n bó sori abo esin Áwon ni sefa fún orunmila Bábá nbe nirogun ota won ni baba ota yí po Orunmila ni nkankan koní sáeóufi Orunmila ni gbogbo won ni óuñ ó bori orunmila Ni oore ni oun ó si máá fi r¡ Oju oro ni n rata bó bo omi Ifá wá rata borní monje Kí owo olubi ó le dé ódo mi Osibata ni n raté bó ódo Ifá wá rata borní monje Ki owo olubi ó le dé odo mi Ata ilé ni n rate bó ilé awun otooto Kí ilu won kíí pe jo je iyan amann Ifá wá rata borní monje Kí owo olubi ó le dé odo mi Ifá monje kí owo ara aye ó peju jo leseni nibi Orí mi ni kí n mon fi según Orí oka ni oka fi n según Iru akéké fi según ota re oko kan soso ni Sango fi nsegun Igbá ota, ogbé ate, Ifá wá teri gbogbo ibi monle fún mi", "traduccion": "Dijeron que debe abandonar el pueblo. Es la casa la que sigue construyendo con otros. Es la arena la que no para de dormir. Es una combinación de dos ropas la que él usa. Si muere bien, no deberá dormir bien. Es el caballo el que monta a la yegua. Hicieron adivinación para orunmila cuando estaba en medio de enemigos. Le dijeron que sus enemigos eran muchos. Y dijo que nada le pasaría a él y que oba a salir victorioso sobre ellos. Será la riqueza la que usará para ver oju oro cubierta con agua. Ifá, ven y cubre el agua. No dejes que el que hace el mal tenga que ver conmigo. Es osibata el que cubre el agua. Ifá, ven y cúbreme. No dejes que el que hace el mal tenga que ver conmigo. Es ata (una raíz) la que cubre la casa. La gente importante del pueblo no recoge ñame molido al segundo día para comer. Ifá, ven a cubrirme y no me dejes al poder del mal. Ifá, no dejes que la gente me haga daño a mí. Que yo sea victorioso con mi propia cabeza. La cobra usa su cabeza para tener la victoria. Con una sola piedra Sango le gana a sus enemigos. Ogbé afe ifá, ve a derrotar a mis enemigos.", "origen_id": "7ab400bdce56903c76ec7c7f"}]}]$q$::jsonb),
(30,'f6ac59075ceb651da5233e9f3525fb4f','1bd378771687f0a16259ae014adfefd1',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀ṣẹ́ trae buenas noticias y logros que se celebran con otros. Anuncia cambios buenos en la relación de pareja. También habla de alguien que lo ha intentado todo sin éxito, o que compró algo de lo que se arrepiente: Ifá dice que a la larga eso le traerá riqueza."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que mejore su relación de pareja o que llegue una celebración compartida (relato de Oloidẹ y Ami).", "Ha probado de todo sin resultado y se pregunta si algún día prosperará (relato del loro Odídẹré).", "Hizo una compra que lo dejó con dudas, pero puede valer más adelante.", "Necesita atender su cabeza (Orí) y revisar cómo toma decisiones (relato de Irẹṣu-ele).", "Busca dinero o hijos y lleva tiempo sin ver avances.", "Hay motivo para celebrar con otros, sin dejar que el interés económico mande en la relación."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Celebración compartida y prosperidad en pareja.", "Que todo el mundo venga a festejar con uno.", "Lo que parecía una mala compra se convierte en fortuna.", "Hijos para quien no los tenía."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la Buena fortuna. (Este Odu habla de honrar a Osun para crear paz de la mente y abundancia)", "origen_id": "0bc8b3388349e064b6ec9c99"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Desesperarse antes de tiempo.", "Despreciar lo que se tiene porque no se le ve valor.", "Descuidar la cabeza (Orí)."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la avaricia. (Este Odu habla de evitar la avaricia honrando a Ogun)", "origen_id": "aa783036cf192a5bd0e4f814"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que parece inútil puede ser la fuente de la riqueza. El esclavo cojo que Òòṣààlá creyó una pérdida fue quien lo hizo rico."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'Sé habla de buenas noticias y logros que serán llamados a celebrar.", "origen_id": "ed56d7cc1704f0c817341b8d"}]}, {"titulo": "Relatos reunidos", "puntos": ["Oloidẹ presenta a Ami. Oloidẹ iba a tomar a Ami como novia y le dijeron que todo el mundo vendría a celebrar con ellos cuando prosperaran. Le marcaron una chiva y cumplió. Un día todos los pájaros le pidieron conocer a Ami; Oloidẹ los citó en la plaza con vino de palma y bebidas. Después de comer y beber, el loro les presentó a Ami cantando: 'Vengo a mostrarles a Ami'. Todos cantaron y bailaron con él.", "Ìrẹṣu-ele y la cabeza. Ṣẹẹṣẹ y Wopwọ le dijeron a Ìrẹṣu-ele, que venía de Òde Àjàláyé, que Ògún sería el único que le arreglaría la cabeza. Le marcaron un cesto lleno de cáscaras de nuez de palma, tres gallos, un ñame asado y 6,600 cauríes. Cumplió.", "El loro y su sangre de cada mes. Odídẹré, el loro, había intentado de todo sin lograr nada; no tenía riqueza ni hijos, y cada mes sangraba. Le pidieron ofrecer y cumplió. La vida le cambió: sus plumas rojas de la cola se volvieron fuente de riqueza, y su sangre de cada mes se convirtió en un hijo.", "Òòṣààlá y el esclavo cojo. Òòṣààlá compró como primer esclavo a un hombre cojo y se lamentó de haber tirado el dinero. Lo mandó a su milpa creyendo que ahí tampoco serviría. Un día de descanso, Òòṣààlá se fue a la ciudad. El cojo vio que los loros se comían las mazorcas, aflojó la tierra al pie de las matas, y cuando los loros se posaron las matas cayeron y las aves quedaron atrapadas con las patas en la tierra. Las fue metiendo en un gran cesto. Al regresar, Òòṣààlá vio la milpa destruida y se enfureció, pero en la casa encontró el cesto lleno de loros. El cojo le dijo que vendieran sus plumas rojas, y fue un gran negocio. Le cantaron: 'El esclavo que compraste te hizo rey; no gastaste en vano'."], "pasajes": [{"titulo": "Verso 30.1", "texto": "Ero-ilé-komopet'onà-nbọ\nadivinó Ifá para Oloidẹ\ncuando iba a tomar a Ami como novia.\nEl adivino dijo:\n\"todo el mundo vendrá a celebrar con ellos\ncuando sean prósperos en la vida\"\nUna chiva debía ser sacrificada.\nÉl oyó el aviso e hizo el sacrificio.", "comentario": "Un día todos los pájaros se reunieron y hablaron a Oloidẹ para conocer a Ami, Oloidẹ convino con ellos y les instruyó que se reunieran en la plaza del mercado provistos de vino de palma y otras bebidas alcohólicas fuertes. El día de la reunión, todos los pájaros se reunieron en el arbusto de la asamblea con el vino y el alcohol. Después que ellos finalizaron de comer y beber, el loro (Odiderẹ) mostró a Ami a todos los pájaros.\nEl canto y bailó: yo he venido a mostrarte a Ami. Oloidẹ, yo he venido a mostrarte a Ami. Oloidẹ, yo vengo a mostrarte a Ami a todos los pájaros Ellos fueron felices y todos se unieron para cantar y bailar junto con él.", "origen_id": "7815f75de9f98af33c741ff8"}, {"titulo": "Verso 30.2", "texto": "Ṣẹẹṣẹ, Wopwọ:\nadivinó Ifá para Irẹṣu-ele,\ncuando estaba viniendo de Òde Àjàláyé.\nEllos dijeron:\n\"Ogún será el único que reparará su cabeza (orí)\"\nPor eso él debía sacrificar:\nun cesto lleno de cascarones de nuez de palma,\ntres gallos, un ñame asado\ny 6600 cauris.\nÉl escuchó y realizó el sacrificio.", "comentario": "69 Apèrẹ̀: cesto.\n7° iwẹn: cascaron de la nuez de palma aceitera.", "origen_id": "c09f6d91bcc9c263b2ce5f61"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le pide a esta persona sacrificar para que\nsiempre se encuentre con sus bendiciones y\nfortunas. Ifá le dice que las buenas cosas le pasean\no mejor dicho, pasan por su lado, sin llegarle a\ntocar. Deberá ofrendar la piel de una hiena. Le\naconsejan que sacrifique bien a Ifá con tal que él\npodría tener algo para mostrar o demostrar.\nIfá dice que esta persona no deberá ser encarcelada\nni encerrada. Para evitar esto, se deberá preparar\nÈkuru, espolvorearlo con Iyerosun rezado y\nenterrarlo en la Tierra.\n\n             Ìkekere èyin Ààsè\n            A día fún Ifánírègún\n             Ti ti ń rin ti ò kore\n       Ệbợ ko le kore n wón ni o şé\n               Wón ní kó rúbợ\n                     Ó şe é\n                  Lajé bá dé\n                    Layá dé\n                    Ợmợ dé\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n             Ìkekere èyin Ààsè\n            A día fún Ifánírègún\n             Ti ti ń rin ti ò kore\n       Ệbợ ko le kore n wón ni o şé\n           Ifánírègún gbébợ ńbè\n                    Ó rúbợ\n         Ire Ajé koó mợ le fò mí ru\n\n            Ire Àrìnnàkò ni n ó kò\n                  Ire àrìnnàkò\n         Ire Ayá koó mợ le fò mí ru\n            Ire Àrìnnàkò ni n ó kò\n                  Ire àrìnnàkò\n        Ire ợmợ koó mợ le fò mí ru\n            Ire Àrìnnàkò ni n ó kò\n                 Ire Àrìnnà kò\n   Şe bí pétípétí ni imí ẹşin i koraa wợn\n                 Ire Àrìnnà kò\n                       Ìkekere èyin Ààsè\n\nAdivinó Ifá para Ifánírègún\nQue había estado andando sin hallar ningún tipo de\nfortuna\nY es el sacrificio que se le pidió hiciera, lo que\npermitiría que se encontrase con la fortuna\nEl así lo hizo y sacrificó de forma plena\nRápidamente llegó la riqueza, y las esposas también\nllegaron\nY con ellas los innumerables hijos\nÉl bailó y se regocijo y alabó a sus babaláwo\nEllos alabaron a Ifá\nÌkekere èyin Ààsè\nAdivinó Ifá para Ifánírègún\nQue había estado andando sin hallar fortuna\nÉl oyó acerca de la ofrenda y la realizó\nNo dejes que la fortuna de la riqueza me esquive\nLas fortunas coincidentes que yo reuniré\nLas fortunas coincidentes\nNo dejes que la fortuna de la esposa me esquive\nLas fortunas coincidentes que yo reuniré\nLas fortunas coincidentes\nNo dejes que la fortuna de los hijos me esquive\nLas fortunas coincidentes que yo reuniré\nLas fortunas coincidentes\n\n¿No es tan duro ese excremento del caballo pero\npega y ata a cada uno de los otros?\nLas fortunas coincidentes que yo reuniré\nLas fortunas coincidentes\n\n       Pátàkó abèdò gbékè-gbékè\n       A día fún Àgbònyín gàgàlà\n           Èyí tíí sợmợ Olúugbó\n    Àwợn òtá láwợn o mùú Àgbònyín\n   Àgbònyín bá tợ àwợn Babaláwo è lợ\n        Wón ní kó fi èkuru bợ ilè\n              Ó bá bợ ilè tán\n           Wón lé Àgbònyín títí\n              Wón ò lè mú u\n        Bí ón bá si lé e, lé e ………\n             Àgbònyín a gbó\n                    Gbóò!\n     Wón a pé b`Àgbònyín bá tí gbó\n               Ợjợ ikú è ó yè\n  Ayé yẹ Àgbònyín gàgàlà ợmợ Olúugbó\n    Ó ni Pátàkó abèdò gbékè-gbékè\n       A día fún Àgbònyín gàgàlà\n           Èyí tíí sợmợ Olúugbó\n          Ni şojú ẹkùn òun Ợdẹ\n          Àgbònyín là wợn ò kú\n          Ni şojú ẹkùn òun Ợdẹ\n\nPátàkó abèdò gbékè-gbékè\nLanzó Ifá para Àgbònyín gàgàlà hijo de Olúugbó\nCuando sus enemigos habían concebido capturarle\nY al consultarlos con sus babaláwo, ellos le pidieron\nQue ofreciera èkuru a la Madre Tierra\nY él sacrificó\n\nEllos persiguieron y le dieron caza a Àgbònyín, pero\nnunca le capturaron\nY luego de un terrible tiempo de cacería\n¡Àgbònyín ladró!\n¡Guauuuuuuuuuu!\nEllos dijeron que: Una vez Àgbònyín hubiese\nladrado, su día predestinado para morir, había de\ncambiar\nLa vida le fue muy placentera a Àgbònyín gàgàlà\nhijo de Olúugbó\nEn presencia del cazador y del leopardo, devino\nsalvado y nunca murió\nEn presencia del cazador y del leopardo", "origen_id": "57c1c6a814e54773d90d1511"}, {"titulo": "Versos complementarios 2", "texto": "Ifá dice que esta persona ha tratado de realizar\nmuchas cosas en la vida, pero no ha sido exitoso.\nPara poderlo ser, tendrá que ofrecer el sacrificio\ncorrespondiente.\nBuscará o sacará una vasija para poder sacar el\nagua que se acumula al lado de la hondonada\ndonde está el altar de Èşù.\nLa persona ha adquirido o comprado algún artículo\nque le ha entristecido su adquisición por x motivos.\nIfá le dice que no se desespere, pues a largo plazo\nle traerá riquezas y mejorías económicas y sociales.\n\n                À şé síhìín\n               À şé sóhùún\n           Lomi koto è é fíí kún\n              Tíí fíí wợnú ilé\n            A dífá fún Odídẹré\n       Tí ń foşù gbogbo şòwò èjè\n    Odídẹré ní ń şe nňkan ni ò lórí yin\n       Òun le şe nňkan rere báyìí?\n        Wón ní kí Odídẹré ó rúbợ\n   Wón ni gbogbo nňkan è ní ó bára mu\n             Odídẹré bá rúbợ\n         Ó nibợ tán layé bá jẹ é\n        Gbogbo nňkan tí ò ti dáa\n                Ti ò tí lájé\n               Ti ò ti bímợ\n      Oşù gbogbo ni fí ń şòwò èjè\n      Wón ni kó tójú nňkan ipợnmi\n               Ni kó fi rúbợ\n           Wón gbẹbợ fún Èşù\n      Béré béré ìdi è bá tún dowó\n              Ni ínú è ń dùn\n         N ní wá ń jó ní wá ń yò\n\n          Ní ń yìn àwợn Babaláwo\n          Àwợn Babaláwo ń yìn Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n                 À şé síhìín\n                À şé sóhùún\n           Lomi koto è é fíí kún\n               Tíí fíí wợnú ilé\n             A dífá fún Odídẹré\n        Tí ń foşù gbogbo şòwò èjè\n                 Yóó dợmợ\n         Òwò èjè kan òwò èjè kàn\n              Tàwa şe lóşu yìí\n                 Yóó dợmợ\n             ợmợ ni ò mòmò dà\n\nLa manera de contar aquí.\nLa manera de contar allá\nEs la razón por la cual el nivel del agua en un koto\n(hueco) no podrá llegar al nivel de alcanzar los\ncimientos de la casa\nFueron los awoses que lanzaron Ifá para Odídẹré\n(Loro)\nAquella que se inyectaba en sangre (rojo color)\ntodos los meses\nOdídẹré había tratado de hacer de todo sin ser\nexitoso en nada de lo que hiciese\n¿Seré capaz de hacer algo que me salga bien? Ella\nse preguntó\nEllos le dijeron que sacrificara. Y que sus cosas\nserían según sus deseos\nElla sacrificó y observó los sacrificios previstos. La\nvida le cambió totalmente para bien\nElla nunca había tenido riquezas, ni hijos y siempre\nse teñía en sangre todos los meses (menstruación)\n\nElla supo que debía buscar un recipiente con agua y\nofrecérselo a Èşù\nLas plumas de su cola, fueron desde entonces la\nfuente de sus riquezas\nY ella comenzó a ser muy feliz. Bailó y regocijó a sus\nbabaláwo\nEllos regocijaron y alabaron a Ifá\nLa manera de contar aquí\nLa manera de contar allá\nEs la razón por la cual el nivel del agua en un koto\n(hueco) no podrá llegar al nivel de alcanzar los\ncimientos de la casa\nFueron los awoses que lanzaron Ifá para Odídẹré\n(Loro)\nAquella que se inyectaba en sangre (rojo color)\ntodos los meses\nCierta inyección mensual de sangre, se convirtió en\nun bebé\nSu mensual inyección de sangre se convirtió en un\nniño\nCierta inyección mensual de sangre, se convirtió en\nun bebé\nSu mensual inyección de sangre se convirtió en un\nniño\n\n              Ààbà séké ń sékè\n     A dífá fún Óòşààlá Òşèèrèmògbò\n           Ti ó fẹrú àkórà şe arợ\n              Óòşà ló fẹ rà ẹrú\n                 Ńgbà ti ó rà\n                 Ló bá ra arợ\n          Ó ti gbé arợ dé ilé è tán\n     Ni wá ń wò ó pé kín lòún a rà yí?\n        Ojí ní ń wò nígbà ti ń ra arợ\n            O si gbin oko àgbàdo\n      Ó bá lợ rù ú kalè lóko àgbàdo è\n\n         Ợrợợrún ni Óòşà sìí şe ibợ\n               Óòşà bá wá ilé\n            Arợ ń bé lóko àgbàdo\n         Arợ bá jáde láti inú ahéré\n         Kó lòó wo oko àgbàdo wò\n            Ó bá rí àwợn Odídẹré\n   Àwợn Odídẹré ń ré gbogbo yangan\n            Arợ bá lòó gbé kùňkú\n             Ó mú àdá Óòşà náà\n         Ni bá fi ń yin yangan nídìí\n      Bi pópóò yangán bá ti wó lulè\n     Àwợn Odídẹré bá ń fẹsẹ kan ilè\n             Wón ò bá le lợ mó\n               Arợ bá ń kí wón\n         Ni ń sợ wón sínúu kùňkú\n                  Kùňkú kún\n         Etì ònà si ni Óòşà dáko si\n          Ìgbà ti Óòşà o fi ti ilé dé\n Gbogbo yangan è ni arợ féèé bé lulè tán\n          Óòşà bá ń kéé bó látònà\n         Ệrú tóun rà tí boko òun jẹ\n         Ńgbà ú Óòşà ó dèé inú ilé\nLó bá rí àwợn Odídẹré ńnúu kùňkú kitikiti\n              Ó kókó rérìín sínú\n  Kín ló wáa dé tóo gé gbogboyangan?\nArợ ni ńgbà ti àwợn Odídẹré féé móo jẹ é\n        Òún bá ń fí àdá yin ìn nídìí\n  Lòún fi kó gbogbo àwợn Odídẹré inúu\n                    kùňkú\n         Óòşà bá dúpé lówó ẹrú é\n     Ó ni sóo ri kinnì ìdí wợn ẹyẹ yìí\n                Bóun bá ta á\n              Owó gidi ni fóun\n\n             Óòşà ò şe méjì mợ\n           N ní wá ń jó ní wá ń yò\n          Ní ń yìn àwợn Babaláwo\n          Àwợn Babaláwo ń yìn Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n              Ààbà séké ń sékè\n     A dífá fún Óòşààlá Òşèèrèmògbò\n           Ti ó fẹrú àkórà şe arợ\n             Ệrú tóo rà ợba lo jẹ\n          Óòşààlá owóò ré ò gbé !\n             Ệrú tóo rà ợba lo jẹ\n\nÀàbà séké ń sékè\nLanzó Ifá para Óòşààlá Òşèèrèmògbò (Obátàlà)\nQue había comprado a un cojo como su primer\nesclavo\nY después de haberlo comprado se dijo a si mismo:\n¡He botado el dinero!\nY decidió enviar al cojo a una plantación de maíz\nque poseía, creyendo que allí tampoco le serviría de\nnada, debido a sus limitaciones físicas\nEsto no le impidió observar sus rezos y plegarias\ndiarias, como le era habitual\nUno de esos días de Ợrùn Ifá (libre plegaria), dejó la\ngranja y se marchó a la ciudad\nEl cojo se internó en el campo de maíz, donde había\nvisto unos loros que se comían los granos de las\nmazorcas que crecían en las plantas\nBuscó una gran cesta y el machete del Óòşà.\nAhuecó la tierra de la base de las plantas y cuando\nlos loros se posaron sobre las mazorcas, las plantas\nse vinieron abajo, topando las aves sus patas en la\ntierra firme, impidiéndole volar de nuevo, al\ncubrírseles con la tierra de los huecos\n\nEl lisiado comenzó a capturarlos y meterlos dentro\nde la gran cesta que llevaba, encerrándoles allí en\nbuena cantidad de aves\nLa granja de maíz quedaba a lo largo del camino\nque el Óòşà usaba para regresar y al ver su\nsembrado todo destruido, exclamó furioso:\n- ¡Ese inservible esclavo ha destruido mi principal\nfuente de sustento y economía! -\nPero al entrar a su casa, vio la inmensa cesta llena\nde aquellos bellos pájaros y su rostro se llenó de\nuna sonrisa interna\nEl esclavo le contó todo lo acaecido y exclamó:\n- ¿Ha visto ud. esas bellas plumas rojas en la cola de\nesos pájaros? -\nPienso que si las vendemos, serían un buen negocio\nÓòşà no dijo ni hizo nada más. El lisiado se encargó\ndel resto\nÀàbà séké ń sékè\nLanzó Ifá para Óòşààlá Òşèèrèmògbò (Obátàlà)\nQue había comprado a un cojo como su primer\nesclavo\nY después de haberlo comprado se dijo a si mismo:\n¡He botado el dinero!\nEl esclavo que adquiriste te ha hecho Rey\nÓòşààlá, no gastaste el dinero en vano\nEl esclavo que adquiriste te ha hecho Rey", "origen_id": "bd6cf36a778b87a6fe09303e"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbe´şe habla de buenas noticias y logros que serán llamado a\n                                                                      celebrar.\n       WO – El cliente puede esperar cambios positivos en sus relaciones\n                                                                 emocionales.\n\n\n30.1 · Ero-ile-komopet´ona-nbo adivinó Ifá para Oloide quien fue a casarse\n\n       con Ami. Él dijo que el mundo vendría a celebrar con ellos cuando\n       fueran prósperos en la vida. 1 chiva debía ser sacrificada. Él oyó el\n                                                     aviso e hizo el sacrificio.\n     La historia de Ifá: Un día todos los pájaros se reunieron y hablaron a\n      Oloide para conocer a Ami, Oloide convino con ellos y les instruyó\n      que se reunieran en la plaza del mercado provistos de vino de palma\n        y otras bebidas alcohólicas fuertes. El día de la reunión, todos los\n         pájaros se reunieron en el arbusto de la asamblea con el vino y el\n     alcohol. Después que ellos finalizaron de comer y beber, el papagayo\n                              (Odidere) mostró a Ami a todos los pájaros.\n     El canto y bailó: yo he venido a mostrarte a Ami. Oloide, yo vengo a\n    mostrarte a Ami a todos los pájaros del arbusto. Ellos fueron felices y\n                                         todos se unieron para cantar y bailar.\n\n\n30.2 · Seese Woowo adivinó Ifá para Iresu-ele quien vino a visitar a Ode\n\n      Ajalaye. Él dijo que Oggún sería el que acomodaría su cabeza (ori).\n           Por eso él debía sacrificar 1 cesto lleno de semillas de palma, 3\n\ngallos, un ñame asado y 6600 cawrie. Él oyó el aviso y realizó el\n                                                                    sacrificio.", "origen_id": "d3dc1b2ba0a31868aaa89ea7"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Oloidẹ: una chiva.", "Ìrẹṣu-ele: un cesto de cáscaras de nuez de palma, tres gallos, un ñame asado y 6,600 cauríes.", "Odídẹré: ofrenda; sacar con una vasija el agua que se junta junto al lugar de Èṣù."], "pasajes": [{"titulo": "Ofrenda en el verso 30.1", "texto": "Ero-ilé-komopet'onà-nbọ\nadivinó Ifá para Oloidẹ\ncuando iba a tomar a Ami como novia.\nEl adivino dijo:\n\"todo el mundo vendrá a celebrar con ellos\ncuando sean prósperos en la vida\"\nUna chiva debía ser sacrificada.\nÉl oyó el aviso e hizo el sacrificio.", "origen_id": "e9a5a44c427027e9ebe92b21"}, {"titulo": "Ofrenda en el verso 30.2", "texto": "Ṣẹẹṣẹ, Wopwọ:\nadivinó Ifá para Irẹṣu-ele,\ncuando estaba viniendo de Òde Àjàláyé.\nEllos dijeron:\n\"Ogún será el único que reparará su cabeza (orí)\"\nPor eso él debía sacrificar:\nun cesto lleno de cascarones de nuez de palma,\ntres gallos, un ñame asado\ny 6600 cauris.\nÉl escuchó y realizó el sacrificio.", "origen_id": "4bb4069f96ff2ef74eeef6ff"}]}, {"titulo": "Relaciones espirituales", "texto": "Ògún arregla la cabeza de Ìrẹṣu-ele. Òòṣààlá es protagonista del relato del esclavo. Èṣù tiene su lugar junto a la hondonada donde se junta el agua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cáscaras de nuez de palma, ñame asado, maíz, plumas rojas de loro, vino de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 30.1 (yorùbá): Ero-ilé-komopet'ònà-nbọ: / lo dífá f'Oloidẹ, / nlọ ngbe Ami ni iyàwó. / Wọ̀n ni: / \"gbogbo ayé liomaa wa pe mọọ / nigbi ayé ba yẹwọn yewọn\". / Ewúrẹ kan li ebọ. / Ó gbọ̀ ó rú.", "Verso 30.2 (yorùbá): Sppse, Woowọ: / li o dífá fún Irẹṣu-ele, / nwa ni Òde Àjàláyé. / Wọ̀n ni: / \"Ôgún ni o maa tún orí rè ṣe\". / Nitorinaa ki ó rú: / Apẹrẹ[69] iwẹn[70], / akuko-adiẹ mẹta, ẹsun iṣu / ati ẹgbẹtaelógbọ̀n owó. / Ó gbó ó rú.", "REZO: OGBE SHE BATOLOSHE ESHU OSHE AWADI EBONI OLE OBA OLUWO OBASHE OMOSHE OMO IYA LODE IFA KAFEREFUN ORUNMILA,YEMAYA, OGGUN, ELEGBA, OSHUN, OLUWO LAYE OGBE SHE BARABASHE BAWA OMO ONIRE AYE TIMBELAYE OLUWO ASHAUDE.", "SUYERE: IBAYE DEWA WASHE DIDE, IBAYE DEWA WAO DIDE GBOGBO AYE ORE IBAYE DOWA AWA SODIDE.", "REZO: OGBE SHE AWO NIRE OLOFIN IRE EYA NI BAWA EYENLO GBOGBO IKU ONIRE OBA NI OLORDUMARE ORI BAWA EYA IRE OBA NI.", "REZO: OGBE SHE BALOBOSHE OBATO WOSHE ADIBA DIBA ONI BABALAWO LODAFUN OLUWO DIDE.", "REZO: OGBE SHE KANTON OBAYE DEWA KODIDE SARAUNDERE OLOLODIDE IYALODE OKERE YI MORO ENIDESUN EFIDEBORO OTOLAREFA EYIBOYO NILA ODDUN AYIBAGADARA NAWASI IKOWOBOSHE IYANI NORO YEYEO SHIYANI MORO YEYEO.", "REZO: OYO OTO EGBA MI OLUWO OGBE SHE LODAFUN AKATAMBO UNTO- RODIYA OWODORE ERIN BATI OTOGBA TOBOSILE ORUNMILA.", "REZO: OGBE SHE OWORI WOWO ADIFA OLOFIN AKARO WAYA.", "REZO: BABA OGBE SHE AYE BABA DAWESHE AMUERUN KARAKU TANSI DEWESHE LOBIODUN KEKERE DIONEGUN TIOKO ADIFAFUN OLUO EBBO.", "REZO: ORUNMILA DIFA ADAFUN AYE ALIAKA ONTIGUO YOKO ORUBO ARAYE EMALKIDA OTUNDA AWO UMBO ELESE ORUNMILA ILESE ORISHA EBINKUAKO.", "REZO: OGBE SHE IKU KALENLEKU OGBA OMO NIEGBA UMBATINILE OMODE OPA OLUGWA YALORDE, LODAFUN SHANGO Y OBA.", "REZO: OGBE SHE AWO ERI IFA ONIOSHE KABASHE ASHO NISHELE AWO NIRE ENI IFA JUNJUN AWONI IFA SHANGO AWO EBA KOLA ENIRE IFA.", "REZO: ADIFAFUN LEKE LEKE EWARADA OBETOLOMIRA NO OSHA LEKE LEKE OFOTILO OUMINI LATIBASI IKOKO OGU OZAIN OFOYUDE OYONOWA TAQUEYO OYU ONI ADIFAFUN OZAIN OLOROFUN.", "SUYERE: LEKE LEKE LAWAO OYU ODARA, AFELA AYE NBO NI ODO OYU ODARA, LEKE LEKE LAMBO LAWAO. SUYERE: IBAYE DEWA WASHE DIDE, IBAYE DEWA WAO DIDE GBOGBO", "AYE ORE IBAYE DEWA AWA SODIDE.", "SUYERE: EYA LEWE ENI LEWE, EYA TUTU MOFORI BAWAO ORI NALAWONI EWE OWE OGGUN YARUKURU OGGUN MASENIWEWE AWO MALAYONI AWO IFA OGBE SHE BORIBOSHE BORITOYO AWO ABONIBOSHE.", "SUYERE DEL OPARALDO: SARAYE IBA KILODE IFA INTORI ARAYE KAURE", "SUYERE DEL KOBORI: EYA BEWA ORI LAWADE EYA WA WA FARI MAMA FARI EYA TUTU BELEKE ORI FELEKEKE ORI FELEKEKE MAMA FARA.", "SUYERE DEL ELLA TUTU A EGGUN: EYA LEKE ENI LEKE EYA TUTU MOFORI BAWAO ERI MALAGUIDI EWE EWE OGGUN YANYA OTE OGGUN MASHE NIGUEGUE OGGUN MALA YENI AWO IFA OGBE SHE BORIBOSHE.", "REZO: OGBE SHE ORIBONOSHE ALALALELEKUN SHANGO OBONIBOSHE ORI OMO OLUO ASHE ARANLALE BI EWA OGGUN IFA ENIEWA OGGUN ORIBOSHE ATENI LARA ONIBARANIREGUN ENI FIFE OYA ANIRE- YE ONIBOSHE ENIFA INLE IYESEWA IFA KAFEREFUN SHANGO, KAFEREFUN ORUNMILA KAFERFUN OYA.", "SUYERE DE ESTA CEREMONIA DEL EYA TUTU: EYA LOWE ENI ELEWE, EYA TUTU MOFORIBAWAO ORI MALAWENI EWE EWE OGGUN YANYA URO OGGUN MASENIWEWE AWO MALAYENI AWO IFA OGBE SHE BORIBOSHE. AWO OBORIBOSHE.", "SI EL EGGUN ES AWO SOLO SE PONE EL SIGNO.", "REZO: OGBE SHE BOLOBOSHE AYE BALOSHE OSU OSHIKALIKA NI NI PAUBESHE NILA ADIFAFUN ODIDE ABANKEKE ADIFAFUN ODIDE TIOLOSI IWOSHALA.", "REZO: ODE LAIWO ADIFAFUN ORUNMILA UNLO IGBO OFE TILE IGBIN AGBANI JORO JORO IWO OPEO OLORUN LODAFUN ELEGBA OPEO OLORUN ODE OPOLOPO OWO OPOLOPO ASHE SODAKE UNSORO OBINI ODE OFETILE ASHURI OLORUN AGBANI OMO OSHOSI ODE ODARA OPOLOPO OWO KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN AYABA OBA MANIBU YAKUA SILE ODOÑE ASHABA", "NIADA ADA OGGUN OFO LERI TOKU EYI NI GBOGBO ENI ARAYE NI OFO TURA LADE NI LATIBA NI LATIBA OSA UMBO ELESE IGI ERO ESON LABA ERO NI ADIMU OBA LODAFUN OSHUN MORI YEYEO OBA OFO AI OTI AYRANI ENYA ASHIRI NI ADA OBA ORISHA.", "REZO: ADIFAFUN OLOFIN MEBBO ESE LOKIKAN MASIBU GBOGBO ARIANA OBAYE ELEWE MOJABAE FAYA SABERE OMI SHANGO ODIDE EAYIA SE OLORISHA ARO ERE FERDA BE LODAFUN SHANGO."]}]$q$::jsonb),
(31,'02c9285aa04694d543e7f6d892a6b1c8','15219c5b3d23c72f514cceeff67fd270',$q$[{"titulo": "Idea central", "texto": "Ogbè Òfún habla de la medicina tradicional y de los sonidos e instrumentos que ahuyentan a la muerte y a los malos espíritus. Advierte que la promiscuidad y meterse con alguien comprometido causan dolor. Pide ofrecer para tener seguidores y atender pronto a los ancestros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en una relación que puede causar dolor porque una de las partes ya tiene compromiso (relato de Ogbè y la esposa de Òfún).", "Busca dinero, pareja, hijos o casa (relato de Owó leléwà).", "Quiere reunir seguidores o reconocimiento (relato del Ọba).", "Cree que ya tiene lo que quería, pero quizá descuidó otras responsabilidades.", "Teme la muerte o la enfermedad (relato de Ikú y Àrùn).", "Está a cargo de un grupo y debe ver cómo ejerce y comparte esa autoridad."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Seguidores en abundancia.", "Dinero, pareja, hijos y casa.", "Vencer a la muerte con lo que Ifá enseña."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a la satisfacción del destino. (Este Odu habla de la enfermedad sobreponiéndose a una enfermedad fatal potencial.)", "origen_id": "892a4c664c6a59fdb2dc02bf"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Una relación con alguien que ya tiene compromiso.", "Desatender a los ancestros (Egúngún).", "Comer de lo del rey sin reconocerlo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El camino abierto lleva a un sentido de satisfacción falso. (Este Odu habla del peligro de comer hongos.)", "origen_id": "dade8efb88f59928314738aa"}]}, {"titulo": "Enseñanza principal", "texto": "No siempre gana el más fuerte. La muerte juntó las doscientas una cabezas, pero el que se llevó a la novia fue la enfermedad, que había ofrecido. El sonido correcto vence al miedo."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ogbè'Fún habla del empleo en la medicina tradicional yoruba y del empleo de instrumentos para alejar a la muerte y a los malos espíritus.", "origen_id": "5b918e7490cf883f9bc0859f"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè y la esposa de Òfún. Moṣaa-li-o-ni-opa y Erogbonre-o-mẹsẹ consultaron para Ogbè cuando iba a seducir a la esposa de Òfún y le dijeron que tendría éxito. Le marcaron una gallina, una rata, un pescado y 44,000 cauríes. Cumplió. A quien le sale este Odù se le advierte ofrecer para no sufrir por una relación nueva, sobre todo si esa persona está comprometida con otra.", "La muerte, la enfermedad y la hija del Òrìṣà. Ikú y Àrùn querían casarse con Lasunwontan, la hija del Òrìṣà, y el Òrìṣà dijo que se la daría a quien le trajera doscientas una cabezas. Ikú fue a la granja, mató a doscientas una personas, ató las cabezas y se las llevó. En el camino oyó a alguien cantar: 'Si veo a Ikú pelearé con él, si veo a Àrùn pelearé con él'. Asustado de que alguien se atreviera a amenazarlo, soltó las cabezas y huyó. No sabía que era Àrùn: su babaláwo le había pedido doscientos caracoles, se los había ensartado en un collar y le había enseñado el canto, y el choque de los caracoles marcaba el ritmo. Àrùn recogió las cabezas, se las llevó al Òrìṣà y se casó con su hija. De ahí el dicho: 'La muerte tuvo que trabajar para que la enfermedad triunfara'. Por eso la medicina tradicional usa instrumentos y sonidos contra la muerte, en el àbíkú y en los niños enfermizos.", "El rey y los frijoles blancos. El rey venía del cielo y lloraba porque no tenía quién lo siguiera. Le dijeron que preparara frijoles blancos (irú) y les diera de comer a todos. Lo hizo, y desde entonces quien come frijoles blancos es servidor del rey; el que los come y no le corresponde se daña a sí mismo. Así el rey se volvió señor de señores.", "Owó leléwà, el dinero que embellece. Owó leléwà venía del cielo a la tierra y ofreció para tener de todo. Le dijeron: no tener dinero es malo, no tener pareja es torpe, no tener hijos es pasar por la vida como turista, y no tener casa es vivir inquieto. Ofreció y tuvo dinero, pareja, hijos, casa y salud. Junto al dinero va la belleza de la pareja; la casa es la belleza de los hijos."], "pasajes": [{"titulo": "Verso 31.1", "texto": "Moṣaa-li-o-ni-opa,\nErogbonre-o-mẹsẹ:\nfueron los que adivinaron Ifá para Ogbè.\nCuando Ogbè estaba yendo a seducir\na la esposa de Òfún.\nEllos dijeron: \"el éxito es seguro\"\nGallina, rata, pescado\ny 44.000 cowries, son el sacrificio.\nÉl escuchó e hizo el sacrificio.", "origen_id": "acc4763b36dfa7666a655887"}, {"titulo": "Verso 31.2", "texto": "Oliwowoji, Oliwowojiwo:\nadivinaron Ifa para lkú (muerte),\nadivinaron Ifá para Àrün (enfermedad),\ncuando ambos querían casarse con Lasunwontan, la hija de Oriṣà.\nÓriṣà dijo:\n\"que él daría su hija a un hombre joven\nque le pudiera traer 201 cabezas frescas (ori)\".\nEllos se fueron pensando cómo lograrlo.\nIkú fue a la granja a ver 201 personas\nque fueron muertas inmediatamente,\nlas cabezas fueron recogidas y atadas juntas,\nlas que fueron llevadas por él.\nAsí, él fue camino hacia la casa de Oriṣà,\nél escuchó el sonido (iro)\nde alguien que cantaba la siguiente canción:\nSi veo Ikú yo pelearé con él,\nOliwowoji-Oliwowojiwo\nSi veo Arùn yo pelearé con él,\nOliwowoji-Oliwowojiwo\nCuando Ikú oyó este sonido,\nél dejó las 201 cabezas y huyó,\nasombrado de que no conocía a nadie\nque fuera lo suficientemente valiente\ncomo para amenazarlo a él y a Arùn.\nÉl no sabía que Àrùn estaba detrás de esta confusión.\nÀrùn había visto a su Babaláwo\npara que le dejaran libre el camino\npara hacer a la hija de Oriṣà, su mujer.\nEl Babaláwo le pidió doscientos caracoles,\na lo cual él accedió.\nEl Babaláwo ató los caracoles juntos,\nlos puso en un collar alrededor del cuello de Àrùn\ny le enseñó a cantar su rezo.\nCuando Ikú dejó las 201 cabezas,\nÀrùn recogió las 201 cabezas y se las llevó a Oriṣà.\nÒriṣà en recompensa le dio a Lasunwontan,\nsu hija, a Arùn.\nNota: Por eso tenemos un proverbio que dice: \"la muerte tuvo que\nsacrificar para que la enfermedad tuviera éxito\". Esta historia nos dice que\nhay sonidos de instrumentos capaces de vencer a la muerte y los espíritus\nmalos. Esta es la razón de porque en la medicina tradicional, usada\nnormalmente por los hombres, use instrumentos de su creación en àbikú y\nen niños enfermizos.\nỌ̀yẹ̀kú", "comentario": "\" Nota r: En adivinación la persona debe sacrificar para evitarse problemas, disgustos o sufrir a causa de una nueva relación de pareja, sobre todo si la relación que desea obtener para sí está comprometida con otra persona.\n12 iro: es el sonido que producen dos o más cuerpos al chocar uno con otro. En este caso el sonido que marca el ritmo de la canción que cantó Àrùn, es el producido por el choque de las conchas de caracol del collar que le hizo su Babalawo cuando él sacrificó,", "origen_id": "16745efe585010ee6bd40bb7"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le pide a esta persona, que sacrifique en el orden\nde tener seguidores en abundancia. Ifá aceptará\nuna cazuela llena de frijoles caritas o blancos\ncocinados, que venga de esta persona. También Ifá\nle augura la fortuna del dinero, las esposas, los hijos\ny la vivienda. Ifá reafirma la presencia de\nmascaradas (Egungún - ancestros de fuerte\npresencia e influencia). La persona rápidamente\n\ndeberá sacrificarle a esas entidades para lograr que\nsu vida sea más placentera y confortable.\n\n           Ogbè fohun fólóhun\n            N ò fohun fólóhun\n     Babaláwo Ợba lo dífá fún Ợba\n        Ợba ń tòrun bò wálé ayé\n      Ợba wá ń sunkún alài lẹnisin\n        Òún le lẹnisin ńlé ayé ìí ?\n             Wón ní kó rùbợ\n    Wón ní gbogbo ayé ní o sín Ợba\n           Ibi táa tí mợ ẹrú nìí\n          Àyàfi ẹni ti ò bá jẹ irú\n         Béèyán bá ń jé irú lóbè\n          Tó bá lóun o sín Ợba\n           Èpè ní ń şé lé ara è\n         Wón ní kí Ợba ó tójú irú\n                Ợba tójú irú\n Wón ni kó fún gbogbo ayé kí wón ó móo\n                     jẹ\n   Wón ni gbogbo àwợn tí bá ń jé irú\n        Gbogboo wợn lẹnisin Ợba\n         Wón ó móo wárí fún un\n     Àfi bí wợn ò bá jẹ irú mó láyé\n          Gbogbo ayé bá jẹ irú\n              Ợba bá di ògá\n                Ayé yẹ Ợba\n         Lợba wá ń jó ni wá ń yò\n         N ń yín àwợn Babaláwo\n        Àwợn Babaláwo ń yín Ifá\n   Ó ní béé làwợn Babaláwo tòún wí\n           Ogbè fohun fólóhun\n            N ò fohun fólóhun\n\n       Babaláwo Ợba lo dífá fún Ợba\n         Ợba ń tòrun bò wálé ayé\n       Ợba wá ń sunkún alài lẹnisin\n              Wón ní kó rùbợ\n           Ợba wáá ngbébo ńbè\n                  Ợba rùbợ\n                Ệni bá jẹ irú\n                 Ệnu rè a ru\n               Ệni ó bá jẹ iyò\n                 Ệnu rè a yò\n               Ệni bá jẹ Epo\n                Ệnuu rè a po\n         Èyin ò mò péni ó bá jẹ irú\n            Ni wón ń lérú Ợba?\n        Gbogbo èèyàn tó bá jẹ irú ó\n               Ó si dẹrú Ợba\n\nOgbè devuelve el artículo a su dueño\nYo no le devolveré el artículo a su dueño\nEl adivino del rey adivinó Ifá para el Rey\nCuando venía del Cielo a la Tierra y clamaba por no\ntener seguidores ni devotos a su rango o jerarquía.\nY se preguntaba: ¿Seré capaz de tener seguidores\nen la Tierra?\nEllos le pidieron que sacrificase que todos en la\nTierra sabrían que tenían que adorar y seguir al Rey\nY aquí fue donde se conoció el ẹrú (esclavo)\nExcepto la persona que no coma irú (granos, frijoles)\nSi alguien come frijoles blancos y no le brinda al rey,\ninconcientemente estará causándose daño a si\nmismo\nSe le pidió al rey preparar frijoles blancos y dárselos\na comer a las personas de la Tierra y así él hizo\nY todos empezaron a venerar y adorar al rey que de\nhecho se convirtió en el Señor de Señores\n\nY fue adorado por todos, excepto a los que rehúsan\ncomer frijoles blancos\nLa vida le fue placentera al rey y alabó a sus\nbabaláwo, bailando y regocijándose y ellos alabaron\na Ifá\nOgbè devuelve el artículo a su dueño\nYo no le devolveré el artículo a su dueño\nEl adivino del rey adivinó Ifá para el Rey\nCuando venía del cielo a la tierra y clamaba por no\ntener seguidores ni devotos a su rango o jerarquía.\nY se preguntaba: ¿Seré capaz de tener seguidores\nen la Tierra?\nEllos le pidieron que sacrificase que todos en la\nTierra sabrían que tenían que adorar y seguir al Rey\nEl rey sacrificó\nSi él come Irú\nSu boca hace “rú”\nSi él come Iyò\nSu boca hace “yò”\nSi él come Epo\nSu boca hace “po”\nAhora todos conocen y saben acerca de aquel que\ncome Irú es el llamado Ệrú (esclavo) y es sirviente\ndel Rey\nTodos aquellos que tengan el gusto de los frijoles\nblancos en sus bocas son esclavos en toda su\nextensión del Rey\n\n               Àgbè relé\n               Àgbè ròde\n   Àgbè gègèègè rợjà Èjìgbòmẹkùn\n         A día fún Owó leléwà\n          Ti ń tòrun bò wáyè\n             Wón ni ó rúbợ\nWón ni gbogbo ohun táàá fíí şe fújà ni kó\n                 rúbợ sí\n\n         Kó lè baà ní wón lópòlopò\n           Béèyàn ò bá lówó-lówó\n                    Kó dàa\n                 Bi ò bá láya\n                    Kò wúlò\n                Béèyàn ò bímợ\n                  Kò káyé yá\n                 Bi o rílé gbé\n                   Ó burú jái\n             Wón ní ẹbợ ni kó rú\n         Ńgbà ti Owó leléwà rúbợ\n                   Ayé yẹ é\n                 Ó lówó-lówó\n                     Ó láya\n                    Ó bímợ\n                     Ó kólé\n            Ń wá ń jó ni wá ń yò\n          N ń yín àwợn Babaláwo\n          Àwợn Babaláwo ń yín Ifá\n     Ó ní béé làwợn Babaláwo tòún wí\n                   Àgbè relé\n                  Àgbè ròde\n     Àgbè gègèègè rợjà Èjìgbòmẹkùn\n            A día fún Owó leléwà\n             Ti ń tòrun bò wáyè\n           Àşé owó lẹwà òun aya\n         Èèyàn è é şé fújà lái lówó\n             Owó lẹwà òun aya\n              Ilé lẹwà òun ợmợ\n          Èèyàn è é şé fújà lái nílé\n              Ilé lẹwà òun ợmợ\n\nSe llevó a la casa\n\nSe llevó a cabo\nSe llevó arriba, al mercado de Èjìgbòmẹkùn\nAdivinaron Ifá para Owó leléwà\nQuien venía a la tierra desde el cielo\nY se le pidió sacrificar en nombre de todas las cosas\nnecesarias para usar como muestra en la tierra\nY pudiesen tener de todo en abundancia, para todos\nNo tener dinero, es muy malo\nNo tener esposa es de torpes\nNo tener hijos es como pasar la vida como un turista\nQuien no halla una casa para vivir, estará\nperturbado siempre\nPara evitar esas desastrosas cosas, se le dijo de\nofrendar\nY así lo hizo Owó leléwà y la vida le fue apacible\nY tuvo mucho dinero, esposas, hijos, casas y salud\nEl cantó y se regocijó y alabó a sus babaláwo\nEllos alabaron a Ifá\nSe llevó a la casa\nSe llevó a cabo\nSe llevó arriba, al mercado de Èjìgbòmẹkùn\nAdivinaron Ifá para Owó leléwà\nQuien venía a la tierra desde el cielo\nY se le pidió sacrificar en nombre de todas las cosas\nnecesarias para usar como muestra en la tierra\nPor consiguiente junto al dinero va la belleza de la\nesposa\nNadie pone al descubierto una belleza sin tener\ndinero\nLa casa es la belleza junto a los hijos\nNadie pone a descubierto sus hijos sin tener una\ncasa\nLa casa es la belleza junto a los hijos\n      PALABRAS DIFICILES EN\n        TRATADO DE OGBÈ:\n\n1.- Ogbèyèkú: uno de los 240 Odù menores\n2.- Àmúlù: Escritura de Ifá con un par de marcas o\npatas. Donde la\n              Pata de la derecha pertenece a Ifá y la\nizquierda a Èşù\n                Si las patas no son iguales, se llama\nOdù menor\n3.- Orí: Cabeza interna, sinónimo del destino de la\npersona\n4.- Ệdan: Indicativo atado a la muñeca (mano) que\nidentifica al\n            Babaláwo (en Cuba= Idésongo).\n5.- “El Elefante usó el avance de la Muerte, para\nconocer el interior\n    De la casa”: Expresión gramatical (exageración)\nque significa una carnicería o matanza creada entre\nlos animales, que nos brinda la carne a la casa.\n6.- Ệbù Èyìn: Retroceso, ruptura inaudita\n7.- Ogun: Guerra, Ajogun\n8.- Kólálù lawo abé ợta: Nombre de un adivino\n9.- Baáyànnì: Nombre de una divinidad\n10.- Dàda: Niño místico con pelo de puntas (crea\npavor o miedo)\n11.- Olúfón: Deidad del estado de Ondo\n12.- Alásiá: Adivino jefe del culto a la deidad de\nÒgiyán\n13.- Ògiyán: Una deidad relacionada al culto de\nÓòşà Oko\n14.- “Ogbè dáwợ òsùn tẹlè”: “Ogbè usa a òsùn\ncomo un bastón para\n      Caminar”\n15.- Àjìjà: Charlas de Ifá\n16.- Ògúníkin: Ògún tiene ikin. Nombre de una\npersona\n17.- Ìbààbá: Tribu nigeriana\n18.- Gbádágbádá Gbudugbudu: Palabra rítmica o\nsonido producido\n\n      Cuando la tribu de los Ìbààbá está pescando en\nel río Òògùn\n19.- Abiamợ: Madre o enfermera, también mujer\nmuy piadosa\n20.- Koto: Guira o guiro, abierto en uno de sus\nlados o topes, para ser\n            Usado como vasija o recipiente\n21.- Àgbònyín Gàgàlà: Gran antílope o ciervo. En\nCuba el venado\n22.- Olúugbó: Divinidad de la profundidad del\nbosque\n23.- “Ogbè ká re káà ká bòdé”: “Ogbè, déjanos\nhacer un viaje de regreso al salón del descanso\ninterno”. Del signo Ogbè Ìká\n24.- “Ệyin ẹ wòmùdúun kókò, ẹ wáá wợmợ\nAkin yááyo”:\n       “Para ver el brote fresco fresco de la hoja del\ncocoyam y estar en\n        Su fuerte descendencia”. (Costumbres, línea\nfamiliar)\n25.- Ệrú: Esclavo\n26.- Irú: Fríjol caritas. Granos o gramíneas\n27.- Èjìgbòmẹkùn: Ciudad ancestral o muy antigua\ndel conclave yoruba, que se destacaba por su\nmercado extenso, productivo y lozano\nEn ocasiones interpretado como frontera entre la\nvida y la muerte o el lugar por donde salen las\ncriaturas del vientre de la madre en su nacimiento y\npor donde penetra el pene en el acto sexual o la\nfecundación\n28.- Owó lẹléwà: “Dinero, es aquel que posee la\nbelleza”. Un nombre de persona", "origen_id": "33fcc34ec3b46b5859c0a906"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogbefun habla de instrumentos químicos para enfrentar y alejar\n                                              a la muerte y a los espíritus del mal.\n               WO – Comportamientos no monógamos pueden causar un gran\n                                                                              dolor.\n\n\n31.1 · Mosaa-li-o-ni-opa, Erogbonre-o-mese adivinó Ifá para Ogbe.\n           Ogbe fue a seducir a la esposa de Ofun. Le fue asegurado el éxito. 1\n           gallina, 1 rata, 1 pescado y 44.000 cawries. Él oyó el aviso e hizo el\n                                                                          sacrificio.\n\n\n31.2 · Oliwowoji, Oliwowojiwo. Ellos adivinaron Ifá para Ikú (muerte).\n\n        Ellos adivinaron Ifá para Arun (enfermedad). Ambos querían casarse\n       con Lasunwontan, la hija de Orişa. Orişa dijo que él daría su hija a un\n       hombre joven que pudiera producir 201 cabezas frescas (ori). Ellos se\n        fueron pensado cómo lograrlo. Ikú fue a la granja a ver 201 personas\n           que fueron muertas inmediatamente, sus cabezas fueron recogidas y\n        atadas juntas, la que fueron llevadas por él. Así, él fue por el camino\n                hacia la casa de Orişa, éste oyó a alguien cantando la siguiente\n                                                                           canción:\n\nSi veo Ikú yo pelearé con él, Oliwowoji – Oliwowojiwo\n                    Si veo Arun yo pelearé con él, Oliwowoji – Oliwowojiwo\n    Cuando Ikú oyó este rezo, él dejó las 201 cabezas y huyó, asombrado\n         que alguno podría ser lo suficientemente valiente para amenazarlo a\n         él y a Arun. Él no sabía que Arun estaba detrás de esto, Arun estaba\n          listo para a ver al Babalawo para pedir auxilio para dejar fuera del\n             camino a la hija de Orişa, su mujer. El babalawo le dijo a que él\n         produciría 2 centenas de caracoles, lo cual accedió. El babalawo ató\n            los caracoles juntos, los puso en un collar alrededor del cuello de\n                                            Arun y le enseñó a cantar su rezo.\n         Cuando Ikú dejó las 201 cabezas, Arun recogió las 201 cabezas y se\n     las llevó a Orişa. Orişa en recompensa le dio a Lasunwontan, su hija,\n           a Arun por eso nosotros tenemos un proverbio que dice, la muerte\n                       tuvo que sacrificar por la enfermedad que tener éxito.\n            Esta historia nos dice que hay instrumentos químicos capaces de\n               vencer a la muerte y los espíritus malos. Esta es la razón de la\n     medicina tradicional usada, normalmente por los hombres que ponen\n           instrumentos de su creación en abiku (nacimeinto muerte) u otras\n                                       enfermedades de los niños (psíquicas).", "origen_id": "cb10d0a623bbb390bee93be1"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: una gallina, una rata, un pescado y 44,000 cauríes.", "Àrùn: doscientos caracoles ensartados en un collar, con su canto.", "El rey: frijoles blancos cocidos para dar de comer a la gente.", "Para seguidores: una cazuela de frijoles blancos o de carita cocidos para Ifá; ofrenda pronta a los Egúngún."], "pasajes": [{"titulo": "Ofrenda en el verso 31.1", "texto": "Moṣaa-li-o-ni-opa,\nErogbonre-o-mẹsẹ:\nfueron los que adivinaron Ifá para Ogbè.\nCuando Ogbè estaba yendo a seducir\na la esposa de Òfún.\nEllos dijeron: \"el éxito es seguro\"\nGallina, rata, pescado\ny 44.000 cowries, son el sacrificio.\nÉl escuchó e hizo el sacrificio.", "origen_id": "247b20c14b3f75fd47a0b69c"}, {"titulo": "Ofrenda en el verso 31.2", "texto": "Oliwowoji, Oliwowojiwo:\nadivinaron Ifa para lkú (muerte),\nadivinaron Ifá para Àrün (enfermedad),\ncuando ambos querían casarse con Lasunwontan, la hija de Oriṣà.\nÓriṣà dijo:\n\"que él daría su hija a un hombre joven\nque le pudiera traer 201 cabezas frescas (ori)\".\nEllos se fueron pensando cómo lograrlo.\nIkú fue a la granja a ver 201 personas\nque fueron muertas inmediatamente,\nlas cabezas fueron recogidas y atadas juntas,\nlas que fueron llevadas por él.\nAsí, él fue camino hacia la casa de Oriṣà,\nél escuchó el sonido (iro)\nde alguien que cantaba la siguiente canción:\nSi veo Ikú yo pelearé con él,\nOliwowoji-Oliwowojiwo\nSi veo Arùn yo pelearé con él,\nOliwowoji-Oliwowojiwo\nCuando Ikú oyó este sonido,\nél dejó las 201 cabezas y huyó,\nasombrado de que no conocía a nadie\nque fuera lo suficientemente valiente\ncomo para amenazarlo a él y a Arùn.\nÉl no sabía que Àrùn estaba detrás de esta confusión.\nÀrùn había visto a su Babaláwo\npara que le dejaran libre el camino\npara hacer a la hija de Oriṣà, su mujer.\nEl Babaláwo le pidió doscientos caracoles,\na lo cual él accedió.\nEl Babaláwo ató los caracoles juntos,\nlos puso en un collar alrededor del cuello de Àrùn\ny le enseñó a cantar su rezo.\nCuando Ikú dejó las 201 cabezas,\nÀrùn recogió las 201 cabezas y se las llevó a Oriṣà.\nÒriṣà en recompensa le dio a Lasunwontan,\nsu hija, a Arùn.\nNota: Por eso tenemos un proverbio que dice: \"la muerte tuvo que\nsacrificar para que la enfermedad tuviera éxito\". Esta historia nos dice que\nhay sonidos de instrumentos capaces de vencer a la muerte y los espíritus\nmalos. Esta es la razón de porque en la medicina tradicional, usada\nnormalmente por los hombres, use instrumentos de su creación en àbikú y\nen niños enfermizos.\nỌ̀yẹ̀kú", "origen_id": "fcbb6e45ad9658e23073b204"}]}, {"titulo": "Relaciones espirituales", "texto": "El Òrìṣà es el padre de Lasunwontan. Ikú y Àrùn son la muerte y la enfermedad. Los Egúngún, ancestros de fuerte presencia, piden atención pronto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Frijoles blancos (irú), caracoles, aceite de palma, sal."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 31.1 (yorùbá): Moṣaa-li-o-ni-opa, / Erogbonre-o-mẹsẹ: / li o dífá f'Ogbè. / Ogbè nlọ gb'obirin Òfún. / Wọ̀n ni: \"a gbaa gbe\". / Abo-adiyẹ, eku, ẹja / ati ẹgbẹjielógún owó li ebọ. / Ó gbọ̀ ó rú.", "Verso 31.2 (yorùbá): Oliwowoji, Oliwowojiwo: / a dífá fún Ikú, / a difá fún Arùn, / wọn lọ fẹ Lasunwọntan ọmọ Oriṣà. / Oriṣà I: / \"ẹnití o ba le ba oun wa orí tutu / Mọ̀kànlerugba ṣa ni oun / maa fi omọ oun fún\". / Gbogbo wọn pada lowa biwọn o ti ṣe ri. / Ikú gba ònà-oko lowa ẹni pa ni warawara / o ti da orí Mokanlerugba jo silẹ. / O di wọn pọ. / O gbe wọn ru. / Bi o ti nlọ lợ'na o ngbọ iro?2 / enikan ti nkorin bayi: / Bi mo r'Ikú ma baa ja. / Oliwowoji. Oliwowojiwo. / Bi mo r'Àrùn ma baa ja. / Oliwowoji. Oliwowojiwo. / Bi Ikù ti gbọ iro yi, / o yara da orí Mókànlerugba naa silẹ. / O salo nitoripe o yaa lẹnu pupo pe / enikan si tun wa tiol'aya / tobẹẹ tiole maa leri oun ati Àrùn. / Ko mọ pe Arùn liowa nidi iwà burúkú yi. / Àrùn sa ti lọs'odo Babaláwo kan / pe ki o jọwọ ba oun wa ọ̀nà / bi oun yoo tiṣe ti oun lefi ni Lasunwontan / ọmọ Òriṣà li aya. / Babaláwo sọ fun un pe: / Kio lọmu igba karahun igbin wa. / Ó ko wọn wa. / Babaláwo so wọn po. / O fi kọọ l'ọrùn. / O kọọ ni orin ti yoo maa kọ ati bẹẹbẹẹ. / Nigbati Ikú da orí Mokánlerugba / naa nu tiosa: / Àrùn ko àwọn orí naa lọ fún Oriṣà. / Oriṣà si fa Lasunwontan omọ rẹ / fún un gẹgẹbi adehun.", "REZO: OGBE FUN FUNLO IKU PUANI ORI BAWA IKU MAYOYORI WANI ADIFAFUN ERUBA OUN LOFE OMA OBATALA ASHO LEBO, JEKUA OSHUSHE IGUNGUN MARIWO LEBO, AIKORDIE MEYI LEBO,AKUKO MEYI LEBO, EKU, EYA, AWADO, LEBO.", "SUYERE PARA HACER ASHINIMA: OGBE FUN FUNLO ENI OYA EWE ASHINIMA ELUDERE OGGUN YEYE OGBE BA ILE, OGUNDE OSHE ARA IKOKO OGUNDE ARIWO TALE.", "REZO: ORUNMIA ADIFAFUN KUBITE TEKAYO OKUNI OLAFUN LAISHE OBINI EURE MEYI LEBO ADOFA OWO LEBO OLOFIN OFUN OBINI ODARA IYAWO KUBITO OLOTIYAKO LOWO ARAYE META ODDUN LESE IGBO, LESE ELEGBA ASHIRI LESE IBU ODE, LODAFUN ELEGBA, KAFEREFUN ORUNMILA.", "REZO: OGBE FUN FUNLO IKU UNLO ARUN UNLO, EYO UNLO, OFO UNLO,IÑA UNLO, ARAYE UNLO, ALKOBA UNLO, OKUMOLORUN INLE, OGBE FUN FUNLE FOSHE FUNLO OLOGARO GOLOWO OMO LAYE OZAIN MOWO OZAIN OSILITUKU WOWO LAYENI OMO OZAIN IÑA OGUNERI IFA OMO OGBE FUN FUNLO ORUNMILA ENI OYA, OTURAO, LODAFUN ORUNMILA, OBATALA OYE OMORABISHE.", "REZO: OGBE FUN IKU FUESAI ORUGABUN YEKI WASI EKUAL ADIFAFUN ERUGBA ESILOPE ESE OBATALA ASHELESE JEKUA ODUSHE GOROGUA MARIBO DIDE AFEFE OTE AFEFE ETA SALUD AYE.", "REZO: ARERE EGGUN YIYEKU NO WAYE SHANGO YEYEREKUN EGGUN MOLELE EGGUN SARAYE OBA KORDARE EGGUN A WAYARE IBA OLORUN KOFIEDEMO EBBO KAYIKO EGGUN EBBO KAYIKO OBA.", "REZO: OGBE FUN FUNLO FOSHE FUNLO OLOGAROGOLOWO MOWO OMO LAYE OZAIN OSILIITKU WONWO LAYENI OMO OZAIN IÑA OWERENI IFA OMO OGBE FUN FUNLO OMO ORUNMILA, ORUNMILA ORUBO.", "REZO: ABITA LOGUN ORUNMILA, ORUNMILA NIKAN TIWO KOMO, OGGUN NI EKETA IMALE KOFIDAN ORUNMILA UMANI ERU IFA, OKUNI KAMPURU ORUNMILA TO BA NIKI IKU ONA LEWA, EDIBADA ABA OLOWARE AKUBI ETU ALU KUBI EKERI AGBA NI IKU ODIJA ABITA TI ORUNMILA, ODIJA ALAFIA BURURU APATAKI IMALE ALA KAIYE IFA ALAFIA. LODAFUN ORUNMILA.", "SUYERE: ONIDE KUYO NIDE, AYARAWO ONIDE KUYU NIDE AYARAWO.", "SUYERE: BARIKU MEBAYA ELEWE WEYI, WEWEYI WEWE OMO BARANU,", "MEBAYA EYE MEBAYA MONA OFO MEBAYA.", "SUYERE: AKUALOYARE ABATILODE EGGUN IKU OFONA.", "SUYERE: OGBE FUN FUNLO OWONIKI AMAIYEGUN OMOKEKERE.", "SUYERE PARA ASHINIMA: OGBE FUN ENI OYA OWO SHINIMA FLUEDERO OGGUN YOYA EGE BAILE FLUDERO OGGUN YOYA EGE BA ILE, OGUNDE OGUNDE ISHE ARA IKOKO OGGUN DE ARIWO.", "SUYERE: ONI KUYU SIDE, ONI KUYU SIDE, ONI KUYU SIDE, AYARABE IALO AFEFE UNTE, UNTE ISLE AFEFE LAE, IKU KUASI IKU MAYEBI OSI NI OPA.", "REZO: ORUNMILA ADIFAFUN KUBITO TOKAYO OKUNI OLAFUN LAISHE OBINI EURE MEYI LEBO ADOFA OWO LEBO OLOFIN OFUN OBINI ODARA IYAWO KUBITO OLOTIYAKO LOWO ARAYE META ODON LESE IGBO LESE ELEGBA ASHIRI LESE IBU ODO, LODAFUN ELEGBA, KAFEREFUN ORUNMILA.", "REZO: ABURE PERRE, PERE, ADIFAFUN ORUNMILA MOBUAN MOBO MOBUAN ORISHA IKU ALASHO ALASHONA.", "REZO: OWENIKU AGBA ASHIRI AMAIYEGUN, LESUN, LABO LERI OGGUN SHANGO ATI AMOKERE, A LO AWONIKU EGUNGUN OMOKERE, AGBA ASHIRI EGGUN EBORA OSHA IMOLE LODAFUN AMAIYEGUN.", "SUYERE: OGBE FUNLO OWONIKU AMAIYEGUN, OMOKERE.", "REZO: OGBE FUNLO FUNLO IKU, UNLO ARUN, UNLO EYO, UNLO OFO,UNLO IÑA, UNLO ARAYE, UNLO AKOBA, OKUMOLORUN INLE, OGBE FUN FUNLO FOSHE FUNLO OLOGARE GOLOWO OMO LAYE OZAIN MOWO OZAIN OSILITU KU WOWO LAYENI OMO OZAIN IÑA, IÑA OGUERENI IFA, OMO OGBE FUN FUNLO ORUNMILA, ENI OYA, OTURAO, LODAFUN ORUNMILA, OBATALA OYE OMORABISHE.", "+++"], "pasajes": [{"titulo": "Suyere 11", "texto_ritual": "OGBE FUN FUNLO OWONIKI AMAIYEGUN OMOKEKERE.\n\nSUYERE PARA ASHINIMA: OGBE FUN ENI OYA OWO SHINIMA FLUEDERO\nOGGUN YOYA EGE BAILE FLUDERO OGGUN YOYA EGE BA ILE, OGUNDE\nOGUNDE ISHE ARA IKOKO OGGUN DE ARIWO.", "origen_id": "c9edc9e5bb4b97f9fd4cace7"}]}]$q$::jsonb),
(32,'8c28b5fd104156a24d68d414b4584c5c','0cc30941e0f5c0e015b431c6767472ee',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ogbè anuncia que la persona se topará con un pleito ajeno. Si en lugar de meterse actúa como mediador, sale ganando. También advierte que hay que cuidarse de las visitas y de la gente que se recibe en casa, porque pueden destruir el hogar. El trabajo o la carrera parecen trabados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su trabajo o su carrera está bloqueado y necesita cambiar de método o de etapa.", "Un pleito entre visitas o gente cercana amenaza la paz de la casa (relato de los dieciséis reyes y Ọ̀rúnmìlà).", "Dejó entrar a alguien en su casa y necesita poner límites (relato del lagarto y el muro de barro).", "Está cerca una mejora de dinero o de amor y teme perderla (relato de Ọ̀rúnmìlà en Àjitòròo Ṣègì).", "Termina una etapa de aprendizaje y le toca asumir responsabilidades de adulto.", "Siente ganas de responder con orgullo a un problema que se puede arreglar con calma."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza y cosas buenas que quedan en la casa después de un pleito entre extraños.", "Paz, que vale más que la riqueza.", "Fortunas que se pegan a la persona y no se le despegan.", "Volver a casa a ocupar el lugar que le corresponde."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Terminación de los ciclos lleva a un camino abierto. (Este odu se refiere a terminar las varias etapas de desarrollo personal en anticipación de la siguiente etapa. Terminar la niñez lleva a ser un adulto.)", "origen_id": "7a8fe44edb8d95b6385855a2"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Aceptar en la casa a alguien que la va a dañar desde adentro.", "Echar de la casa a quien trae la fortuna, por no tener paciencia.", "Perder la fortuna que ya está cerca por no ofrecer."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "Terminación de los ciclos lleva a la inestabilidad radicada en la arrogancia. (Este odu previene que el fracaso para apreciar las responsabilidades de la siguiente etapa de desarrollo puede llevar a problemas. Enfermedades de transmisión sexual).", "origen_id": "3038eb83230f90c413fc3cc6"}]}, {"titulo": "Enseñanza principal", "texto": "Los reyes tienen riquezas pero no tienen paz; Ọ̀rúnmìlà, que ofreció y medió, tuvo las dos cosas. Por eso todo el que manda debe tener un babaláwo como consejero."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú Logbè sugiere (insinúa) que el cliente se tropezará con un conflicto (lucha). Se recomienda que antes de verse envuelto en el conflicto, el cliente deberá actuar como mediador. Si actúan de esta forma, él o ella sacarán provecho (beneficios). También Ọ̀yẹ̀kú Logbè nos advierte que tengamos cuidado de los amigos y personas que acogemos en nuestra casa y que podría causar la destrucción de nuestro hogar.", "origen_id": "094b3f49c3422d24d91e2205"}]}, {"titulo": "Relatos reunidos", "puntos": ["Los extraños que pelean en casa de Ọ̀rúnmìlà. Agila Awo y Opa-gilagila Awo consultaron para los dieciséis reyes y para Ọ̀rúnmìlà, y les avisaron que llegarían unos extraños que se iban a pelear entre ellos. Les marcaron dieciséis babosas, dos chivas y 32,000 cauríes para tener buena fortuna y paz cuando se fueran. Solo Ọ̀rúnmìlà cumplió. Los extraños llegaron a casa de Alárá y empezaron a golpearse; Alárá los echó. Lo mismo hicieron Ajerò y los otros catorce reyes. Cuando llegaron a casa de Ọ̀rúnmìlà, él trató de calmarlos, y mientras peleaban iban dejando dinero, cuentas y joyas, que Ọ̀rúnmìlà recogía. La pelea duró días, hasta que su casa quedó llena de riqueza. Los dieciséis reyes son Olówu, Olibini, Alárá, Ajerò, Ọràngún, Èwí, Aláàfin de Ọ̀yọ́, Owore, Ẹlẹpẹ, Ọba Adada, Alaajogun, Olú Oyinbo, Olú Ṣabẹ, Ọlọ́wọ̀, Olú Tapa y Olóko.", "El lagarto y el muro de barro. Arun-poṣe-ireke consultó para el lagarto de la casa cuando iba a vivir en un muro de barro. Al lagarto le marcaron cuatro palomas para tener un lugar cómodo, y cumplió. Al muro le marcaron un gallo para que no aceptara a alguien que lo fuera a escarbar por dentro, y no quiso. Por eso el lagarto vive cómodo dentro del muro y lo va agujereando.", "La riqueza que se pega. Ifá consultó para Ọ̀rúnmìlà el día que iba a la ciudad de Àjitòròo Ṣègì, y le preguntó si sus asuntos marcharían bien, si se establecerían seguros y si no perdería lo bueno. Le marcaron una paloma vieja y bastante dinero. Ofreció, y la riqueza se le pegó y no se le cayó, igual que las esposas, los hijos y todo lo bueno. Cantó: 'La riqueza se pegó a mí y no se cayó, wonkoko, como los racimos se pegan al tronco de la palma'.", "El bejuco del campo. Ifá consultó para Awóńwón, el bejuco trepador, que era adivino en el campo. Le dijeron que su destino era que la fortuna llegara a él, que ofreciera y fuera a su lugar de trabajo. Ofreció, todo lo bueno empezó a entrar bajo su techo, y le pidieron volver a casa a sentarse en su trono."], "pasajes": [{"titulo": "Verso 32.1", "texto": "Agila Awo,\nAgila Awo,\nOpa-gilagila Awo:\nadivinaron Ifá para Aladé Mẹrindilógún\n(los dieciséis reyes),\nadivinaron también para Ọ̀rúnmìlà.\nLos adivinos dijeron:\n\"están llegando unos visitantes (extraños)\nquienes pelearán entre ellos\"\nPor eso ellos aconsejaron a todos sacrificar\npara tener buena fortuna y paz\ndespués de la partida de los extraños.\nSacrificio: dieciséis caracoles babosa,\ndos chivas y 32000 cowries.\nỌ̀rúnmìlà fue el único que efectuó el sacrificio.\nCuando llegaron los extraños a casa de Alárá,\ncomenzaron a golpearse unos contra otros.\nAlárá los echó fuera de su casa.\nTambién fueron a casa de Ajero\ny a la de los 14 reyes restantes,\ntodos ellos echaron a los extraños.\nCuando los extraños\nllegaron a casa de Ọ̀rúnmìlà\ny comenzaron a golpearse unos a otros\nỌ̀rúnmìlà trató de pacificarlos,\nmucho dinero y cuentas fueron dejadas\npor estos luchadores extraños.\nỌ̀rúnmìlà estaba ocupado\nrecogiendo todo el dinero,\nlas cuentas preciosas y joyas.\nLa batalla entre los extranjeros\ncontinuó por días,\nhasta que la casa de Ọ̀rúnmìlà\nestuvo repleta de dinero y de cosas buenas.\nỌ̀yẹ̀kúlogbè Edú se tranquilizó,\nlos nombres de los dieciséis reyes son:\nOlówu, Olibini, Alárá, Ajerò,\nOràngún, Ewí, Alaafin-Ọ̀yọ̀, Owore,\nElẹpẹ, Ọba-Adada, Alaajogun, Olù-Oyinbo,\nOlù-Ṣabẹ, Ọlówọ, Olú-Tapa y Olóko u Oṣinlẹ.\nLos reyes tienen riquezas\ny todas las cosas buenas,\npero no tienen paz,\nỌ̀rúnmìlà, el único que efectuó el sacrificio\ntiene una paz completa.\nEsta es la razón por la que todos los reyes\ndebieran tener Babaláwos como consejeros,\nespecialmente cuando se enfrentan\ncon problemas o dificultades.", "origen_id": "31f52eab3636bbe8b2ab65ad"}, {"titulo": "Verso 32.2", "texto": "Arun-poṣe-ireke:\nadivinó Ifá para Omo-nlé (lagarto casero),\ncuando él iba a vivir con Oro (muro de barro).\nLe fue aconsejado a Ọmo-nlé hacer sacrificio:\ncuatro palomas,\npara asegurar un lugar confortable para vivir.\nEl hizo el sacrificio.\nLe fue aconsejado a Ọrọ hacer sacrificio\npara que no fuera a aceptar la compañía\nde alguien que fuera a cavar dentro de él\n(no acertar a alguien que fuera hacerle daño)\nSe le pidió sacrificar un gallo.\nỌrọ rehusó sacrificar.", "origen_id": "cfbd3dafc77f04e797fd193f"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que la persona sacrificará para no perder la\nfortuna que está por llegarle y está muy cerca de su\nmorada.\n\n                Òyèkú lợ logbè\n           Kankaankan bííná ẹyín\n             A dífá fún Òrúnmìlà\n       Nijó ti Ifá ń rebi àjitòròo şègì\n          Nňkan òún le dáa báyìí?\n            Ó wúlò fóun ńlé ayé?\n              Nňkan òún tòrò?\n         Kò já sợnù mó òun lówó?\n               Wón ní kó rúbợ\n        Wón ní kó rú òwúùrù ẹyẹlé\n            Kó si rú ợpợlợpợ owó\n                Òrúnmìlà rúbợ\n                   Ajé bá dé\n              Ó di mó Òrúnmìlà\n                     Kò já\n               Aya náà di mó ợ\n                     Kò já\n               Ire gbogbo ò já\n              Ayé yẹ Òrúnmìlà\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n                Òyèkú lợ logbè\n           Kankaankan bííná ẹyín\n             A dífá fún Òrúnmìlà\n       Nijó ti Ifá ń rebi àjitòròo şègì\n         Wón ní ó sá káalè ó şẹbợ\n\n             Òrúnmìlà gbébợ ńbè\n                   Ó rúbợ\n          Ńjé ajé wo mó mi mó jàá\n                  Wonkoko\n              Nítàá woó méyìn\n                  Wonkoko\n            Aya wo mó mi mó jàá\n                  Wonkoko\n              Nítàá woó méyìn\n                  Wonkoko\n            Ợmợ wo mó mi mó jàá\n                  Wonkoko\n              Nítàá woó méyìn\n                  Wonkoko\n        Ire gbogbo wo mó mi mó jàá\n                  Wonkoko\n              Nítàá woó méyìn\n                  Wonkoko\n\nEs Òyèkú que posee a Ogbè\nY que brilla como la leña del carbón\nProfetizó Ifá para Òrúnmìlà\nEl día en que Ifá venía a la ciudad de Àjitòròo şègì\n¿Podrán marchar bien mis asuntos?\n¿Me serán útiles del todo?\n¿Podré establecerlas bien seguras?\n¿No perderé las buenas cosas de la vida? Se\npreguntó a Ifá\nLe pidieron que sacrificara\nEllos dijeron que una Paloma entrada en años era el\nsacrificio\nAdemás de bastante dinero Òrúnmìlà ofrendó\nLa riqueza se pegó a él y llegó a montones\nAsí como las demás bendiciones seguras nunca le\nfaltaron\n\nY la vida le fue en extremo placentera\nÉl alabó a sus babaláwos y ellos alabaron a Ifá\nÉl hizo todo como ellos le dijeron que hiciera\nEs Òyèkú que posee a Ogbè\nY que brilla como la leña del carbón\nProfetizó Ifá para Òrúnmìlà\nEl día en que Ifá venía a la ciudad de Àjitòròo şègì\nSe le dijo que cuidase de la tierra y sacrificase Él lo\nrealizó\nLa riqueza se pegó a mí y no se perdió\nWonkoko\nEs la manera como se adhiere el tronco a las frutas\nde la Palma de aceite\nWonkoko\nLas esposas se pegaron a mí y no se perdieron\nWonkoko\nEs la manera como se adhiere el tronco a las frutas\nde la Palma de aceite\nWonkoko\nLos descendientes (hijos) se pegaron a mí y no se\nperdieron\nWonkoko\nEs la manera como se adhiere el tronco a las frutas\nde la Palma de aceite\nWonkoko\nTodas las buenas cosas de la vida vinieron a mí y no\nse perdieron\nWonkoko\nEs la manera como se adhiere el tronco a las frutas\nde la Palma de aceite\nWonkoko\n\n             Òyèkú logbè lábàrá\n             A dífá fún Awóńwón\n                Awo wợn lóko\n          Lóko ní Awóńwón tíí şawo\n\n         Wón ní ìwợ Awóńwón rúbợ\n   Ní ibùjokòó rẹ nire ó ti móo wáá bá ợ\n           Ó bá kợrí síbùjokòó rè\n            Iré bèrè síí wợlé tò ó\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n             Òyèkú logbè lábàrá\n            A dífá fún Awóńwón\n                Awo wợn lóko\n              Awóńwón pèlé o\n                  Awo oko\n        Wón ní o wáá joyè o wá ńlé\n\nÒyèkú logbè lábàrá\nLanzó Ifá para el bramante Awóńwón\nSus adivinos en la villa\nAwóńwón había venido practicando su sacerdocio\nen esta villa y ellos le dijeron que debía sacrificar\nEstá en su destino que las fortunas vengan a ti Ve a\ntú lugar de trabajo         Y todas las buenas cosas\ncomenzaron a entrar bajo su tejado\nÉl alabó a sus babaláwos y ellos alabaron a Ifá\nÉl hizo todo como ellos le dijeron que hiciera\nÒyèkú logbè lábàrá\nLanzó Ifá para el bramante Awóńwón\nSus adivinos en la villa\nTe saludo Awóńwón\nEl sacerdote establecido en el campo\nSe te pidió venir a casa y sentarte en el trono", "origen_id": "0f5b469c2525c1fa6b9a84bf"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku Logbe nos habla que el cliente se encontrará en un\n     conflicto. Se recomienda que antes de verse envuelto, el cliente deberá\n     actuar como intermediario. Haciendo esto, él o ella sacarán provecho.\nTambién nos advierte que tengamos cuidado los amigos que podría causar\n                                                la destrucción de nuestro hogar.\n            WO – Un trabajo o carrera, parece haber sido bloqueada o está en\n                                                                   dificultades.\n      En la filosofía Yoruba no hay ida sin retorno (Oyeku) el decimoctavo\nOdu fijado de Orunmila representa el retorno de Oyeku, el lado derecho de\nOgbe ahora en el izquierdo . Este Odu completa el ciclo de movimiento de\n                                             Ogbe a Oyeku y de Oyeku a Obge.\n\n\n32.1 · Agila awo, Agila awo, Opa-gilagila awo adivinó Ifá para Alade\n\nMerindilogun, (16 reyes) y para Orunmila, Ifá predijo el arribo de\nalgunos extraños quienes pelearían entre ellos. Se le aconsejó por lo\n  tanto, ofrecer sacrificio para tener paz después de la partida de los\n       extraños. Ebo: 16 caracoles de babosa, 2 chivas, y 32 cowrie.\n                     Orunmila fue el único que efectuó el sacrificio.\n      Cuando llegaron los extraños a casa de Alara y comenzaron a\n    golpearse unos contra otros. Alara los echó fuera a los extraños\ntambién fueron a casa de Ajero y a la de los 14 reyes restantes todos\n                                          ellos echaron a los extraños.\nPero cuando los extraños llegaron a casa de Orunmila y comenzaron\n    a golpearse unos a otros Orunmila trató de pacificarlos, dinero y\n   cuentas fueron dejados por estos luchadores extraños y Orunmila\n estaba ocupado recogiendo todo el dinero y las preciosas cuentas y\n                                                                joyas.\n La batalla entre los extranejros continuó por días, hasta que la casa\n     de Orunmila estuvo repleta de dinero y de cosas buenas Oyeku\n  Logbe Edu se tranquilizó, los nombres de los 16 reyes principales\n     son Olowo, Olibini, Alara, Ajero, Orangun, Ewi, Alaafin-Oyo,\n    Owore, Elepe, Oba-Adada, Alaajogun, Olu-Oyinbo, Olu– Sabe,\n                                   Olowo, Olu-Tapa y Oloko u Osinle.\n  Los reyes tienen riquezas y todas las cosas buenas, pero no tienen\n      paz, Orunmila, el único que efectuó el sacrificio tiene una paz\n completa. Esta es la razón por la que todos los reyes debieran tener\nBabalawos como consejeros, especialmente cuando se enfrentan con\n\nproblemas o dificultades.\n\n\n32.2 · Arun-posei-ireke adivinó Ifá para Omo-nle (lagarto casero),\n              cuando él iba a vivir con Oro (muro de barro). A Omo-nle se le\n      aconsejó sacrificar 4 palomas, para asegurar un lugar confortable para\n      vivir. El hizo el sacrificio. A Oro se le aconsejó sacrificar para que no\n             aceptara la amistad de cualquiera que pudiera hacerle el mal. Fue\n           pedido 1 gallo para este sacrificio. Oro rehusó sacrificar. Debido a\n           que Oro rehusó aceptar el sacrificio prescrito por Ifá, ella tuvo que\n          suministrarle una vivienda a Omo Nle, en otras palabras los lagartos\n                                             viven ahora en los muros de barro.", "origen_id": "e759fdb91a8c6f83a1a8958a"}, {"titulo": "Relato en inglés 1", "texto": "“The hunter opens his pouch and takes out poison;+ Argnimgja loosens his\npouch and takes out medicine;? the farmer seeks a soft piece of ground in which\nto plant his yams” was the one who cast Ifa for Oluorogbo, the apprentice® of\n“King on earth\"? and who beat palm nuts for Olushonsho, the apprentice of\n\n“King in the sky.? They said that if it should happen that the earth should spoil,\nOluorogbo will set it right again; if it should happen that heaven should spoil,\nOlushonsho will set it right again. Olushonsho is the name that we call Qramfe.\n\nIfa says that a deity® will set the world of this person right again in the mat-\nter for which he cast this figure. Four rats, four fish, and four snails is the sac-\nrifice. We will finish making this sacrifice; then we will carry a covered offer-\ning’ to this deity.", "comentario": "1. Oro (poison) is used by hunters, both as an ingredient in charms and on\nthe tips of arrows, 4\n\n2. Argnimgja (or Argni) is a spirit living in the forest; he frequently ab-\nducts humans and either kills them or sends them back with a vast knowledge of\ncharms and medicines. It is to this that the phrase refers. Cf. Farrow (1926:\n65).\n\n3. An apprentice carries his master’s bag and runs errands for him. Cf.\nn, 4, verse 6-1,\n\n4. Oluorogbo is a title of Orisha Alashe, one of the white deities. Aja is\nsaid to be a contraction of 9-1(i)-gja (one:who-has-market), the “owner of the\nmarket,” and to refer to the ruler of a town; and some informants identify the\n“King on earth” with such rulers as the Qni of Ifẹ and the Alafin of Ọyọ. However\n4. (Cont.) here it seems to refer to a deity, the counterpart of the Sky God,\nwho is ruler over the earth; but no details concerning such a deity could be ob-\ntained. His association with Orisha Alashe makes it unlikely that the reference\nis to Ogboni, the Earth God and son of Odua.\n\n5. Olushonsho, as this verse explains, is a title of Qramfe (or Qramife), a\nGod of Thunder and the Ifẹ counterpart of Shango. His name is said to mean Qra-\nhas-If¢ [Qra-n(i)-If¢] or “Qra owns the town of Ifẹ. “The King in the sky” was\ninterpreted as being Q-l(i)-grun, the Sky God. Although some informants equate\nQramfg¢ with the Sky God, he is specifically described here as his messenger or\napprentice.\n\n6. Orisha does not seem to refer to Orishala here, but rather to one of his\nfollowers, Orisha Alashe, who is mentioned in this verse by his title Oluorogbo.\n\n7. An ibo here is a covered offering, usually of little monetary value (cold\nwater, kola nuts, etc.) which is carried to the deity either enclosed in a calabash\nwith a lid (such as igbademu), or wrapped in a bag or leaf.", "origen_id": "17887719b2741e744c4b7d46"}, {"titulo": "Relato en inglés 2", "texto": "ba\n\n\"Ashedere,\" the diviner of the Agbe bird,! was the one who cast Ifa for the\nAgbe bird when he was going to take Olukori as hig wife. He said that the storm\nclouds might grow dark “fere,” and the rain might beat down “giri,”? but he still\nwould not fail to bring home his wife.\n\nIfa says that this is his wife;? if we do not give this woman to him, she will\ndie. Two hens, two rats, two fish, and one shilling is the sacrifice.4 When we\nhave completed the sacrifice, we will give the woman to a diviner who is indi-\ncated through the use of specific alternatives® as the one to whom the woman\nshould be given.", "comentario": "1, Agbe is identified as \"a kind of woodcock” in the CMS Dictionary, as a\ncockatoo by Bowen (1858), and as “the bird Blue Touraco Musophagidae, i.e.\nCuckoo Family” by Abraham (1958),\n\n2. Giri represents the sound made by rain falling heavily; fẹrẹ describes\nthe way in which rain clouds gather.\n\n3. That is, a “wife of Ifa.\" See n. 5, verse 3-4,\n\n4. Since cowries are counted by the two thousand, there are two units of\ncowries, as there are two hens, rats, and fish.\n\n5. See Chapter V.", "origen_id": "f1ba46b9053cdb2fbe92e9df"}, {"titulo": "Relato en inglés 3", "texto": "“Qyeku next to Ogbe, Qyeku next to Ogbe\"! was the one who cast Ifa for “The\nchild that does not die but returns to life.’”?_ They said no one would be as old as\nhe. They said one ewe and five shillings is the sacrifice. “The child who does\nnot die but returns to life” is the name of Road. Ifa says someone should make\na sacrifice that he may be able to grow old.", "comentario": "1. Qyeku-1(u)-Ogbe is a commonly used alternative name for Qy¢ku Ogbe.\n\n2. Is reincarnated in another child. Cf. Bascom (1960).\n\n3. This verse thus explains why a read “lives” for such a long time, and why\nit is older than human beings. Road is identified as the character for whom the\nprecedent divination was made, and it is implied that he made the sacrifice.", "origen_id": "bb74921818fc917b28d7b5c3"}, {"titulo": "Relato en inglés 4", "texto": "“An iron staff strikes the ground ‘ha nana’”? was the one who cast Ifa for\nAraba? when he was going to take a title belonging to his house. They said we\nmust assemble to serve him. Ifa says someone should make a sacrifice because\nof a title that is to be taken in his lineage; he says that someone who is descend-\ned from the chief will be made chief. One ram, one white cloth to cover the body,\nand four shillings is the sacrifice.", "comentario": "1, The sound made by an iron staff, vibrating efter its end has been struck\nagainst the ground. Cf. n. 5, verse 19-1.\n2. The title of the chief priest of Ifa and highest ranking diviner.", "origen_id": "7e0bfb4cddec134eba9e63d0"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà y los dieciséis reyes: dieciséis babosas, dos chivas y 32,000 cauríes.", "El lagarto: cuatro palomas. El muro (rechazado): un gallo.", "Para que la riqueza se pegue: una paloma vieja y bastante dinero."], "pasajes": [{"titulo": "Ofrenda en el verso 32.1", "texto": "Agila Awo,\nAgila Awo,\nOpa-gilagila Awo:\nadivinaron Ifá para Aladé Mẹrindilógún\n(los dieciséis reyes),\nadivinaron también para Ọ̀rúnmìlà.\nLos adivinos dijeron:\n\"están llegando unos visitantes (extraños)\nquienes pelearán entre ellos\"\nPor eso ellos aconsejaron a todos sacrificar\npara tener buena fortuna y paz\ndespués de la partida de los extraños.\nSacrificio: dieciséis caracoles babosa,\ndos chivas y 32000 cowries.\nỌ̀rúnmìlà fue el único que efectuó el sacrificio.\nCuando llegaron los extraños a casa de Alárá,\ncomenzaron a golpearse unos contra otros.\nAlárá los echó fuera de su casa.\nTambién fueron a casa de Ajero\ny a la de los 14 reyes restantes,\ntodos ellos echaron a los extraños.\nCuando los extraños\nllegaron a casa de Ọ̀rúnmìlà\ny comenzaron a golpearse unos a otros\nỌ̀rúnmìlà trató de pacificarlos,\nmucho dinero y cuentas fueron dejadas\npor estos luchadores extraños.\nỌ̀rúnmìlà estaba ocupado\nrecogiendo todo el dinero,\nlas cuentas preciosas y joyas.\nLa batalla entre los extranjeros\ncontinuó por días,\nhasta que la casa de Ọ̀rúnmìlà\nestuvo repleta de dinero y de cosas buenas.\nỌ̀yẹ̀kúlogbè Edú se tranquilizó,\nlos nombres de los dieciséis reyes son:\nOlówu, Olibini, Alárá, Ajerò,\nOràngún, Ewí, Alaafin-Ọ̀yọ̀, Owore,\nElẹpẹ, Ọba-Adada, Alaajogun, Olù-Oyinbo,\nOlù-Ṣabẹ, Ọlówọ, Olú-Tapa y Olóko u Oṣinlẹ.\nLos reyes tienen riquezas\ny todas las cosas buenas,\npero no tienen paz,\nỌ̀rúnmìlà, el único que efectuó el sacrificio\ntiene una paz completa.\nEsta es la razón por la que todos los reyes\ndebieran tener Babaláwos como consejeros,\nespecialmente cuando se enfrentan\ncon problemas o dificultades.", "origen_id": "834924ee479c6e4d17bdbd18"}, {"titulo": "Ofrenda en el verso 32.2", "texto": "Arun-poṣe-ireke:\nadivinó Ifá para Omo-nlé (lagarto casero),\ncuando él iba a vivir con Oro (muro de barro).\nLe fue aconsejado a Ọmo-nlé hacer sacrificio:\ncuatro palomas,\npara asegurar un lugar confortable para vivir.\nEl hizo el sacrificio.\nLe fue aconsejado a Ọrọ hacer sacrificio\npara que no fuera a aceptar la compañía\nde alguien que fuera a cavar dentro de él\n(no acertar a alguien que fuera hacerle daño)\nSe le pidió sacrificar un gallo.\nỌrọ rehusó sacrificar.", "origen_id": "5fd37a07fe22802d71fea0a6"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es el mediador que gana la paz. Los dieciséis reyes representan el poder sin consejo. Ifá recibe las ofrendas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Babosas, palomas, cuentas preciosas, racimos de la palma, bejuco awóńwón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 32.1 (yorùbá): Agila Awo, / Agila Awo, / Ọpa-gilagila Awo: / wọ̀n dífá f'Alade Mérindílógún, / wọ̀n dífá f'Ọ̀rúnmìlà. / wọ̀n nì: / \"Awon àlejò kan nbọ, / ijà ni wọ̀n mi a maa / jà nigbati wọ̀n ba de\". / Nitorinaa kiwọn rúbọ / ki adẹhinbọ akoko / ti àwọn àlejò naa wa le bosi ire fún wọn. / İgbin mẹrindilógún, / ewúrẹ Méjì, égbàá mẹrindilógún owó. / Ọ̀rúnmìlà nikansoso li o rúbo ninu won. / Nigbati o pẹ diẹ àwọn àlejo / naa de si llé Alárá. / Nigbati wọ̀n bẹrẹsiina ara wọn, / Alárá le wọn jade. / Wọ̀n de ilé Ajerò / ati gbogbo àwọn Alade Mérinlá iyokun. / Wọ̀n le wọ̀n jade / Ṣùgbọ̀n nikẹhin àwọn àlejò / naa wade ilé Ọ̀rúnmìlà, / wọ̀n bẹrẹsii na ara wọn. / Ọ̀rúnmìlà nla wọ̀n nijà, owó nbọ, / ilẹkẹ nbọ silẹ. / Ọ̀rúnmìlà nko gbogbo àwọn / inkan alumoni ti nbosilẹ / li ara wọ̀n s'ile. / Bẹẹ ni wọn nṣe li ojoojumo / titi ilé Ọ̀rúnmìlà / fi kun fún owó / ati awon ohun rere miran gbogbo. / Qyèkúlogbè! ara mi tu Ẹdú nẹne. / Oruko àwọn Aladé mẹrindilógún / agbà naa ni: / Olówu, Olibini, Alárá, Ajerò, / Oràngún, Èwí, Alaafin-Qyọ̀, Owore, / Flẹpẹ, Ọba Adada, Alaajogun, / Olú-Oyinbo, Olú-Ṣabẹ, Ọlówọ, / Olú-Tapa, Olóko tabi Oṣinlẹ. / Àwọn Ọba wọ̀n ni owó / tabi ohun rere miran, / sibẹsibẹ wọ̀n ko ni itura. / Ọ̀rúnmìlà nikansoso / ti o rúbọ lioni itura pipe. / Nitori Ìdí eyi ni àwọn Ọba / kò le wa laini / Babaláwo gẹgẹbi òkan / ninu àwọn ti yoo maa / fún wọn ni imoran paapaa / nigbati iyonu tabi wahala ba de ba wọn.", "Verso 32.2 (yorùbá): Arun-poṣe-ireke: / li o dífá f'Ọmo-nlé / nlọ ṣe ibakalẹ (Orọ) ipalero. / Wọ̀n niki Ọmo-nlé rú: / Fiyẹle mẹrin / ki o baa le ribi rere joko si. / Ó rú bọ. / Wọ̀n niki Ọrọ rúbọ / kioma baa gba ibakalẹ buburú / ti o mi a maa waa ni'di s'ode. / Akuko-adiyẹ kan ni ẹbọ. / Ọro, eyini ni Ogiri, kò rúbọ.", "REZO: OYEKUN NILOBE BABA AMALU KOMA ARUGBO NISHE EKUN BAYE AVALO BOGBO NISHE AYALO OUN BISYE OMODE BAYA OMA ARUGBO NITU AYE SHE OBIFIN OBIFA KONINIBO.", "REZO: BARA OYEKUN SEMI LOGUE RAULO ASHESE BODO LORISHA.", "SUYERE: ORO NIDE IKU DEDE OMI ODUDUWA AWODE TESIODE ODIRISHE.", "SUYERE: ARARA SOBEYEYO BADO AKUE DAYOKUN YEKU LOBE SOBEYEYO BANOWI BAMIESI YEKU LOGBE.", "SUYERE: OKOKIDI IKIDI KUADE OMO DUDU DESHESI OKOKIDI IKIDI KUADE OMO DUDU DESHESI AWO.", "REZO: BABA ODAJUN RA UNLO LORI ESHESI ODO ORISHA.", "REZO: ONILA SHANGO Y EBELLI OBATALA NI OLOGUN NI ORUNMILA ORONIN SHAGUE OFA OLLEGUNGUI EGUIN ECHIGUELLE OLIROBO NINCHE COLA OYA ONI SHOSHORO ICRINOCU GUEGUERE COLLE KOBAYO ELIROBO NI TA LLECHE COMO FICAN ILUA TOBAFO PE LE OLLE EBBO LUBO EGUO LA MELLO.", "REZO: OGBE EKO OYEKUN OGGUN OLOKOSHE EYANKA ELULU EYIOSA EIYE, LODAFUN OZAIN, KAFEREFUN ORUNMILA.", "REZO: UMBOIFA INLE OLOFIN AWO MERILOGUN OMO IFA OUNTISHE ATEFA AYO OMODE OLOFIN OMO LAYE LOVI OMO OLUO INTORI KEKERE ODDUN."], "pasajes": [{"titulo": "Encantación para protección, salud y alejar malas influencias (Oyeku Ogbé)", "texto_ritual": "I sé orí ran ni rí mo n jé Oná ti Órísás la sí/é ni mo n to mo Toná titi mo fi dé gbó oiú koro koro bijó Moba aro ¡oná ara ó sé gbá iojú Moba arara ioná arara Ó sé di n¡gbó laya Órísás io dawo Efun te Epin ¡orí A d'ífá fún Eri Nitor i n ti odé órun bó wá sité ayé Njé ewo owó ope tara ni e wá owó ope ¡ara ni ti a ba jé eto tan á darijin i pe pe re jé erán ata tan a darijin ipe pe re ti a be jé Eran Oore tan a darijin ¡pepe re jé Eran iówó iówó ru ti Eran Oore tan a dari jin ¡pepe re jé Eran iówó iówó ru ti Eran be jé ti á bá J Jé igbon tan a dari jin ikarahun re Njé e jé kí orno o/ówó iié Ewé o/ówó ókó orno a rayé kó sai fowó témi wómi tori pe Emi toba ná Óyékú á riga ogbé Ó owó ope ¡ara mi ewo owó ope", "traduccion": "El destino me ha mandado a hacer un mandado. Es el camino que ha seguido la deidad, el cual yo sigo. Caminé por el camino hasta que llegué al pueblo de Olu Koro Koro bij. Me encontré un inválido en el camino, no se le puede dar golpes. Me encontré un enano en el camino, que es el que limpia al Órisás y marca con la mano limpia. Epin hizo adivinación para alguien honorable, que venía del cielo a la tierra. Por eso la mano de Ifá está sobre mí. Después que comemos, perdonamos a las hojas después de comer Aka. Soltamos el Ipe, es un honor haber comido al animal de Ibeje. Después de comer babosa, perdonamos al caracol. Por eso el hijo de Olooro debe ir.", "origen_id": "71a8fc588bd6abc5bdc0af17"}, {"titulo": "Oyeku Logbe — el contrabure", "texto_ritual": "Oyeku logbe konkolojiko Adifa fun bata Tinse omo leyin sango Bata ani oyekun logbe kokolojiko", "traduccion": "Oyeku logbe konkolojiko. Hizo adivinación para bata, el acompañante de Sango. Bata suena oyekun logbe konkolojiko.", "origen_id": "4dd09b22e9969c250286a342"}]}]$q$::jsonb),
(33,'4c428f2c73577a1db22abe5d97ca1f1e','abca7e0d415bc778837168413469abf7',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìwòrì trae solución para la esterilidad de la mujer y del hombre y para la impotencia. Es un momento muy propicio para quedar embarazada. También pide ofrecer en grande para que la vida sea bella y placentera hasta el final."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pregunta por un embarazo o por hijos (relato de las palomas Eyẹlé y Adaba).", "Le preocupa un problema sexual o para tener hijos (relato de Oromina).", "Quiere saber si su vida mejorará y si podrá disfrutar lo que espera (relato de Wáléọlá).", "Una etapa terminó en conflicto y necesita aprender a cuidar a quienes dependen de él.", "Busca apoyo mutuo en la pareja sin que el deseo de tener hijos se vuelva motivo de culpa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fertilidad para la mujer y para el hombre.", "Un embarazo en buen momento.", "Una vida bella y rica hasta el final.", "Paz mental."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva a la transformación. (Este Odu habla de la necesidad para tomar responsabilidad por el bienestar de otra persona).", "origen_id": "f6acae77a83cb3a6be1a55a0"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Fracasar en la intimidad por no ofrecer.", "Vivir con la duda de si la vida será buena."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva al conflicto. (Este Odu habla de la posibilidad de impotencia o de la infertilidad).", "origen_id": "4961e51c43052661ff20c3e4"}]}, {"titulo": "Enseñanza principal", "texto": "La paloma y el palomo ofrecieron los dos, y los dos fueron fértiles: la descendencia es tarea de la pareja. Y quien ofrece en abundancia, vive en abundancia."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù yèkúbiwòrilodò ofrece soluciones para la esterilidad femenina y masculina, y para la impotencia masculina.", "origen_id": "c13ddc8c85ded88e7efcc718"}]}, {"titulo": "Relatos reunidos", "puntos": ["La paloma y el palomo. Ọ̀yẹ̀kúbìrì consultó para la paloma y le dijo que sería fértil si ofrecía doscientos frijoles y 2,000 cauríes. Cumplió y fue fértil. También consultó para el palomo, que hizo su ofrenda y también fue fértil.", "Oromina va a la lucha. Los adivinos Ọ̀yẹ̀kú y Ìwòrì consultaron para Oromina, el miembro viril, cuando iba a pelear en la ciudad de Ajatiri, y le advirtieron que si no ofrecía no lograría entrar. Le marcaron tres carneros, tres chivos, tres perros machos, tres gallos, tres jicoteas machos y 6,600 cauríes. Cumplió y logró entrar.", "Wáléọlá, el que trae riqueza a casa. La Tierra se traga todo lo que se le da como regalo. Así se consultó para Wáléọlá, hijo de Àsàńléèyere, que preguntaba si la vida le sería placentera hasta el final. Le pidieron una ofrenda enorme; la dio en grande, cumplió los ritos y su vida fue placentera. Wáléọlá es el sobrenombre del hombre blanco: nadie ha sido tan rico como él, y gasta su dinero siempre fresco.", "El espectro que bajó del cielo. 'Ọ̀yẹ̀kú gira para acá, Ọ̀yẹ̀kú gira para allá, y la cara de la bandeja de Ifá se llena hasta el borde.' Así se consultó para el espectro que venía del cielo a la tierra, para que dejara de preguntarse si la vida le sería buena. Ofreció, hizo los regalos a Èṣù y encontró la paz. Las bendiciones se encuentran al pie del rey de los Òrìṣà."], "pasajes": [{"titulo": "Verso 33.1", "texto": "Ọ̀yẹkúbìrì:\nadivinó Ifá para la paloma (Eyẹlé).\nÉl dijo: \"la paloma será fructífera (fértil)\",\npor lo tanto ella deberá sacrificar:\n200 frijoles (Igbá eree) y 2.000 cowries.\nElla escuchó y ejecutó el sacrificio.\nLa paloma se convirtió en fructífera (fértil).\nÉl también adivinó para el palomo (Adaba).\nÉl fue aconsejado ofrecer el sacrificio.\nEl palomo ejecutó el sacrificio.\nÉl se convirtió en fructífero (fértil).", "origen_id": "6750fedb8dba2a7dd4689f95"}, {"titulo": "Verso 33.2", "texto": "Ọ̀yẹ̀kú-awo-omodé,\nÌwòrì-awo-àgbàlagbà\nBi oyin kobaṣeerẹ-ofufu-liafiitini'di:\nadivinaron Ifá para el pene (Oromina),\ncuando iba a luchar en la ciudad de Ajatiri.\nEllos dijeron:\n\"si no sacrifica, fracasará en penetrar\".\nSacrificio: Tres carneros,\ntres chivos, tres perros (machos),\ntres gallos, tres jicoteas machos\ny 6.600 cowries.\nEl escuchó y ejecutó el sacrificio.\nÉl logró penetrar.\nOromina es lo que llamamos pene.", "origen_id": "94aa93980a0253229324b221"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le pide a esta persona que sacrifique para que la\nvida le sea bella y placentera y obtenga las buenas\ncosas que brinda el Cielo.\n\n          Iná jókùn wợn a dìkán\n      Iná jó réfe tán ló bá ń dẹfun\n         Ilè níí jòtòtò èèyàn lérù\n            A dífá fún Wáléợlá\n        Èyí tíí sợmợ Àsàńléèyere\n        Ayé le yẹ òun délè báyìí?\n       Wón ní kó rú ợpợlợpợ ẹbợ\n  Wáléợlá ợmợ Àsàńléèyere bá dẹbợợ lẹ\n                 Ló bá rúbợ\n        Ló rúbợ tán layé bá yẹ é\n            À á séé mợ Wáléợlá\n               N làá pé Èèbó\n                   Ayé yẹ é\n          N ní wá ń jó ní wá ń yò\n        Ní ń yin àwợn Babaláwo\n        Àwợn Babaláwo ń yin Ifá\n   Ó ní béè làwợn Babaláwo tòún wí\n          Iná jókùn wợn a dìkán\n      Iná jó réfe tán ló bá ń dẹfun\n         Ilè níí jòtòtò èèyàn lérù\n            A dífá fún Wáléợlá\n        Èyí tíí sợmợ Àsàńléèyere\n  Bàbá ẹnìkan ò là làà là kée téèbó mợ\n       Èèbó dé ò abợlà rẹberẹbẹ\n        Owó minimini lèèbó ń ló\n\nIná jókùn wợn a dìkán\nIná jó réfe tán ló bá ń dẹfun\n\nEs la Madre Tierra quien se traga todo en forma de\nlibres regalos\nLanzó Ifá para Wáléợlá, el hijo de Àsàńléèyere\nQuien se preguntaba si la vida le sería placentera\nhasta su final\nLe dijeron que ofrendara un enorme sacrificio\nY brindó su ofrenda en multitudes              Finalizó\nobservando los ritos y la vida le fue placentera\n¿Cómo sabemos quién es Wáléợlá, el hijo de\nÀsàńléèyere?\nEse es el sobrenombre que se le da al Hombre\nBlanco\nÉl alabó a sus babaláwos y ellos alabaron a Ifá\nÉl hizo todo como ellos le dijeron que hiciera\nIná jókùn wợn a dìkán\nIná jó réfe tán ló bá ń dẹfun\nEs la Madre Tierra quien se traga todo en forma de\nlibres regalos\nLanzó Ifá para Wáléợlá, el hijo de Àsàńléèyere\nNunca nadie ha sido tan rico como el “Hombre\nBlanco”\nEl Blanco está aquí con una estupenda riqueza y\ngasta su dinero fresco\n\n            Òyèkú pòòrì síhìín\n           Òyèkú pòòrì sóhùún\n          Ojú Ợpón kún tétéété\n A dífá fún Eégún ti ń tòrun bò wálé ayé\n             Wón ní kó rúbợ\n           Ayé le yẹ òún báyìí?\n          Wón ní ayé ó yẹ Eégún\n               Ệbợ ní kó rú\n              Eégún bá rúbợ\n              Okáan rè balè\n                 Ó nísinmi\n              Ni bá ń dá bírà\n\n          Ó ní Òyèkú pòòrì síhìín\n           Òyèkú pòòrì sóhùún\n          Ojú Ợpón kún tétéété\n A dífá fún Eégún ti ń tòrun bò wálé ayé\n         Wón ní ó sá káalè ó şẹbợ\n            Eégún gbébợ ńbè\n                  Ó rúbợ\n          Rírú ẹbợ èèrù àtùkèşù\n        Ệ wá bá wa ni màrínrìn ire\n   Màrínrìn ire làá bá ní lésè ợba òrìşà\n\nÒyèkú gira aquí\nÒyèkú gira para el otro lado\nEl rostro de la bandeja de Ifá se llena hasta el borde\nLanzó Ifá para el espectro que venía del Cielo a la\nTierra\nY se le pidió que ofrendase para que no se\npreguntase más si la vida le sería placentera\nEl espectro sacrificó y adquirió la paz mental\n(Irorùn)\nY bailó haciendo maravillas\nÉl dijo: Òyèkú gira aquí\nÒyèkú gira para el otro lado\nEl rostro de la bandeja de Ifá se llena hasta el borde\nLanzó Ifá para el espectro que venía del Cielo a la\nTierra\nLe dijeron que cuidase de la tierra y sacrificase Él lo\nhizo\nSacrificó y realizó los regalos libres a Èşù\nLlega y encuéntranos con las buenas bendiciones\nUno usualmente se encuentra con las buenas\nbendiciones, al pie del rey de los Òrìşàs", "origen_id": "35c6047f0dacef55d8c60b16"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyekubiworilodo ofrece soluciones para la esterilidad e\n\nimpotencia.\n                  WO - Este es una perfecta ocasión para quedar embarazada.\n\n\n33.1 · Oyekubiri profetizó ifá para la paloma (eyele), le fue predicado\n          que la paloma sería fructífera, por lo tanto ella deberá sacrificar 200\n      frijoles (gba ere) y 2.000 cowrie. Ella escuchó y ejecutó el sacrificio.\n     La paloma se convirtió en fructífera. El oráculo de Ifá fue profetizado\n      para la paloma (adaba). A ella le fue aconsejado ofrecer el sacrificio.\n                La paloma ejecutó el sacrificio, ella se convirtió en fructífera.\n\n\n33.2 · Oyeku-awo-omode, Iwori-awo-agbalagba profetizó Ifá para el\n               pene (oromina), quien iba a luchar en la batalla en la ciudad de\n             Ajatiiri. Ellos decían que él fracasaría porque no penetraría si no\n            ejecutaba el sacrificio. 3 carneros, 3 chivos, 3 perros, 3 gallos y 3\n      jicoteas machos y 6.600 cowrie. Él escuchó y ejecutó el sacrificio. Él\n                                   penetró. Oromina es lo que llamamos pene.", "origen_id": "123589afc3ad89587697ea13"}, {"titulo": "Relato en inglés 1", "texto": "“Someone who owns rats sends rats at my chest to call me;! my chest will\nnot accept them; the chest of Reverberating? Qyeku is the elder;> Someone who\nowns fish sends fish at my chest to call me; my chest will not accept them; the\nchest of Reverberating Ọyẹku is the elder; Thick Edi,‘ the water becomes Vibrat-\ning® Edi of the town where rituals are held; my chest is seeking money and chil-\ndren, oh.\"5\n\nIfa says that someone should make a sacrifice lest he be killed with medicine\nor “call and shoot.” One he-goat and three shillings is the sacrifice. Ifa says\nthat he will not allow us to die.", "comentario": "1, That is, someone is using rats (and fish) to make medicine to cause my\ndeath.\n\n2, Gbiri is the sound of something big and heavy falling to the ground, or of\nthe shot of a cannon reverberating. It may appear as gbiri-gbiri-gbiri, pronounced\nwith decreasing volume, like an echo gradually dying away. Qyeku Gbiri may be\nan alternative name for Qyeku Iwori. Cf. verses 19-2 and 19-3,\n\n3. Notes 3-6 appear on p. 261.\n3, That is, my chest, which is very strong like that of “Reverberating Qyeku,”\nwill resist the bad medicine; Qy¢ku will protect me.\n\n4, Ediis the name of one of the sixteen basic Ifa figures, but it appears here\nin a figure whose name does not involve Edi.\n\n5. Nana describes the way something sways or vibrates, like a clock spring\nheld at one end. Cf. n. 1, verse 17-4.\n\n6. These phrases resemble those interpreted as diviner’s names, but no divi-\nnation for a legendary character is cited.\n\n7. A type or category of charm which can cause death at a distance.", "origen_id": "822aafcbd617604658f29ccc"}, {"titulo": "Relato en inglés 2", "texto": "“Reverberating Ọyẹku\"1 was the one who cast Ifa for Yam Heap when she\nwas pregnant with food, They said that so that the child in her belly would be\nable to mature, she should sacrifice one he-goat, one lightly dyed cloth,” five\npiles of money of one shilling and six pence each for the mother, and six pence\nfor her unborn child.\n\nIfa says that he will not let us bear our child prematurely. Ifa says that a\npregnant woman should make a sacrifice so that she will not give birth to her\nchild prematurely. We must not recite this verse in the presence of a pregnant\nwoman.®\n\n(The diviner must not recite this verse in the presence of a pregnant wom-\nan; if he should recite this verse in the presence of agpregnant woman, the preg-\nnancy is certain to spoil.*)", "comentario": "1. Cf. n. 2, verse 19-1.\n\n2. A cloth which has been dipped only once in indigo, and is therefore light\nblue in color.\n\n3. The diviner must make certain that no pregnant women are present be-\nfore he recites this verse. If the client herself is present, arrangements will be\nmade for the sacrifice without reciting the verse to her as is usually done.\n\n4. This is not recited as a part of the verse itself, but it is a part of the in-\nstructions given to the diviners when they are learning the verse.", "origen_id": "bb43bcdc7d229b3eb7ed8069"}, {"titulo": "Relato en inglés 3", "texto": "“Reverberating Ọyẹku\"1 was the one who cast Ifa for Pigeon, child of “The\none who makes her nest and sleeps like a child at Ekiti Ẹfọn\"? when she cast Ifa\nbecause she had no children,\n\nThey said she would bear children, but that she should make a sacrifice. Two\nnew pots, two hens, and one shilling* was the sacrifice.\n\nWhen Pigeon had completed this sacrifice, they took one of the two pots and\ngave it toher. They said if her child should touch this pot with its head, it would\nnot die. When Pigeon gave birth to her child, she touched its head against the\npot and began to recite:\n\n\"I made the sacrifice of Reverberating Qyeku, Reverberating Qyeku,\n\n“My child touches the pot with its head; it will not die any more.”4\n\nIfa says that this person is seeking children; she will have children but she should\nmake a sacrifice lest her children die as soon as they are born.", "comentario": "1, Seen. 2, verse 19-1.\n\n2. The town of Efgn-Alaye, east of Ilesha, which was the capital of Ẹfọn,\nove of the Ekiti Yoruba kingdoms,\n3, As cowries are counted by the two thousand, there are two units of cow-\nries as there are two pots and two hens.\n\n4, There is a play on words and word magic in the use of a pot (ikoko) so\nthat the child will not die (ko ku) again. The belief is that several children who\ndie very young in succession, as abiku, are in reality one child who fails to live\nin its successive rebirths. (Cf. n. 3, verse 1-4). This verse is to be compared\nwith verse 33-1, where Pigeon begins to live in a pot.", "origen_id": "199eac85907abaf042219f2c"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La paloma: doscientos frijoles y 2,000 cauríes. El palomo: su ofrenda.", "Oromina: tres carneros, tres chivos, tres perros machos, tres gallos, tres jicoteas machos y 6,600 cauríes.", "Wáléọlá: una ofrenda abundante.", "El espectro: ofrenda y regalos libres a Èṣù."], "pasajes": [{"titulo": "Ofrenda en el verso 33.1", "texto": "Ọ̀yẹkúbìrì:\nadivinó Ifá para la paloma (Eyẹlé).\nÉl dijo: \"la paloma será fructífera (fértil)\",\npor lo tanto ella deberá sacrificar:\n200 frijoles (Igbá eree) y 2.000 cowries.\nElla escuchó y ejecutó el sacrificio.\nLa paloma se convirtió en fructífera (fértil).\nÉl también adivinó para el palomo (Adaba).\nÉl fue aconsejado ofrecer el sacrificio.\nEl palomo ejecutó el sacrificio.\nÉl se convirtió en fructífero (fértil).", "origen_id": "847ade043fab5c8ca4483fd0"}, {"titulo": "Ofrenda en el verso 33.2", "texto": "Ọ̀yẹ̀kú-awo-omodé,\nÌwòrì-awo-àgbàlagbà\nBi oyin kobaṣeerẹ-ofufu-liafiitini'di:\nadivinaron Ifá para el pene (Oromina),\ncuando iba a luchar en la ciudad de Ajatiri.\nEllos dijeron:\n\"si no sacrifica, fracasará en penetrar\".\nSacrificio: Tres carneros,\ntres chivos, tres perros (machos),\ntres gallos, tres jicoteas machos\ny 6.600 cowries.\nEl escuchó y ejecutó el sacrificio.\nÉl logró penetrar.\nOromina es lo que llamamos pene.", "origen_id": "a2cd310299c19c359d911014"}]}, {"titulo": "Relaciones espirituales", "texto": "La Tierra recibe los regalos. Èṣù recibe la parte libre. El rey de los Òrìṣà es donde se encuentran las bendiciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Frijoles, jicoteas, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 33.1 (yorùbá): Qyèkúbìri: / li o dífá f'Ẹyẹlé. / Wọ̀n ni: \"Eyẹlé a rẹ\", / nitorinaa ki ó rúbọ: / Igbá eree, egbèwá owó. / Ó gbọ̀ ó rú. / Eyẹlé rẹ. / Wọ̀n dá f'Adaba. / Wọ̀n niki Adaba rúbọ. / Adaba rúbo. / Ó rẹ.", "Verso 33.2 (yorùbá): Ọ̀yẹ̀kú-awo-omodé, / Ìwòrì-awo-àgbàlagbà, / Bi oyin kobaṣeerẹ-ofufu-liafiitini'di: / wọn dífa fOromina / nlọ jagun ilu Ajatiri / Wọ̀n ni: \"bi ko ba rúbo koniile wọle\" / Ebọ: Agbo méta, / òbúkọ mẹta, ako-ajá mẹta, / akuko-adiyẹ, ako-ájapá mẹta / ati egbaa mẹtaelógbòn owó. / Ó gbọ̀ ó rú. / Ó wọle. / Oromina oruko ti aipe okó.", "REZO: OYEKUN WORI ADIFAFUN OKUNI ELEGBARA OWO KAFEREFUN OSHUN, LODAFUN ORUNMILA.", "REZO: EPANDIKI O EFANDIKI ESHANDIKI OKO SHAMBAKIRAN. ADIFAFUN ORUNMILA OFANDIKI OKO SHAMBA KIRAN. ADIFAFUN ORUNMILA.", "REZO: INSHO ADIFAFUN KETA ABOÑU, IÑA KOYEBEFA, IÑI ONU OKUNI OJUN OYEKUN IWORI PITI PITI LODAFUN ELEGBA, KAFEREFUN ORUNMILA.", "REZO: OSUN OKAN SHOSHE ADIFAFUN LOBO ASHO PUPUA ASHO FUN FUN LEBO.", "REZO: APUANDIKI, APUANDIKI ONI SHAMBA KIRIN LOYO ONI SHAMBA INAN, ADIFAFUN ORUNMILA BARABANIREGUN.", "REZO: OYEKUN WORI OKO OWO KOLLELEBO LODAFORRIMU BORI KOYULO INBARI EYELE MEYO BUYE AKUKO EKU EYA OBI OWO LA MEYO OUYO. ORIRU BODIYO KETAOKOAYE KUN OPADO OYU MEYI OKI ORI APADE ETU MEYI APADO IRU MEY APADO OYU MEYI OKI ORI APADO ETU MEYI APADO EMU MEYI APADO IRU MEYI APADO IRO MEYO.", "REZO: OSUN OKAN SHOSHE ADIFAFUN LOBO ASHO PUPUA ASHO FUN FUN LEBO.", "SUYERE: OJA OSUN LOFIN KITUNIBA KAMARIKU KAMARI ANO, KAMARI EYO, KAMARI OFO, ETC.", "REZO: INSHO ADIFAFUN KETA ABOÑU, IÑA KOYEBEFA, IÑI ONU OKUNI OJUN OYEKUN IWORI PITI PITI LODAFUN ELEGBA, KAFEREFUN ORUNMILA."]}]$q$::jsonb),
(34,'1359a17ea15e0cf86104bf477d8eecff','fd539ecb3eb91aa4713c0676ab4b8308',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìdí, en buena fortuna, anuncia éxito personal, de dinero y con las mujeres, y éxito en un viaje. En mala fortuna pide ofrecer para alejar a la muerte. Advierte que poner demasiado énfasis en la vida sexual amenaza la salud. La persona será popular y rica, vencerá muchos obstáculos y debe ser muy honesta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por escasez y necesita recuperarse poco a poco.", "Va a viajar por trabajo o por una relación y espera un buen resultado (relato de Ọ̀rúnmìlà en la ciudad).", "Busca éxito en el amor o en el dinero, cuidando que sus decisiones íntimas no le hagan daño.", "Teme una enfermedad o una pérdida grave (relato de Ikú y Àrùn de visita).", "Trabaja muchísimo y anhela descanso y reconocimiento (relato de Ayílórùlé Òjòpò Òrà).", "Necesita actuar con honestidad para sostener lo que mejoró."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Éxito y felicidad en un viaje de trabajo.", "Popularidad y riqueza; descanso y paz mental.", "Vencer obstáculos grandes, como Ògún venció a los monos rebeldes.", "Protección de la casa contra la muerte y la enfermedad."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva al renacimiento. (Este Odu habla de la persona en la pobreza gradualmente crea la abundancia).", "origen_id": "8576c4641f1c985c978765e9"}]}, {"titulo": "Ibi y advertencias", "puntos": ["La muerte y la enfermedad preguntan por la casa.", "Excesos en la vida sexual que dañan la salud.", "Faltar a la honestidad."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final prematuro de un ciclo lleva al azar. (Este Odu habla de la posibilidad que la pobreza llegue a mala salud.)", "origen_id": "64eefe1fac6a4336a43a4149"}]}, {"titulo": "Enseñanza principal", "texto": "La paciencia y la astucia vencen a la fuerza. Ògún se hizo pasar por muerto y atrapó a los dieciséis monos que ningún ejército pudo vencer. Hay que saber esperar el momento."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Si habla de buena fortuna, Odù ọyẹkúf'owóradí predice éxito personal y financiero con las mujeres, y éxito en un viaje, pero en la mala fortuna, habla de sacrificar para evitar la muerte.", "origen_id": "68ec9264e1db712fa54bd1e7"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà en la ciudad de las mujeres. Bi oyin bi Ado consultó para Ọ̀rúnmìlà cuando iba de viaje de adivinación a la ciudad de las mujeres, y le dijo que ahí tendría mucho éxito y felicidad si ofrecía dieciséis palomas y 32,000 cauríes. Cumplió.", "La muerte pregunta por la casa. Ogidol'Egbá y Sagamo, el adivino de Eṣa, consultaron para Ọ̀rúnmìlà el día que la muerte y la enfermedad andaban preguntando dónde vivía. Le dijeron que si no ofrecía, moriría. Le marcaron dos perros negros y 4,400 cauríes. Cumplió.", "Ayílórùlé, el que compra y compra. Ifá consultó para Ayílórùlé Òjòpò Òrà, que compraba una y otra vez y llegó a comprar seis siervos en un día. Preguntó si la vida le sería placentera; ofreció una parte de su dinero y le llegaron una riqueza inmensa, la paz y el descanso. Desde entonces la paloma, cuando arrulla, dice su nombre.", "Ògún y los dieciséis monos. El rey de Ọ̀yọ́ estaba en guerra con dieciséis monos mandriles que lo atacaban sin parar. Su amigo Òdùyè lo llevó con el adivino, y este le dijo que buscara a Ògún. Ògún consultó a Ifá y Ọ̀rúnmìlà le pidió ofrecer su morral, su arco y sus flechas, su sueño, un trozo de carne guisada ya masticada y bastante maíz, y le dijo que no se pusiera nervioso. Ògún se tiró en la entrada del camino como si estuviera muerto, con el morral de almohada y el arco de bastón. Llegó el jefe de los monos y cantó: 'Veo al cazador muerto en el camino; usa su morral de almohada; el muerto no come carne guisada; saltaré por encima de él'. Uno a uno, los dieciséis monos fueron saltando sobre Ògún. Cuando saltó el último, Ògún abrió los ojos, lo agarró por la cola y fue capturándolos a todos, y se los llevó al rey. Desde entonces el rey de Ọ̀yọ́ no viaja ni emprende nada sin el consentimiento de Ògún."], "pasajes": [{"titulo": "Verso 34.1", "texto": "Bi oyin bi Ado\nadivinó Ifá para Ọ̀rúnmìlà.\ncuando Ifá (Ọ̀rúnmìlà) iba en un viaje\nde adivinación a la ciudad de las mujeres.\nEl adivino dijo:\n\"él será muy exitoso y feliz allá\"\n\"por lo tanto debe hacer sacrificio\":\ndieciséis palomas y 32.000 cowries.\nÉl escuchó e hizo sacrificio.", "origen_id": "60f916829074adad3b2cfdb6"}, {"titulo": "Verso 34.2", "texto": "Ogidol'Egbá,\nSagamo el adivino de Eṣa:\nadivinaron Ifá para Çrúnmilà,\nel día que la muerte\nestaba preguntando por su casa para visitarlo;\ncuando la enfermedad\ntambién preguntó por su casa.\nEllos dijeron que si él (Ọ̀rúnmìlà) fallaba\nen realizar el sacrificio, moriría.\nSacrificio: dos perros negros\n· 4.400 cowries.\nEl oyó y sacrificó.", "origen_id": "3e0aa992c0ae463299a2982a"}, {"titulo": "Versos complementarios 1", "texto": "Esta persona será popular y rica. Vencerá muchos\nobstáculos en la vida y se le exhorta a ser muy\nhonesta.\n\n             Òyè kùndì kundi\n     A dífá fún Ayílórùlé Òjòpò òrà\n             Èyí ti ó rà ràà rà\n           Ti ó rẹrú méfà lóòjó\n     Ti gbogbo ẹyẹ okó fi sorùn kợ\n           Ayé le yẹ òun báyìí?\n   Wón ní kí Ayílórùlé Òjòpò òrà ó rúbợ\n        Wón ní ợpợlợpợ owó lẹbợ\n            Ayílórùlé bá rúbợ\n              O bá bèrè síí là\n                 Ayé yẹ é\n               Ợkàan rè balè\n                 Ó nísinmi\n          N ní wá ń jó ní wá ń yò\n         Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n             Òyè kùndì kundi\n     A dífá fún Ayílórùlé Òjòpò òrà\n             Èyí ti ó rà ràà rà\n           Ti ó rẹrú méfà lóòjó\n     Ti gbogbo ẹyẹ okó fi sorùn kợ\n            Awo rere mòmò ni\n           Ayílórùlé Òjòpò òrà\n            Awo rere mòmò ni\n        Adábà bá ń kigbee rè kiri\n        Ni ń pAyílórùlé Òjòpò òrà\n           Ayílórùlé Òjòpò òrà\n\nÒyè kùndì kundi\nLanzó Ifá para Ayílórùlé Òjòpò òrà\nQuien compraba una y otra vez\nY que compró la cantidad de seis esclavos en un día\nEl acto, por el cual todo pájaro canta en el bosque\n¿Será placentera la vida para mí? Ellos le dijeron\nque ofrendase\nY le exigieron que una parte de dinero fuera el\nsacrificio Él lo hizo\nY llegó la inmensa riqueza, y la paz mental y el\ndescanso\nÉl regocijó a sus babaláwos y ellos a Ifá\nÒyè kùndì kundi\nLanzó Ifá para Ayílórùlé Òjòpò òrà\nQuien compraba una y otra vez\nY que compró la cantidad de seis esclavos en un día\nEl acto, por el cual todo pájaro canta en el bosque\nÉl es un buen adivino\nAyílórùlé Òjòpò òrà\nÉl es un buen adivino\nLa paloma después de comenzar a gorjear, dice:\n-“Ayílórùlé Òjòpò òrà”-\n-“Ayílórùlé Òjòpò òrà”-\n\n             Lèşelèşe lá ń fé\n   Òòşà mó jèé á dáwó lé n táà leè şe\n            A dífá fún Òdùyè\n       Òdùyè tíí sòré Ợba lóde Òyó\n             Lèşelèşe lá ń fé\n   Òòşà mó jèé á dáwó lé n táà leè şe\n  A dífá fún Àáyá Onírù mèrindínlógún\n         Èyí ti ń gbógúun ti Ợba\n            Ó kó lele mó Ợba\nÒún wáá le mú Àáyá Onírù mèrindínlógún\n                   báyìí?\n\n Òdùyè tíí sòré Ợba lóde Òyó bá mú Ợba\n      lợòdò àwợn lèşelèşe lè ń fé\nÀwợn lèşelèşe lá ń fé ní kí Ợba ó tợ Ògún\n                      lợ\n            Ợba bá tợ Ògún lợ\n      Ògún lóun ó mùú Àáyá òhún\n      Ògún nàá bá tợ Òrúnmìlà lợ\n      Òrúnmìlà ní kí Ògún ó rúbợ\n          Ó ní kí Ògún ó rú apó\n                 Kó rú ợfà\n               Kó si rú oorun\n     Ó ní ki Ògún ó rú orin àrùnkù\n                Kó si rú èèrí\n            Ó ní ki Ògún ó dirà\n    Ojú ònà si ni àwợn àáyá yíí i rin\n             Lati orí onirù kan\n   Tée dorí onirù mèrindínlógún ti ń\n              gbógúun ti Ợba\n      Wón ní kí Ògún ó korí si ijú\n              Kó mu apóo rè\n                  Kée rợrí\n                 Kó mu Ợfà\n                 Ké rợ ẹsè\n       Kó mu orín àrùnkù àti èèrí\n              Kó gbé e kègbé\n  Kó wáá pirợrợ şojú ònà bi ẹni ó ti kú\n                Ogun şe béè\n  Onírù kan ló kókó ba Ògún lójú ònà\n        Ó ri Ògún tó sùn gbalaja\n                Ló bá kígbe\nÓ ní Ààyá onírù méjì súré tete súré tete\n        Mo ródẹ lódikodi lónà o\n            Àlùjannjan n kíjan\n\n           Ợdẹ fapó rợrí\n         Àlùjannjan n kíjan\n          Ợdẹ fợfà rosè ò\n         Àlùjannjan n kíjan\n          Ợdẹ rà ó sindin\n         Àlùjannjan n kíjan\n           Òkú è é rorín\n         Àlùjannjan n kíjan\n        Alààyè è é sindin ò\n         Àlùjannjan n kíjan\n            Ó di pónhun\n              Ó di pó\n         Àlùjannjan n kíjan\n     Ló bá fo Ògún ru lójú ònà\n        Onírù méjì náà wò ó\n  Òun náà ké si Ààyá onírù méta\nÀàyá onírù méta súré tete súré tete\n      Mo ródẹ lódikodi lónà o\n         Àlùjannjan n kíjan\n           Ợdẹ fapó rợrí\n         Àlùjannjan n kíjan\n          Ợdẹ fợfà rosè ò\n         Àlùjannjan n kíjan\n          Ợdẹ rà ó sindin\n         Àlùjannjan n kíjan\n           Òkú è é rorín\n         Àlùjannjan n kíjan\n        Alààyè è é sindin ò\n         Àlùjannjan n kíjan\n            Ó di pónhun\n              Ó di pó\n         Àlùjannjan n kíjan\n        Òun náà fo Ògún ru\n\n            Onírù meta náà dè\n            Òun náà fo Ògún ru\n      Tée dórí onírù mérìndínlógún\n                Bó ti dé ibè\n             Ogun rợra ń wò ó\n               Òun náà ba ké\n       Ó ní mo ródẹ lódikodi lónà o\n             Àlùjannjan n kíjan\n               Ợdẹ fapó rợrí\n             Àlùjannjan n kíjan\n              Ợdẹ fợfà rosè ò\n             Àlùjannjan n kíjan\n              Ợdẹ rà ó sindin\n             Àlùjannjan n kíjan\n               Òkú è é rorín\n             Àlùjannjan n kíjan\n            Alààyè è é sindin ò\n             Àlùjannjan n kíjan\n                Ó di pónhun\n                   Ó di pó\n             Àlùjannjan n kíjan\n              Kó fó Ògún kợjá\n          Ògún ba gbá ìru è mú\n   Ó ba mú Ààyá wá fún Ợba lóde Òyó\nỢba ní iwợ Ògún o ò si tún ni jìnnà si òun\n                  mợ láíláí\n                  Tée dòní\n     Bợba ó bàá jade yóó şojú Ògún\n             Bi yóó bàá wợ ilé\n             Şojú Ògún ní ó şe\n    Ògún ợjợ kìíní Ợba ń yin tée dòní\nỢba ó níí şe nňkankan kó mó şojú Ògún\n  Ifá pé ipáa eléyìun ó kàá nňkan láyé\n\nEl logro es lo que más deseamos\nÒòşà, no dejes que nos frustremos e lo que pueda\nser obtener logros\nLanzó adivinación para Òdùyè, que era amigo del\nrey de Òyó\nY también para dieciséis monos mandriles, que\nguerreaban contra el rey, de manera persistente y\nconstante\n¿Seré capaz de capturar a esos rebeldes?, de dijo el\nrey\nSu amigo Òdùyè, le llevó a ver al awo “Lèşelèşe lá ń\nfé”\nEl awo le dijo al rey que se encontrara con Ògún\nY aquel le prometió a semejanza, la captura de los\nmonos rebeldes\nÒgún también consultó a Ifá Y Òrúnmìlà le pidió\nsacrificar su mochila o saco de viaje (apó), su arco y\nflechas, su sueño y un trozo de carne estofado, pero\nya masticado, así como bastante maíz\nLe dijo a Ògún que se preparara en si mismo y no\nestuviese nervioso\nY mandó a que pusiera esos ingredientes envueltos\ncomo si fuese un eje, detrás de su cuerpo y se\nechara a aparentar estar muerto a la entrada del\ncamino a la ciudad\nAsí lo hizo Ògún, cuando se acercaba la columna de\nmonos lidereada por su caudillo, que al ver al dios,\ncomo si estuviese muerto, exclamó con júbilo:\n- ¡Veo al cazador, que ha quedado muerto en la\nsenda al azar!-\nÀlùjannjan n kíjan\nEl cazador usó su mochila como almohada\nÀlùjannjan n kíjan\nEl cazador usó su arco y flechas como bastón de\nsoporte\nÀlùjannjan n kíjan\n\nEl cazador se pudre y produce gusanos\nÀlùjannjan n kíjan\nEl cazador muerto no podrá comer carne estofada\nÀlùjannjan n kíjan\nEl cazador que está vivo no producirá gusanos\nÀlùjannjan n kíjan\nBrincaré por encima de él, con un poderoso y rápido\nsalto\nÀlùjannjan n kíjan\nSaltaré por encima de Ògún y me adueñaré del\ncamino\nLos restantes monos, fueron llegando y miraron fijo\na Ògún y se unieron a las exclamaciones de su jefe:\nÀlùjannjan n kíjan\nEl cazador usó su mochila como almohada\nÀlùjannjan n kíjan\nEl cazador usó su arco y flechas como bastón de\nsoporte\nÀlùjannjan n kíjan\nEl cazador se pudre y produce gusanos\nÀlùjannjan n kíjan\nEl cazador muerto no podrá comer carne estofada\nÀlùjannjan n kíjan\nEl cazador que está vivo no producirá gusanos\nÀlùjannjan n kíjan\nBrincaré por encima de él, con un poderoso y rápido\nsalto\nÀlùjannjan n kíjan\nSaltaré por encima de Ògún y me adueñaré del\ncamino\nY los monos fueron brincando por encima del\ncuerpo inanimado de Ògún Cuando brincó el mono\nnúmero dieciséis,\nÒgún entreabrió sus ojos y cantó suavemente:\nVeo al cazador torpemente tirado en el camino\nÀlùjannjan n kíjan\n\nEl cazador muerto ha usado su mochila como\nalmohada\nÀlùjannjan n kíjan\nEl cazador muerto ha usado su arco y flechas como\nbastón de soporte\nÀlùjannjan n kíjan\nEl cazador se pudre y produce gusanos\nÀlùjannjan n kíjan\nEl cazador muerto no podrá comer carne estofada\nÀlùjannjan n kíjan\nEl cazador que está vivo no producirá gusanos\nÀlùjannjan n kíjan\nY le agarró fuertemente por la cola\nY al capturar a todos se los llevó al rey en la ciudad\nde Òyó\n-Ògún, no te has distanciado de mí - dijo el rey\nY hasta el día de hoy, cada vez que el rey debe\nviajar, lo hace con el previo consentimiento del\noráculo de Ògún\nAl igual que al retornar a su casa\nY es a esa misma divinidad a quien le reza el rey, en\nnuestros días\nEl rey nunca emprenderá una acción sin el\nconsentimiento o la bendición de Ògún Ifá dice que\nesta persona vencerá muchas cosas", "origen_id": "36f7fd130926be7ee8a0169d"}, {"titulo": "Versión complementaria de los relatos", "texto": "En la buena fortuna, Odu Oyekuf´oworad habla del éxito personal y\nfinanciero con las mujeres, pero en la mala fortuna, habla de sacrificar para\n                                                               evitar la muerte.\n           WO - Poner mucho énfasis en la actividad sexual pues amenaza la\n                                                               salud del cliente.\n\n\n34.1 · Bi oyin bi Ado adivinó Ifá para Orunmila. Ifá (Orunmila) estuvo\n\n      adivinando en la ciudad de las mujeres y predijo que tendría felicidad\n          allá. Por lo tanto debía hacer sacrificio: 16 palomas, 32.000 cowrie.\n                                                   Él escuchó e hizo sacrificio.\n\n\n34.2 · El Ogidol´Egba, Sagamo, el adivino de Eşa ambos adivinaron Ifá\n\n           para Orunmila, en el día la muerte (Ikú) estaba preguntando por su\n               casa; la enfermedad (arun) también preguntó por su casa. Ellos\n            dijeron que si él, Orunmila faltaba al sacrificio, él moriría. Ebo: 2\n                             perros negros y 4.400 cowrie. Él oyó y sacrificó.", "origen_id": "1d363c543d45f32927a45748"}, {"titulo": "Relato en inglés 1", "texto": "Qyeku Edi”? was the one who cast Ifa for Snail, They said he should sacri-\nfice three cocks and one shilling six pence? against one who showed contempt\nfor him. Snail did not make the sacrifice. From that time, the whole world has\nbeen showing contempt for Snail. Agbgnniregun says, “Bare handed, bare handed\nwe will catch* snail.” Ifa says someone should make a sacrifice against one who\nshows contempt for him. One who shows contempt for him is coming.", "comentario": "1. The name of the diviner is identical with that of the figure.\n\n2. Since cowries are counted by the two thousand, there are three units of\ncowries as well as three cocks.\n\n3. No one is afraid of snail since “it has no teeth.\n\n4. The Yoruba word “he” is even more insulting; it is applied to the gather-\ning of fruit. This verse thus explains why no one is afraid of snails, and why\npeople can catch snails without weapons and without any protection on the hands.", "origen_id": "d9549a4f96d0483a95edbe8e"}, {"titulo": "Relato en inglés 2", "texto": "“The road is very straight, it does not turn” was the one who cast Ifa for Qye\nwhen he was going to bring home a bride from his ward.’ They said he should\nsacrifice one he-goat and three shillings six pence? so that his penis should not\ndisgrace him. Qyg¢ did not make the sacrifice.\n\nWhen Qye brought his bride home, he was not able to sleep with her. They\nsaid, “What kind of an Ọyẹ is he?” They said \"He is Ọyẹ who has died at his\nwaist.” From that time on we have been calling him Qyeku-(e)di*\n\nIfa says someone should make a sacrifice against a disease which can be\nconcealed under his clothing,‘ or that someone’s penis is setting his dates for\nhim;> he should make a sacrifice so that he can have intercourse with the wife he\nwants to marry.", "comentario": "1. A neighbor, a girl living in the same ward of the town.\n\n2. Seven units of 2000 cowries, or 14,000 cowries.\n\n3, This verse thus explains how this figure got its name. Note the pun which\nis the basis of the etymology: Qyeku-(E)di, the name of the figure, and Ọyẹ-ku-\n(i)di, Qye-die-waist.\n\n4. This refers to social diseases.\n\n5. That is, he cannot have sexual relations regularly. Cf. verse 9-1.", "origen_id": "a2d3e5eab2fd3b4df7daa241"}, {"titulo": "Relato en inglés 3", "texto": "“Pekube, the diviner of Waxbill”! was the one who cast Ifa for Waxbill when\nshe was grieving because she was barren and had no children. They said she\nwould bear children; they said she should sacrifice two hens, one she-goat, and\nfive shillings. She sacrificed. She bore children and she began to rejoice, sing-\ning:\n\n“The Ifa of Pekube came true, Pekube;\n“Iam pregnant, I bear children, Pekube.”\n\nIfa says we should tell this person who is seeking children that she should\nmake a sacrifice and she will bear a child.", "comentario": "1. The Orange-cheeked Waxbill (Estrilda Melpoda M.). The meaning of\nPẹkubẹ is unknown.", "origen_id": "e26420524a80eec3a2aa7260"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà (viaje): dieciséis palomas y 32,000 cauríes.", "Contra la muerte y la enfermedad: dos perros negros y 4,400 cauríes.", "Ayílórùlé: una parte de su dinero.", "Ògún: su morral, su arco y flechas, carne guisada masticada y bastante maíz."], "pasajes": [{"titulo": "Ofrenda en el verso 34.1", "texto": "Bi oyin bi Ado\nadivinó Ifá para Ọ̀rúnmìlà.\ncuando Ifá (Ọ̀rúnmìlà) iba en un viaje\nde adivinación a la ciudad de las mujeres.\nEl adivino dijo:\n\"él será muy exitoso y feliz allá\"\n\"por lo tanto debe hacer sacrificio\":\ndieciséis palomas y 32.000 cowries.\nÉl escuchó e hizo sacrificio.", "origen_id": "0644809d0986b80e3bf53fb3"}, {"titulo": "Ofrenda en el verso 34.2", "texto": "Ogidol'Egbá,\nSagamo el adivino de Eṣa:\nadivinaron Ifá para Çrúnmilà,\nel día que la muerte\nestaba preguntando por su casa para visitarlo;\ncuando la enfermedad\ntambién preguntó por su casa.\nEllos dijeron que si él (Ọ̀rúnmìlà) fallaba\nen realizar el sacrificio, moriría.\nSacrificio: dos perros negros\n· 4.400 cowries.\nEl oyó y sacrificó.", "origen_id": "f27c158b14dd9ad7090c7450"}]}, {"titulo": "Relaciones espirituales", "texto": "Ògún es quien vence a los enemigos del rey y se consulta antes de cada viaje. Ọ̀rúnmìlà indica la ofrenda. Ikú y Àrùn, la muerte y la enfermedad, rondan la casa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz, carne guisada, perros negros, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 34.1 (yorùbá): Bi oyin bi Ado / li o difá fÖrúnmilà / Ifá nṣawo lọ silu obirin. / Wọ̀n ni: / \"ayé a ye Ọ̀rúnmìlà lohun papoju / nitorinaa ki ó rúbo\": / Ṣyẹlé mẹrindilógún / ati egberíndilógún owó-ẹyo / Ó gbọ̀ ó rú.", "Verso 34.2 (yorùbá): Ogidol'Ẹ̀gbá, / Sagamo awo Eṣa: / wọ̀n difá fỌ̀rúnmìlà, / nijọ ti Ikú nfi ilé rẹ lọ, / ti Àrùn nfi ilé rẹ lọ. / Wọ̀n ni bikoba rúbọ I yoo kú. / Ebọ: ajá dúdú Méjì / ati egbejielógún owó. / Ó gbọ̀ ó rú.", "REZO: OYEKUN DI ORUNMILA ADIFAYOKO OLO U YUEKO ORUGBO ORUGBO, AKUKO, EURE YARAKO, AYA, EBEYO, OWO IWA, BOGBO INKAN ARAYE EBEBIKAN LONLE ILE OLOFIN.", "REZO: OYEKUN DI OLORUN LATIKU ORUN KANTARI OYEKUN DI.", "REZO: OYEKUN DI LERI NI BOGBO ORISHA PINU OLOFIN KURI LATINO ORISHA LERI BOGBO KO KOGNA LENI ELERI NI AWO ORUNLA ESI ELERI NI OMO MINU OLODUMARE MODDU KUESUN LO ALODO IRE.", "REZO: OLLOCUNDI ILO TIN UN OLORUN ALLECUIDI. ORUNMILA ADIFALLOCO OLO ILUOCUO ORUBO OQUE EURE YARAKO EKU, EYA, EBELLO EGUE IGUABOBO INCARALLE EBICAN LOALO ILA OLOFIN. OLLATUN OCU OLORUN OTI OLLECUIDI ELEUN AGUORIEBIARI OBA OCUN ANIALLE A LA ILU OCUN AGUORI.", "REZO: OYEKUN DIDI ADIFAFUN ALLE TONLOCO ODA ADIE EYELE LEBO. ALLOILUN ECUN AWO RIRE AWO RIRE BIERI OLALLE ALOLLUN A EKUN AWO RIRE.", "REZO: OYEKUN DI LERI NI GBOGBO ORISHA PINU OLOFIN KURI LATINO ORISHA LERI BOGBO KO KOGNA LENI ELERI NI AWO ORUNMILA ESI ELERI NI OMO MINU OLODUMARE MODDU KUESUN LO ALODO IRE.", "REZO: OYEKUN DI ILO TIN UN OLORUN ALLECUIDI. ORUNMILA ADIFAYOKO OLO ILUOKUO ORUBO OQUE EURE YARAKO EKU, EYA, EBELLO EWE IGUABOBO INCARALLE EBICAN LOALO ILA OLOFIN. OYATUN OCU OLORUN OTI OLLECUIDI ELEUN AGUORIEBIARI OBA OKUN ANIALLE A LA ILU OKUN AGUORI.", "REZO: OYEKUN DIDI ADIFAFUN ALLE TONLOCO ODA ADIE EYELE LEBO. ALLOILUN ECUN AWO RIRE AWO RIRE BIERI OLALLE ALOLLUN A EKUN AWO RIRE."]}]$q$::jsonb),
(35,'efb242d3aad870f3b1d2736c00543a17','2773336d1641401113cf52b232e156aa',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìrosùn habla de obedecer a Ifá para tener éxito y evitar la muerte. Un buen pensamiento lleva a buenas acciones. Pide formar o unirse a un grupo de ahorro (èésú) para reunir riqueza, no ser avaro ni codicioso, y respetar a los adivinos aunque sean jóvenes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Empieza una etapa nueva y teme desperdiciar la oportunidad por cerrar mal la anterior.", "Quiere mejorar su economía juntando de poco en poco con otros (relato del grupo de Èésú).", "Piensa en formarse o comprometerse en lo espiritual.", "No toma en cuenta el consejo de alguien más joven o de menor rango (relato de Ọlọ́fin).", "Espera prosperar con un conocimiento o práctica tradicional (relato de Gbẹrẹfu y sus ikines).", "Un malentendido en una reunión o con bebida genera un problema (relato de Òyè Ògosùn y Ṣàngó).", "Debe vigilar la codicia y dejar claros los acuerdos con quienes comparte recursos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Los ikin de Ifá enriquecen a la persona.", "Riqueza reunida poco a poco en un grupo de ahorro.", "Paz y una vida provechosa."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la satisfacción del destino. (Este Odu habla de la necesidad para alguna forma de vida de iniciación espiritual a asegurar el destino más alto de la persona).", "origen_id": "d8aaec168bdff01bdba2850c"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Faltarle al respeto a un babaláwo, aunque sea joven.", "Provocar la ira de Ògún o de Ṣàngó.", "Mantener en alto los recipientes vacíos: aparentar lo que no hay.", "La avaricia y la codicia."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final prematuro del ciclo lleva a perder la oportunidad. (Este Odu habla de la consecuencia negativa de la decepción).", "origen_id": "1c72c7c01ae01eef3a3755a1"}]}, {"titulo": "Enseñanza principal", "texto": "No hay adivino pequeño. Ọlọ́fin despreció el consejo de uno joven y lo pagó con la vida. Y cuando se acaba el vino, se voltean los recipientes: aparentar que hay cuando no hay provoca la ira de los que esperan."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú'Rosù habla de la importancia de obedecer a Ifá para alcanzar el éxito y evitar la muerte.", "origen_id": "d95ce8d7f391fca7ccd1c05f"}]}, {"titulo": "Relatos reunidos", "puntos": ["Gbẹrẹfu y sus ikin. Ajaweṣola consultó para Gbẹrẹfu, el hijo mayor de Ọ̀rúnmìlà, y le dijo que sus ikin lo harían rico. Le marcaron una rata, un pescado y una chiva. Cumplió.", "Ọlọ́fin y el adivino joven. Awokekeré-ilé-ẹni-kotan'nijẹ consultó para Ọlọ́fin y le pidió un perro, ñame asado, vino de palma y 6,600 cauríes para no ver la ira de Ògún. Ọlọ́fin no hizo caso y Ògún lo mató. Ifá advierte: a ningún babaláwo se le falta al respeto, aunque sea un adivino joven.", "El grupo de ahorro. Ifá consultó para la gente de Ẹgbàá Èésú, que estaba tratando de entender cómo se junta la riqueza. Les marcaron bastante dinero y una paloma vieja. Ofrecieron, y cada uno empezó a aportar una pequeña cantidad al grupo. Al cabo de un tiempo se repartieron lo reunido, tuvieron paz y sus vidas se volvieron ricas. Cantaron: '¿Quién hizo tanta ofrenda? El pueblo de Ọ̀yè rùsùrùsù'.", "Ọ̀yè Ògosùn y la sed de Ṣàngó. Ọ̀yè Ògosùn y su gente se tomaron cuarenta recipientes de vino. Ṣàngó pasó un día con mucha sed y no encontraba vino en ninguna parte, hasta que llegó con ese grupo que tenía los recipientes en alto. Se quedó esperando a que lo invitaran, sin saber que el vino ya se había acabado, y nadie lo llamó. Furioso, sacó de su bolsa su piedra de rayo (ẹdùn) y los fulminó a todos. Al tomar los recipientes descubrió que estaban vacíos y gritó: '¿Por qué los mantenían en alto si estaban vacíos?'. Desde entonces, cuando se acaba la bebida, el recipiente se pone boca abajo en el suelo para que todos sepan que ya no hay."], "pasajes": [{"titulo": "Verso 35.1", "texto": "Ajaweṣola,\nAtẹ-iyè-iròsù-ṣe-ola:\nadivinaron Ifá para Gbẹrẹfu,\nel hijo más viejo de Ọ̀rúnmìlà.\nEllos dijeron:\n\"Sus Ikines (Ifá) lo enriquecerán\".\nLe fue aconsejado hacer sacrificio:\nrata, pescado y chiva.\nÉl escuchó y realizó el sacrificio.", "origen_id": "fe0102aa44203ebc4a65fbd8"}, {"titulo": "Verso 35.2", "texto": "Awokekeré-ilé-ẹni-kotan'nijẹ:\nadivinó Ifá para Ọlófin.\nSe le pidió sacrificar:\nperro, ñame asado, vino de palma\ny 6600 cowries,\npara evitar que viera la ira de Ogún.\nEl escuchó y no sacrificó.\nOgún lo mató.\nIfa advierte:\n\"ningún Babaláwo debe ser irrespetado,\naún siendo un joven adivino\".", "origen_id": "94c342e78b29286f22f7130b"}, {"titulo": "Versos complementarios 1", "texto": "Ifá exhorta a esta persona a formar un grupo de\ncontribución de dinero llamado “Èésú”. El primer\nverso es el que establece esta sociedad o grupo\ngerencial. Esta persona tendrá paz y obtendrá\nriquezas. Ifá le pide no ser avaro, ni codicioso. Cada\nvez que se beban bebidas alcohólicas, se deberá\n\nverter en el suelo antes de comenzar a beber, y al\nfinalizar la vasija, o recipiente donde se ha bebido,\nse dejará por algunas horas a uno de los lados sobre\nel suelo, donde se estuvo bebiendo. La persona es\nexhortada o instada a servir a sus visitantes con\nvino, o alguna otra bebida, debido a la acción de\nuna entidad espiritual que disfruta el vino o el licor,\ncuando está apegado a él (ella).\n\n                Òyè rùsùrùsù\n        A dífá fún wợn lỆgbàá Èésú\n        Níbi wón gbé ń kórí ajée jợ\n           Wón ní kí wón ó rúbợ\n         Wón ní ợpợlợpợ owó lẹbợ\n             Òwúùrú ẹyẹlé lẹbợ\n             Wón níre fún wợn\n                Wón bá rúbợ\n            Ệgbàá ní wón si ń dá\n          Ńgbà ó pé wón bá kówó\n                 Wón nísinmì\n              Ợkàan wón balè\n                Ayée wón dáa\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n                Òyè rùsùrùsù\n        A dífá fún wợn lỆgbàá Èésú\n        Níbi wón gbé ń kórí ajée jợ\n        Taa ló rúbợ báwònyí bẹẹrẹ?\n                Òyè rùsùrùsù\n       Àwợn ló rúbợ báwònyí bẹẹrẹ\n                Òyè rùsùrùsù\n\nÒyè rùsùrùsù\nAdivinó Ifá para ellos en Ệgbàá Èésú\nDonde ellos estaban tratando de agregar y entender\nel concepto de “Riqueza”\nLe pidieron que sacrificaran con:\n- Bastante dinero, y una paloma con varios años de\nvida -\nEntonces ellos pidieron la invocación de la riqueza\npara ellos\nEllos sacrificaron\nY contribuyeron con cinco peniques cada uno a la\nincipiente sociedad\nDespués de un largo período de tiempo, ellos\npudieron repartirse el monto de lo ganado con las\ncontribuciones\nEllos ganaron en paz mental y sus vidas se\nvolvieron muy provechosas y ricas\nAlabaron a sus babaláwos y estos alabaron a Ifá\nÒyè rùsùrùsù\nAdivinó Ifá para ellos en Ệgbàá Èésú\nDonde ellos estaban tratando de agregar y entender\nel concepto de “Riqueza”\n¿Quién realizó esta abundancia de sacrificio?\nEl pueblo de Òyè rùsùrùsù\nEllos son aquellos que realizaron juntos muchos\nsacrificios\nEl pueblo de Òyè rùsùrùsù\n\n             Ipín lawo òdómợdé\n           Àwàlàňfà lawo Àgagò\n           Ayé ń re Ifè awo sóko\n           A dífá fún Òyè Ògosùn\n       Èyí ti ó mutí Ogóji dun Şangó\n        Şangó ní ń kợjáá lợ lójợ kan\n               Ợtí si ń wù ú mu\n      O ti dé gbogbo ibi tó ti lè rí díè\n\n             Kó rì fi sara rindin\n         Ló bá rí àwợn ti ń mutí\n            Ti ón gbé ègùn dúó\n          Ợtí sì ti tán ńnú ègùn\n              Şangó bá kợjá lợ\n   Ó rosè bíí kí wón ó pè é kó wáá mu\n      Kò gbó kí wón o pe òun padà\nKò si mò pé ợtí ti tán ńnú ègùn ni wợn ò\n                  fi pe òun\n               Şangó bá padà\n             Ló bá bínú sí wợn\n          Àrirà bá fẹdùn yợ lápò\n     Ló bá yợ iná lára gbogboo wợn\n            Ipín lawo òdómợdé\n          Àwàlàňfà lawo Àgagò\n          Ayé ń re Ifè awo sóko\n          A dífá fún Òyè Ògosùn\n      Èyí ti ó mutí Ogóji dun Şangó\n           Şangó bá bợ síbi ợtí\n         Yóó mu èyí tó kù lágbè\nÓ gbénu è sókè bíi kíkankan ó mó le kán\n                      sílè\n                   Àfi báfó\n                  Ợtí ti tán\n    Şangó ní kín ló gbégùn duo şe?\n                Òyè Ògosùn\n                Ìgbà tợtí tán\n           Kín ló gbégùn duo şe\n                Òyè Ògosùn\n\nIpín es el awo de òdómợdé\nÀwàlàňfà es el awo de Àgagò\nAyé ń re Ifè es el awo de sóko\n\nLanzaron Ifá para Òyè Ògosùn\nAquél que consumió cuarenta recipientes de vino y\ncausó el disgusto de Şangó\nŞangó un día estaba sediento de beber vino y no\nhabía hallado ningún lugar donde obtenerlo, hasta\nque llegó a ese grupo de personas que lo estaban\nconsumiendo, pero mantenían los recipientes arriba\nsin estar llenos (vacíos)\nŞangó se detuvo allí, pensando que sería invitado,\npero no escuchó que nadie le llamase a unirse a\nellos en su libación, sin saber que el líquido se había\nterminado\nY furiosamente se volvió y los castigó a todos\nÀrìrà sacó la forma de ẹdùn de su bolsillo (piedra de\nrayo) y los fulminó a todos con rayos\nIpín es el awo de òdómợdé\nÀwàlàňfà es el awo de Àgagò\nAyé ń re Ifè es el awo de sóko\nLanzaron Ifá para Òyè Ògosùn\nAquél que consumía cuarenta recipientes de vino y\ncausaba el disgusto de Şangó\nŞangó tomó los recipientes y trató de beber el vino\nque suponía estaba dentro de ellos y se dio cuenta\nde que estaban vacíos y exclamó:\n- ¿Por qué si estaban vacíos, los mantenían en alto?\n–\nÒyè Ògosùn\n- Cuando sepas que se terminó el vino -\n- ¿Por qué si estaban vacíos, los mantenían en alto?\n–\nÒyè Ògosùn\n- Si se han vaciado, boléalos boca abajo o ponlos en\nel piso, virados al revés de manera que se den\ncuenta que están vacíos –\nÒyè Ògosùn!", "origen_id": "ad1124d49e1767de3681d6ad"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku´Rosu habla de la importancia de obedecer a Ifá para\n                                              alcanzar el éxito y evitar la muerte.\n           WO - Buenos pensamientos conducen a buenas acciones para evitar\n                                                                   los problemas.\n\n\n35.1 · Ajawesola, Ate-iye-irosu-se-ola adivinó Ifá para Gberefu, el\n                 hijo más viejo de Orunmila. Ellos dijeron que su Ikin (Ifá) lo\n              enriquecería. Se le pidió sacrificar 1 jutía, 1 pescado, 1 chiva. Él\n                                                   escuchó y realizó el sacrificio.\n\n\n35.2 · Awokekere-ile-eni-kotan´nije adivinó Ifá para Olofin. Se le\n       pidió sacrificar: 1 perro, 1 ñame asado, vino de palma y 6600 cowrie,\n      para evitar el disgusto de Oggún. Él escuchó y no sacrificó. Oggún lo\n       mató. Él advirtió que ningún Babalawo debería ser irrespetado ni aún\n                                                     siendo un joven adivinador.", "origen_id": "2f4e776ca7a423761e9fdb41"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Gbẹrẹfu: una rata, un pescado y una chiva.", "Ọlọ́fin (rechazado): un perro, ñame asado, vino de palma y 6,600 cauríes.", "Ẹgbàá Èésú: bastante dinero y una paloma vieja.", "Al beber: derramar un poco en el suelo antes de empezar, y al terminar dejar el recipiente de lado en el suelo; ofrecer bebida a las visitas."], "pasajes": [{"titulo": "Ofrenda en el verso 35.1", "texto": "Ajaweṣola,\nAtẹ-iyè-iròsù-ṣe-ola:\nadivinaron Ifá para Gbẹrẹfu,\nel hijo más viejo de Ọ̀rúnmìlà.\nEllos dijeron:\n\"Sus Ikines (Ifá) lo enriquecerán\".\nLe fue aconsejado hacer sacrificio:\nrata, pescado y chiva.\nÉl escuchó y realizó el sacrificio.", "origen_id": "516b18f1617c656912325a04"}, {"titulo": "Ofrenda en el verso 35.2", "texto": "Awokekeré-ilé-ẹni-kotan'nijẹ:\nadivinó Ifá para Ọlófin.\nSe le pidió sacrificar:\nperro, ñame asado, vino de palma\ny 6600 cowries,\npara evitar que viera la ira de Ogún.\nEl escuchó y no sacrificó.\nOgún lo mató.\nIfa advierte:\n\"ningún Babaláwo debe ser irrespetado,\naún siendo un joven adivino\".", "origen_id": "7bf161fb7bdccdedf063c25e"}]}, {"titulo": "Relaciones espirituales", "texto": "Ògún castiga el desprecio al adivino. Ṣàngó castiga la apariencia y la tacañería con la bebida. Los ikin de Ifá son fuente de riqueza para el hijo de Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Vino de palma, ñame asado, rata, pescado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 35.1 (yorùbá): Ajaweṣola, / Atẹ-iyẹ̀-iròsù-ṣe-ola: / li o difá fún Gbẹrẹfu / tiiṣe arẹmo Ọ̀rúnmìlà. / Wọ̀n ni: / \"Ikin rẹ niyoo gbe e la\", / wọ̀n niki ó rú: / Eku, eja, ati ewúré. / Ó gbó ó rú.", "Verso 35.2 (yorùbá): Awokékeré-ilé-ẹni-kotan'nijẹ: / li o difá f'Ọlófin / Ó niki ó rúbọ: / ajá, ẹsun-iṣu, ẹmu / ati egbẹtalélógbọ̀n owó, / ki o ma baa ri ijà-Ogún. / Ó gbọ̀ kò rú. / Ogún pa a. / Ifá ni: / \"ki a mafi ojú di Babaláwo kan pe / ko nilaari tabi o keré\".", "REZO: OYEKUN BIROSO AWO OTI OLOFIN TULO SHWO SADU MERIN OTI OWO IWOKO, EBEYO ALA, ERI, BOGBO INTORI AYE KURBO OTIBE EYELE ABO INTORI IKU.", "REZO: OYEKUN IROSO, OGUO OTI OGUO IGUOBO ABOLLE ALA ORI GOGO INTORI ALLO CURBO OTIBO ALBA LEBO INTORI IKU.", "REZO: OYEKUN BIROSO AWO KOMO OWOBIA ABANIRE AWO KOMO AKONE RI IKU AWO KOMO AYE ADIE DUN DUN, BANIRE KOMO AWO PARALDO OBARISHAWO KOMO AWO IKU ABERIKUNLO ONA BENIREGUN AWO KOMO AWO AYO IKU AWO KOMO AWO OYEKUN BIROS ABONI ORUNMILA OMO KOMO ABUYA IFA AWO NO ORUN.", "REZO: ABITI OMO INLE ABEYI AWO ADIFAFUN LODAFUN ORUNMILA.", "REZO: OYEKUN BIROSO AWO KOMO OWOBIA ABANIRE AWO KOMO AKONERI IKU AWO KOMO AYE ADIE DUN DUN, BANIRE KOMO AWO OPARALDO OBARISHAWO KOMO AWO IKU ABERIKUNLO ONA BENIREGUN AWO KOMO AWO AYO IKU AWO KOMO AWO OYEKUN BIROSO ABONI ORUNMILA OMO KOMO ABUYA IFA AWO NO ORUN.NOTA: AQUI NACIO EL GRAN PODER DEL HIJO DE IKU Y EL GRAN PODER DEL HIJO DE IFA Y EL OPARALDO.", "REZO: ABITI OMO INLE ABEYI AWO ADIFAFUN LODAFUN ORUNMILA.", "SUYERE BBO LASHE EBBO LASHE ONI IGBA OMO IKUN EBBO LASHE OJOKORO ANGBE IKA."]}]$q$::jsonb),
(36,'3b28756a345f7fc1b96856e7d357a95d','ae12ef2b429e17a63e846c06d401f3ff',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀wọ́nrín da remedio para las consecuencias del adulterio y para los peligros de los viajes lejanos. Las acciones descuidadas, indiscretas o sin pensar bloquean los negocios y el trabajo. Pide una ofrenda eficaz para no perder lo heredado de los padres; algo maravilloso viene en camino."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Actuó con prisa o fue indiscreto, y eso complica un negocio o una relación.", "Hay un pleito familiar que conviene hablar antes de que duela más.", "Hay un secreto o falta de confianza en la pareja (relato de Lawẹ́nibu).", "Se acerca una salida al monte o un viaje lejano por agua (relatos del cazador y de Ọ̀rúnmìlà).", "Un cambio inesperado le obliga a preparar recursos y explicar bien sus planes.", "Vive una angustia fuerte y necesita apoyo de gente cercana a tiempo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Conservar lo que se heredó de los padres frente a quienes lo quieren quitar.", "Regresar con vida de un viaje lejano o por agua.", "Algo maravilloso que viene a su encuentro.", "Ser elegido entre muchos por saber pedir ayuda."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva a la preparación para el cambio inesperado. (Este Odu habla de resolver disputas familiares antes de que ellas se vuelvan perturbadoras.)", "origen_id": "0392a5679951d494d3ff71a1"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Un adulterio que puede costar la vida si se descubre.", "Actuar sin pensar y bloquear los propios asuntos.", "Enemigos que conspiran para sacarlo de su lugar."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación prematura de los ciclos lleva al caos. (Este Odu habla de los problemas ancestrales que son potencialmente capaces de causar tendencias suicidas).", "origen_id": "e585fd37c484bf9067dc9f2e"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que es de la familia se defiende con la ofrenda, no con la fuerza. El cocodrilo siguió en las aguas de su padre y ningún enemigo pudo sacarlo."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú'Wónrín ofrece remedios para evitar las terribles consecuencias de cometer adulterio (que maten a la persona cuando se conozca que cometió adulterio) y para evitar los peligros en viajes distantes.", "origen_id": "56f4ed01101bfd1b954e86e1"}]}, {"titulo": "Relatos reunidos", "puntos": ["Lawẹnibu confiesa. Okitibi-aketekiitan-nidi-ọ̀pẹ consultó para Lawẹnibu y le marcó una chiva para que pudiera confesar su adulterio sin que la mataran. Cumplió. Ifá dice que a la mujer a quien sale este Odù se le está viendo un adulterio.", "El cazador y Ọ̀rúnmìlà van lejos. Los adivinos consultaron para el cazador que iba al bosque de Olikorobojó y le marcaron seis gallos y 14,000 cauríes para no morir ahí; cumplió. También consultaron para Ọ̀rúnmìlà, que viajaba muy lejos cruzando el agua, y le marcaron un recipiente de aceite de palma, nueve gallos, nueve chivos, nueve ratas, nueve pescados y palomas. Cumplió.", "El cocodrilo en las aguas de su padre. Ifá consultó para el cocodrilo, que vivía en las aguas profundas que habían sido de su padre en Ìrágbìjí. Algunos se confabularon para sacarlo de ahí. Le marcaron un chivo viejo, o tres gallos, y bastante dinero. Ofreció, y ningún enemigo pudo con él: siguió estirándose a gusto en sus aguas. '¿Quién va a sacar ahora al cocodrilo de las aguas de sus padres?'.", "Ajíbówú, el herrero de la luna. Olódùmarè reunió a los herreros del mundo y les pidió crear toda clase de cosas, buscando al más hábil. Ajíbówú, herrero de Ògèlé, fue con los babaláwo porque lo que pedía el Supremo superaba lo que él sabía. Le dijeron que sirviera a las Madres, las Ancianas. Cumplió, y ellas le dieron la luna. Le dijeron que la tallara y la pusiera en un recipiente àdèmú, y que durante dieciséis días lo fuera destapando poco a poco. La gente veía cómo la luna creciente aparecía día a día, hasta que el último día la luna llenó el recipiente. Después la fue tapando de nuevo. Así nació la luna creciente."], "pasajes": [{"titulo": "Verso 36.1", "texto": "Okitibi-aketekiitan-nidi-ọ̀pẹ\nadivinó Ifá para Lawẹnibu,\na ella le fue aconsejado hacer sacrificio\npara que pudiera confesar su adulterio\nsin que la mataran.\nUna chiva sería ofrecida como sacrificio\nsi ella no queria morir a causa del adulterio.\nElla hizo el sacrificio.\nIfá dice: la mujer a quien este Ifá se le está adivinando, está\ncometiendo adulterio.", "origen_id": "5cdaeff8e11678c58cff4541"}, {"titulo": "Verso 36.2", "texto": "Jafirijafi, Kẹmkẹjakẹ,\nAgadagidiwonu-odo-ef'arabo-omi:\nadivinó Ifa para el cazador (Odẹ)\nEllos también adivinaron Ifá para Ọ̀rúnmìlà.\nOdẹ estaba yendo al bosque de Olikorobojó.\nLe aconsejaron sacrificar\npara evitar la muerte allí:\nseis gallos y 14000 cowries.\nEl cazador hizo el sacrificio.\nỌ̀rúnmìlà estaba yendo de viaje\na un lugar muy distante (a través del agua).\nLe aconsejaron sacrificar\npara evitar la muerte allí:\nun recipiente de aceite de palma,\nnueve gallos,\nnueve chivos, nueve ratas,\nnueve pescados y paloma.\nỌ̀rúnmìlà escuchó y realizó el sacrificio.", "origen_id": "aa25f75b34bf308eb9f42eb3"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le pide a esta persona que sacrifique y que esta\nofrenda deberá ser eficaz, para que las posesiones\nheredadas de padres y que aún mantiene, no le\nsean quitadas. Ifá dice que es una gran persona. Ifá\ndice que algo maravilloso viene a su encuentro,\npero deberá sacrificar, para que así su sumisión sea\nampliamente aceptada.\n\n              Òyè wònrin mì\n              Òyè wònrin jẹ\n       Òyè sợni pàkàpàkà gbé mì\n        A dífá fún Òni wàkàwàkà\n         Èyí ti ń bẹ níbú Ìrágbìjí\n              Ibúu babaa rẹ\n          Àwợn òtá bá ń yí i po\n      Wón láwợn ó gba ibú lówó è\n          Wón ní kí Òni ó rúbợ\n  Wón ní kò sẹni tí ó gba ibúu babaa è\n                   lówó è\n               Bó bá tí rúbợ\n         Wón ní bí ợpón bá téjú\n           Gìrìpá òrúkợ lẹbợ è\n                Bí ò bá téjú\n         Àkùkợ adìẹ méta lẹbợ\n      Kó sí rú ợpợlợpợ owó pèlú è\n                 Òni rúbợ\n Gbogbo nňkan ti ợn láwợn ó gbà lówó è\n    Kò sẹni ó le gbodò lówó Òni mó\n    Yóó nawó nasè lódòo bàbá rè ni\n                Ayé yẹ Òni\n         N ní wá ń jó ní wá ń yò\n\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n                Òyè wònrin mì\n                Òyè wònrin jẹ\n        Òyè sợni pàkàpàkà gbé mì\n         A dífá fún Òni wàkàwàkà\n           Èyí ti ń bẹ níbú Ìrágbìjí\n                Ibúu babaa rẹ\n          Taa ní ó gbodò lówó Òni\n       Òni wàkàwàkà bàbá è ló nibú\n          Taa ní ó gbodò lówó Òni\n\nÒyè wònrin mì\nÒyè wònrin jẹ\nÒyè sợni pàkàpàkà gbé mì\nFueron quienes lanzaron Ifá para el Cocodrilo\nmagnánimo\nQuien vivía en las aguas profundas que fueron de su\npadre en la región de Ìrágbìjí\nAlgunos elementos se confabularon y planearon\nsacarlo de aquellas aguas, que habían sido su lugar\nnativo\nLos awoses le pidieron que sacrificase, para no\nperder su propiedad\nUn añejo chivo era la ofrenda, de lo contrario tres\ngallos, además de una buena cantidad de dinero Él\nsacrificó\nY ninguno de sus adversarios pudo lograr nada\ncontra él Así pudo estirar sus miembros como quiso\nen las aguas\nEl alabó y regocijó a sus babaláwos\nEllos alabaron a Ifá\nÒyè wònrin mì\nÒyè wònrin jẹ\nÒyè sợni pàkàpàkà gbé mì\n\nFueron quienes lanzaron Ifá para el Cocodrilo\nmagnánimo\nQuien vivía en las aguas profundas que fueron de su\npadre en la región de Ìrágbìjí\n¿Quién sacará de esas aguas al Cocodrilo?\nDe esas aguas que pertenecieron a sus padres\n¿Quién retará ahora al Cocodrilo?\n\n              Òyè wònrin mì\n              Òyè wònrin jẹ\n       Òyè sợni pàkàpàkà gbé mì\n           A dífá fún Ajíbówú\n         Èyí tíí salágbèdẹ Ògèlé\n              Wón ní ó rúbợ\nOlódùmarè ló kó gbogbo àwợn Alágbèdẹ\n            ti ń bẹ ńlé ayé jợ\n     Wón ní kí wón ó móợ rợ nňkan\n  Gbogbo nňkan ti wón bá lè ronú kán\n     Ó lóun féé wo tẹni tí ó gbayì jù\n           Àwợn kán rợ tàkúté\n                  Ìlu ò níye\n              Èwòn ń bẹ ńbè\n               Àdá ò gbèyín\nGbogbo nňkan tèèyán le fin irin dá ń bírà\n          Gbogbo è ni ợn ti rợ\n Alágbèdẹ Ògèlé bá tó àwợn Babaláwo è\n                      lợ\n                  Ệ gbàun!\n     Nňkan ti ợn ní kí àwợn ó rợ yìí\n          Ó di ìmòràn fún òun!\nÀwợn Òyè wònrin mi ní kó pèsè fún àwợn\n                     ayé\n            Àwợn Àgbàlàgbà\n          Àwợn ní ó fònà hàn ó\n\n              Ajíbówú bá rúbợ\n      Ó pèsè fún àwợn Àgbàlàgbà\n      Ni ón bá fún Ajíbówú ní Oşù\n               Wón ní kó rợ ó\n     Kó wáá gbé e sínú igbá àdému\n                Fèrè tó bá sí\n           Yóó móợ sún díèdíè\n             Wón ó pèé oşù lé\nDíèdíè ti yée tijợ kèédógún ti gbogbo ojú\n                  è ó sìí sílè\n          Yóó ti kún inú igbá tán\n             Ńgbà ó bá tún yá\n            Yóó tùún móợ bò ó\n          Bó bá tún ku ibi tíínrin\n     Wón ó tùún móợ pé osú lè lónìí\n          N ní wá ń jó ní wá ń yò\n         Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n   Ó ní béè làwợn Babaláwo tòún wí\n               Òyè wònrin mì\n               Òyè wònrin jẹ\n       Òyè sợni pàkàpàkà gbé mì\n            A dífá fún Ajíbówú\n          Èyí tíí salágbèdẹ Ògèlé\n             Ệbợ n wón ní ó şe\n              Ó si gbébợ ńbè\n                    Ó rúbợ\n         Ệ mó jèé á mu rợ agogo\n             Irin ta mu rợ oşù\n         Ệ mó jèé á mu rợ agogô\n\nÒyè wònrin mì\nÒyè wònrin jẹ\n\nÒyè sợni pàkàpàkà gbé mì\nLanzaron Ifá para Ajíbówú\nEl herrero de la ciudad de Ògèlé\nA quien se le pidió sacrificar, ya que Olódùmarè\nhabía congregado a los herreros del mundo y les\nhabía pedido que creasen todo tipo de cosas, con\nsus manos buscando el más diestro de ellos\nY se crearon todo tipo de artefactos como cuchillos,\nmachetes, vasijas, asientos, armaduras, cascos, etc\nAjíbówú vino a los babaláwos y les pidió ayuda\n- ¡Las cosas que el Supremo pidió hacer,\ntrascienden mi conocimiento!-\n- Los sacerdotes Òyè wònrin, me han pedido que\nsirva a las Brujas, a los Ancianos – ellos le dijeron\nque le enseñarían el camino a seguir\nAjíbówú hizo todo lo que le fue orientado y ofrendó\nEllas (las Brujas) entonces le brindaron La Luna\nEllos le dijeron que la tallara y la pusiera dentro de\nun recipiente llamado “Àdèmú”\nY en el término de 16 días debía irla destapando\nlentamente, día a día y las personas dijeron que La\nLuna Creciente iba poco a poco apareciendo, hasta\nel último día que La Luna llenó completamente la\nvasija Después de un tiempo, él la volvió a tapar\nlentamente\nA partir de entonces de solo verla una vez, las\npersonas decían que había aparecido la Luna\nCreciente\nÉl bailó y alabó a sus babaláwos\nEstos alabaron a Ifá\nÒyè wònrin mì\nÒyè wònrin jẹ\nÒyè sợni pàkàpàkà gbé mì\nLanzaron Ifá para Ajíbówú\nEl herrero de la ciudad de Ògèlé\nA quien se le pidió sacrificar, y así lo hizo\nNunca nos permita tallar usando el gong\n\nEl hierro usado en formar a la Luna\nNunca nos permita formar usando el gong", "origen_id": "e960c2755729fcca38ef90d2"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku Wonrin ofrece remedios para horribles consecuencias de\n                                      adulterio y peligros en viajes distantes.\n                   WO – Acciones no pensadas resultan negocios bloqueados.\n\n\n36.1 · Okitibi-aketekitan-nidi-ope adivinó Ifá para Lawenibu. Ella le\n          había pedido confesar su adulterio si no quería morir. 1 chiva, sería\n      ofrecida como sacrificio si ella no quería morir a causa del adulterio.\n      Ella hizo el sacrificio. Ifá dice que las mujeres para quienes esto está\n                                      adivinando, están cometiendo adulterio.\n\n\n36.2 · Jafirijafi, Kemkejake, Agadagidiwonu-odo-ef´arabo-omi\n      adivinó Ifá para el cazador (Ode) y para Orunmila. Ode estaba yendo\n             al bosque de Olikorobojo. Le fue pedido sacrificio para evitar la\n           muerte allí. 6 gallos y 14,400 cowrie. El cazador hizo el sacrificio.\n             Orunmila estaba en un viaje hacia un lugar muy distante, Le fue\n            pedido un sacrificio para evadir la muerte allí. 1 pote de aceite de\n            palma, 9 gallos, 9 ratas, 9 pescados y 9 palomas. Orunmila oyó el\n                                                   aviso y realizó el sacrificio.", "origen_id": "cc35b770ddf5995e60f90bb1"}, {"titulo": "Relato en inglés 1", "texto": "“The Qka snake stays in its nest stretching out its face;1 Python stays by the\nwaterside stretching out its neck like one who wants to become a chief; Rainbow,\nthe foolish one, stays in the heavens, spreading very brightly”? was the one who\ncast Ifa for all the people of Ifẹ when things were going badly for them, when their\nworld was covered like a calabash.\n\nIfa says that the affair for which we are divining has spoiled, but that we can\nset it right by sacrificing. Six of everything must be sacrificed: six bunches of\ndried rats, six bunches of dried fish, six cloths, six bags of money (thirty shil-\nlings), six ewes—six of everything —and six drums. The people of Ifẹ completed\nthe sacrifice, and when they carried these things to Mesi Alukunrin,° rain began\nto fall.4 They brought the six drums to the square and began to sing:\n\n“We are making a sacrifice;\n\n“Rain does not fall, we are planting guinea corn;\n“We are making a sacrifice.\n\n“We are making a sacrifice;\n\n“Oh King of the Igbo, Children of Leopard,®\n\n“We are making a sacrifice;\n\n“Rain does not fall, we are planting guinea corn.”\n\nIfa says that the affair for which we are divining has spoiled, and that it cannot\nbe put right again unless we make a sacrifice.", "comentario": "1. This kind of snake does not run away when hunters come to kill it, but\nrises up and peers out at them to see what is happening. The CMS Dictionary\nlists ọka as “a species of boa constrictor. See ‘Elebu’ = cobra,” and for “cobra”\ngives gka. Abrahams suggests that it may be the Gaboon viper. It is also called\n“Nana Buruku’s snake” (ejo Buku), and is described in Mekg as small, about a\nfoot long, with black and red markings.\n\n2. As the rainbow is thought of as a python (er’), all three statements con-\ntain a reference to snakes. Cf. the last with verse 35-6.\n\n3. A place in the square before the palace at Ifẹ (formerly a building with-\nin the palace walls) where humans were formerly executed.\n\n4, The implication of this verse, made clear in Yoruba mythology, is that\nit rains nowadays when planting time comes only because the very early in-\nhabitants of Ifẹ made the sacrifice described here. It is said that at this time\nthere were no yams or maize, and that guinea corn was the only food.\n\n5. The names Igbomekun and Ejigbomẹkun (cf. verse 18-10) appear ina\nnumber of Yoruba myths and are commonly interpreted by informants as refer-\nring to an ancient town with the word used here (Onigbomekun) as the title of its\nruler. However, an Ifẹ diviner explained Onigbomekun as meaning O-n(i)-Igbo-\n(ọ)m(ọ)-ẹkun or “Owner of Igbo, Child (or Children) of Leopard”; he identified him\nas Qsangangan Qbamakin and “Igbo” as his subjects—the people from whom\nMọrẹmi saved the people of Ifẹ. This interpretation, which is followed here, was\nconfirmed by a priest of Qsangangan Qbamakin, who added that Qsangangan\nQbamakin is a deity (ebura) who once ruled as an early king of Ifẹ and that the\nIgbomekun were the original inhabitants of Ife. Cf. n. 6, verse 247-5.", "origen_id": "08d4b423385a896683426166"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Lawẹnibu: una chiva.", "El cazador: seis gallos y 14,000 cauríes.", "Ọ̀rúnmìlà: un recipiente de aceite de palma, nueve gallos, nueve chivos, nueve ratas, nueve pescados y palomas.", "El cocodrilo: un chivo viejo (o tres gallos) y bastante dinero.", "Ajíbówú: servir y ofrecer a las Madres (Ìyàmi)."], "pasajes": [{"titulo": "Ofrenda en el verso 36.1", "texto": "Okitibi-aketekiitan-nidi-ọ̀pẹ\nadivinó Ifá para Lawẹnibu,\na ella le fue aconsejado hacer sacrificio\npara que pudiera confesar su adulterio\nsin que la mataran.\nUna chiva sería ofrecida como sacrificio\nsi ella no queria morir a causa del adulterio.\nElla hizo el sacrificio.\nIfá dice: la mujer a quien este Ifá se le está adivinando, está\ncometiendo adulterio.", "origen_id": "1ecc425bcc85e472d8ea297d"}, {"titulo": "Ofrenda en el verso 36.2", "texto": "Jafirijafi, Kẹmkẹjakẹ,\nAgadagidiwonu-odo-ef'arabo-omi:\nadivinó Ifa para el cazador (Odẹ)\nEllos también adivinaron Ifá para Ọ̀rúnmìlà.\nOdẹ estaba yendo al bosque de Olikorobojó.\nLe aconsejaron sacrificar\npara evitar la muerte allí:\nseis gallos y 14000 cowries.\nEl cazador hizo el sacrificio.\nỌ̀rúnmìlà estaba yendo de viaje\na un lugar muy distante (a través del agua).\nLe aconsejaron sacrificar\npara evitar la muerte allí:\nun recipiente de aceite de palma,\nnueve gallos,\nnueve chivos, nueve ratas,\nnueve pescados y paloma.\nỌ̀rúnmìlà escuchó y realizó el sacrificio.", "origen_id": "739c8f712c84bfc4595284f0"}]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè convoca a los herreros. Las Madres (Ìyàmi), las ancianas, entregan la luna a quien las sirve. Ọ̀rúnmìlà ofrece antes de cruzar el agua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, recipiente àdèmú, gallos, ratas, pescados."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 36.1 (yorùbá): Okitibi-aketekiitan-nidi-ğpẹ / li o difa fun Lawẹnibu, / a niki ó wa rúbo, / kiosi wa ka'ką biobawipe ki oun ma kú. / Ewúrẹ kan li ebọ / tiobawipe ki oun ma kú ikú òràn naa. / Ó gbọ̀ ó rú. / Ifá nwipe: Obirin ti a da'fá yi fún ndoką.", "Verso 36.2 (yorùbá): Jafirijafi, Kẹmkẹjakẹ, / Agadagidiwonu-odo-ef'arabo-omi: / li o dífá fOdẹ. / Ó dífá f'Ọ̀rúnmìlà. / Odẹ nre igbó Olikorobojó, / wọ̀n niki ó rúbọ / kioma baa kus'ohun: / akuko-adiyẹ méje ati ẹgbàáje owó. / Qdẹ rúbo. / Ọ̀rúnmìlà nlọ s'ajo / ti o jin gbungbungbun bi omi. / Wọ̀n niki ó wa rúbọ / kioma baa Kus'ohun: / ata (ikoko) epo, / akuko-adiyẹ mésàn, / obúko mẹsàn, / eku mésàn, / ẹja mẹsăn ati ẹyẹlé. / Ọ̀rúnmìlà gbọ̀ ó rúbọ.", "REZO: OYEKUN JUANI BADAWA IFA OBA MAYIRE ELEGBARA BADAWA FA AYORE LOKUN OBA YORE OBA LOKUN ELEGBARA IFA LAYE BEITA IRE ASHEGUN OTA LESE ELEGBARA UN BATI AWO BOGBO OUN BAYE OLUWO.", "REZO: INTORI ARAYE OUKO ELEBO INTORI IWABOBO AKUTA ELEBO AIKU NIARE.", "REZO: OYEKUN ONIGUA ADIFAFUN OBINI INTORI ELLO IKOKO EFUN KUPA EYELE LEBO ADIE.", "REZO: IYERE O BABA ETIKA OSHEGUN FUN KOLOSHEGURE COBO OMASHE LONI ESETONSHE AKUKO ADIE AGUTAN EBEFA OWO.", "REZO: ORUNMILA ADIFAYOKO ODAFUN A IKU OWO NI ORIN.", "REZO: ADIFAFUN OBATALA LERI OMO ILEWA INTORI ARAYE LATI ILE OYEKUN OJUANI OBATALA UNLO ILE IÑA LOFEKEBA YOKO SHILEKUN ILE ARAYE IÑA KURUMA SHANGO OGGUN ATI OSHOSI IFA NI KAFEREFUN ORUNMILA.", "REZO: BADAWA IBA OBA OMAYERE ELEGBARA BADAWA EFA ELE OYERE LEKUN OBAYERE OBALEKUN ELEGBARA UMBATI AYE UNBATE AWO WAWA GBOGBO CABAYE OLUO FARE.", "REZO: IGUI INTORI OYO LAYO OPA KOFIADENO AYA ARUBO ORUN ONA NI ADA GBOGBO TENUYEN YOURO ABITI LARI LORUBO EKU, EYA, EPO, OWUNKO, MEDILOGUN OWO.", "REZO: ADIFAFUN OBATALA LERI OMO ILEWA INTORI ARAYE LATI ILE OYEKUN OJUANI OBATALA UNLO ILE IÑA LOFEKEBA YOKO SHILEKUN ILE ARAYE IÑA KURUMA SHANGO OGGUN ATI OSHOSI IFA NI KAFEREFUN ORUNMILA.", "REZO: BADAWA IBA OBA OMAYERE ELEGBARA BADAWA EFA ELE OYERE LEKUN OBAYERE OBALEKUN ELEGBARA UMBATI AYE UNBATE AWO WAWA GBOGBO CABAYE OLUO FARE.", "REZO: IGUI INTORI OYO LAYO OPA KOFIADENO AYA ARUBO ORUN ONA NI ADA GBOGBO TENUYEN YOURO ABITI LARI LORUBO EKU, EYA, EPO, OWUNKO, MEDILOGUN OWO."]}]$q$::jsonb),
(37,'e820ef3c9ebf23d7e30fa3e3e86e0d84','f307d905fa35adf89497991814a3818e',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀bàrà da la oportunidad de librarse de las consecuencias de malas acciones o decisiones equivocadas del pasado, y rompe ataduras, deudas e impedimentos que bloquean la libertad. La persona pide lo bueno de la vida y le llegará; nunca estará sola."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Arrastra una deuda u obligación sin resolver y debe decidir cómo cumplirla (relato de Awun y Esi).", "Quiere evitar las consecuencias de algo que hizo antes.", "Se siente solo y se pregunta si tendrá apoyo (relato de Orí, al que se le unen las partes del cuerpo).", "Cuida de un hijo o de alguien que depende de él y teme un trato injusto (relato del caballo Eṣin).", "Usa la astucia para salir ganando y debe ver si con eso respeta a los demás.", "La impaciencia puede echar a perder un cambio que ya venía (relato del mono de Ìdèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Liberarse de una deuda o de una atadura.", "Compañía: nunca estará solo.", "Honra y admiración.", "Lo bueno de la vida llega a su lado."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La determinación del ciclo lleva a la transformación. (Este Odu habla de la necesidad de reponer una deuda con integridad).", "origen_id": "0a59629714c7afd8620f4f55"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Que los hijos sufran castigos por no haber ofrecido completo.", "Ofrecer solo por lo que gusta y olvidar lo que protege.", "Problemas en el día a día por no atender la ofrenda."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva al egoísmo. (Este Odu habla de los problemas asociados con el fracaso a mantener la disciplina espiritual).", "origen_id": "250154cf56795062c6c71108"}]}, {"titulo": "Enseñanza principal", "texto": "La ofrenda se hace completa. La yegua ofreció para ser admirada pero no para no ser azotada, y hoy la montan y la golpean a ella y a sus hijos."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ọ̀yẹ̀kú'Bàrà exhorta a realizar sacrificios para evitar consecuencias negativas en las actividades cotidianas normales (problemas en el día a día del cliente).", "origen_id": "0794d6613be5ad9a5fd7eb0a"}]}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga y su deuda con Esi. La tortuga (Awun) trabajaba como sirviente de Esi para pagarle una deuda. Le marcaron 3,600 cauríes y una cabra para no tener que pagar el préstamo, y cumplió. Después se quedó cinco días en su casa sin reportarse. Envolvió un paquete de piedras con una cuenta de coral y lo dejó en casa de Esi. Esi, al volver, tiró el paquete al monte. Awun le preguntó si había visto lo que le dejó, y cuando Esi dijo que lo había tirado, gritó: '¡Tiraste mis cuentas de coral al monte!'. Fueron con los ancianos que hacían de jueces, Esi resultó culpable y tuvo que aceptar las cuentas que tiró como pago del préstamo.", "Orí y las partes del cuerpo. El adivino de la Cabeza consultó para Orí cuando venía del cielo a la tierra. Siempre había estado solo, y preguntaba si encontraría quién lo acompañara. Le pidieron ofrecer y cumplió. Cuando decidió partir, los ojos se pararon frente a él y dijeron que lo seguirían; la boca dijo que iría con él a donde fuera; la nariz dijo 'no te dejaré solo'; y las orejas, las piernas, los brazos y todas las partes del cuerpo se fueron con él, y él quedó como su líder. Por eso esta persona no estará nunca sola.", "La yegua y los azotes. El adivino del caballo consultó para la yegua (Ẹṣin) cuando venía del cielo, y al llegar a la tierra le pidieron ofrecer otra vez: para ser honrada y admirada, y también para no ser azotada. Solo ofreció para ser admirada; no dio los dieciséis fuetes de àtòòrí, doscientos garrotes, un chivo y 2,600 cauríes que la protegían del castigo. Cuando tuvo a su cría fue a Ọ̀yọ́, y Èṣù pidió que la gente se montara en ella. La gente dijo que acababa de parir, y Èṣù respondió que eso no le impedía caminar y que llevaran fusta. Desde entonces la montan y la golpean, a ella y a sus hijos. Se lamentó: 'Ọ̀yẹ̀kú pabala, pabala', que es el sonido de su trote recordando al adivino."], "pasajes": [{"titulo": "Verso 37.1", "texto": "Ọ̀yẹ̀kú-Pabala,\nỌ̀yẹ̀kú-Pabala:\nadivinó Ifá para la tortuga (Awun)\ncuando él era sirviente de Esi\n(trabajaba para Esi)\npor un dinero que le debía a este.\nA él se le dijo que debía sacrificar:\ntres mil seiscientos cowries y una cabra.\nSi él hacia el sacrificio,\nevitaría tener que reembolsar\nel préstamo que le habían hecho.\nÉl escuchó el consejo y realizó el sacrificio.", "comentario": "Durante mucho tiempo, la tortuga había estado sirviendo a Esi como convenio de pago por una deuda con este. Después del sacrificio, él decidió permanecer en su casa durante cinco días y no se lo reportó a su acreedor. Él envolvió un paquete de piedras con una cuenta especial (cuenta de coral) y lo llevó el hogar de Esi. Cuando Esi volvió a casa, le dieron el paquete, el cual botó lejos en la manigua. Awun le preguntó si él vio el paquete que le dejó en su casa. Esi dijo que él lo vio y que lo había lanzado lejos en la manigua. Awun dijo: \"Ha! usted lanzó las cuentas de coral (iyun')\" lejos en la maleza?\". Para hacer la historia corta, el asunto se convirtió en un proceso legal entre ellos. Ellos tuvieron que ir a los ancianos en la ciudad que entonces actuaban como los jueces. Esi fue encontrado culpable. A él se le exigió que aceptara las cuentas de coral que botó como el reembolso del dinero que debía darle Awun por el préstamo recibido.\n\"Nota r: Este Odù sirve para romper ataduras, amarres, impedimentos o deudas que bloquean el progreso y libertad de acción del cliente.\nEsl: amuleto, protección, fetiche.", "origen_id": "580d1062e1a6459ae09e349e"}, {"titulo": "Verso 37.2", "texto": "Ọ̀yẹ̀kú-pabala,\nỌ̀yẹ̀kú-pabala el adivino del Eṣin (caballo):\nadivinó Ifá para Eṣin,\nle pidieron ofrecer sacrificio\npara evitar el castigo\ny la pena después que tuviera un hijo:\ndoscientos palos (garrotes, porras),\nun chivo y dos mil seiscientos cowries.\nEṣin escuchó. Ẹṣin rechazó sacrificar.", "comentario": "Eṣin fue a visitar la ciudad de Oyó cuando ella tuvo un hijo. Eṣú pidió que la gente montara sobre ella. Ellos dijeron, \"Ha! ella acaba de tener un bebé\". Èṣú dijo que eso no significaba que ella no podría caminar. Él dijo que debían llevar un palo (fusta) para azotarla. Las personas montaron sobre ella. Ella caminó. Sin embargo siempre que ella no caminaba correctamente, era azotada. Eṣin dijo que lamentaba no haber realizado el sacrificio prescrito por Ọ̀yẹ̀kú-Pabala , Ọ̀yẹ̀kú-Pabala, Ọ̀yẹ̀kú-Pabala, Pabala, etcétera.\n75 iyun: Cuentas de coral. Tienen gran valor, son usadas por reyes, dignatarios y personas con gran poder.\n* Ọ̀yẹ̀kú-Pabala: Ọ̀yẹ̀kú-Pabala es el sonido del trote de Eṣin recordando al adivino.", "origen_id": "5f5495312ede3fe8e3929dcc"}, {"titulo": "Versos complementarios 1", "texto": "Esta persona está pidiendo por las buenas cosas de\nla vida, y estas vendrán a estar a su lado Nunca\nestará solo en su existencia. Deberá sacrificar para\nevitar sufrir de alguna manera o causa.\n\n        Òyèkú pàlàbà pàlàbà I pàbó\n           Awo Orí a dífá fún Orí\n      Orí ń tìkòlè òrun bò wá ilé ayé\n  Ń ti ń jẹ nígbàrà òrun òun nìkan şoşo\n                    gíogío\n   Òún şe lè rí ẹni mú lowo lợ ilé ayé?\n          Ti ó bàá òun dúó báyìí?\n               Wón ní kó rúbợ\n         Wón ní yóó rìí ẹni kún un\n            Orí sí dá dúó télè ni\n                 Orí bá rúbợ\n            Ńgbàa Orí ó móợ bợ\n                Ojú bá dúó tì í\n              Ệnú lóun ó ba rin\n       Imú ní tòun àtiè làwón jợ ń lợ\n           Etí náà lóun ò ní fí sílè\n   Apá, Ệsẹ, gbogbo ara ló dúó ti Orí\n   Ifá péléyiun ò níí dá wà lóun nìkan\n                  Ayé yẹ Orí\n          N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n\n       Òyèkú pàlàbà pàlàbà I pàbó\n           Awo Orí a dífá fún Orí\n      Orí ń tìkòlè òrun bò wá ilé ayé\n  Ń ti ń jẹ nígbàrà òrun òun nìkan şoşo\n                   gíogío\n                   Kèèkè\n                Ojú borí dúó\n                   Kèèkè\n               Òrun bórí duo\n                   Kèèkè\n                Etí bórí dúó\n                   Kèèkè\n                Ệnú bórí dúó\n                   Kèèkè\n               Imú borí dúó\n          Orí wá ń bẹ ní wòwó ire\n    Wòwó ire lá bàá ní lésè ợba òrìşà\n\nÒyèkú pàlàbà pàlàbà I pàbó\nAdivino de la Cabeza, profetizo Ifá para la Cabeza\nCuando venía desde el Cielo a la Tierra\nÉl había estado defendiéndose regularmente en los\ncampos celestiales\nPor eso decidió venir a la Tierra\n¿Podré hallar personas que me acompañen, ya que\nsiempre he estado solo? Se preguntaba delante de\nIfá\nLe pidieron sacrificar, para hallar acompañantes Él\nsacrificó\nPasado un tiempo, él decidió partir al Mundo\nterrestre\nLos ojos se pusieron de pie frente a él y dijo que le\nseguirían\nLa Boca dijo que iría con él a cualquier parte\n¡Yo no te dejaré solo!, exclamó la Nariz\n\nPiernas, brazos y todas las partes que hoy\ncomponen el cuerpo humano, decidieron irse con la\nCabeza al Mundo de la Tierra y por supuesto que él\nfue el líder\nIfá dice que esta persona no será jamás un ermitaño\nni solitario\nÉl se regocijó y alabó a sus babaláwos\nEstos alabaron y se regocijaron con Ifá\nÉl hizo lo que ellos le dijeron que hiciera\nÒyèkú pàlàbà pàlàbà I pàbó\nAdivino de la Cabeza, profetizo Ifá para la Cabeza\nCuando venía desde el Cielo a la Tierra\nÉl había estado defendiéndose regularmente en los\ncampos celestiales\nSiempre había permanecido en solitario y sin\ncompañía alguna\nCon el tiempo\nLos ojos se quedaron con él\nCon el tiempo\nLa Boca se quedó con él\nCon el tiempo\nLa Nariz se quedó con él\nCon el tiempo\nLa Oreja se quedó con él\nCon el tiempo\nLas partes del cuerpo en su totalidad, se quedaron\ncon él\nLa Cabeza está en el centro de muchas fortunas\nUno se encuentra en medio de incontables fortunas\nal pie del Òrìşà\n\n        Òyèkú pàlàbà pàlàbà I pàbó\n       Babaláwo Ệşin ló dífá fún Ệşin\n      Ệşin ń tìkòlè òrun bò wá ilé ayé\n       Wón ní kó rúbợ kó tóó móợ lợ\n     Ệşin dé ilè ayé wón tún ni ó rúbợ\n\n             Wón ní yóó gbayì\n                 Yóó gbèyẹ\n            Şùgbón kó rúbợ ìyà\n          Ệbợ iyì àtèyẹ ni Ệşin rú\n Kó rú àtòòrì mèríndìnlógún ti ợn ni ó fí\n                  rúbợ ìyà\n           Ti ợn bá ti ra Ệşin tán\n   Nňkan òşó ni wón ó móợ wá fún un\n           Wón ó dàá gàárí fun\n       Wón ó so ohun ẹşợ móợ lára\n          Şùgbón bó bá dijợ kan\n         Ệşin ó sì ní ợmợ nínú ilé\n       Ợmợ èèyán ó bàá ta mợ Ệşin\n         Bí ợn tí ń gún un ní késé\n  Béè ni wón ó móợ nà án ní gbóńgbó\n        A pé “Tóun sì lómợ ńnú ilé\n  Lóun ń fèyín gbé ợmợ ẹlòmíín looko”\n    Wón ní şe bí àwợn ní ó rúbợ ìyà\n Àyin ẹyin ní Ệşin ń yin àwợn Babaláwo\n       Òyèkú pàlàbà pàlàbà I pàbó\n      Babaláwo Ệşin ló dífá fún Ệşin\n     Ệşin ń tìkòlè òrun bò wá ilé ayé\n     Wón ní kó rúbợ Iyì kó rúbợ èyẹ\n       Kó si rúbợ kó mó lê jìyà láyé\n        Ệbợợ kó níyì kó léyẹ ló rú\n          Ệşin wáá lómợ nínú ilé\n                Ệ è wèèmợ!\n    Ệşin ń fèyín gbómợ ẹlòmíín roko\n                Ệ è wèèmợ!\n\nÒyèkú pàlàbà pàlàbà I pàbó\nAdivino del Caballo, profetizo para el Caballo\n(Yegua)\n\nQue venía del Cielo a la Tierra\nSe le pidió que ofrendase Y al llegar a la Tierra, se\nle volvió a pedir que sacrificase de nuevo, para que\nfuese honrado y admirado\nTambién debía sacrificar para no ser azotado ni\ngolpeado\nPero solo ofreció sacrificio para ser honrado y\nadmirado\nNo ofreció los 16 cujes o fuetes de mar pacífico o\nrasca-barriga (ewé àtòòrí) que era el ingrediente\npara evitar ser azotado o golpeado\nUna vez comprado o adquirido un Caballo, es la\ncosa más hermosa que se pueda mirar, y le\nfabricarán un buen asiento para ella, llenándole de\nabalorios y adornos hermosos que llamen la\natención de todos\nPero al tener sus descendientes (hijos), los hijos del\nhombre los montarán y les patearán en sus\nabdómenes Y golpeará al Caballo con látigos y\nfustas de àtòòrí\nEl Caballo dijo entonces: - Tuve a mis hijos y los\nensille, para que los hijos de otras personas, les\nmontasen y les pegasen –\n¿No te dijimos que sacrificaras contra el azote? Los\nbabaláwos le recordaron\nLes imploró tardíamente\nÒyèkú pàlàbà pàlàbà I pàbó\nAdivino del Caballo, profetizo para el Caballo\n(Yegua)\nQue venía del Cielo a la Tierra\nSe le pidió que ofrendase Y al llegar a la Tierra, se\nle volvió a pedir que sacrificase de nuevo, para que\nfuese honrado y admirado\nTambién debía sacrificar para no ser azotado ni\ngolpeado\nPero solo ofreció sacrificio para ser honrado y\nadmirado\n\nNo ofreció los 16 cujes o fuetes de mar pacífico o\nrasca-barriga (ewé àtòòrí) que era el ingrediente\npara evitar ser azotado o golpeado\nEl Caballo tuvo sus hijos en casa\n¡Eso es una aberración!\nAhora el Caballo monta a los hijos de otras personas\nsobre el lomo de sus hijos que también son\ngolpeados y azotados\n¡Eso es una aberración!", "origen_id": "2d896f41409dd99a67a69bfc"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyekubara llama a hacer un sacrificio para evitar las\n                             consecuencias de las actividades de un día normal.\n               WO – Oyekubara ofrece al cliente la oportunidad de evitar las\n                                   consecuencias de las malas acciones previas.\n\n\n37.1 · Oyeku-pabala, Oyeku-pabala adivinó Ifá para la tortuga\n            (awun), cuando él estuvo sirviendo a Esi por un dinero que debía.\n     Ellos dijeron que debería ofrecer un sacrificio, 3600 cowrie y 1 chiva.\n          Él evitaría el reembolso de su préstamo. Él oyó el aviso y realizó el\n                                                                       sacrificio.\n            Historia de Ifá: Por un largo tiempo la tortuga estuvo sirviendo en\n                acuerdo de reembolsar a él. Él decidió estar en casa y faltó en\n     reportarle a su acreedor por 5 días. Él envolvió un bulto de piedra con\n           una cuenta especial (coral) que tomó de la casa de Esi. Cuando Esi\n     retornó a la casa, él encontró el paquete el cual lanzó a de un arbusto.\n                   Awun (jicotea), le preguntó a él si había visto el paquete a la\n          izquierda en su hogar y Esi le dijo que él lo había visto y que estaba\n     tirado dentro de un arbusto, la tortuga le dijo “ah”, sonrió, tú tiraste la\n\ncuenta de coral dentro del arbusto. Para resumir historia, él llevó a\n              una corte el caso entre ellos, tuvieron que ir a los ancianos de la\n      ciudad quienes estaban actuando de jueces. Esi fue hallado culpable.\n     Se habló de usar las cuentas para pagarle el préstamo que había hecho\n                                                                (awun) tortuga.\n\n\n37.2 · Oyeku-pabala, Oyeku-pabala, el adivino del yegua, adivinó Ifá para\n\n     la yegua (esin), se le habló de ofrecer un sacrificio para evitar la pena\n                al obtener un niño: 200 palos, 1 chivo, 2600 cowrie. La yegua\n          escuchó pero rehusó hacer sacrificio. Su historia: Esin fue a visitar a\n           Oyo cuando ella tuvo un niño, Eşu le habló a la gente montar sobre\n     ella, ellos dijeron: ah! ella es una recién parida, Eşu le dijo que eso no\n           significaba que ella no caminara, él le dijo a ellos que él cogería un\n             palo y la azotaría a ella. Ellos montaron sobre ella y ella caminó,\n          cuando ya ella no pudo caminar más, ella fue azotada, Esin dijo que\n     ella no había regresado hacer el sacrificio indicado por Oyeku-pabala,\n                                    Oyeku-pabala Oyeku-pabala y así sucedió.", "origen_id": "64e8397e942d4f9c9e6ef185"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La tortuga: 3,600 cauríes y una cabra.", "Orí: ofrenda para tener compañía.", "La yegua (no ofreció completo): dieciséis fuetes de àtòòrí, doscientos garrotes, un chivo y 2,600 cauríes."], "pasajes": [{"titulo": "Ofrenda en el verso 37.1", "texto": "Ọ̀yẹ̀kú-Pabala,\nỌ̀yẹ̀kú-Pabala:\nadivinó Ifá para la tortuga (Awun)\ncuando él era sirviente de Esi\n(trabajaba para Esi)\npor un dinero que le debía a este.\nA él se le dijo que debía sacrificar:\ntres mil seiscientos cowries y una cabra.\nSi él hacia el sacrificio,\nevitaría tener que reembolsar\nel préstamo que le habían hecho.\nÉl escuchó el consejo y realizó el sacrificio.", "origen_id": "6eb044a67aaac43e7eb57b2c"}, {"titulo": "Ofrenda en el verso 37.2", "texto": "Ọ̀yẹ̀kú-pabala,\nỌ̀yẹ̀kú-pabala el adivino del Eṣin (caballo):\nadivinó Ifá para Eṣin,\nle pidieron ofrecer sacrificio\npara evitar el castigo\ny la pena después que tuviera un hijo:\ndoscientos palos (garrotes, porras),\nun chivo y dos mil seiscientos cowries.\nEṣin escuchó. Ẹṣin rechazó sacrificar.", "origen_id": "d8cbef33423d7b5385c85021"}]}, {"titulo": "Relaciones espirituales", "texto": "Orí es el líder del cuerpo y la cabeza de la persona. Èṣù hace cumplir la palabra de Ifá en el relato de la yegua. Los ancianos de la ciudad actúan como jueces."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àtòòrí (fuetes), cuentas de coral (iyùn), piedras."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 37.1 (yorùbá): Ọ̀yẹ̀kú-Pabala, / Ọ̀yẹ̀kú-Pabala: / li o dífá f'Awun, / nigba ti o nṣe olofa / fún Esi™ wọ̀n ni biobarú, / Egbejidilógún owó ati ewúrẹ li ebọ. / A je owó ohun gun. / Ô gbọ̀ ó rú.", "Verso 37.2 (yorùbá): Ọ̀yẹ̀kú-Pabala, / Ọ̀yẹ̀kú-Pabala awo Ẹṣin: / li o dífá fún Ẹṣin / wọ̀n niki ó wa rúbọ / nitoripe nigbati o ba bimo / ki iyà ma baa jẹẹ: / igba opa, òbúko ati egbètalá owó. / Ẹṣin gbọ. Ẹṣin ko rú.", "REZO: OYEKUN BARA ALORDAFUN OSHUN LO OSAIN OÑI SHANGO SHEBE SHINTILU OSUSHE MUTI ESHIN NILOKO SHISHE IFA SHEMI OSHUN LONSHE OLUFINA OPOLOPO OTI OÑI SHANGO.", "REZO: OYEKUN BARA OLODOFA ESHU LOQUI MALU NI MALU AKUSHEWI TI OSHI MI BOKOSHISHE BI TONSHENILA FASHE NIBA ABALE NI TISHE OBINI AMBIMU PAWALE NO KITIM IYA LONA AKUKO UN BERESI MI PAMALE LONDE OMO OLOFIN. OYEKUN BARA MOFOKO SHOKUOLLO KAFEREFUN OBATALA, KAFEREFUN ESHU.", "REZO: ADIFAFUN IFA IKU YOYE ADIFAFUN ITA LUBA OLEFANA SOFA NIKUA MAMETA LODO SHEDE LADE SHOKA LUDO EKUN, ADIE DUN DUN, ISHERI META, EWEFA OWO LOKE OMA AYE RERE OMA AYE KERE OMA AYE IKUPA KEKE IKUPA MAKI ASHEBO PASHAN ELEBO, KAFEREFUN OZAIN, LODAFUN OBATALA.", "REZO: OYEKUN BARA LODAFUN ESHIN LO OZAIN SHANGO SHINTILU OSUSHE MUTI ESHIN NILOKO IFA SHOMI OSHUN LONSHE MAMU OLUFINA OPOLOPO OTI OGU WERE NINSHE OMO OLOFIN LODAFUN OZAIN KAFEREFUN ABOÑO OÑI SHANGO.", "SUYERE: ESHIN KIKO, ORO ASARELE ONI SHANGO WERE WERE NI TO SUN.", "REZO: ADIFAFUN IFA IKU YOYE ADIFAFUN ITA LUBA OLEFANA SOFA NIKUA MAMETA LODO SHEDE LADE SHOKA LUDO EKUN, ADIE DUN DUN, ISHERI META, EWEFA OWO LOKE OMA AYE RERE OMA AYE KERE OMA AYE IKUPA KEKE IKUPA MAKI ASHEBO PASHAN ELEBO, KAFEREFUN OZAIN, LODAFUN OBATALA.", "REZO: OYEKUN BARA LODAFUN ESHIN LO OZAIN SHANGO SHINTILU OSUSHE MUTI ESHIN NILOKO IFA SHOMI OSHUN LONSHE MAMU OLUFINA OPOLOPO OTI OGU WERE NINSHE OMO OLOFIN LODAFUN OZAIN KAFEREFUN ABOÑO OÑI SHANGO.", "SUYERE: ESHIN KOKO, ORO ASARELE ONI SHANGO WERE WERE NI TO SUN.", "REZO: OYEKUN BARA OLODABA ESU LO KIMOLU NI OKUSENI TE ESIN NI LOKO SESE NI TOASEMI LAFOSE NIBA ABAL BONSE OMO OLOFIN."]}]$q$::jsonb),
(38,'7294b66290983fdbaaca70689c8e7b6b','e451496c122c4d1da8a4b216dbe782b0',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀kànràn habla de cómo la ofrenda protege de las malas intenciones de otros y de la pérdida del prestigio. La persona es terca y no quiere seguir un consejo sabio. Ifá promete arreglarle la vida y pide cuidar la relación con la pareja y no hacer falsas amistades."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No quiere seguir un consejo razonable y se aleja de quien podría ayudarle.", "Quiere cuidar su prestigio y teme que una mala decisión lo dañe (relato de la estrella Irawọṣaṣa).", "Siente una amenaza en una salida o una fiesta (relato del mono Oyi).", "Una amistad o una relación de pareja necesita cuidado y límites.", "Busca descanso y estabilidad después de una etapa difícil (relato del Akápò de Ọ̀rúnmìlà).", "Si deja la terquedad, un cambio de rumbo puede traerle oportunidades."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que los enemigos no puedan vencerlo.", "Una vida reparada y tranquila.", "Conservar a la pareja a su lado."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva a nuevas oportunidades. (Este Odu habla de la necesidad de hacer ebo para una larga vida y buena salud.)", "origen_id": "cdf43acf6b3578663c96a09f"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder la fama y el honor por apartarse del camino del dueño.", "Meterse con la pareja de un amigo: puede costar la vida.", "La terquedad que rechaza el consejo.", "Ir a una fiesta donde alguien planea hacerle daño."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva al aislamiento no necesitado. (Este Odu habla del potencial para apagarse físicamente y la posibilidad de perdida financiera).", "origen_id": "6898ee942d08b01ba6d16346"}]}, {"titulo": "Enseñanza principal", "texto": "El orgullo hace caer a la estrella. La que no siguió el camino de su señor es la estrella fugaz que vemos caer a la oscuridad. Y el que se mete con la mujer ajena, aunque esté avisado, paga con su vida."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú Pẹlẹkan habla de cómo el sacrificio nos puede proteger de las malas intenciones de los demás y de la pérdida del prestigio.", "origen_id": "6a050ef85aefe9385e66b192"}]}, {"titulo": "Relatos reunidos", "puntos": ["El hijo del mono y la fiesta. Kabẹkukutekurolonà consultó para Akibola, que iba al campo a la fiesta anual con la idea de matar al hijo del mono (Oyi) y lucir su piel. Al mono le marcaron tres lanzas, tres gallos y 6,600 cauríes. Rechazó la ofrenda y lo mataron.", "La estrella orgullosa. Atorirorayo consultó para Irawọṣaṣa, la estrella, una de las sirvientas de Olódùmarè, y le dijo que si no seguía el camino de su señor, su fama se acabaría. Le marcaron una chiva y 2,000 cauríes, y se negó. Por eso, el día que Olódùmarè se refleja en el orgullo de una estrella, vemos una estrella fugaz caer del cielo a la oscuridad.", "El animal de cuernos para el Akápò. Ifá consultó para Ọ̀rúnmìlà, y Ọ̀rúnmìlà le dijo a su Akápò (su adivino ayudante) que preparara un animal del monte con buenos cuernos para que su vida mejorara. Lo prepararon y lo ofrecieron a Ifá; todo mejoró y llegaron la paz y el descanso.", "Mágbàgbéọlá y la mujer de su amigo. Ifá consultó para Mágbàgbéọlá y le advirtió que ofreciera y tuviera mucho cuidado con las mujeres de sus amigos. No hizo caso: se llevó a una mujer casada de su casa a la de sus padres. Unos asaltantes desconocidos lo golpearon hasta matarlo en su propia casa, que quedó robada y casi destruida. Ifá pide a esta persona mucho cuidado con los amoríos y el adulterio."], "pasajes": [{"titulo": "Verso 38.1", "texto": "Kabẹkukutekurolonà-\nkaribipade-ijàpẹkipẹki:\nadivinó Ifá para Akibola\ncuando él fue al campo al festival anual.\nÉl iba para matar al hijo de Oyi (mono).\nEl planeó mostrar su piel.\nLe fue aconsejado a Oyi hacer sacrificio:\ntres lanzas, tres gallos\ny 6600 cowries.\nÉl rechazó el sacrificio.\nÉl fue muerto.", "origen_id": "971077e979cebb55955f1ef7"}, {"titulo": "Verso 38.2", "texto": "Atorirorayo-llélaba-Irókò-ngbe:\nadivinó Ifá para Irawoṣaṣa (estrella)\nuno de los sirvientes de Olódùmarè.\nA él le fue dicho que si no seguía\nel camino de Olúwa (de su dueño),\nsu fama (honor, respeto) se acabaría.\nUna chiva y 2000 cowries son el sacrificio.\nIrawọ (la estrella) rechazó el sacrificio.\nPor eso, el día que Olódùmarè\nse refleja en el orgullo de una estrella,\nnosotros vemos una estrella fugaz\ncaer del cielo a la oscuridad.\n\" Olúwa: significa: dueño, amo, patrocinador. Olúwa es también un nombre de\nalabanza para Ọlorun (\"Fuente fundamental de la creación\"), significa: \"Soberano\nposeedor del buen carácter\".", "origen_id": "f76c99c5185e31ee0bcbee85"}, {"titulo": "Versos complementarios 1", "texto": "Ifá enmendará la vida de esta persona. Para esto\npide un animal con grandes tarros, para que sus\nenemigos o detractores nunca puedan vencerle.\nTambién sacrificará para estar a bien con su mujer\no esposa y que ella no le abandone. No deberá\nhacer falsas o malas amistades.\n\n                 Awáwa\n                 Awàwa\n             Awàwa ň wawà\nỢta pété pètè pèté ni wón fi ń wawà nífè\n          A dífá fún Òrúnmìlà\nIfá ó gbẹran ahùwo wàňwà lowo akápòo\n                    rè\n Òrúnmìlà ló ní kí Akápò òun ó tójú ẹran\n              abìwo wàňwà\n           Kí ayée rè ó lè dáa\n    Akápò bá tójú ẹran abìwo wàňwà\n            Ó fi bòkè ìpòrí è\n          Ni nňkan è bá ń dáa\n               Ayé bá yẹ é\n              Ợkàan rè balè\n                Ló nísinmi\n\n                Ó ní Awáwa\n                   Awàwa\n               Awàwa ň wawà\nỢta pété pètè pèté ni wón fi ń wawà nífè\n            A dífá fún Òrúnmìlà\nIfá ó gbẹran ahùwo wàňwà lowo akápòo\n                      rè\n Ệran abìwo wàňwà tIfá gbà lówó Akápò\n                      rè\n       Ifá fi tún ti Akápòo rè şe ni\n\nAwáwa\nAwàwa\nAwàwa ň wawà\nỢta pété pètè pèté ni wón fi ń wawà nífè\nLanzaron Ifá para Òrúnmìlà\nIfá acepta un animal con tarros elaborados de su\nAkápò\nÒrúnmìlà le dijo a su Akápò, que preparase un\nanimal salvaje con buenos cuernos, con tal de que\nsu vida (Akápò) fuese mejor\nEl animal fue preparado y sacrificado a Ifá\nY entonces todo mejoró para mucho mejor, se\nobtuvo la paz mental y el reposo pleno\nÉl dijo: Awáwa\nAwàwa\nAwàwa ň wawà\nỢta pété pètè pèté ni wón fi ń wawà nífè\nLanzaron Ifá para Òrúnmìlà\nIfá acepta un animal con tarros elaborados de su\nAkápò\nY lo ha usado para reparar su vida (Akápò)\n\n           Sígìdí ni ò yírùn padà\n          A dífá fún Mágbàgbéợlá\n\n         Ợmợ a şe lenle pàdé àlè lợnà\n                   Wón ní ó rúbợ\n            Kó si şợra lợdợ Obìnrin\n            Mágbàgbéợlá ò gbòrán\n              Ilé Obìnrin tíí móợ lợ\n    Obìnrin òhún si ti kó kúò ńlé ợkợ ẹ\n              Ó ti kó lợ ilée bàbá è\n Ibí tí ilé gbé şe yabugẹ léyìn ni ợ lù ú pa\n                         sí\n            Ifá pé kí eléyìun ó şợra\n                  Kó sì mó déjàá\n             Sígìdí ni ò yírùn padà\n            A dífá fún Mágbàgbéợlá\n         Ợmợ a şe lenle pàdé àlè lợnà\n           Wón ní ó sá káalè kó jarè\n                    Ệbợ ní ó şe\n             Kó mó baà bóbìnrin lợ\n              Mágbàgbéợlá gbébợ\n                   Béè ní ò rúbợ\n          Mágbàgbéợlá ìwợ lòó şeun\n                  Ìwợ lòó şèèyàn\n E bí ón ní ó rúbợ kó mó baà bóbìnrin lợ?\n         Ìwợ ló şe lenle pàdé àlè lợnà\n\nTalla de madera con rostro humanoide rehusó virar\nsu cuello\nLanzó Ifá para Mágbàgbéợlá\nEl hijo de A şe lenle pàdé àlè lợnà\nA quien se le dijo de sacrificar, y que tuviese mucho\ncuidado con las mujeres de sus amigos\nMágbàgbéợlá, no escuchó el consejo\nLa muchacha que estaba con él, la había sacado de\nsu casa matrimonial y le había llevado a la casa de\nsus padres\n\nY él fue golpeado hasta la muerte por asaltantes\ndesconocidos en su propia casa que fue robada y\ncasi destruida\nIfá le pide a esta persona que sea cuidadosa en\nestos asuntos de amoríos y adulterios\nÉl no se guardó de los tabúes ni de los avisos\nrecibidos por Ifá\nTalla de madera con rostro humanoide rehusó virar\nsu cuello\nLanzó Ifá para Mágbàgbéợlá\nEl hijo de A şe lenle pàdé àlè lợnà\nA quien se le dijo de sacrificar, y que tuviese mucho\ncuidado con las mujeres de sus amigos\nMágbàgbéợlá, eres quien sabía que una mujer ajena\nte llevaría a la muerte y aún así no sacrificaste No\neres humano, pues no entendiste que la ofrenda era\npara evitar morir prematuramente y por asuntos de\npromiscuidad\nPor no oír la advertencia sacrificatoria te hallaste\ncon el cuello del cadáver, debido a la concubina\nprohibida", "origen_id": "6796c4c14da949ea76241ce3"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyekupelekan habla de cómo el sacrificio puede protegernos de\n                     las malas intenciones de otros y de la pérdida del prestigio.\n                    WO – El cliente es porfiado y se rehúsa a un consejo sabio.\n\n\n38.1 · Kabekukutekurolona-karibipade-ijapekipeki adivinó Ifá para\n       Akibola cuando él fue al campo al festival anual para matar al hijo de\n                  Oyi (mono). El planeó mostrar su piel. Oyi le fue pedido que\n            ofreciera sacrificio: 3 lanzas, 3 gallos, 6.600 cowrie. Él rechazó el\n                                                       sacrificio. Él fue muerto.\n\n\n38.2 · Atorirorayo-Ilelaba-Iroko-ngbe adivinó ifá para Irawosasa el\n                esclavo de Olodumare. A él le fue predicho que si no seguía el\n           camino de Oluwa, su fama sería desterrada. 1 chiva, 2000 cowrie se\n           debe hacer como sacrificio. Irawo (la estrella) rechazó el sacrificio.\n                 Por eso, el día de Olodumare se reflejaría en el orgullo de una\n            estrella, nosotros veríamos una estrella repentina caer del cielo a la\n                                                                       oscuridad.", "origen_id": "000e8184fc54f42fea39a0ec"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El mono (rechazado): tres lanzas, tres gallos y 6,600 cauríes.", "La estrella (rechazado): una chiva y 2,000 cauríes.", "El Akápò: un animal del monte con cuernos grandes para Ifá.", "Mágbàgbéọlá (rechazado): ofrenda para no morir por una mujer ajena."], "pasajes": [{"titulo": "Ofrenda en el verso 38.1", "texto": "Kabẹkukutekurolonà-\nkaribipade-ijàpẹkipẹki:\nadivinó Ifá para Akibola\ncuando él fue al campo al festival anual.\nÉl iba para matar al hijo de Oyi (mono).\nEl planeó mostrar su piel.\nLe fue aconsejado a Oyi hacer sacrificio:\ntres lanzas, tres gallos\ny 6600 cowries.\nÉl rechazó el sacrificio.\nÉl fue muerto.", "origen_id": "66875f489d3f19ba7dd4c6d1"}, {"titulo": "Ofrenda en el verso 38.2", "texto": "Atorirorayo-llélaba-Irókò-ngbe:\nadivinó Ifá para Irawoṣaṣa (estrella)\nuno de los sirvientes de Olódùmarè.\nA él le fue dicho que si no seguía\nel camino de Olúwa (de su dueño),\nsu fama (honor, respeto) se acabaría.\nUna chiva y 2000 cowries son el sacrificio.\nIrawọ (la estrella) rechazó el sacrificio.\nPor eso, el día que Olódùmarè\nse refleja en el orgullo de una estrella,\nnosotros vemos una estrella fugaz\ncaer del cielo a la oscuridad.\n\" Olúwa: significa: dueño, amo, patrocinador. Olúwa es también un nombre de\nalabanza para Ọlorun (\"Fuente fundamental de la creación\"), significa: \"Soberano\nposeedor del buen carácter\".", "origen_id": "0b6a0b930ed3ad2e80ca64ce"}]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè es el señor de la estrella. Ọ̀rúnmìlà y su Akápò, su ayudante, aparecen en el relato del animal de cuernos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Lanzas, animal de cuernos, chiva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 38.1 (yorùbá): Kabẹkukutekurolonà- / karibipade-ijàpẹkipẹki: / li o dífá f'Akibola / hlos'oko àlorò odún. / Ó nlọ pa qmọ Oyi (obọ) / O mi a so awo rẹ kọ, / wọ̀n niki Oyi wa rú: / Ako-ofà mẹta, / akuko-adiyẹ mẹta / ati egbẹ̀talelọ̀gbọ̀n owó. / Ko rúbọ. / Wọ̀n paa.", "Verso 38.2 (yorùbá): Atorirorayo-llélaba-Irókò-ngbe: / li o difá fún Irawoṣaṣa, / tiiṣe erú Olódùmare / Wọ̀n ni: / \"bikobafiti Olúwa\" rẹ ṣe / ònà l yo pa ọlá mọọ lára\" / Ewúrẹ ati egbèwá owó li ẹbọ. / Irawą ko rúbo. / Nitorinaa ni ojo ti Olódùmarè / ba ro ti igberaga irawọ kan / liaṣe nrii ti irawo naa ṣidi lojüji / a si wọ ookun.", "REZO: OYEKUN PELEKA ADIFAFUN OKANA OYEYU OBARA YIRE WA OBINI AYE OLONU OGUTIYUN LARIFUHN LODI IKU OYEKU PELEKA.", "REZO: IDI FORISHE MOLEGU BABA ILINGUO AUN MODIA NO EIFE CAPADA KORIMIO LIRE META OTAPI BABARE LO CADAMO MOCHI ILUDEDE SAGUA LEGUA COCURI RE OLEDAO OBINI LO CON LOGUN ORUBO AKORDIE ETU MELLO, EKU, EYA, EWE JARA JARA ABEFA OWO.", "REZO: OYEKUN OKANA KARA AWO WITI EFAN AWO IBANA ADIFAFUN IMPEGUO OKARAN YAKUN IMPEGUO OKARAN WAMPO OMO OWO WAMPO LODE ADIE MEYI ELEBO OWO MEDILOGUN LA MESA UOSAN.", "REZO: ADIFAFUN OKANA YEKUN AGRIA BLENIRE IFA EGGUN AGUANI LOKUN LERI FIFESHU LERI EGGUN OKUA AKUARI EGGUN FIFESHU AOBANI OLOKUN OBANIRE ALAKUARA YALE OGUANI IFA OLOKUN IFA KAFEREFUN OLOKUN Y AAYE.", "REZO: OYEKUN PELEKA ADIFAFUN OKANA YEKU OBARAYIRE YA OBINI AYE OLONU OMO TITUN LARIFUN LODIKU OYEKUN PELEKA ADIFAFUN ELEKUN OMO BARAYAN OKANA YEKU OYEKUN PELEKA EGGUN EFU OBARADARASE NI ELEKUN OBAYEKU LARA LARA LAYEBAISHE SHELERI OYEKUN PELEKA OKANA YEKU MODAWA AMOYARE MOYARE YOYOUN LEKUN ELEKUN OMO LERIFUN LEDIFUN.", "REZO: ODARA BI OSHA OYE AWO OSHAKUNODA, OMO OSHA TIRO OFIN TOKUN AGBA ENI OSHA EYE EKUN SHINAYAKUA BABA ERIN, EFUN KAFUN TOLE AYE, EKUN OBANI BOSHE OSUN KAFUN TOLE ILEKE AWO LAYE EKUN, NIYE BABA ERIN OKE ENIFA OSHA BABA OSUN ASHE ORI BEWA, BABA NILEFUN OSHA ORI AGBANI BOSHE BABANIFA OLORUN EFUN LOWA, ORUN LOWA, OSUN AYEGBE ENI OSHA BABA OLOFIN LOWA AYEGBE ENI OBOLOYO YEMAYA LANIRE SHANGO BI OSUN BABANI IRAWO OBATALA BABA IROKE BOWAO OMO ONI AYE OSHA IFA NI KAFEREFUN OBATALA, KAFEREFUN SHANGO, YEMAYA, OSUN, LODAFUN ORUNMILA.", "REZO: ADIFAFUN OKANA YEKUN AGRIA BLENIRE IFA EGGUN AGUANI LOKUN LERI FIFESHU LERI EGGUN OKUA AKUARI EGGUN FIFESHU AOBANI OLOKUN OBANIRE ALAKUARA YALE OGUANI IFA OLOKUN IFA KAFEREFUN OLOKUN Y AAYE.", "REZO: ODARA BI OSHA OYE AWO OSHAKUNODA, OMO OSHA TIRO OFIN TOKUN AGBA ENI OSHA EYE EKUN SHINAYAKUA BABA ERIN, EFUN KAFUN TOLE AYE, EKUN OBANI BOSHE OSUN KAFUN TOLE ILEKE AWO LAYE EKUN, NIYE BABA ERIN OKE ENIFA OSHA BABA OSUN ASHE ORI BEWA, BABA NILEFUN OSHA ORI AGBANIBOSHE BABANIFA OLORUN EFUN LOWA, ORUN LOWA, OSUN AYEGBE ENI OSHA BABA OLOFIN LOWA AYEGBE ENI OBOLOYO YEMAYA LANIRE SHANGO BI OSUN BABANI IRAWO OBATALA BABA IROKE BOWAO OMO ONI AYE OSHA IFA NI KAFEREFUN OBATALA, KAFEREFUN SHANGO, YEMAYA, OSUN, LODAFUN ORUNMILA."]}]$q$::jsonb),
(39,'ea518ca8c910043b5f3c7e23995a8309','078d0997c7daeb3a03a08d6a92a5aa0c',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ògúndá protege contra una muerte cercana. Un trabajo o una relación están por terminar a causa de pleitos emocionales. Pide cuidar la manera de hablar, porque una palabra descuidada puede destruir a la familia, y comportarse bien dentro de ella."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una relación o un trabajo está en riesgo por tensión y pleitos repetidos.", "Habla sin pensar y otros toman sus palabras como ofensa (relato de Òyè).", "Un desacuerdo familiar empieza a abrir distancia y conviene atenderlo pronto.", "Teme una pérdida grave que todavía se puede prevenir (verso de Ọ̀yẹ̀kú).", "Busca una vida más tranquila después de mucha lucha.", "Debe saber cuándo y cómo decir una verdad, sin callar por miedo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Pasar el día señalado sin que ocurra lo anunciado.", "Larga vida y felicidad.", "Que la conspiración contra él no se cumpla.", "Riqueza por saber hablar con cuidado."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva a la eliminación de los obstáculos. (Este Odu habla de evitar el conflicto para asegurar la buena fortuna).", "origen_id": "8ea6317394383dc58f083ef1"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Hablar sin cuidado y ofender sin querer.", "Faltas dentro de la familia que la pueden destruir.", "Pleitos que acaban con el trabajo o con la pareja."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "El final del ciclo lleva al conflicto. (Este Odu habla de un conflicto que lleva a un daño serio)", "origen_id": "938596bd594bfe18c670805f"}]}, {"titulo": "Enseñanza principal", "texto": "Si la pared no se abre, el lagarto no entra. Quien se sabe callar a tiempo no le da a nadie con qué usarlo en su contra. Ningún árbol alcanza el cielo: no es todavía la hora de nadie."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú-Egúntán ofrece protección contra una muerte inminente.", "origen_id": "0648932f5b3ffa3065ca2be5"}]}, {"titulo": "Relatos reunidos", "puntos": ["La muerte anunciada para cuatro días. Los adivinos consultaron para Ọ̀yẹ̀kú, a quien le habían anunciado la muerte en cuatro días. Le marcaron un carnero; cumplió. Llegó el día señalado y no pasó nada; desde entonces no se conoce el día de la muerte de Ọ̀yẹ̀kú.", "La pared que se abre. 'Por donde la pared se abre entra el viento.' Así consultaron para Ọ̀yè, hermano de Ojóòmódá, y le advirtieron que cuidara su manera descuidada de hablar: 'Si la pared no se abre, el lagarto no entra; cuida que tus palabras no destruyan a tu familia'. Al escucharse a sí mismo, ofreció, y su vida mejoró: 'Mi manera cuidadosa de hablar me hará rico'.", "El árbol que no toca el cielo. Ọ̀yè preguntó si viviría mucho y sería feliz. Le dijeron que sí, que ofreciera un chivo viejo, y que muchos conspirarían contra él pero su plan no se cumpliría. Ofreció y dijo: 'Todavía no es la hora de mi fin; ningún árbol podrá tocar el cielo'."], "pasajes": [{"titulo": "Verso 39.1", "texto": "Eni l'ojà Ewọn,\nọla lojà Owe:\nadivinaron Ifá para Ọ̀yẹ̀kú\nde quien se predijo la muerte\nen cuatro días.\nLe fue aconsejado hacer sacrificio:\nun carnero.\nEl escuchó y realizó el sacrificio.\nEl día predicho no pasa nada,\nel día de la muerte de Ọ̀yẹ̀kú no se conoce.", "origen_id": "0926a2715466837ac6f35180"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le pide que sacrifique para que su vida le sea\nplacentera y cordial.\nDeberá cuidarse de sus expresiones, para que no le\ncataloguen como un mal hablado o mal educado, al\nigual que ofenda sin desearlo.\nIfá le pide que se comporte correctamente dentro\ndel círculo familiar, para que las faltas cometidas no\ndestruyan la familia. Además sacrificará para larga\nvida.\n\n             Níbi ti ògirí gbé lanu\n\n          Ibè lèfúùfùú gbé wợlé\n               A dífá fún Òyè\n         Èyí tíí şègbón Ojóòmódá\n       Wón ní ó sợra fún òrò ní sísợ\n              Wón ní ìwợ Òyè\n              Bógiri ò bá lanu\n          Aláàmù ò ní kó sénú è\n               Wón ní sợra o\n        Kí òrò ó mó ba ẹbíl rẹ jẹ o\n       Bèèyàn ò ba sợ nňkan jade\n      Àwợn èèyàn ò níí fi mu olúwa è\n              Òyè ba só ẹnu è\n                 Òyè ba rúbợ\n                 Ayé yẹ Òyè\n        Ó ní níbi ti ògirí gbé lanu\n          Ibè lèfúùfùú gbé wợlé\n               A dífá fún Òyè\n         Èyí tíí şègbón Ojóòmódá\n       Wón ní ó sợra fún òrò ní sísợ\n                     Òrò\n          Òrò ní n ó sợ là láyé o\n                     Òrò\n\nEs aquí donde la pared se abre en crujidos y\nrajaduras\nY por ellas entra la Brisa\nProfetizó Ifá para Òyè, hermano de Ojóòmódá\nLe dijeron de cuidarse en sus expresiones y forma\ndescuidada al hablar\nLe dijeron: - ¡Òyè, si la pared no se abre, los\nlagartos no podrán entrar! – Sé cuidadoso, para que\ntus pronunciamientos, no destruyan a tú familia - Si\nuno es capaz de refrenarse en un señalamiento\npersonal, nadie podrá usarlo contrariamente\n\nCuando él mismo se escuchó, ofreció el sacrificio y\nsu vida mejoró\nEs aquí donde la pared se abre en crujidos y\nrajaduras\nY por ellas entra la Brisa\nProfetizó Ifá para Òyè, hermano de Ojóòmódá\nLe dijeron de cuidarse en sus expresiones y forma\ndescuidada al hablar\nExpresiones y discursos\nMi forma de hablar cuidadosa, me harán rico en la\nvida\nExpresiones y discursos\n\n     Ìtò ògànjó níí múlè sợ kùtùkùtù\n               A dífá fún Òyè\n         Òyè tíí şègbón Ojóòmódá\n             Inú òún dùn láyé?\n                Èmí òún gùn?\n               Ó dáa fún òun?\n             Wón ní ayé ó yẹ ẹ\n         Wón ní girìpá òrúkợ lẹbợ\n    Wón ní wón ń dábàá ti ò dáa lórí è\n                 Wón nírợ ní\n       Wón ní àbá náà ò níí şe lórí è\n               Wón ní kó rúbợ\n                 Ó bá rúbợ\n   Ó ní Ìtò ògànjó níí múlè sợ kùtùkùtù\n               A dífá fún Òyè\n         Òyè tíí şègbón Ojóòmódá\n             Wón ní kó sá káalè\n              Kó jàre kó şẹbợ\n                Ó gbébợ ńbè\n                   Ó rúbợ\n            Ợjợ ti mo dá ò pé o\n\n                  Àkànmànà\n              Nígi ó móợ kànrun\n                  Àkànmànà\n           Ợjợ ti mo dá ò pé láíláí\n                  Àkànmànà\n              Nígi ó móợ kànrun\n                  Àkànmànà\n           Igí ò níí le kànrun láíláí\n\nEs el orine (micción) de la Medianoche que produce\ngrandes burbujas en la Tierra\nLanzó Ifá para Òyè, el hermano de Ojóòmódá\n¿Seré longevo, y feliz? ¿La vida me será agraciada?\nSe preguntó él\nTendrás todas esas cosas ellos le dijeron Debía\nsacrificar un añejo chivo\nMuchas personas conspirarán contra tí, pero nunca\nese plan se materializará si no olvidas ofrecer la\nofrenda aconsejada\nÉl sacrificó y dijo que: Es el orine (micción) de la\nMedianoche que produce grandes burbujas en la\nTierra\nLanzó Ifá para Òyè, el hermano de Ojóòmódá\nLe pidieron que cuidase de la Tierra Él escuchó y\nsacrificó\nAún no es el momento de que yo pre-ordene mi fin\nÀkànmànà\nEs la manera con la que los árboles tratan de tocar\nel Cielo\nÀkànmànà\nNingún árbol podrá tocar el Cielo", "origen_id": "44466c345852bee3da510964"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku-Eguntan ofrece protección contra una inminente muerte.\n           WO - Un empleo o relación está en peligro de finalizar por batallas\n                                                                    emocionales.\n\n\n39.1 · Eni l´oja Ewon, Ola l´oja Owe adivinó Ifá para Oyeku de quien\n                  se predijo la muerte en 4 días, él fue advertido para ofrecer el\n            sacrificio. Ebo: 1 carnero. El atendió el aviso y realizó el sacrificio.\n            El día predecido no llega a pasar nada, el motín acerca de la muerte\n                                                                 no se materializó.", "origen_id": "436d2e10eaf8e1c3d5bff986"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀yẹ̀kú: un carnero.", "Ọ̀yè (larga vida): un chivo viejo.", "Ọ̀yè (palabra): ofrenda para cuidar lo que dice."], "pasajes": [{"titulo": "Ofrenda en el verso 39.1", "texto": "Eni l'ojà Ewọn,\nọla lojà Owe:\nadivinaron Ifá para Ọ̀yẹ̀kú\nde quien se predijo la muerte\nen cuatro días.\nLe fue aconsejado hacer sacrificio:\nun carnero.\nEl escuchó y realizó el sacrificio.\nEl día predicho no pasa nada,\nel día de la muerte de Ọ̀yẹ̀kú no se conoce.", "origen_id": "7514df0511d75866cc9fbace"}]}, {"titulo": "Relaciones espirituales", "texto": "La familia es el espacio que se cuida con la palabra. Ikú, la muerte, pasa de largo ante quien ofreció."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Carnero, chivo viejo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 39.1 (yorùbá): Eni l'qjà Ewọn, / Ờla lọjà Owe: / li o difá f'Ọ̀yẹ̀kú / tii wọn nfi qjọ ikú rẹ / da piriti (ojẹ mẹrin). / Wọ̀n niki ó rú / Agbo kan / Ó gbọ̀ ó rú. / Qjọ ti wọn nda koipe / Imọ ikú awo koijọ'ra.", "REZO: OYEKUN TEKUNDA LOBINA NASA OYO OPA OTA KUKU WORA ADIFAFUN ABEREGUE LUBA OMO ORUNMILA KOBA OGGUN TITIWO BEBERE OLOTURA AGOGO LABINIKU TENIYE EWE OGUMA IFA NI OTA OJOJO EBBO ADIE, EKU, EYA, OWO TETEBORU.", "REZO: OYEKUN OGUNDA INTORI ARAYE KAFEREFUN OSHUN OLOFIN ESHU AKATA BOMI OMI AMUOKOTE MOSU SOYO OSHE LOTI LOSE AUN OTA ORUNMILA OLOFIN DIRE LOFA ORUNMILA.", "REZO: INTORI EYELE NI LETE AWO IBASEN BONO NO LOLO ERO LOMBA TUMBA AWO RERE NI ADIFAFUN TOBO SHIWI IFA OWUNKO ODDUNDE ASHO TELEDI INTORI OKUNI ILE LONA, LODAFUN OBATALA.", "REZO: INTORI ARAYE EYELE LEBO INTORI IGUABOBO AGUTAN LEBO ORUNMILA IFAYOKO LODAFUN EGGUN AYAKA.", "REZO: ORUNMILA ADIFAYOKO OGGUN AYAKA.", "REZO: APATO MABIRAN AQUITE MABIBELLI EFIN ABILOGUE SHAUNDATI LARE ILISHU RANIPO ARDE MAMAKE BABA SHIKE IGUIORIBE OLLOKU TEGUNDA LOBINA NASA TITI GUO LELERE ELETURA AGOGO LEBO LEOBABEBINKA TENULLA OGUOAGUMA IFANI OTA OFOFO LEBO OKU EYA.", "REZO: OYEKUN OGUNDA INTORI ARAYE KAFEREFUN OSHUN OLOFIN ESHU AKATA BOMI OMI AMUOKOTE MOSU SOYO OSHE LOTI LOSE AUN OTA ORUNMILA OLOFIN DIRE LOFA ORUNMILA.", "REZO: INTORI EYELE NI LETE AWO IBASEN BONO NO LOLO ERO LOMBA TUMBA AWO RERE NI ADIFAFUN TOBO SHIWI IFA OWUNKO ODDUNDE ASHO TELEDI INTORI OKUNI ILE LONA, LODAFUN OBATALA."]}]$q$::jsonb),
(40,'85793afab0119310fdcc9aeb164b0011','7d5053ecef86fa07e7cbd7a6e40b831d',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀sá aconseja negociar, ceder y pactar antes de perderlo todo. Señala pleitos de pareja, de familia y entre compañeros que se resuelven con diplomacia. Ifá le desea victoria: ninguna guerra lo detendrá si ofrece, y las fortunas entrarán bajo su techo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Dos personas o grupos se pelean algo que podrían repartir (relato del elefante entre Olijede y Onitiyo).", "Una relación de pareja, familiar o de trabajo se volvió conflictiva y necesita negociarse.", "Teme perderlo todo por no ceder a tiempo.", "Busca prosperidad y continuidad familiar honrando a sus ancestros.", "Siente oposición y quiere superarla (relato de Ọ̀rúnmìlà).", "Puede arrepentirse de algo que sigue posponiendo (relato de la gente de Ogere-egbe)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Victoria; ninguna guerra lo detiene.", "Acabar con los pleitos usando la palabra.", "Que las fortunas entren bajo su techo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la abundancia. (Este Odu habla de honrar a los ancestros para asegurar la abundancia).", "origen_id": "1ab4bbcc54e2512970dd4b01"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Pelear por algo que se puede repartir, hasta que se echa a perder.", "Arrepentirse por no ofrecer a tiempo.", "Creer que lo propio no se puede perder y descuidarlo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la inestabilidad mental. (Este Odu habla del fracaso para honrar a los ancestros llevando a la pobreza).", "origen_id": "9cd5dbd18fda2105eb7ced78"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que se pelea se pudre. El elefante muerto entre dos granjas se echó a perder mientras discutían, y al final Èṣù repartió el marfil. Ọ̀rúnmìlà acabó con las guerras con su estera: con la conversación."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú Gasá sugiere que es mejor negociar una solución (hacer concesiones, negociar, pactar) para evitar la pérdida total.", "origen_id": "9dc1b5d8e02da24d9fe7e416"}]}, {"titulo": "Relatos reunidos", "puntos": ["La gente de Ogere-egbe. Ile-ẹwu-ab'ojuṣokoto consultó para la gente de Ogere-egbe y les marcó una jícara de vino de palma, cuatro palomas y 800 cauríes para no tener que lamentarse en la vida. No quisieron ofrecer.", "El elefante entre dos granjas. Un elefante murió en la granja de Olijede, pero la cola le cayó en la granja de Onitiyo. Los de Onitiyo dijeron que era suyo y los de Olijede también. Un elefante muerto entre dos granjas anuncia guerra. Les marcaron un chivo y 12,000 cauríes para que no pelearan por algo que se podía repartir. Tres meses después hicieron la ofrenda que habían ignorado; para entonces el elefante ya se había podrido. Èṣù repartió el marfil entre los dos y les aconsejó dejar de pelear.", "Ọ̀rúnmìlà acaba las guerras con su estera. El pájaro vuela moviendo las alas arriba y abajo y toca la tierra con el ala derecha, con un sonido como el de una azada o un machete al caer. Así consultaron para Ọ̀rúnmìlà, contra quien habían levantado una guerra. Le dijeron que aplastaría todas las guerras con su estera, con la conversación. Ofreció y venció toda confrontación, y dijo que nunca dejaría que la gente del mundo fuera detenida por la guerra mientras hiciera las ofrendas de Ifá.", "Kúkúnrú, el agua de la lluvia. Ifá consultó para Kúkúnrú, cuyos hijos eran todos hermosos, y le pidió ofrecer para que tuvieran lugares dichosos donde vivir y nadie les cerrara el camino. Kúkúnrú dijo que, una vez que se tienen hijos, nadie les puede negar la entrada a la vida, y no ofreció. Kúkúnrú es el agua que escurre de la lluvia: nadie la deja entrar en su casa, y si entra la sacan. Ya tarde, lloró: 'Ifá, no permitas que se pierda la fortuna'."], "pasajes": [{"titulo": "Verso 40.1", "texto": "Ile-ẹwu-ab'ojuṣokoto\nadivinó Ifá para la gente de Ogere-egbe.\nLes fue aconsejado hacer sacrificio,\npara evitarles expresiones de lamento en la vida\n(evitarles pesar, arrepentimientos).\nUna igbá de vino de palma,\ncuatro palomas y 800 cowries.\nEllos rechazaron ejecutar el sacrificio.", "origen_id": "e054c2a1a02513ae94b6c739"}, {"titulo": "Verso 40.2", "texto": "Un elefante murió en la granja de Olijede,\npero su cola cayó sobre la granja de Onitiyo.\nLos pobladores del pueblo de Onitiyo\ndijeron que el elefante les pertenecia.\nLos pobladores del pueblo de Olijede\ndijeron que el elefante les pertenecia.\nUn elefante que muere entre los límites\nde dos granjas simboliza una guerra.\nLes fue aconsejado hacer sacrificio\npara que ellos no disputaran\nsobre algo que se podía administrar (repartir):\nun chivo y 12.000 cowries deberían ser sacrificados.\nDespués de 3 meses,\nellos realizaron el sacrificio\nque había sido ignorado.\nEl elefante se había podrido.\nEntonces Èṣú dividió el marfil\nentre las dos partes\ny les aconsejó que desistieran de luchar.", "origen_id": "278416fca1f466eb7c75c821"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que esta persona deberá sacrificar para ser\nvictorioso en la vida. Ifá le desea lo mejor y que\nninguna guerra le detendrá. El sacrificio es un viejo\nchivo. También sacrificará para que las buenas\nfortunas entren bajo su tejado.\n\n   Ệyẹ kan ní ń fò I léérémi léérémi\n            Ó fapá òtún nalè\n      Ó ró gbợrangandan bí ợkợ\n   Ệyẹ kan ní ń fò I léérémi léérémi\n            Ó fapá òtún nalè\n      Ó ró gbợrangandan bí àdá\n      Ogun ó dúó ní kòtò odò mó\n    Ogun dúó ní gegele sáále sáále\n          A dífá fún Òrúnmìlà\n         Wón ní kí bàbá ó rúbợ\n    Kó le fÀjìjà wó wợn mólè fíínfín\nÒrúnmìlà ní ń bèèrè pé ogun tí ợn gbé ti\n                 òun yìí\n             Òún şẹgún ńbè\n  Wón ní gbogbo ogun òhún ní ó run\n Wón ní Àjìjà ợwóò rè ni ó móợ fi nalè\n           Òrúnmìlà bá rúbợ\n    Òrúnmìlà bá lé gbogbo ogun lợ\n              Ayé ba ń dára\n         N ní wá ń jó ní wá ń yò\n        Ní ń yin àwợn Babaláwo\n        Àwợn Babaláwo ń yin Ifá\n   Ó ní béè làwợn Babaláwo tòún wí\n   Ệyẹ kan ní ń fò I léérémi léérémi\n            Ó fapá òtún nalè\n      Ó ró gbợrangandan bí ợkợ\n   Ệyẹ kan ní ń fò I léérémi léérémi\n            Ó fapá òtún nalè\n\n        Ó ró gbợrangandan bí àdá\n       Ogun ó dúó ní kòtò odò mó\n      Ogun dúó ní gegele sáále sáále\n            A dífá fún Òrúnmìlà\n           Wón ní kí bàbá ó rúbợ\n      Kó le fÀjìjà wó wợn mólè fíínfín\n              Bàbá gbébợ ńbè\n                    Ó rúbợ\n         Mo ló fÀjìjà wó wợn mólè\n               Gbợrangandan\n        Bàbá ti fÀjìjà wógun mólè\n               Gbợrangandan\n            Àjìjà tí wógun mólè\n               Gbợrangandan\n\nEl pájaro vuela, moviendo sus alas metódicamente\narriba y abajo\nUsó su ala derecha para tocar la tierra\nY se escuchó un sonido campaneante, igual que el\nde la caída de una Azada\nEl pájaro vuela, moviendo sus alas metódicamente\narriba y abajo\nUsó su ala derecha para tocar la tierra\nY se escuchó un sonido campaneante, igual que el\nde la caída de un\nMachete\nLa guerra no se quedará de nuevo en las orillas de\nun río\nLa guerra no se quedará de nuevo insolemnemente\nen el tope de una Colina\nAdivinaron para Òrúnmìlà a quien se le pidió que\nsacrificara\nPara que la guerra que habían creado contra él, la\npudiese     aplacar   con   sus      bellas charlas\n(conversación en la estera)\n\n¿Triunfaré? Él preguntó\nTodas las guerras las aplastarás a tiempo, ellos le\ndijeron\nY que siempre usará sus esteras (charlas) para\ngolpear o batir la tierra\nÒrúnmìlà sacrificó y venció toda confrontación\nfutura\nÒrúnmìlà dijo que nunca permitiría que las personas\ndel mundo fuesen detenidas por motivos de la\nguerra, siempre que ellos y solo ellos performaran\nlos sacrificios prescritos por Ifá\nLa vida comenzó a ser inmejorable Se acabaron las\nguerras\nÉl cantó y se regocijó, alabando a sus babaláwos\nEllos alabaron a Ifá\nEl pájaro vuela, moviendo sus alas metódicamente\narriba y abajo\nUsó su ala derecha para tocar la tierra\nY se escuchó un sonido campaneante, igual que el\nde la caída de una Azada\nEl pájaro vuela, moviendo sus alas metódicamente\narriba y abajo\nUsó su ala derecha para tocar la tierra\nY se escuchó un sonido campaneante, igual que el\nde la caída de un\nMachete\nLa guerra no se quedará de nuevo en las orillas de\nun río\nLa guerra no se quedará de nuevo insolemnemente\nen el tope de una Colina\nAdivinaron para Òrúnmìlà a quien se le pidió que\nsacrificara\nAl Padre se le ha pedido sacrificar y así lo ha hecho\nYo digo que él ha usado su estera para acabar con\nlas guerras completamente\nGbợrangandan (golpe seco)\nEl Padre ha aplastado las guerras\n\nGbợrangandan (golpe seco)\nLa estera lo ha aplastado todo\n\n              Atéérété orí àsá\n              Ệni ó gun àsá yò\n             A dífá fún Kúkúnrú\n       Ợmợ abímợ ní pupa ní pupa\n    Ó bí gbogbo ợmợ è ti ợn rí béléńjé\nWón ní ó rúbợ bí àwợn ợmợ è ó şe wợ ilée\n                     rere\n             Kí òna ó là fún wợn\n        Tí ire ó móợ şe gẹgẹẹ wợn\n       Kí wón ó mó díí òná fún wợn\n  Kúkúnrú ní “Tóun tí bí ợmợ lợpợlợpợ”\n  “Ó di dandan kí wón ó móợ ráyè wợlè\n               ńbii wón bá dé”\nÀ á séé mợ Kúkúnrú ợmợ abímợ ní pupa?\n              N làá pé Àgbàrà\n        Ệníkan ò jẹ jẹ ó wợ inú ilé\n Bí Àgbàrà bá ti lóun ó kòólé èèyàn báyìí\n         Wón ó móợ pé kó móợ lợ\n                  Kó móợ lợ\n                Yóó bá móợ lợ\nÀyìn ẹyìn ní Àgbàrà ń yin àwợn Babaláwo\n                       è\n            Ó ní Atéérété orí àsá\n              Ệni ó gun àsá yò\n             A dífá fún Kúkúnrú\n       Ợmợ abímợ ní pupa ní pupa\nKúkúnrú Ợmợ abímợ ní pupa ní pupa làá\n                   pàgbàrà\n         Mó jèé ire ó nù mi dákun\n                  Èlààsòdè\n\n        Ifá mó jèé ire ó nù mi dákun\n                  Èlààsòdè\n\nAtéérété orí àsá\nỆni ó gun àsá yò\nLanzó Ifá para Kúkúnrú\nEl hijo de abímợ ní pupa ní pupa\nTodos sus hijos eran de buenas complexiones físicas\ny hermosas\nSe le pidió sacrificar, para que todos sus hijos\ntuviesen lugares dichosos donde vivir, así que las\ncosas le fueran buenas, y sus senderos se les fueran\nabiertos y los hombres no cerrarán su buen destino\nKúkúnrú dijo: - “Una vez que se tienen hijos, no se\nles puede negar su entrada en la vida”- No sacrificó\n¿Cómo identificamos a Kúkúnrú?\nEs el nombre alternativo o sobrenombre que se le\nda al Agua que se escurre en la Lluvia\nNadie le permite a la Lluvia que entre en sus\nhogares Una vez entra, se le pide o se le saca\nafuera\nKúkúnrú, entonces invocó a sus babaláwos, pero ya\nera tarde\nCon gran pesar y lágrimas, exclamó: Atéérété orí\nàsá\nỆni ó gun àsá yò\nLanzó Ifá para Kúkúnrú, nombre dado al Agua que\nse escurre en la Lluvia\nEl hijo de abímợ ní pupa ní pupa,\nNo permitas que se pierda la fortuna, por favor\nÈlààsòdè\nIfá, no permitas que se pierda la fortuna, por favor\nÈlààsòdè", "origen_id": "69c7aa8c876fea50d2752ef1"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku Gasa sugiere compromiso para evitar pérdida total.\n            Wo – Oyeku Gasa a menudo denota sociedad o relación conflictiva.\n\n\n40.1 · Ile-ewu-ab´ojusokoto adivnó Ifá para la gente de Ogere-egbe.\n        A ellos se les pidió ofrecer sacrificio para evitar expresiones de pesar\n        en la vida. Ebo: 1 botella de vino de palma, 4 palomas y 800 cowrie.\n                                           Ello rechazaron ejecutar el sacrificio.\n\n\n40.2 · Un elefante murió en la granja de Olijede, pero su rabo llego a\n\n               descansar en la granja de Onitiyo. Los pobladores del pueblo de\n              Onitiyo dijeron que el elefante les pertenecía. Los pobladores del\n\npueblo de Olijede dijeron que el elefante les pertenecía. El elefante\n          que murió en 2 granjas administradas simbolizaba una guerra. Ellos\n              fueron avisados para ofrecer sacrificios porque ellos pelearían o\n                 lucharían por algo. Ebo: 1 chivo, 12.000 cowrie deberían ser\n            sacrificados. Después de 3 meses, ellos realizaron el sacrificio, el\n          cual había sido ignorado. El elefante se había podrido, entonces Eşu\n           dividió el marfil entre las 2 partes y les aconsejó que desistieran de\n                                                                         luchar.", "origen_id": "f923b636d8bb3d70da6bcf90"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogere-egbe (rechazado): una jícara de vino de palma, cuatro palomas y 800 cauríes.", "Olijede y Onitiyo: un chivo y 12,000 cauríes.", "Ọ̀rúnmìlà y para la victoria: un chivo viejo.", "Kúkúnrú (rechazado): ofrenda para el camino de los hijos."], "pasajes": [{"titulo": "Ofrenda en el verso 40.1", "texto": "Ile-ẹwu-ab'ojuṣokoto\nadivinó Ifá para la gente de Ogere-egbe.\nLes fue aconsejado hacer sacrificio,\npara evitarles expresiones de lamento en la vida\n(evitarles pesar, arrepentimientos).\nUna igbá de vino de palma,\ncuatro palomas y 800 cowries.\nEllos rechazaron ejecutar el sacrificio.", "origen_id": "0693da5c6ec7e7d622fbfe9d"}, {"titulo": "Ofrenda en el verso 40.2", "texto": "Un elefante murió en la granja de Olijede,\npero su cola cayó sobre la granja de Onitiyo.\nLos pobladores del pueblo de Onitiyo\ndijeron que el elefante les pertenecia.\nLos pobladores del pueblo de Olijede\ndijeron que el elefante les pertenecia.\nUn elefante que muere entre los límites\nde dos granjas simboliza una guerra.\nLes fue aconsejado hacer sacrificio\npara que ellos no disputaran\nsobre algo que se podía administrar (repartir):\nun chivo y 12.000 cowries deberían ser sacrificados.\nDespués de 3 meses,\nellos realizaron el sacrificio\nque había sido ignorado.\nEl elefante se había podrido.\nEntonces Èṣú dividió el marfil\nentre las dos partes\ny les aconsejó que desistieran de luchar.", "origen_id": "a5421497d81cf5724fbdc4c0"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù reparte lo que se disputa y aconseja la paz. Ọ̀rúnmìlà vence con la palabra, no con las armas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Vino de palma, marfil, estera, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 40.1 (yorùbá): Ile-ẹwu-ab'ojuṣokoto / li o difá fún wọn l'Ogere-egbe. / A niki wọ̀n wa rúbọ, / kiwọn ma baa ta'hun l'ayé: / Igbá iregbe-ògurọ̀, / ẹyẹlé mẹrin ati ẹgbèrin owó. / Wọ̀n kọ wọn ko rú.", "Verso 40.2 (yorùbá): Erin kus'oko Olijede, / Of'irusoko Onitiyo. / Àwọn ara ilu Onitiyo / ni àwọn li o ni Erin. / Àwon ara Olijede / ni àwọn li o ni Erin. / Erin ti o kus'oko Ọloja Méjì, ogun ni. / A niki wọn rúbọ / nitoripe wọn maa jüjadu lori / ohun kan bayi. / Öbúkọ ati ẹgbàáfà owó ni ebọ. / Lẹhin oṣu méta, / wọn wa rúbọ ti wọn kosilẹ. / Erin ti ra. / Eṣú wa pin ehin Erin naa / fún wọn li okookan / O niki ẹ ma jà mọ o.", "REZO: OYEKUN BIKUSA KUKUTE KUKI ADIFAFUN OGGUN ATI OSHOSI. DARIKO OYEKUN SA KAFEREFUN OYA, ORUNMILA ADIFAYOKO ALADAFA AWO ALADAFA OTOKE TOYO INA MEYI INYA LOWO ODSA NITO LOSUSHU KOMANDI KOLILU EDAN ATOKE TOYO ORUGBO AIKORDIE, AKUKO PUPUA ELEBO.", "REZO: KUKUTE KUKADIFAFUN OGGUN Y OSHOSI DARICO YOKUNSA KAFEREFUN OYA ORUNMILA ADIFAYOKO ALADAFA OWO ALADAFA ATOKEOYO OÑA MEYI INYA LOGUO ASONITO LASUSHU KOMANDIO LILU EDAN OLOKU ATOQUE TELLO ORUBO AIKORDIE AKOKO PUPUA.", "REZO: AGOI OMODE AZOWANO OMOLITASA TASA NIWA GUDU UNLO AZON MALITE OBINI ODARA OBEYAWO OKUNI OPOLOPO OWO ALAGBA AGBA ODARA NANU IYA BOGBO AZOWANU, ENIMO OTERI BASHO KUKUTONI LE ZANGBETO DAJONI NILE BABA EGUNGUN ORO AWO IKOFA AGOI ARIKU LODAFUN ORUNMILA, MAFEREFUN AZOWANU IKU.", "SUYERE: AGOI WIYEBO AGOI KOIYEWO BABA EGUNGUN, ONIFA ARIKU."]}]$q$::jsonb),
(41,'135859de9ed4675af80aa65a04e70022','ef83036198880a975966221b2cdb16a5',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìká habla de compartir las ofrendas con Èṣù y con las demás divinidades, porque eso garantiza la seguridad. La persona necesita poner más atención a lo espiritual y menos al dinero. Debe ofrecer lo que su Orí acepte para que lo bueno llegue a sus manos, y no envidiar el éxito de otros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tan metido en ganar dinero que descuidó otras responsabilidades o su vida espiritual.", "Se compara con alguien y la envidia daña la relación (relato de Ọ̀yẹ̀kú y Èká).", "Siente que no alcanza lo que esperaba de su destino (relato de Sàniyàn y Orí).", "Necesita consejo de sus mayores o ancestros antes de entrar en un conflicto.", "Una lectura mal interpretada puede traer daño (relato de Owá).", "Teme pérdidas y busca firmeza sin rebajarse ni dañar a otros."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Clientes, dinero y sabiduría para quien trabaja con honestidad.", "Ser salvado de las aguas por los gemelos.", "Una vida hermosa cuando se ofrece a la propia cabeza."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la afirmación misma. (Este Odu habla de la necesidad de buscar guianza espiritual de los ancestros para evitar el conflicto).", "origen_id": "077cdece7abbbb9c2ee0f0f1"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Envidiar al que prospera y querer hacerle daño.", "Interpretar mal una consulta y pagar las consecuencias.", "Descuidar lo espiritual por el dinero.", "Cobrar de más por una ofrenda."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la denigración misma. (Este Odu habla de la posibilidad de perturbación debido a la falta de protección espiritual).", "origen_id": "e339bfbc34bb0c5c9989d9ff"}]}, {"titulo": "Enseñanza principal", "texto": "Solo Ọ̀rúnmìlà controla el destino a través de la ofrenda. Quien escoge su destino sin incluir la ofrenda escoge mal. Y el honesto prospera mientras el tramposo se queda solo con su rencor."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ğyẹkúbẹká habla de la necesidad de que los Babaláwos compartan sus sacrificios con Eṣú y otras divinidades. Los sacrificios garantizan su seguridad.", "origen_id": "566441a5b19988ba7ce29a21"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀yẹ̀kú, Èká y el balsero. Gbingbin erẹkẹ consultó para Ọ̀yẹ̀kú y para Èká, una rama, y les pidió ofrecer juntos dos gallinas, maíz y 3,200 cauríes. Ọ̀yẹ̀kú no ofreció. Los dos se fueron de viaje de adivinación: a Èká le fue bien y a Ọ̀yẹ̀kú no. Al regresar llegaron al cruce del río; Ọ̀yẹ̀kú llegó primero y le pagó al balsero para que tirara a Èká al agua. El mono (Ẹdùn) fue quien rescató a Èká: el agua nunca se lleva al cangrejo.", "Cómo Èṣù recibe la primera porción. Ọ̀yẹ̀kú y Èká consultaron para Owá, que preguntaba por las mujeres estériles de su casa. Interpretaron mal la consulta, y Owá los mató a los dos en un cruce de caminos. Kokofakokoyẹrẹ, que es Èṣù Ọ̀dàrà, bajó del cielo, arrancó una hoja, se la frotó en los ojos y en la cabeza, y cantando los levantó. Los llevó con Owá, y esta vez le dijeron bien: lo que quería era que sus mujeres quedaran embarazadas, y si no ofrecía ese mismo día moriría. Owá ofreció. Repartieron los materiales y le dieron a Èṣù su parte. Èṣù dijo que no sabía cuánto sufrían los babaláwo, que seguiría ayudándolos, pero que en adelante él tomaría la primera porción de toda ofrenda. Desde ese día los babaláwo comparten con Èṣù lo que se ofrece.", "Sàniyàn y su destino. El buitre se posa en lo alto y desde ahí ve la ciudad y el bosque. Así consultaron para Sàniyàn, esclavo del destino en el cielo. Cada quien escoge lo que será al venir del cielo a la tierra, y él preguntó qué debía hacer. Le dijeron que solo Ọ̀rúnmìlà controla el destino a través de la ofrenda, y que cualquier destino escogido sin ofrenda sale mal. Le mandaron ofrecer a su cabeza. Lo hizo y su vida se volvió hermosa.", "Ìká el honesto y Ọ̀yè el tramposo. Ọ̀yè fue a ejercer la adivinación en la ciudad de Ìká, donde Ìká ya trabajaba desde hacía tiempo. Ìká era honesto: si una ofrenda costaba ocho cauríes, cobraba ocho. Ọ̀yè mentía, y todo lo que hacía le salía mal. Ìká se hizo muy rico en clientes, dinero y sabiduría, y Ọ̀yè se llenó de rencor. Un día Ọ̀yè retiró el tronco que servía de puente, esperando que la corriente arrastrara a Ìká para quedarse con su dinero. Pero Ìká, al que también llamaban Oníkàá, había ofrecido muchas mazorcas de maíz a los gemelos, que lo habían hecho rico; cuando lo vieron ahogándose, se echaron al agua y lo sacaron con vida. Canto: 'No dejes que el príncipe de los babaláwo se ahogue en el agua del odio'."], "pasajes": [{"titulo": "Verso 41.1", "texto": "Gbingbin erẹkẹ el adivino de la orilla del río\nadivinó Ifá para Ọ̀yẹ̀kú,\ntambién adivinó Ifá para un Èká (una rama).\nLes fue aconsejado hacer sacrificios juntos:\ndos gallinas, maíz\ny 3200 cowries.\nỌ̀yẹ̀kú no realizó el sacrificio.", "comentario": "Ambos Ọ̀yẹ̀kú y Èká (una rama) fueron a un viaje de adivinación. Éká tuvo éxito en las adivinaciones, pero Ọ̀yẹ̀kú no tuvo éxito. Eká dijo: \"vamos a casa\". Cuando ellos estaban regresando, llegaron a donde el balsero cruza el río. Ọ̀yẹ̀kú, fue el primero en llegar allí y le pidió al balsero que lo ayudara a lanzar a Éká al río. La primera persona le pagó al balsero 2.000 cowries. La segunda persona le pagó al balsero 2.000 cowries. ¿quién ordenó que Erinwo Ifé fuera lanzado al agua?. El agua nunca se llevará al cangrejo (akon). Podría nadar hasta sitio seguro. Ọ̀yẹ̀kú instigó al balsero a soltar a Eká en el agua. Edùn (el mono) fue el que rescató a Ẹ̀ká.", "origen_id": "9706bd987b8e9b90e2a5b65d"}, {"titulo": "Verso 41.2", "texto": "Aderomokun el adivino del pueblo de ljoṣa,\nAdebori ol adivina del pueblo (gba\nKokofakokpyerg-o-bawon-pin-eru-\nl'ogboogba-Ọrun-niitil-wa\nes el nombre dado a Éṣú-Ôdàrà.", "comentario": "Ọ̀yẹ̀kú con Ẹká ambos adivinaron Ifá para Owá, quien usó cinco cowries para consultar sobre la salud de las mujeres estériles de la casa. Debido a que ellos fallaron en la interpretación correcta de la adivinación, Owá los mató a ambos en un cruce de caminos.\nKokofakokoyẹrẹ bajó al lugar desde el cielo. Él arrancó una hoja y frotó la misma en los ojos y cabezas de ellos. Él estaba cantando: Erirugale-gbende, gbende o, Gbende, Erirugale-gbende.\nEllos se levantaron. Él los escoltó a donde estaba Qwá. Ellos prescribieron el sacrificio para Owá por doscientos. Ellos dijeron: \"el propósito de tu consulta al oráculo de Ifá fue por la esterilidad de las mujeres de tu casa. \"Tú preferirías tenerlas embarazadas\". El fue advertido de ofrecer sacrificio ese día, si no quería morir ese día. Owá realizó el sacrificio. Ellos dividieron el material del sacrificio y dieron a Eṣú su propia porción. Èṣú dijo que no sabía que esto era por cómo los Babaláwos habían sufrido. Él tomó su porción y dijo que mejor está en el cielo y continuarán tomando la primera continuaría ayudándolos. Pero ellos porción fuera de todos los materiales del sacrificio. Èṣú fue bondadoso con los Babaláwos. Desde ese día, los Babaláwos han resuelto en compartir los beneficios del sacrificio con Éṣú.", "origen_id": "060a09fb4938717b993919a9"}, {"titulo": "Versos complementarios 1", "texto": "La persona deberá sacrificar todo lo que acepte su\nOrí, para que las buenas cosas lleguen a sus manos.\nSi las cosas deseadas por su Orí son ofrecidas, nada\nse perderá en su vida. No se podrá envidiar ni odiar\nel éxito de otras personas.\n\n          Gúnnugún bà lórùlé\n             Ojúu rẹ a tólé\n          Ojúu rẹ a móợ tóko\n           A dífá fún Sàniyàn\n       Sàniyàn tíí şẹrú ìpin lórun\n             Wón ní ó rúbợ\nOníkálùkù ló ti yan ìpin ti òún ó jèé ńnú\n                   ìyá è\n        Ńgbà ti ń bò látòde òrun\n           Ńgbà ó dé ilé ayé\n   Ń wá ń bèèrè pé bòo lòun ó ti şe\n         Wón ní: ¿O ò pé bóo ní?\n           Ệbợ lÒrúnmìlà mò\n Gbogbo nňkan téẹ bá yàn tí ò bá dáa\nÒun ní ó móợ báa yin fi ẹbợ gbé şójú ònà\n         Wón ní kó lòó bợ Orí è\n       Wón lórí ní móợó bá wợn já\n          Wón ó móợ pé Ifá ní\n               Ló bá rúbợ\n              Ayé yẹ wón\n             Wón bóójú ònà\n Wón ní béè làwợn Babaláwo tàwợn wí\n          Gúnnugún bà lórùlé\n             Ojúu rẹ a tólé\n          Ojúu rẹ a móợ tóko\n           A dífá fún Sàniyàn\n       Sàniyàn tíí şẹrú ìpin lórun\n\n          Wón ní ó sá káalè ó jàre\n                 Ệbợ ní ó şe\n                Wợn a nIfá ni\n                   Sàniyàn\n            bÓrí bá ń bá wợón jà\n                   Sàniyàn\n        Àşé Orí ní ń bá wợón jà láyé?\n\nEl Buitre se posa en la cima de un alto farallón\nAsí su vista cubre toda la extensa ciudad\nAsí su vista cubre todo el extenso bosque\nFue quien lanzó Ifá para Sàniyàn\nSàniyàn, el esclavo del destino en el Cielo, a quien\nse le dijo de ofrendar\nTodos escogen en lo que se convertirán en la\nduración de su etapa de la vida, cuando vienen de\nla ciudad del cielo a la tierra\nPero él pregunto: ¿Qué debía de hacer?\n¿Sabes qué? Le contestaron –\n- Solo Òrúnmìlà es quien controla el destino a través\nde los sacrificios -\n- No sabe hacerlo de otra manera, sino es con\nsacrificios –\nY es así, ya que cualquier otra cosa que el hombre\nescoja como destino, sino está incluido el sacrificio,\nestará erróneo\nSe le dijo a Sàniyàn, de ir y ofrecer sacrificio a su Orí\n(Cabeza)\n¿Es su propia cabeza, la que estará contra ellos?\nEllos dirán:\n- ¡No, es Ifá! –\nSàniyàn sacrificó y su vida se tornó hermosa y\nplacentera\nEllos retomaron los senderos seguros y perfectos y\ndijeron e hicieron lo que Ifá decía que hicieran y\ndijeran\n\nEl Buitre se posa en la cima de un alto farallón\nAsí su vista cubre toda la extensa ciudad\nAsí su vista cubre todo el extenso bosque\nFue quien lanzó Ifá para Sàniyàn\nSàniyàn, el esclavo del destino en el Cielo, a quien\nse le dijo de ofrendar\nSe le dijo de cuidar de la tierra y ofrendar Él lo hizo\n¿Es tú Orí quien está contra ti? ¿Ellos dicen que es\nIfá?\n¿Realmente están sus cabezas en contra de ellos en\nla Tierra?\n\n          Oníşe wợn ò fiseè lé rebi\n       Ìgbín ní ń ràjò tó filé è şẹrù rù\n                   Òjììjì lègè\n                   Òjììjì lògò\n          Òjììjì ò níí fOlúwa rè sílè\n          Kó sá wợ inú omi lòó gbé\n                A dífá fún Òyè\n          Níjó ti ń sawoó rode Ìká\n                 Wón ní ó rúbợ\n           Òyè ní sawoó rode Ìká\n        Ìká si tí ń bẹ níbè tí ń sawoó\n              Ńgbà Òyè dóhùún\n          Ó bèrè si Ifáá şe lóde Ìká\n           Ká si rí kéré ká jẹ kéré\n           Ká rí wòmù ká jẹ wòmù\n                  Ìká ń sòótó\n           Bí ẹbợ bá gba òké méjợ\n              Òké méjợ ní ó gbà\n            Şùgbón Òyè è é sòótó\n              Bó bá si şe nňkan\n                Nňkan rè ò dáa\n                Ìká ń lówó ńtiè\n\n    Ayé yẹ àwợn èèyàn nígbàa tÌká\n           Ìká wá ń bợ níjó kan\n              Inú bá ń bí Òyè\n        Oníşe wợn ò fiseè lé rebi\n     Ìgbín ní ń ràjò tó filé è şẹrù rù\n                  Òjììjì lègè\n                  Òjììjì lògò\n        Òjììjì ò níí fOlúwa rè sílè\n        Kó sá wợ inú omi lòó gbé\n               A dífá fún Òyè\n        Níjó ti ń sawoó rode Ìká\n        Kó sá wợnú omi lòó gbé\n               A dífá fún Òyè\n        Níjó ti ń sawoó rode Ìká\n Àwợn Èrùwà singín singín awo ẹbá ònà\n             A dífá fún Oníkàá\n            Èyí tí wón ní ó rúbợ\n            Kó lé baà sérí dele\n             Gbinňgbin yèkètè\n    Ệ má jèé kí Eríwo lósin ó béri lợ\n             Gbinňgbin yèkètè\n            Òyè bá fa afará yợ\n        Kí omí ó le gbé Oníkàá lợ\n           Kí wón ó le kó owó è\nŞùgbón nínú àwợn tí Oníkàá ti şoore fún\n                ni àwợn Ìbejì\n  Ti ợn tí ní kí wón ó rú ợpợlợpợ eríin\n      yangan kí wón ó lè rí oore şe\n          Àwợn Ìbejì si ti şe béè\n       Wón bá rí Oníkàá nínú omi\n       Tí ń şe Ìká mù ú, Ìká gbé e\n       Gbígbé ní wón gbé Oníkàá\n              Wón bá ń kigbe\n\n             Ệ mó jèé ó béri lợ\n             Gbinňgbin yèkètè\n          Ệ mó jéríwo lósin ó béri lợ\n             Gbinňgbin yèkètè\n\nLos malos perpetradores no dejarán su maldad en la\ncasa, para viajar a otra parte; seguirán siendo\nmalos\nLa Babosa (Caracol) viaja y lleva como carga su\npropia concha (casa)\nÒjììjì (sombra) lègè\nÒjììjì (sombra) lògò\nLa Sombra nunca dejará o se alejará de su sujeto,\npara vivir en profundas aguas\nLanzaron      adivinación   para    Òyè,    quien   se\naventuraba en sacerdocio en la ciudad de Ìká, y se\nle pidió sacrificar\nCuando Òyè llegó a la ciudad, halló que ya Ìká\npracticaba el sacerdocio (adivinación) desde hacía\nalgún tiempo\nY para quien ve poco y come poco, o come mucho\nen medio de lo mucho, Ìká era un hombre honesto\nSi un sacrificio costaba 8 cowríes, él solo aceptaba y\npedía esa cantidad\nPero Òyè era un mentiroso cada vez que emprendía\nuna función de adivinación o ceremonia de Ifá, sus\nasuntos resultaban inexactos\nÌká se convirtió en un hombre extremadamente rico\nen clientes, dinero y sabiduría\nUn día venía Ìká en el camino y se topó con Òyè que\nse enfureció al verle          Ìká dijo: Los malos\nperpetradores no dejarán su maldad en la casa,\npara viajar a otra parte; seguirán siendo malos\nLa Babosa (Caracol) viaja y lleva como carga su\npropia concha (casa)\nÒjììjì (sombra) lègè\nÒjììjì (sombra) lògò\n\nLa Sombra nunca dejará o se alejará de su sujeto,\npara vivir en profundas aguas\nLanzaron     adivinación    para   Òyè,   quien   se\naventuraba en sacerdocio en la ciudad de Ìká\nÈrùwà singín singín, adivino del borde del camino\nLanzó Ifá para Oníkàá, a quien se le había estado\ndiciendo que sacrificase para que regresara a su\nhogar de forma sana y segura\nGbinňgbin yèkètè\nNo dejes que el príncipe de los Babaláwos se\nahogue en el agua\nGbinňgbin yèkètè\nÒyè quitó el puente de madera, para que el río se\nllevara a Ìká y así poder quedarse con su dinero\nPero Oníkàá había aportado un juego de gemelos,\ncuando ofreció muchas mazorcas de maíz como\nofrenda\nLos Ìbejì habían hecho a Oníkàá inmensamente rico\ny cuando le vieron en las aguas tratando de\nrespirar, se lanzaron a las aguas y le sacaron,\nsalvándole la vida\nGbinňgbin yèkètè\nNo dejes que el príncipe de los Babaláwos sea\nbarrido afuera por la marea del odio\nGbinňgbin yèkètè", "origen_id": "0a9bc391bb05631ddaf2982e"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyekubeka habla de la necesidad de que las acciones del\n            Babalawo se concentren en sus sacrificios a Eşu y otras divinidades\n                                                    para garantizar su seguridad.\n                    WO – El cliente necesita ser más enfaticó en sus cuestiones\n                                      espirituales o podrá perder dinero o cosas.\n\n\n41.1 · Gbingbin ereke. Adivino de la orilla del arroyo, profetizó el oráculo\n\n                  de Ifá para Oyeku y Eka. Ellos fueron advertidos de ofrecer 2\n                gallinas, maíz y 3.200 cowrie. Oyeku no realizó el sacrificio.La\n       historia de Ifá: Ambos Oyeku y Eka fueron a una gira de adivinación.\n              Eka tuvo éxito pero Oyeku no tuvo éxito. Eka dijo: vamos a casa.\n            Mientras ellos estaban regresando, ellos llegaron a donde el balsero.\n            Oyeku, el primero en llegar allí, le pidió al balsero que lo ayudara a\n\nempujar a Eka al río. La primera persona le pagó al balsero 2.000\n  cowrie. La segunda persona le pagó al balsero 2.000 cowrie. ¿quién\n       ordenó que Erinwo Ife fuera soltado al agua?. El agua nunca se\n llevará al cangrejo. Podría nadar hasta sitio seguro. Oyeku instigó al\nbalsero a soltar a Eka en el agua. Edun (el mono) fue el que rescató a\n                                                                    Eka.\n\n\n41.2 · Aderomokun, el adivino de Ijesa. Adebori, el adivino de Egba.\n\n     Kokofakokoyere-o-bawon- pin-eru-l´ogboogba-orun-niitii-wa, el\n    nombre dado a Eşu Odara. La historia de Ifá: Oyeku y Eka ambos\n     profetizaron Ifá para Owa, quien usó cinco cowrie para consultar\nsobre la salud de las mujeres estériles de la casa. Porque ellos fallaron\nen la interpretación correcta de la adivinación, Owa los mató a ambos\n      en un cruce de caminos. Kokofakokoyere bajó al lugar desde el\n  cielo. Él arrancó una hoja y frotó la misma en los ojos y cabezas de\n      ellos. Él estaba cantando: Erirugale-gbende, gbende o. Gbende.\n  Erirugale-gbende. Ellos se levantaron. Él los escoltó a donde estaba\n Owa. Ellos prescribieron el sacrificio para Owa en doscientos. Ellos\n       dijeron, “el propósito de tu consulta al oráculo de Ifá fue por la\n           esterilidad de las mujeres de tu casa. Tú preferirías tenerlas\n    embarazadas.” El fue advertido de ofrecer sacrificio ese día, si no\n    quería morir ese día. Owa realizó el sacrificio. Ellos dividieron el\n material del sacrificio y dieron a Eşu su propia porción. Eşu dijo que\nno sabía que esto era por cómo los babalawos habían sufrido. Él tomó\n\nsu porción y dijo que mejor está en el cielo y continuaría\n             ayudándolos. Pero ellos continuarán tomando la primera porción\n           fuera de todos los materiales del sacrificio. Eşu fue bondadoso con\n                 los babalawos. Desde ese día, los babalawos han resuelto en\n                               compartir los beneficios del sacrificio con Eşu.", "origen_id": "48422a5f2cc3e2bf9360060d"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀yẹ̀kú y Èká: dos gallinas, maíz y 3,200 cauríes.", "Owá: doscientos de cada cosa; la primera porción para Èṣù.", "Sàniyàn: ofrenda a su Orí.", "Ìká: muchas mazorcas de maíz a los gemelos."], "pasajes": [{"titulo": "Ofrenda en el verso 41.1", "texto": "Gbingbin erẹkẹ el adivino de la orilla del río\nadivinó Ifá para Ọ̀yẹ̀kú,\ntambién adivinó Ifá para un Èká (una rama).\nLes fue aconsejado hacer sacrificios juntos:\ndos gallinas, maíz\ny 3200 cowries.\nỌ̀yẹ̀kú no realizó el sacrificio.", "origen_id": "26091170ccb69bc812cb7d65"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù Ọ̀dàrà resucita a los adivinos y recibe desde entonces la primera porción de toda ofrenda. Orí y Ọ̀rúnmìlà deciden el destino. Ìbejì, los gemelos, salvan al honesto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz y mazorcas, hojas de Ifá, gallinas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 41.1 (yorùbá): Gbingbin ẹrẹkẹ awo eti odò / li o ṣe Ifá fQyèkú, / o bu fún Ẹ̀ká kan / A niki awọn mejeji wa rúbọ: / Agbebo-adiyẹ Méjì, igbàdo / ati ẹgbèrindilógún owó. / Ọ̀yẹ̀kú ko rúbọ.", "Verso 41.2 (yorùbá): Aderomokun awo ode ljeṣa, / Adebori awo ode Çabá, / Kokofakokgyprẹ-o-bawon-pin-eru- / l'ogboogba-ọ̀run-niith-wa, / li a pe Éṣü-Ọ̀darà.", "REZO: OYEKUN OYEWODELAKA ADIFAFUN OYEKUN ADIFAFUN IKA. OYEKUN BIKA ALAKE EDON ADIFA OYE OKA NOGBATI TIN ISOPO KUN EKU, EYA TIO LA SHAWO.", "REZO: IFA NIRE ERE AWADO OMO OLOFIN OMONI SHANGO ABURA IÑA OLOTE MEYA ADIFAFUN ORUNMILA, LODAFUN IBEYI ORU EDUN LOBAYE EGGUN ABURE ÑAÑIRE AWO ITUTO BILAYEO NI IFA KAFEREFUN OLOFIN AWO ELE TTUTU MOSHE OBANI YEKUN ELLA NIRE OLOFIN Y ORUNMILA.", "REZO: LEJE EL LERI OKURIN OROGBO IGBA DUDU ELEJE OKANA IKU BIÑI.", "REZO: OYEKUN BIKA LERI MESAN ABALODO AWO ILE GUNGUN ELEMARE EGGUN AWO KORO IWA EGO KAFEREFUN ASHEDA, KAFEREFUN OPA IGUI LERI MESAN.", "REZO: OYEWODE LAKA ADIFAFUN OYEKUN ADIFAFUN IKA OYEKU BIKA ALAKE EDON ADEFA OYE UN OKA WATI FIN WOSHOKUN TROLA SHAWO.", "REZO: OYEKU BIKA LOMI OLASHO ORUNMILA AWAKAN MADAJUN OJO ORUKO OBI ISHEYI SOROPE ORONIA JUN OLORI BURUKU OFI ORIYA IGUI ODIOLODI OFI ISHEWE LU IGUI YUBU.", "REZO: IGBA, 41 CARACOLES, ORO, PLATA, COBRE, BRONCE, ESTAÑO, PLOMO, PLATINO, HIERRO, MARFIL, ALGODON QUE SEA DE LOS SANTOS OLEOS, ERO, KOLA, OBI, OSUN, ORUGBO, IYEFA, IGUI PEREGUN, 4 KOIDE, OTI, EPO, EFUN, ASHO FUN FUN, ASHO DUN DUN, PUPUA, OÑI , OPOLOPO OWO.", "SUYERE: OLAÑO OLAÑO OUN OTA EWE BARA OLAÑO OLAÑO OUN OTA EWE BARA.", "SUYERE: IKUTOPA OJUBA ONOPOWO. SUYERE:", "OJO OWORO TIBI OLOWO NINU OLOWO GOLOTO IMOFA GELOTO OJO OJO ASHE IMEFA NONI OKO ISHERODO YON A MA NONWO YON A MA NO RA.", "REZO: IFA NIRE ERE AWADO OMO OLOFIN OMONI SHANGO ABURA IÑA OLOTE MEYA ADIFAFUN ORUNMILA, LODAFUN IBEYI ORU EDUN LOBAYE EGGUN ABURE ÑAÑIRE AWO ITUTO BILAYEO NI IFA KAFEREFUN OLOFIN AWO ELE TTUTU MOSHE OBANI YEKUN EYA NIRE OLOFIN Y ORUNMILA.", "REZO: AKIKARA IGBA IMIYA MUYA EGU AWO OYEKUN BIKA OMOLU SOYAYA ILE OKOKON BOROMU BOLELE DE MI BASHEYA KOFIBORI IÑIRI EYA KAFEREFUN BOROMU ADIFAFUN SOYAYA.", "REZO: LEJE EL LERI OKURIN OROGBO IGBA DUDU ELEJE OKANA IKU BIÑA.", "SUYERE: IKUTOPA OJUBA ONOPOWO.", "REZO: OYEKUN BIKA LERI MESAN ABALODO AWO ILE GUNGUN ELEMARE EGGUN AWO KORO IWA EGO KAFEREFUN ASHEDA, KAFEREFUN OPA IGUI LERI MESAN.", "SUYERE: “BABA LERI IKU MESAN, LERI IKU OPOLOPO LERI IKU ASHEDA LERISO LERI YEKUN BIKA OYEKUN AZONA”.", "REZO: OYEWODE LAKA ADIFAFUN OYEKUN ADIFAFUN IKA OYEKU BIKA ALAKE EDON ADEFA OYE UN OKA WATI FIN WOSHOKUN TROLA SHAWO.", "REZO: OYEKU BIKA LOMI OLASHO ORUNMILA AWAKAN MADAJUN OJO ORUKO OBI ISHEYI SOROPE ORONIA JUN OLORI BURUKU OFI ORIYA IGUI ODIOLODI OFI ISHEWE LU IGUI YUBU.", "REZO: IGBA, 41 CARACOLES, ORO, PLATA, COBRE, BRONCE, ESTAÑO, PLOMO, PLATINO, HIERRO, MARFIL, ALGODON QUE SEA DE LOS SANTOS OLEOS, ERO, KOLA, OBI, O SUN, ORIGBO, IYEFA, IGUI PEREGUN, 4 AIKORDIE, OTI, EPO, EFUN, ASHO UN FUN, ASHO DUN DUN, PUPUA, OÑI, OPOLOPO OWO."]}]$q$::jsonb),
(42,'9f62bae22279976e296bef4f7b51062d','413b68d327c413b6ee7ce363d0062367',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òtúrúpọ̀n da la posibilidad de evitar el castigo por malas acciones, pero exige buena conducta en adelante. La persona enfrenta problemas legales, muchas veces con el gobierno. Se queja de que su éxito se retrasa: si ofrece, será respetado y admirado, y vencerá a la muerte, la enfermedad y las pérdidas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un problema legal o de trámites y necesita actuar con responsabilidad y buena asesoría.", "Debe reparar una falta anterior o pedir perdón.", "Hay un acuerdo de dinero oculto o confuso que conviene aclarar (relato de Aribijo).", "Ha trabajado sin reconocimiento y se impacienta (relato del tambor Dùndún llamado al palacio).", "Se siente amenazado por pérdidas o enfermedad (canto de Ọ̀rúnmìlà ante los ajogun).", "Un pleito largo le está afectando y se puede aliviar hablando y tomando decisiones concretas."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser perdonado en un problema legal.", "Que lo llamen de un lugar importante sin esperarlo.", "Respeto y admiración.", "Vencer a la muerte, la enfermedad, las pérdidas y los malos hechizos."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la prevención de una enfermedad. (Este Odu habla de la necesidad para perdonar algo, para evitar la tensión y la enfermedad)", "origen_id": "46a82fac2ac18cd9d33a52cb"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Hacer acuerdos secretos de dinero.", "Problemas con la justicia o con el gobierno.", "Que los enemigos esperen verlo resbalar."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación el ciclo lleva a una enfermedad prolongada. (Este Odu habla del peligro de acuerdos secretos)", "origen_id": "ec9fa475dcc45385097ada5c"}]}, {"titulo": "Enseñanza principal", "texto": "Lo que se pacta de dinero se pacta a la vista de todos. Y frente a los que esperan nuestra caída, se baila: Ọ̀rúnmìlà llevó su ofrenda a Èṣù bailando y los ajogun se quedaron sin poder hacerle nada."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú Batutu ofrece la posibilidad de evitar o anular el castigo por malas acciones realizadas, sin embargo, insiste en que se tenga un buen comportamiento moral en el futuro.", "origen_id": "24fee6d16672afb71dac2b96"}]}, {"titulo": "Relatos reunidos", "puntos": ["El rezo del perdón. Ọ̀rúnmìlà me perdonará, el que perdona me perdonará. Si el agua mata a una persona, se le perdona; si un rey mata a una persona, se le perdona. Ọ̀rúnmìlà, déjame ser perdonado en este caso, como la comunidad siempre perdona a la lluvia. Se ofrecen dos gallos y 1,200 cauríes, y se prepara un collar de protección: hojas de túdè molidas con iyẹ̀rosùn de este Odù sobre dos cauríes, envueltos con hilo de algodón.", "Aribijo y los acuerdos secretos. Los adivinos de la casa de Olúfọn consultaron para Aribijo, el hijo menor de Oke-Apa, y le aconsejaron no hacer nunca acuerdos secretos de dinero ni de nada: todo debía ser abierto y público. Le marcaron una chiva, una rata, un pescado, dos gallinas, vino, nuez de kola y 6,000 cauríes.", "El tambor Dùndún llamado al palacio. Nadie había invitado nunca al tambor Dùndún, porque no lo consideraban importante. Fue con el adivino y le marcaron una paloma vieja. Ofreció, y sin aviso lo mandaron llamar del palacio. Sorprendido dijo: '¿Yo? ¡Nadie me había llamado para oír mi música!'. Cantó: 'Hice la ofrenda de Ọ̀yẹ̀kú Òtúrúpọ̀n; todo lo bueno viene a mí y mi vida se ha vuelto fresca'.", "Ọ̀rúnmìlà baila frente a los ajogun. Ọ̀rúnmìlà estaba rodeado de enemigos y malos hechizos. Le pidieron ofrecer contra la muerte, la enfermedad, la pérdida y todos los ajogun que lo vigilaban esperando atacarlo. Ofreció un chivo, y al llevar la ofrenda a Èṣù le dijeron que fuera cantando y bailando, porque esperaban que resbalara y se matara. Cantó: 'Muerte, déjame bailar para tu asombro; enfermedad, déjame bailar; pérdida, déjame bailar'. Todos lo miraban sorprendidos. Èṣù tomó la ofrenda y la repartió entre los ajogun; ellos comieron, y desde entonces Èṣù es el jefe que reparte la comida entre los ajogun. Una vez que comen, no pueden hacer nada contra quien ofreció."], "pasajes": [{"titulo": "Verso 42.1", "texto": "Ọ̀rúnmìlà me perdonará,\nEl perdonador me perdonará,\nSi el agua mata a una persona,\nésta será perdonada.\nSi un rey mata a una persona,\nél será perdonado.\n¡Ọ̀rúnmìlà! déjame ser perdonado en este caso.\nEn todos los casos, la lluvia (eeji)\nha sido perdonada por la comunidad.\nDos gallos y 1200 cowries\ndeben ser ofrecidos como sacrificio.", "origen_id": "8f6c2ef07c5949108a0a544c"}, {"titulo": "Verso 42.2", "texto": "Oyin-wọnyinwọnyin\nel adivino de la casa de Olúfon,\nIbarajuba-Ibarajuba\nadivino también de la casa de Olúfon,\nadivinaron Ifá para Aribijo,\nel hijo más joven de Oke-Apa.\nA él se le aconsejó:\n\"no hacer nunca acuerdos secretos\nacerca de dinero u otros asuntos, por siempre\".\nTal que sus acuerdos de dinero\ndeben ser hechos abierta y públicamente.\nChiva, rata, pescado,\ndos gallinas, vino, nuez de kola\ny 6.000 cowries deben ser sacrificados.", "comentario": "ipinhun: acuerdo, convenio, pacto. ipínhùn ikòkọ̀: acuerdo secreto. ipinhùn owó: pacto de dinero.", "origen_id": "47f6e447873591af63ea01d6"}, {"titulo": "Versos complementarios 1", "texto": "Esta persona se queja del retraso del éxito de sus\naspiraciones en la vida. Si sacrifica, será muy\nrespetado y admirado por todos.\nDeberá sacrificar para vencer los ajogunes de\nMuerte, Enfermedad, Pérdidas, Malos Hechizos, etc.\nEl sacrificio se complementa con un Chivo padre y\ncuando le lleve el sacrificio a Èşù, Ifá le pide que lo\nhaga bailando, ya que sus enemigos esperan o\nvigilan para que resbale y se mate de la caída.\n\n             Eékún ni sébúké\n             Ệdợ ni pàráňkàtá\nA dífá fún Dùndún ti ợn ń pé lÁàfìn ợsán\n                  gangan\n         Dùndún ni ò ti réni pè é\n                 Kò gbayì\n           Ệnìkan ò mò ó télè rí\nDùndún bá tợ àwợn Eékún ni sébúké lợ\n     Ó lợòdò àwợn Ệdợ ni pàráňkàtá\n          Ệ yẹ òun lóókan ibò wò\n        Wón ní kí Dùndún ó rúbợ\n        Wón ní Òwùúrù ẹyẹlé lẹbợ\n     Wón níre lợpợlợpợ fún Dùndún\n              Dùndún bá rúbợ\n              Ló bá di àbàadi\n  Ni ợn bá ráńşe pé wón ń pè é lÁàfin\n                 Òun náà?\n     Tóun ti ń bẹ lái rénìkan bá şeré\n          N ní wá ń jó ní wá ń yò\n         Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n   Ó ní béè làwợn Babaláwo tòún wí\n             Eékún ni sébúké\n             Ệdợ ni pàráňkàtá\nA dífá fún Dùndún ti ợn ń pé lÁàfìn ợsán\n                  gangan\n             Ệbợ ń wón ní ó şe\n         Dùndún wáá gbébợ ńbè\n                  Ó rúbợ\n     Mo mò ti şẹbợ Òyèkúbàtúrúpòn\n            Ire gbogbo wòmù!\n               Ayée wá tutù\n                 Ayé nini\n\nEékún ni sébúké\nỆdợ ni pàráňkàtá\nLanzaron Ifá para el tambor Dùndún que fue\nenviado a llamar inesperadamente del palacio\nDùndún estaba sorprendido, pues nunca nadie le\nhabía invitado\nNadie le tomaba en atención, porque no era\nimportante\nDùndún entonces vino al adivino Eékún ni sébúké y\nal adivino Ệdợ ni pàráňkàtá\n¡Por favor lancen Ifá usando ibò para mí! Pidió\nDùndún\n- Una Paloma veterana es el sacrificio - Ellos dijeron\nque vendrían muchas buenas cosas por este\nsacrificio Dùndún ofrendó y sin aviso previo fue\nenviado a buscar del palacio\nÉl dijo: ¿Yo? ¡Nunca nadie me había llamado para\noír mi música!\nY bailó y alabó a sus babaláwos y ellos alabaron a\nIfá\nEékún ni sébúké\nỆdợ ni pàráňkàtá\nLanzaron Ifá para el tambor Dùndún que fue\nenviado a llamar inesperadamente del palacio\nEl antídoto prescrito para él, fue el sacrificio\nDùndún escuchó acerca de la ofrenda y sacrificó\n- Yo hice los sacrificios de Òyèkúbàtúrúpòn -\n- Todas las buenas fortunas vendrán a mí\ngenerosamente -\n- Nuestras vidas se han establecido de manera\nfresca y suave -\n\n                   Gangatè\n               Gangaatè Ganga\n             A dífá fún Òrúnmìlà\n       Níjó tí ń bẹ láàrin Òtá sángílítí\n\n         Ifá ń bẹ nínú ajogun\nÒún şẹgun àwợn ajogun to di òun mólè\n                    yìí?\n             Wón ní kó rúbợ\n           Wón ní ikú ń só ợ\n              Àrùn ń só ợ\n               Òfò ń só ợ\n    Gbogbo ajogun pátá ni ń só ợ\n               Ó ba rúbợ\n   Ńgbà tí ó móợ gbébợ lợ fún Èşù\n         Wón ní kó móợ dárin\n              Kó si móợ jó\nÀwợn ti si ń sợ ợ gợ sí kòrò légbèé ònà\n Wón ń wò ó bò nígbà tí ń gbé ẹbợó lợ\n                   fÈşù\n        Wón rí Òrúnmìlà tí ń jó\n                 Ni ń yò\n         Ni ń pé jé n jó hàn ó\n                Gangatè\n           Gangaatè Ganga\n            Ikú jẹ n jó hàn ó\n                Gangatè\n           Gangaatè Ganga\n           Àrùn jẹ n jó hàn ó\n                Gangatè\n           Gangaatè Ganga\n            Òfò jẹ n jó hàn ó\n                Gangatè\n           Gangaatè Ganga\n           Òràn jẹ n jó hàn ó\n                Gangatè\n           Gangaatè Ganga\n         Ajogun jẹ n jó hàn ó\n\n                 Gangatè\n             Gangaatè Ganga\n    Wón ba ń wợ Òrúnmìlà pèlú ìyanu\n   Òrúnmìlà ba gbébợ kalè níwájú Èşù\n             Èşù bá bù ńnú è\n                Ló fún Ikú\n                 Ikú jẹ é\n                Ó fún Àrùn\n              Àrùn jẹ ńnú è\n                Ó fún Òfò\n              Òfò náà jẹ ńbè\n      Gbogbo Ajogun pátá nikú fún\n        Gbogbo wợn ni ón jẹ ńnú è\n  Ńgbà ó jẹ pé Èşù ni Bàbá àwợn Ajogun\n          Òun níí pàşẹ fún wợn\n   Bí gbogbo Ajogun ba si ti bà ni jẹun\n          Wón ò gbợdò múni mó\n      Wón ní Ikú è é jẹun ẹni kó pani\n       Wón ò bá le pa Òrúnmìlà mó\n         Ifá pé ayé ó yẹ eléyìun\n\nGangatè\nGangaatè Ganga\nProfetizó Ifá para Òrúnmìlà, cuando estaba en\nmedio de sus enemigos jurados\nIfá estaba rodeado de malos hechizos          ¿Podré\nsobrepasar esos hechizos que están cercanos a mí\npersona? Se preguntaba Òrúnmìlà –\nEllos le dijeron a Òrúnmìlà que ofreciera sacrificio\ncontra la Muerte, la Enfermedad, la Pérdida y todos\nlos        malos    Ajogunes    que    le  vigilaban\nconstantemente, esperando la oportunidad para\natacarle y exterminarlo\nÉl sacrificó En el momento que llevaba el sacrificio\nal altar de Èşù, le dijeron que cantara y bailara, ya\n\nque ellos esperaban que en el último momento se\ncayera y muriera de un resbalón\nÉl cantó: ¡Déjame bailar en tu admiración!\nGangatè\nGangaatè Ganga\n¡Muerte, déjame bailar para tú asombro!\nGangatè\nGangaatè Ganga\n¡Enfermedad, déjame bailar para tú asombro!\nGangatè\nGangaatè Ganga\n¡Pérdida, déjame bailar para tú asombro!\nGangatè\nGangaatè Ganga\n¡Problemas, déjame bailar para tú asombro!\nGangatè\nGangaatè Ganga\n¡Ajogun, déjame bailar para tú asombro!\nGangatè\nGangaatè Ganga\nTodos ellos miraban a Òrúnmìlà sorprendidos, poner\nsu sacrificio frente a Èşù que tomó la ofrenda y la\nrepartió entre todos los Ajogunes que acechaban a\nÒrúnmìlà\nEllos comieron su porción y desde entonces Èşù es\nel líder de todos los Ajogunes Es quien pide y\ndistribuye la comida entre los Ajogunes\nUna vez ellos coman su porción nada podrán hacer\ncontra su enemigo que ha sacrificado, dijeron los\nbabaláwos\nEllos dijeron que la Muerte no se come el alimento y\nsigue con los deseos de matar a la persona\nYa ellos no podrían matar a Òrúnmìlà, ni intentarlo\notra vez\nIfá dice que la vida le será placentera a esta\npersona", "origen_id": "efe813dfea50850da2c761d1"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku Batutu ofrece evitar el castigo por cosas mal hechas,\n                           pero insiste en el comportamiento moral en el futuro.\n            WO – El cliente tiene con frecuencia problemas legales, sobretodo\n                                                                    con el gobierno\n\n\n42.1 · Orunmila me perdonará. El perdonador perdonará, si el agua\n                  mata a una persona, ésta será perdonada, si un rey mata a una\n\npersona, él será perdonado, Orunmila dejame ser perdonado en este\n                                                                           caso.\n                    En todas los casos, la lluvia (seji) ha sido perdonada por la\n                 comunidad. 2 gallos, y 1200 cowrie deben ser ofrecidos como\n              sacrificio. Medicina de Ifá, moler hojas de tude y mezclarlas con\n              iyerosun de este Ifá, poner la mezcla sobre 2 cowrie, taparlos con\n            cuerdas de algodón (hilo) y usarlo como un collar para protección.\n\n\n42.2 · Oyin-wonyinwonyin, el adivino de la casa de Olofun junto a\n       Ibarajuba- Ibarajuba, adivinaron Ifá para Aribujo, el hombre joven de\n      Oke Apa. A él se le aconsejó nunca hacer acuerdos secretos acerca de\n               dinero u otros asuntos por siempre. Algunos acuerdos de dinero\n      deben ser hechos abierta y públicamente. Ebo: 1 chiva, jutía, pescado,\n           2 gallinas, vino, nuez de kola, 6.000 cowrie deben ser sacrificados.", "origen_id": "67f18846442dbdc12f957994"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Perdón: dos gallos, 1,200 cauríes y collar de túdè con iyẹ̀rosùn sobre dos cauríes envueltos en hilo de algodón.", "Aribijo: una chiva, una rata, un pescado, dos gallinas, vino, nuez de kola y 6,000 cauríes.", "Dùndún: una paloma vieja.", "Ọ̀rúnmìlà: un chivo padre llevado a Èṣù bailando."], "pasajes": [{"titulo": "Ofrenda en el verso 42.1", "texto": "Ọ̀rúnmìlà me perdonará,\nEl perdonador me perdonará,\nSi el agua mata a una persona,\nésta será perdonada.\nSi un rey mata a una persona,\nél será perdonado.\n¡Ọ̀rúnmìlà! déjame ser perdonado en este caso.\nEn todos los casos, la lluvia (eeji)\nha sido perdonada por la comunidad.\nDos gallos y 1200 cowries\ndeben ser ofrecidos como sacrificio.", "origen_id": "67b2d8d2ac94886dfefc2cc8"}, {"titulo": "Ofrenda en el verso 42.2", "texto": "Oyin-wọnyinwọnyin\nel adivino de la casa de Olúfon,\nIbarajuba-Ibarajuba\nadivino también de la casa de Olúfon,\nadivinaron Ifá para Aribijo,\nel hijo más joven de Oke-Apa.\nA él se le aconsejó:\n\"no hacer nunca acuerdos secretos\nacerca de dinero u otros asuntos, por siempre\".\nTal que sus acuerdos de dinero\ndeben ser hechos abierta y públicamente.\nChiva, rata, pescado,\ndos gallinas, vino, nuez de kola\ny 6.000 cowries deben ser sacrificados.", "origen_id": "5864185ac421692a9db09948"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù es el jefe que reparte la comida a los ajogun (muerte, enfermedad, pérdida, problemas). Ọ̀rúnmìlà es el que perdona."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Túdè, iyẹ̀rosùn, hilo de algodón, nuez de kola, vino."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 42.1", "texto": "moler hojas de Túdé?\n, mezclarlas con iyè-ròsun de este Ifá, poner la mezcla sobre dos cowries, cubrirlos enrollándole hilo de algodón y usarlo en el cuello para protección (tipo collar).\n7ª Túdè: CALLIANDRA PORTORICENSIS (Jacq.) Benth., Leguminosae Mimosoideae.", "origen_id": "29627af8d6108efd2e8d55b2"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 42.1 (yorùbá): Ọ̀rúnmìlà fi'hun jimi, / Ojiji fi'hun jimi, / Bi Omi bapọ'ni wọn a fi jii. / Bi Ọlojà ba pọ'ni wọn a fi jii. / Bi Ọba ba pọni nse ni wọn fi jii. / Ọ̀rúnmìlà! Ki wọn fỌ̀ràn yi jimi. / Gbogbo ilú nii f'oràn ji Eeji. / Akuką Méjì ati egbèfà owó lẹbọ.", "Verso 42.2 (yorùbá): Oyin-wọnyinwonyin awo ilé Olüfon, / Ibarajuba-Ibarajuba awo ilé Olüfon, / a difá f'Aribijo / Lipe gmokunrin Oke-Apa. / A niki ó ma yan ipinhun* ikpkọ̀ / kioma yan ti ibaba laelae. / Gbamgba-gbamgba / niki o yan ipinhun owó. / Ewarg, eku, eja, / agbebo-adiyẹ Méjì, oti, obi / ati ggbẹtalélógbọ̀n owó li ebọ̀.", "REZO: OYEKUN BATRUPON IFA NI UNLOSILE ILARE LOKIN ILARE OBINI PAMI KAFEREFUN ORUNMILA OBARABANIREGUN OLOFIN.", "REZO: ADIFAFUN SHANGO OBA SALAMANO INLE OGGUN OPA ENI BELE BELE BEKE ILE IKU MAWANI AWO ASARE AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI KOKE UNSORONITITONI SORO EGGUN, LODAFUN OBATALA.", "REZO: IFANI UN LOSINE ILARE YEKUN YAREDO PAMI MEFEREFUN OLOFIN Y ORUNMILA OBARABO NIREGUN.", "REZO: IFA ILARE, OKUN UNYE KUBAONA AKASHE EKO OBI META INTOGGUN UMBAWA OTUKA OLUO AKOPOLA.", "REZO: ADIFAFUN SHANGO OBA SALAMANO INLE OGGUN OPA ENI BELEBELE BEKE ILE IKU MAWANI AWO ASARE AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI KOKE UNSORONITITONI SORO EGGUN, LODAFUN OBATALA."]}]$q$::jsonb),
(43,'c02f82dab8e00a59697aa5937b6d6be8','f19387ce4934f8769408d77fa4eccc6e',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òtúrá habla de quitar la culpa de encima y recuperar la libertad. Los asuntos legales se resuelven y se vuelve a disfrutar la vida social. Pide no ser tacaño con nadie, sobre todo con la comida, y no ser violento con la pareja, porque ella le traerá una gran fortuna."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta una acusación, una crítica o un trámite y busca que se aclare su situación (relato de Ṣoràngun).", "Un pleito le limita su vida social y sus actividades de siempre.", "Las relaciones se tensan por orgullo o egoísmo y necesitan otra forma de hablar.", "Hay un tema de matrimonio o de acuerdos de pareja (relato de Oni-alakan-esuru).", "Busca orientación espiritual para mejorar su conducta y su trato con los demás."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salir libre de un gran problema.", "Dos esposas en un día; una pareja estable para siempre.", "No enfermarse.", "Volver a ver con vida a personas que están lejos."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación de un ciclo lleva a la visión mística. (Este Odu habla de la necesidad cambiar el Espirtu para la guianza para mejorar las relaciones)", "origen_id": "cf73be4e61a3d168d93d731c"}]}, {"titulo": "Ibi y advertencias", "puntos": ["La tacañería, sobre todo con la comida.", "La violencia con la pareja.", "Dejar que otros pasen hambre teniendo de comer."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terrminación del ciclo lleva al egoismo. (Este Odu habla de la posibilidad de litigación).", "origen_id": "4a59f4942d54f82c90fccc18"}]}, {"titulo": "Enseñanza principal", "texto": "Ifá advierte con fuerza: si se tiene comida, no se deja pasar hambre a quien la necesita. Quien comparte con generosidad conserva a su pareja y su fortuna."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú Batuyẹ habla de despejar (remover) la culpa y de restablecer la libertad de actividades.", "origen_id": "1b72909aad99e54c685086c0"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ṣoràngun sale libre. Ifá consultó para Ṣoràngun y le aconsejó ofrecer para salir libre de un gran problema. Le marcaron dos gallos, una rata igbégbé, hojas de gbégbé, 2,600 cauríes y medicina de Ifá: envolver la rata con ocho hojas de gbégbé y enterrarla en el monte.", "Dos esposas en un día. Los adivinos consultaron para Ọni-alakan-esuru, que tendría la fortuna de casarse con dos esposas en un día. Le marcaron dos gallinas y 1,600 cauríes. Cumplió.", "Ọ̀yè, esposo de Òtúá. Ifá consultó para Ọ̀yè, que iba a ser esposo de Òtúá, y le pidió ofrecer y no ser tacaño con la gente, sino regalar comida. Ofreció y repartió harina de ñame en abundancia; todas las ancianas hambrientas se acercaron y él les dio hasta que se saciaron. Ọ̀yè fue esposo de Òtúá hasta el final de sus días y su vida fue placentera.", "La kola que se comparte. Pákúdidi y Pàkùdidi vivían en el mismo lugar sin haberse visto cara a cara. Así consultaron para Ọ̀yè, que iba a traer nuez de kola de Òtúá a su casa, y le pidieron ofrecer para no enfermarse, porque su fortuna estaba llegando. La gente le cantaba: 'Ayúdanos, Ọ̀yè, danos nuez de kola'."], "pasajes": [{"titulo": "Verso 43.1", "texto": "adivinó Ifá para Ṣoràngun,\nle fue aconsejado sacrificar,\npara salir exonerado de un gran problema.\nSacrificio: dos gallos,\nrata igbégbé,\nhojas de gbégbé,\n2600 cowries\ny medicina de Ifá.", "origen_id": "5013c27c91f5827605552e7b"}, {"titulo": "Verso 43.2", "texto": "lyán-bi-atungun,\nObẹ-bi-atunse,\nOkelegbongbo-di-atunbu-baálé:\nadivinaron Ifá para Qni-alakan-esuru,\nquien sería afortunado en tener\ndos esposas en un día.\nEllos le aconsejaron hacer sacrificio\ndos gallinas y 1600 cowries.\nÉl escuchó y ejecutó el sacrificio.", "origen_id": "06fc6caac9043365dc529345"}, {"titulo": "Versos complementarios 1", "texto": "La persona no deberá ser miserable con nada ni con\nnadie y menos al repartir polvo de ñame. No deberá\nser violento con su esposa, porque ella le proveerá\nde inmensa fortuna en la tierra. No deberá ser\ntacaño con las personas que le rodean y menos en\nfunciones de alimentación. Si no lo es su vida será\nespléndida. No se enfermará y deberá ofrecer\nsacrificio para unas personas que están muy\nalejados, para que puedan verse de nuevo con vida.\n\n               Elélùbó etí àjà\n               A dífá fún Òyè\n              Èyí tíí sợkợ Òtúá\n               Wón ní ó rúbợ\n    Wón ní kò gbợdò şe ahun si èèyàn\n        Wón ní kó móợ foúnjẹ tợrợ\n                Òyè bá rúbợ\n            Ní bá ń fí èlùbó tợrợ\n Gbogbo àwợn ìyá arúgbó tí ò tí ri nňkan\n                       jẹ\n           Yóó bu èlùbó fún wợn\n  Ifá pé ki eléyìun ó mó foúnjẹ dùùnyàn\n           Òyè bá sợkợ Òtúá dalé\n                 Ayé yẹ Òyè\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n               Elélùbó etí àjà\n\n                A dífá fún Òyè\n              Èyí tíí sợkợ Òtúá\n             Ệbợ ń wón ní ó şe\n               Òyè gbébợ ńbè\n                    Ó rúbợ\n         Taa ni ó sợkợ Òtúá fún wá?\n                      Òyè\n         Òyè ni ó sợkợ Òtúá fún wá\n                      Òyè\n\nElélùbó etí àjà\nProfetizó Ifá para Òyè, que sería el esposo de Òtúá\nLe dijeron que sacrificara y que no fuera tacaño con\nlas personas\nEl debía brindar bastante comida como regalos\nÉl sacrificó y brindó abundante polvo de ñame como\npresente a todos\nTodas las ancianas que estaban famélicas se\nacercaron a él\nY él les brindó polvo de ñame hasta que se saciaron\ntodas completamente Ifá fuertemente advierte que\nsi tiene alimentos no dejará pasar hambre a las\npersonas que lo necesitan\nÒyè se convirtió hasta sus días finales en el esposo\nde Òtúá\nY su vida le fue muy placentera\nÉl bailó y alabó a sus babaláwos y ellos alabaron a\nIfá\nÉl hizo exactamente lo que ellos le dijeron que\nhiciera\nElélùbó etí àjà\nProfetizó Ifá para Òyè, que sería el esposo de Òtúá\nÉl escuchó y sacrificó debidamente\n¿Quién será a nuestro juicio el esposo de Òtúá?\nÒyè\nA nuestro juicio Òyè será siempre el esposo de Òtúá\n\nÒyè\n             Pákúdidi Pàkùdidi\n     Pákúdidi ló gbélé bí ợdún méta\n     Béè ní wón ò fojú kan araa wợn\n               A dífá fún Òyè\n      Níjó ti ń lợ rèé kóbì lówó Òtúá\n               Wón ní kó rúbợ\n              Wón níre rè ń bo\n            Wón ní ò níí ri àárè\n   Ó ni Pákúdidi ló gbélé bí ợdún méta\n     Béè ní wón ò fojú kan araa wợn\n               A dífá fún Òyè\n      Níjó ti ń lợ rèé kóbì lówó Òtúá\n           Bá ni kóbì wá dákun\n                     Òyè\n           Bá ni kóbì wá dákun\n                     Òyè\n\nPákúdidi Pàkùdidi\nPákúdidi vivió en los mismos lugares entre ellos,\npero aún no se habían visto frente a frente\nLanzó Ifá para Òyè, el día en que venía a brindar\nnuez de kolá de Òtúá\nLe pidieron que ofrendara para que no cayese\nenfermo, ya que su fortuna estaba llegando\nPákúdidi Pàkùdidi\nPákúdidi vivió en los mismos lugares entre ellos,\npero aún no se habían visto frente a frente\nLanzó Ifá para Òyè\nQuien venía de acarrear nuez de kolá de Òtúá a la\ncasa\n¡Ayúdanos!, bríndanos nuez de kolá\nÒyè\nPor favor, ayúdanos, brindándonos nuez de kolá\nÒyè", "origen_id": "c27d8455d307317bf77239bd"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku Batuye habla del removimiento de la censura o culpa y\n                                restablecimiento de la libertar de actividades.\n               WO - Los asuntos legales serán resueltos y puede disfrutar los\n                                                             asuntos sociales.\n\n\n43.1 · Oropoto profetizó Ifá para Sorangun. Le fue aconsejado\n     ejecutar sacrificio para salir exonerado: 2 gallos, jutía egbegbe, 2.600\n      cowrie, medicina de Ifá (Envolver una jutía con 8 hojas de igbegbe y\n                                             enterrarla en el bosque o campo).\n\n\n43.2 · Iyan-bi-atungun, Obe-bi-atunse, Okelegbongbo-di-atunbu-baale\n             adivinó Ifá para Oni-alakan-esuru. Quien sería afortunado en tener\n            dos esposas en un día. Le fue aconsejado sacrificar 2 gallinas, 1600\n                                       cowrie. Él escuchó y ejecutó el sacrificio.", "origen_id": "a5a4c9b2b42f728ff64026fa"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ṣoràngun: dos gallos, rata igbégbé, hojas de gbégbé, 2,600 cauríes y medicina de Ifá.", "Ọni-alakan-esuru: dos gallinas y 1,600 cauríes.", "Ọ̀yè: harina de ñame (èlùbọ́) repartida en abundancia.", "Para la salud: ofrenda por las personas que están lejos."], "pasajes": [{"titulo": "Ofrenda en el verso 43.1", "texto": "adivinó Ifá para Ṣoràngun,\nle fue aconsejado sacrificar,\npara salir exonerado de un gran problema.\nSacrificio: dos gallos,\nrata igbégbé,\nhojas de gbégbé,\n2600 cowries\ny medicina de Ifá.", "origen_id": "b70e2a0cd9c71dd6cf7b054d"}, {"titulo": "Ofrenda en el verso 43.2", "texto": "lyán-bi-atungun,\nObẹ-bi-atunse,\nOkelegbongbo-di-atunbu-baálé:\nadivinaron Ifá para Qni-alakan-esuru,\nquien sería afortunado en tener\ndos esposas en un día.\nEllos le aconsejaron hacer sacrificio\ndos gallinas y 1600 cowries.\nÉl escuchó y ejecutó el sacrificio.", "origen_id": "076f2dca7f02b4bc1069d1e3"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá es quien libra de la culpa. Las ancianas reciben la comida del generoso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gbégbé, rata igbégbé, harina de ñame, nuez de kola (pákúdidi)."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 43.1", "texto": "Envolver una rata igbégbé con 8 hojas de gbégbé®1 y sepultarla dentro del bosque.\n8° eku igbégbé: tipo de rata desconocida 8 gbégbé: ICACINA TRICHANTHA Oliv., Icacinaceae.", "origen_id": "5ea47f36680312bb5df811da"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 43.1 (yorùbá): Ọropọto: / li o difá fún Ṣoràngun, / a niki ó rúbo / kioba leṣe ràn naa gun. / Ebọ: Akuko-adiyẹ Méjì, / eku igbégbé8o, / ewé gbégbé, / ẹgbẹtala owó / ati ewé Ifá. / Ọropotọ:", "Verso 43.2 (yorùbá): Iyán-bi-atungun, / Ọbẹ-bi-atunse, / Okelegbongbo-di-atunbu-baálé: / wọ̀n dífá f'Qni-alakan-esuru, / nigbati o maa rire aya Méjì loojo. / Wọ̀n niki ó rú: / Agbebo-adiyẹ Méjì / ati egbăájo owo. / Ô gbọ̀ ó rú.", "REZO: OYEKUN TESIA AKIKI OLORUN OBI LOLUN MATI BIBIKOUGUN AWO APIGUMI WATA ORUNMILA AKINE IDILA SARA AKUKO ABELO WO ELEBO.", "REZO: OYEKU TESIA AKIKI OLORUN INIBOLON MATIBIBI KONGU OWO APIGUNI GUATA ORUNILA AGUINO IDILA SARA AKUKO ABELO GUE.", "REZO: LLEBO NIBUNI ADIFAFUN ERONI MOYELE TINTIATE OMO OLOKUN NIFA EBBO ADIE RE ELEGBA AKUKO.", "REZO: EKARU EKARU OMILE LODAFUN ORUNMILA INTORI OMO ADIFAFUN OLOKUN ADIFAFUN SHANGO.", "REZO: UWOYUJO OMINO ADIFAFUN OBATALA OSHEREGBO UMBOBO UMBATI OMARE.", "REZO: OYEKUN OTURA ASIA ADIFAFUN OMOLOKUN OZAIN OLORUN YODA ORI INLE MABA DA LEYA OBANSHE LERI OMA ARONI MEYEYE OWA OLOKUN ORUNMILA NIFA OMA OBAYENI AWO AUM ORIKANI META BENI LAYE OMO OBAYANI AUM AWO AKINKUN OLO ORUN ABIBO MARAYELENI AWO OLO ABIBO GONGO ORUN ADIFAFUN ISHENI OBAYE LODAFUN ORUNMILA Y OLOFIN.", "REZO: EKARU EKARU OMILE LODAFUN ORUNMILA INTORI OMO ADIFAFUN OLOKUN ADIFAFUN SHANGO.", "REZO: UWOYUJO OMINO ADIFAFUN OBATALA OSHEREGBO UMBOBO UMBATI OMARE.", "REZO: OYEKUN OTURA ASIA ADIFAFUN OMOLOKUN OZAIN OLORUN ODA ORI INLE MABA DA LEYA OBANSHE LERI OMA ARONI MEYEYE OWA OLOKUN ORUNMILA NIFA OMA OBAYENI AWO AUM ORIKANI META BENI LAYE OMO OBAYANI AUM AWO AKINKUN OLO ORUN ABIBO MARAYELENI AWO OLO ABIBO GONGO ORUN ADIFAFUN ISHENI OBAYE LODAFUN ORUNMILA Y OLOFIN."]}]$q$::jsonb),
(44,'62039c751e9a879555a889e801081a09','78ccfc3041b77083451a893d8381c29a',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìrẹtẹ̀ trae solución para la enfermedad: la persona o alguien de su casa está o estará enfermo. También habla de una mujer que desea hijos aunque le digan que ya es mayor, y de dos personas que planean ir a un lugar y deben ofrecer para que una no se acomode a costa de la otra."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien de la casa está enfermo y la familia busca apoyo (relato de la familia de Kuṣeru).", "Una persona sigue como si nada aunque hay señales que piden atención.", "La familia necesita organizarse para cuidar sin paralizarse por la preocupación.", "Con determinación y decisiones a tiempo, el cuidado puede salir adelante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Recuperación de un enfermo de la casa.", "Hijos para una mujer a la que creían demasiado mayor.", "Establecerse y multiplicarse en un lugar nuevo."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación de un ciclo lleva a la determinación. (Este Odu habla de la necesidad para proteger la salud de una persona y su familia.)", "origen_id": "916ec054848188b8f42d77ed"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedad que hincha el cuerpo; conviene atenderse con el médico además de la ofrenda.", "Llegar primero y creerse dueño sin ofrecer.", "Que uno se acomode a costa del otro."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminacion del ciclo lleva a la testarudez. (Este Odu habla de la posibilidad a enfermedad seria que puede tener un efecto de larga vida).", "origen_id": "f8a20d9e7bf45639cfe1e2b6"}]}, {"titulo": "Enseñanza principal", "texto": "No basta con llegar primero. La hierba Èèsún tomó el mejor terreno sin ofrecer y el hombre la cortó; la caña de azúcar ofreció su machete y la dejaron crecer."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú-Ìrẹtẹ̀ ofrece solución para las enfermedades.", "origen_id": "d052ffdc5818681688a933c9"}]}, {"titulo": "Relatos reunidos", "puntos": ["El joven de la familia Kuṣeru. Los adivinos consultaron para la familia Kuṣeru y vieron a un joven, antes delgado, al que una enfermedad le había hinchado manos, piernas, ojos y nariz. Ifá dijo que se recuperaría si ofrecían cuatro palomas, 44,000 cauríes y medicina de Ifá: corteza del árbol ayẹ, hojas de asunrun, mucha sal y chiles rojos pequeños, hervidos en una olla, para bañarse y beber.", "Ìyálóde Òpò, la que creían vieja. Ìyálóde Òpò lloraba porque no tenía hijos y la gente decía que ya era muy mayor. Le marcaron una gallina que ya hubiera sido madre, una rata y un pescado ahumado. Ofreció, y al poco tiempo quedó embarazada y después tuvo muchos hijos. La gente cantaba: '¿Quién tiene tantos hijos? La que llamaban anciana'.", "La hierba Èèsún y la caña de azúcar. Èèsún y la caña buscaban tierra pantanosa donde vivir, y a las dos les pidieron ofrecer. Èèsún llegó primero, escogió una gran porción sin ofrecer y dijo: '¿Quién me va a sacar de aquí?'. La caña ofreció un machete y se estableció en la misma tierra. Con el tiempo las dos se multiplicaron. Cuando el hombre llegó, tomó el machete de la ofrenda, cortó toda la hierba por dañina y de la caña solo tomó unos trozos para calmar su sed, dejándola crecer porque vio su beneficio."], "pasajes": [{"titulo": "Verso 44.1", "texto": "Afinjuyẹle,\nOkünrün-kojẹkẹwàfuyi\nAwowonsàn el adivino de la familia Kuṣeru:\nadivinaron Ifá para Kuṣeru.\nLos adivinos dijeron:\n\"hay un joven en esa familia que antes era delgado,\nél fue atacado por una enfermedad\nque hizo que sus manos, piernas, ojos y nariz estén hinchados\".\nKuṣẹru fue advertido a ofrecer sacrificio\nporque Ifá predijo que el muchacho se recobraría.\nSacrificio: cuatro palomas, 44.000 cowries y medicina de Ifá.", "comentario": "ayẹ: STERCULIA RHINOPETALA K. Schum., Sterculiaceae.\nasunrun: asunron: asunrin: SENNA PODOCARPA (Guill. & Perr.) Lock, Leguminosae Caesalpinioideae.", "origen_id": "28a12cd3c6b3bf2470b0a974"}, {"titulo": "Versos complementarios 1", "texto": "Esta mujer desea tener hijos, pero las gentes dicen\nque ya está muy vieja para parir. Ifá dice que\ndeberá sacrificar ya que hay dos personas que\nplanean viajar a algún lugar. El asunto del sacrificio\nes para que los dos se acomoden a lo que desean y\nno suceda que uno de ellos se acomode a costa del\notro. Ambos deberán ofrecer un machete como\nelemento del sacrificio.\n\n                 Òpòkúrẹtè\n      Ệran ẹşín kún mi lénu tẹtẹẹtẹ\n           A dífá fún Ìyálóde Òpò\n             Ệkún ợmợ ní ń sun\n        Òún le bímợ láyé òun báyìí?\n               Wón ní kó rúbợ\n             Wón níre ó to lówó\n         Wón ní Àgbébợ adiẹ lẹbợ\n                Eku, ẹja, lẹbợ\n            Ìyálóde Òpò bá rúbợ\n            Wón bòkè ìpòrí ẹ fun\n       Ìyálóde ti ợn ti ń pé ó dàgbà\n                 Ló bá lóyún\n                   Ló bímợ\n                 Ợmợ kún ilè\n         Ìyálóde bá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n                 Òpòkúrẹtè\n      Ệran ẹşín kún mi lénu tẹtẹẹtẹ\n           A dífá fún Ìyálóde Òpò\n\n             Ệkún ợmợ ní ń sun\n          Wón ní ó sá káalè jàre\n                 Ệbợ ní ó şe\n                Ó gbébợ ńbè\n                   Ó rúbợ\n        Taa ló bímợ báwònyí bẹẹrẹ?\n                Ìyálóde Àgbà\n          Ló bímợ báwònyí bẹẹrẹ\n                Ìyálóde Àgbà\n\nÒpòkúrẹtè\nEl bistec de Caballo llena mi boca hasta hartarme\ndel todo\nLanzó adivinación para Ìyálóde Òpò, cuando ella\nlloraba a causa de no tener hijos\n¿Seré capaz de tener hijos en la Tierra?, se\npreguntaba llorando\nEllos le dijeron que para que esa bendición llegase a\nella debía sacrificar, una gallina que ya hubiese sido\nmadre, además de Rata y Pez ahumado\nÌyálóde Òpò se dedicó a buscar los ingredientes y\nellos le realizaron el sacrificio       Y aunque ella\npensaba que ya era muy vieja para quedar preñada,\nal poco tiempo concibió su embarazo y a partir de\nese primero tuvo muchos hijos\nÌyálóde Òpò, bailó y se regocijó y alabó a sus\nbabaláwos y ellos alabaron a Ifá\nÒpòkúrẹtè\nEl bistec de Caballo llena mi boca hasta hartarme\ndel todo\nLanzó adivinación para Ìyálóde Òpò, cuando ella\nlloraba a causa de no tener hijos\nEllos le pidieron de cuidar la tierra y sacrificar\nElla sacrificó\n- ¿Quién ha tenido tantos hijos? –\n- La presunta anciana Ìyálóde –\n\n- Ha tenido muchos hijos –\n- La susodicha anciana Ìyálóde -\n\n                 Òpòkúrẹtè\n      Ệran ẹşín kún mi lénu tẹtẹẹtẹ\n       A dífá fún Èèsún òun Ìrèké\n Níjóợ wón ń lợ rèé bá wợn múlè lákùrò\n          Wón ní kí wón ó rúbợ\n   Èèsún àti Ìrèké ní ợn jợ ń lợ Àkùrò\n           Èèsún ló kókó dé ibè\n                 Ló ti múlè\nWón ní ìwợ Èèsún rúbợ kí ààyè ó le gbà ó\n      Èèsún ní taa ní ó wàá mú òun\n    Ńgbà ó yá àwợn èèyán bá rí Ìrèké\n       Wón bá mú Ìrèké lợ sí àkùò\n       Wón rí Èèsún tó ti hù lợ súà\n             Wón ní “kín lèyí”\nWón bá mú àdá ti ợn ní kí Èèsún ó rú lẹbợ\n           Wón fi gé Èèsún kúò\n           Wón fààyè gba Ìrèké\n               Ìrèké ló rúbợ\n          N ní wá ń jó ní wá ń yò\n         Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n                 Òpòkúrẹtè\n      Ệran ẹşín kún mi lénu tẹtẹẹtẹ\n       A dífá fún Èèsún òun Ìrèké\n Níjóợ wón ń lợ rèé bá wợn múlè lákùrò\n        Ệbợ n wón ní kí wón ó şe\n         Taa ní ń bẹ léyìn tó rúbợ\n                Ìrèké nikàn\n    Ìrèké nikàn ní ń bẹ léyìn tó rúbợ\n\n                   Ìrèké nikàn\n\nÒpòkúrẹtè\nEl bistec de Caballo llena mi boca hasta hartarme\ndel todo\nLanzó adivinación para la hierba Èèsún y la Caña de\nAzúcar, cuando buscaban una tierra cenagosa\ndonde vivir\nA ambos se les habló de brindar sacrificio, para\npoder establecerse\nÈèsún, llegó primero al lugar y escogió una extensa\nporción de terreno\nSin haber sacrificado     Le dijeron: - Debes de\nsacrificar, para poder crecer y expandirte – y él\ncontestó: ¿Quién osará sacarme de este lugar\npantanoso? -\nLa Caña de Azúcar si sacrificó con un machete y se\nestableció en la misma tierra que la hierba Èèsún\nTranscurrido un tiempo, ambos habían crecido en\nmultitudes y cuando el hombre les vio, tomó el\nmachete (elemento del sacrificio) y cortó toda la\nhierba Èèsún, por considerarla dañina a la Caña de\nazúcar y de esta última solo tomo unos trozos, para\naliviar su sed, dejándola crecer y multiplicarse\ncuando vio sus beneficios\nLa Caña de azúcar alabó a sus babaláwos y ellos\nalabaron a Ifá\nÒpòkúrẹtè\nEl bistec de Caballo llena mi boca hasta hartarme\ndel todo\nLanzó adivinación para la hierba Èèsún y la Caña de\nAzúcar, cuando buscaban una tierra cenagosa\ndonde vivir\n¿Quién se quedó sola en el sacrificio? – La Caña de\nazúcar -\nEs quien solamente ofreció el sacrificio prescrito por\nIfá\n\nLa Caña de Azúcar (Ìrèké)", "origen_id": "dea26e68ac17077ae42b97ca"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku-Irete ofrece solución para las enfermedades.\n                                       WO – El cliente está o estará enfermo.\n\n\n44.1 · Afinjuyele, Okunrun-kojekewafuyi y Awowonsan, adivinos en la\n\n          casa de Kuseru, fueron los tres adivinos quienes adivinaron Ifá para\n            Kuseru. Los adivinos dijeron que había un muchacho joven en su\n           casa que fue una vez flaco, él fue atacado por una enfermedad que\n          hizo que sus manos, sus piernas, ojos y nariz estuvieran hinchados.\n           Kuresu fue advertido a ofrecer sacrificio porque Ifá predijo que el\n                 muchacho se recobraría. Ebo: 4 palomas, 44.000 cowrie y la\n          medicina de Ifá (vaciar agua en una barca de un árbol de ayẹ, hojas\n          de asunrun, mucha sal y algunos pimientos rojos chiquitos, cocinar\n                      en una cazuela y usar la medicina para baños y bebida).", "origen_id": "45eec16087db40914a03aeca"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Kuṣeru: cuatro palomas, 44,000 cauríes y medicina de corteza de ayẹ, hojas de asunrun, sal y chiles, para baño y bebida.", "Ìyálóde Òpò: una gallina que ya haya sido madre, una rata y un pescado ahumado.", "La caña de azúcar y las dos personas que viajan: un machete cada una."], "pasajes": [{"titulo": "Ofrenda en el verso 44.1", "texto": "Afinjuyẹle,\nOkünrün-kojẹkẹwàfuyi\nAwowonsàn el adivino de la familia Kuṣeru:\nadivinaron Ifá para Kuṣeru.\nLos adivinos dijeron:\n\"hay un joven en esa familia que antes era delgado,\nél fue atacado por una enfermedad\nque hizo que sus manos, piernas, ojos y nariz estén hinchados\".\nKuṣẹru fue advertido a ofrecer sacrificio\nporque Ifá predijo que el muchacho se recobraría.\nSacrificio: cuatro palomas, 44.000 cowries y medicina de Ifá.", "origen_id": "09ba69af4ecd78c417a3eac3"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá cura a través de la medicina de hojas. La Ìyálóde es la jefa de las mujeres de la ciudad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ayẹ (corteza), asunrun, sal, chiles rojos, caña de azúcar, hierba èèsún."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 44.1", "texto": "Echar en agua pedazos de corteza del árbol ayẹ®2 hojas de asunrun®3 , mucha sal y bastante pimientos rojos picantes chiquitos, cocinar en una cazuela. Usar esta medicina para baños y como bebida.", "origen_id": "4a37c2b418dcbbf858cbe311"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 44.1 (yorùbá): Afinjuyẹle, / Okùnrùn-kojẹkẹwàfuyi, / Awowonsàn awo wọn ni'le Kuṣeru: / li o difá fún Kuṣeru. / Wọ̀n ni: / \"omokunrin kan wa ni ilé rè. / O ti tẹẹrẹ ri, àrùn kan kọluu. / O kun lọwọ̀, o kun lẹsẹ, ojú ati imu\". / A niki ó wa rúbo. / Ifá a woosan. / Ẹbọ: Ẹyẹlé mẹrin, ẹgbàá méjilélógún owó ati ewé Ifá", "REZO: OYEKUN BIRETE MOLALA AWO MOLALA INTORI IFA ARUN MOLALA ABE OYU LAYE TINSHORE IFA OLOWO-POPO MOLALA AWO TINSHORE IFA OSHE OSHANLA IFA MOLALA NI YABE OTARENI IFA MOYARE NI LAYE MOLALA.", "REZO: OWO ADA ADIFAFUN IBINO NIRUBO ADIFAFUN ERU NILLO IBEYO OBUOMELLO MAFEREFUN BABALU AYE.", "REZO: OPO CURETA ADIFAFUN ESHU BATILOMBIBE ACOSHE EYELE EMENI OWO KAFEREFUN AGRINIKA ENI BABALAWO KIROSHILE NIKA.", "REZO: OYEKUN IRETE ADIFAFUN BABALU AYE KONIBO ESHI TETAN OBATALA, EPO AKUKO, KOLONI, EIYOKO, OWO LA MERIN ADIFAFUN ADA ADANIBI AYALUBERI ETUFO EYELE MEYI, ORI, OWO LA EPO KARETE ADIFAFUN ESHU UMBALE VIE.", "REZO: OYEKUN IRETE MOLOLA AWO MOLOLA INERI ARUN MOLOLA ABE EYULELE EYU LERUN TINSHORE IFA MOYARE BE IFA ORANLA MELALA NI YABE OTORONI IFA MOYARE NILAYE MOLOLA NI SHANGO YOROBO FUN BORI BEKUN INTOBI AWO MOLOLA.", "REZO: OYEKUN BIRETE YANA YANA IFA ABELEYERE IFA OBO ODEDI ESHUN Y AYOBI ETA AGUA YEBA ARA EYEKU LOKUN ABONISE SHANGO AWO OBAYOBI AWO OYEKU BIRETE BAYA BAGUARA BABARA ABAYEKU OLUO POPO OYEKUN IRETE OMO EWE YEKUN NI SHANGO A IÑA.", "REZO: OYEKUN IRETE MOLOLA AWO MOLOLA INERI ARUN MOLOLA ABE EYULELE EYU LERUN TINSHORE IFA MOYARE BE IFA ORANLA MELALA NI YABE OTORONI IFA MOYARE NILAYE MOLOLA NI SHANGO YOROBO FUN BORI BEKUN INTOBI AWO MOLOLA. INTORI ARUN GIN GUN:"]}]$q$::jsonb),
(45,'6b17b4ab82e714f1365c22d6997bd5a3','9cf432dfd8da78923f2049b16368df3e',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀ṣẹ́ explica que la muerte es parte del ciclo que renueva el orden natural. La persona se resiste a aceptar el final de una relación, de una etapa familiar o de un negocio. Ifá le desea lo mejor: se volverá alguien importante en el lugar al que viaja con frecuencia, y tendrá un nombre grande."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le cuesta aceptar el fin de una relación, un negocio o una etapa familiar.", "Vive un duelo o se pregunta por el sentido de la muerte (relato de los sabios y el agua que fluye).", "Desea hijos o continuidad familiar (relato del sapo Òpòló).", "Quiere establecerse y dejar un nombre respetado (relato del árbol Àràbà).", "El deseo de tener algo no le deja ver un cambio necesario.", "Llegar a un lugar nuevo puede abrirle una posición importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos robustos y numerosos.", "Un nombre grande y respetado que se perpetúa en la familia.", "Volverse importante en el lugar al que viaja.", "Sobresalir por encima de los demás."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la abundancia. (Este Odu habla de la necesidad de venir a teminos con la idea de la muerte.)", "origen_id": "6a3f683d36ff269da7e6c1de"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Aferrarse a lo que ya terminó.", "Vivir con miedo a la muerte."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la codicia. (Este Odu habla del posible fallecimiento de un amigo).", "origen_id": "f3e36bfd98e560154389e825"}]}, {"titulo": "Enseñanza principal", "texto": "El agua estancada se pudre y enferma; el agua que corre limpia y renueva. Así es la muerte en el orden del mundo: lo que no se va no deja lugar a lo nuevo."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú-İṣó explica la necesidad de la muerte como parte del ciclo de renovación del orden natural.", "origen_id": "c46c93b098c3a7b0c475e8b9"}]}, {"titulo": "Relatos reunidos", "puntos": ["Los sabios preguntan por la muerte. Varios adivinos consultaron para los sabios, que querían saber por qué la muerte mata a la gente y nadie se salva. Los babaláwo respondieron que Amuniwayé, que es Òrìṣà-ńlá, creó la muerte como algo bueno para la humanidad: el agua que no corre se estanca, se pudre y trae enfermedad; el agua que se deja correr se lleva la enfermedad de la casa y renueva el cuerpo y el carácter. Los sabios gritaron a Ifá: 'Ọ̀rúnmìlà, que la ofrenda sea aceptada'. Se dispersaron y nunca volvieron a ver a la muerte como un problema.", "El sapo y sus hijos. Ifá consultó para el sapo cuando lloraba porque no tenía descendencia, y le dijo que si ofrecía tendría hijos robustos y gordos. Ofreció, y empezó a tener crías que saltaban por todas partes. '¿Quién tiene tantos hijos? Solo el sapo'.", "El baobab en el bosque. Ifá consultó para el baobab (Àràbà) cuando iba a escoger tierra en el bosque y preguntaba cómo podría ser más grande que los demás árboles. Ofreció rápido; al establecerse creció por encima de todos, y los otros árboles preguntaban qué árbol era ese. Ifá dice que esta persona tendrá un nombre grande y honorable y que su linaje será respetado."], "pasajes": [{"titulo": "Verso 45.1", "texto": "K'amatètèkú,\nel adivino del pueblo de la alegría (Alayo).\nÀitètèkú-ìṣé,\nel adivino del pueblo de la aflicción (Ibànújé).\nBi-ikú-ba-de-ka-yin-Olúwa-logo,\nel adivino de Igboya ewà\nAlọgbọ̀n-on-makú-ninú,\nMaṣimale ninmẹyẹniyi,\nel adivino de Afinju-makú-maṣe'bajẹ,\nÖyěkẹṣeniyì:\nadivinaron Ifá para los sabios (Èniyàn ṣaṣa),\nquienes invitaron a los Babaláwos\npara consultar los problemas sobre la muerte,\npreguntando:\n¿por qué la muerte mata a las personas\ny nadie se ha salvado de la muerte?\nLos Babaláwos dijeron:\nIfá nos enseña que Amuniwayé creó la muerte\ncomo algo bueno para la humanidad.\nEl agua estancada se convierte en un estanque\ny se empantana como agua putrefacta\nque puede causar la enfermedad.\nEl agua que le gente deja correr libremente\ny el agua que nos regresa de vuelta,\nse lleva la enfermedad de la casa para curarla\ny renueva el cuerpo y el carácter debilitado.\nEl loco es cuidado por su propia familia.\nLos Babaláwos preguntaron:\n¿por qué vemos esto como algo desagradable?\nLos sabios gritaron a Ifá diciendo:\nỌ̀rúnmìlà: Iború, Iboyè, Iboṣẹ.\nTodos ellos se dispersaron\ny más nunca recordaron a la muerte\ncomo un problema más.\nÖriṣà-ńlá es llamado Amuniwayé.", "origen_id": "4cd446b34029d8d56d99f25b"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le desea a esta persona lo mejor. La persona se\nconvertirá en alguien importante en el lugar donde\nfrecuentemente viaja o está viajando.\n\n            Òyè kúsé kùsè kúsé\n A dífá fún Òpòló ti ń fojúú şògbérè ợmợ\n        Wón ní yóó bímợ lợpợlợpợ\n           Ệbợ ợmợ ní kó wáá şe\n   Wón ní ribiti ribiti lợmợợ rè ó móợ rí\n               Òpòló bá rúbợ\n            Ló bá bèrè síí bímợ\n            Ní ợn ń fò kúsé kùsè\n                Ayé yẹ Òpòló\n          N ní wá ń jó ní wá ń yò\n         Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n            Òyè kúsé kùsè kúsé\n A dífá fún Òpòló ti ń fojúú şògbérè ợmợ\n          Wón ní ó sá káalè jàre\n          Ệbợ ợmợ ń wón ní ó şe\n       Taa ló bímợ bágònyí bẹẹrẹ?\n                Òpòló nikàn\n          Ló bímợ bágònyí bẹẹrẹ\n                Òpòló nikàn\n\nÒyè kúsé kùsè kúsé\nLanzó Ifá para el Sapo, cuando lloraba por no tener\ndescendencia\n\nLe dijeron que la tendría, pero debía sacrificar y que\nde hacerlo, sus hijos serían robustos y muy gordos\nEl Sapo ofreció el sacrificio previsto y comenzó a\ntener prole que saltaban aquí y allá\nÉl agradeció a sus babaláwos y les alabó y ellos\nalabaron a Ifá\nÒyè kúsé kùsè kúsé\nLanzó Ifá para el Sapo, cuando lloraba por no tener\ndescendencia\nLe dijeron que la tendría, pero debía sacrificar y que\nde hacerlo, sus hijos serían robustos y muy gordos\n¿Quién tiene tantos hijos?- solo el Sapo –\nSolo el Sapo ha tenido tantos hijos, por haber\nsacrificado\n\n             Òyè kúsé kùsè kúsé\n               A dífá fún Àràbà\n     Èyí ti ń lợ rèé bá wợn múlè légàn\n              Òún le tóbi báyèé?\n         Tóun ó borí àwợn igí tó kù\n           Wón ní kí Àràbà ó rúbợ\n                Àràbà bá rúbợ\n                O dé inú ẹgàn\n          Ló bá ga ju gbogbo igí lợ\n           Ní ợn bá ń pé igí kínnìí?\n              Wón ń pé Àràbà ní\n    Ifá pé eléyìun ó lòókợ rere láyé yìí\n             Òyè kúsé kùsè kúsé\n               A dífá fún Àràbà\n     Èyí ti ń lợ rèé bá wợn múlè légàn\n              Ệbợ ń wón ní ó şe\n        Àràbà ló bá wợn múlè légàn\n                    Ó yợrí\n            O ju gbogboo wợn lợ\n                        Òyè kúsé kùsè kúsé\n\nLanzó Ifá para el Baobab, cuando venía a escoger\nuna tierra en la floresta\n¿Seré grande y majestuoso?, él se preguntó\n¿De qué manera sobrepasaré al resto de los\nárboles?\nLe dijeron que ofrendase a Ifá Y rápidamente él lo\nhizo\nAl establecerse en la floresta, creció por encima de\nlos demás árboles, que preguntaron: - ¿Qué clase\nde árbol es ese? – El Baobab, dijo Ifá\nIfá dice que esta persona tendrá en su vida un\nnombre grandioso y honorable, además de\nperpetuar su linaje de manera respetada y querida\nÒyè kúsé kùsè kúsé\nLanzó Ifá para el Baobab, cuando venía a escoger\nuna tierra en la floresta\nEl Baobab, escogió tierra en la floresta y creció por\nencima de los demás árboles Fue el sacrificio a Ifá\nquien le engrandeció", "origen_id": "e3310f92be15598f7b36658b"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku-Isẹ explica la necesidad de la muerte como parte del\n                                                                orden natural\n      WO – El cliente se está resistiendo a aceptar el final de una relación\n                                                                   o negocio.\n\n\n45.1 · K´amateteku, el adivino de la casa de la alegría (alayo), Aiteteku-ise,\n\n            el adivino de la casa de la pena (ibanuje), Bi-iku-ba-de-ka-yin-\n         Oluwa-logo, el adivino de Igboya ewa – Alogbon-on maku-ninu,\n              Masimale ninmeyeniy, el adivino de Afinju-maku-mase´baje\n          Oyekeseniyi, adivinaron Ifá para los sabios (eniyan–sasa), quien\n       invitó a los babalawos para consultar los problemas sobre la muerte\n     (iku), preguntando: ¿por qué la muerte mata a las personas y nadie se\n       ha salvado de la muerte? Los babalawos dijeron Ifá nos enseña que\n       Amoniwaye creó la muerte como algo bueno para la humanidad. El\n       agua estancada se convierte en un estanque y este estanque de agua\n       putrefacta puede causar enfermedad. Agua que le gente deja correr\n              libremente agua que ellos nos traerán de vuelta. Permite a la\n    enfermedad retornar a la casa para ser curada y renovada en el cuerpo\n          y renovar el carácter debilitado. El loco es cuidado por su propia\n            familia. los babalawos dijeron ¿por qué vemos esto como algo\n        desagradable? Los sabios gritaron a Ifá diciendo, Orunmila: Iboru,\n        Iboye, Ibose. Ellos todos se dispersaron y más nunca recordaron la\n       muerte como un problema más – Orişa-nlá es llamado Amuniwaye.", "origen_id": "645697c4ebd2f77d386364e2"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Los sabios: la ofrenda pedida por Ifá, aceptada (Iború, Iboyè, Ibọṣẹ).", "El sapo y el baobab: ofrenda para descendencia y grandeza."]}, {"titulo": "Relaciones espirituales", "texto": "Òrìṣà-ńlá, llamado Amuniwayé, creó la muerte como parte del orden. Ọ̀rúnmìlà recibe el grito de los sabios."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Baobab (Àràbà), agua que corre."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 45.1 (yorùbá): K'amatètèkú awo ilé Alayo, / Aitètèkú-iṣé awo wọn nile Ibànújé, / Bi-ikú-ba-de-ka-yin-Olúwa-logo / awo Igboya ewà / Alogbón-on-makú-ninú, / Maṣimale ninmẹyẹniyi / awo Afinju-makú-maṣe'bajẹ, / Öyẹkẹṣeniyi: / a difá f'àwọn Èniyàn ṣaṣa / ti wọn gbara jọ npe Babaláwo / wa difá ikú wope: / Eetiri ti ikú fi npo'ni ti kos'ẹnitikiikú? / Àwọn Babaláwo ni Ifá wipe: / Ire li Amuniwayé nfi Ikú ṣe. / Omi ti ko ṣan siwájú / ti ko pada s'ẹhin a d'ogodo, / Ọgodo omi ibajẹ. / Ọgọdo omi àrùn. / Omi ngbe wọn lo rerẹ, / Ọmọ nko wọn bọ rẹrẹ, / Olokunrun kare'le lọ gba Awotitun, / Aṣebajẹ kare'lé lọ gbiwa-titun bowa'yé. / Alasínwin ni nwo asíinwin san. / Àwọn Babaláwo ni: / Ewo ni ko dùn? / Awọn èniyàn foribalẹ fún Ifá-nwipe: / Ọ̀rúnmìlà! Iború, Iboyè, Iboṣẹ. / Wọn tuka lọ, / wọn ko tun gba ikú si ràn edun mo. / Oriṣà-ńlá liape ni Amuniwayé.", "REZO: OYEKUN PAKIOSHE OBI OSHEMA EYELEO KAMA SHERUWO ILE KENDE OMA FIRO OSHUN OBINI MEYI TANILO.", "REZO: NI MORE OYE PAKIOSHE EFU AGUATUN MELLA AFITORI MABO OSHE ASHUN KAODERU UMBA OKULA ABANI OMO LLOMO ARUN IKU LAMODI LOMBOLO LLUMU.", "REZO: OYEKUN PAKIOSHE NI MARI ALLO PAKIOSHER APAGUO OTRUN MELLO APOTARI MOBO OSHE OSHUPA ONDENI UMBAICA ABAN AMALLA MU ERU IKU LONDI TOUMBA IKU BOOMO LLUMU.", "REZO: ONI BIBE KORO GUAGUO ELA LAKAN AYAFO AKUKO LEBO OYEKUN PAONE NIMORE SIYO PAKIOSHE OJO OWO LA MELLO OFOSI MABO OSHUKA ODARU OMBAIKU LA ABAN OMO YOMILI ERU IGULANDI TOMBLE YOMU.", "REZO: ADIFAFUN BABARE ADAFUN ORUNMILA ESHU OSHUN Y EGGUN.", "REZO: ADIFAFUN BABARE ODO FUN ORUNMILA ESHU, OSUN Y EGGUN."]}]$q$::jsonb),
(46,'e987df3c2049672b4716a2ab54bc5c73','c4b2c1ebcde58537f68d6c1d642d0216',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òfún advierte de una enfermedad repentina y da protección contra ella. La persona enfrenta un obstáculo inesperado en su vida diaria o en el negocio. Pide ofrecer ñames, cuidarse de las burlas de la gente y que los hijos no sean soberbios con sus padres."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Surgió un obstáculo inesperado en el día a día o en el negocio.", "Tiene síntomas repentinos o teme enfermar (relato de Abaralile-oṣiṣẹ-oṣabą).", "Se siente a merced de cosas que no controla y busca tranquilidad.", "Hay tensiones en la familia por burlas, presunción o falta de respeto de los hijos a los padres (relato de Baálé y sus hijos).", "Quiere saber si su esfuerzo de hoy le traerá bienestar, recursos o hijos (relato de Èèyàn e Ìpín)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Recuperarse de una enfermedad repentina tomando la medicina.", "Fuerza, resistencia y paz mental.", "Larga vida para el padre y para los hijos."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a los milagros. (Este Odu habla de la curación de una enfermedad inesperada.)", "origen_id": "4fef3c23e07a9e5fdc7eef08"}]}, {"titulo": "Ibi y advertencias", "puntos": ["Una enfermedad repentina que puede dejar lisiado; conviene atenderse con el médico.", "Hijos soberbios con sus padres.", "Burlas de la gente."], "pasajes": [{"titulo": "Orientación tradicional", "texto": "La terminación del ciclo lleva a la disfunción. (Este Odu habla de la sconsecuencias de evitar el proceso de sanar).", "origen_id": "7813037591b53dc6ebaa7901"}]}, {"titulo": "Enseñanza principal", "texto": "El destino tiene riquezas, pareja, hijos y todo lo bueno, pero se trabaja con la ofrenda. Y quien se niega a caminar junto al mal, el mal se le mete encima."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ọ̀yẹ̀kú'Fuu advierte de una inminente enfermedad y ofrece protección contra ella.", "origen_id": "362f0457adb7326a070222a8"}]}, {"titulo": "Relatos reunidos", "puntos": ["Abaralile, el que nunca se había enfermado. Los adivinos del bastón y de lo alto del estante consultaron para Abaralile, que nunca había estado enfermo, y le advirtieron que venía una enfermedad repentina que lo podía dejar lisiado. Le marcaron una babosa, un bagre, aceite de palma, 20,000 cauríes y medicina de Ifá. Ofreció. La enfermedad llegó de todos modos, pero tomó el remedio y se recuperó.", "El ser humano y los ñames. Pékótókótó, el adivino del vendedor de manteca de òrí, consultó para el ser humano, esclavo del destino en el cielo, y le pidió ofrecer ñames. Ofreció, y cada persona empezó a desarrollar músculos fuertes y una vida con más fuerza. Canto: 'Ven a ver el trabajo del destino: el destino tiene riqueza, tiene pareja, tiene hijos, tiene todo lo bueno'.", "El jefe de la casa y sus hijos. 'Ọ̀yẹ̀kú camina al lado de la muerte, Ọ̀yẹ̀kú camina al lado de la maldad; quien no le hace lugar al mal, el mal se le trepa encima.' Así consultaron para el jefe de la casa y para sus hijos, y les pidieron ofrecer para vivir mucho. Mientras el padre se traslada, los hijos pasean en sus caballos."], "pasajes": [{"titulo": "Verso 46.1", "texto": "Adurogangan el adivino del bastón (báculo),\nAyẹgiridanu el adivino de lo alto del estante:\nadivinaron Ifá para Abaralile-oṣiṣẹ-oṣabą,\nquien nunca había tenido enfermedad alguna.\nÉl fue advertido:\n\"La enfermedad está viniendo,\nuna enfermedad repentina está por ocurrir,\nes inminente un malestar\nque lo puede dejar lisiado\"\nEl preguntó: ¿Cuál es el sacrificio?\nLe dijeron: una babosa, un pescado (eja-aro), epo,\n20.000 cowries y medicina de Ifá.\nÉl oyó el aviso y sacrificó.\nLa enfermedad vino a toda costa (ocurrió),\nél tomó el antídoto, él se recuperó.\nlừ Odun\nÌwòrì", "comentario": "8* àrün öjiji: enfermedad repentina.", "origen_id": "9d353b33064edf1ff11214ba"}, {"titulo": "Versos complementarios 1", "texto": "La persona deberá sacrificar 16 tubérculos de\nÑame. El babaláwo deberá raspar la cáscara o\nsuperficie de los ñames durante el sacrificio.\nEl deberá cuidarse de las bufonadas de las\npersonas. Sus hijos no deberán comportarse de\nmanera pomposa con los padres.\n\n            Pékótókótó awo Olórìí\n               A dífá fún Èèyàn\n           Èèyàn tíí şẹrú Ìpín lórun\n             Wón ní kó fi işu rúbợ\n                  Ó bá rúbợ\n           Oníkálukú bá ń níşu lára\n               Ayée wón ń dára\n          Ifá pé ợkàn eléyìun ó balè\n\n          Pékótókótó awo Olórìí\n             A dífá fún Èèyàn\n         Èèyàn tíí şẹrú Ìpín lórun\n            Ệbợ ń wón ní ó şe\n            Èèyàn gbébợ ńbè\n                  Ó rúbợ\n                 Ìyànňyàn\n           Ệ wá woşé Ìpín ń şe\n                 Ìyànňyàn\n              Ìpín mó ń lájé\n                 Ìyànňyàn\n           Ệ wá woşé Ìpín ń şe\n                 Ìyànňyàn\n               Ìpín si ń láya\n           Ệ wá woşé Ìpín ń şe\n                 Ìyànňyàn\n              Ìpín si ń bímợ\n           Ệ wá woşé Ìpín ń şe\n                 Ìyànňyàn\n        Gbogbo ire pátá nÌpín ń ni o\n           Ệ wá woşé Ìpín ń şe\n                 Ìyànňyàn\n          Pékótókótó awo Olórìí\n\nLanzó Ifá para el Ser Humano, quien era esclavo del\ndestino en el Cielo Le dijeron de ofrecer ñames\ncomo ofrenda Y así lo realizó\nCada ser humano, comenzó a desarrollar músculos\nfuertes y su vida mejoró en resistencia y fuerza vital\nIfá dice que esta persona tendrá paz mental (Urèe\nIrợrùn)\nPékótókótó awo Olórìí\n\nLanzó Ifá para el Ser Humano, quien era esclavo del\ndestino en el Cielo Le dijeron de ofrecer ñames\ncomo ofrenda Y así lo realizó\n\n                 Ìyànňyàn\n    Ven y mira el trabajo o la labor del\n                  destino\n                 Ìyànňyàn\n         El destino tiene riquezas\n                 Ìyànňyàn\n         El destino tiene esposas\n                 Ìyànňyàn\n    Ven y mira el trabajo o la labor del\n                  destino\n                 Ìyànňyàn\n           El destino tiene hijos\n    Ven y mira el trabajo o la labor del\n                  destino\n                 Ìyànňyàn\n El destino tiene todas las cosas buenas\n                 de la vida\n    Ven y mira el trabajo o la labor del\n                  destino\n                 Ìyànňyàn\n\n              Òyèkú yà fókùú\n                 Yà fún Ìkà\n           Béèyàn ò bá yà fún Ìkà\n       Ìkà ó wulè tè é pa pátápátá ní\n              A dífá fún Baálé\n               A bú fún Ợmợ\n            Wón ní kí wón ó rúbợ\n                 Òkùràkùtà\n\n             Bàbá mò ń rín nílè\n               Ợmợ ń gẹşin!\n                Òkùràkùtà\n        Ệyin ò mò páyé doníran ìran\n\nÒyèkú, camina al lado de la Muerte\nÒyèkú, camina al lado de la Maldad\nSi se rehúsa andar con la Maldad, esta se trepará y\nse meterá en la persona hasta matarla\nLanzó Ifá para el cabeza de familia, y también para\nsus descendientes (hijos)\nA todos se les pidió sacrificar para vivir largo tiempo\nÒkùràkùtà\nEl Padre se traslada\nÒkùràkùtà\nMientras los niños pasean sobre sus caballos\nÒkùràkùtà\n¿No ves que el Mundo entero está lleno de\nespectáculos?\n\n              PALABRAS DIFÍCILES:\n\nÀjítòròo Şègí: şègí es un nombre especial para un\ntipo de cuenta de\n                 Mucho valor en su precio monetario\nWonkoko: Es una palabra rítmica, que se enclava\nen algo inseparable\nAwónńwón: Tipo de planta que crece en la floresta,\ny es trepadora\nLèşelèşe là ń fẹ: “El logro o triunfo es lo que\nnosotros deseamos”\nÒyè wónrin mi: “Òyè tragó algunas pelotillas de\nhierro al salir”\nÀjé: Las Brujas\nAkápò: Cualquiera de los adivinos de Òrúnmìlà\n\nŞigidi: Figura o talla de madera, con rostro y físico\nhumanoide\nÀkànmànà: “Tocando con la habilidad de golpear\nen directo”\nGbợnrangandan: Palabra rítmica del sonido\nproducido cuando un\n                    Metal se deja caer al suelo\nAbímợ ni pupa: Referente al mestizo Hijo mulato\n(Color carmelita)\nDùndún: Tambor sagrado en tierras de Nigeria\nPákúdidi: Un tipo de nuez con dos cotiledones\nseparados\nÌyálóde Òpò: Titulo de la líder del grupo de\nmujeres en la ciudad Òpò\nÈèsún: Hierbas que crecen en lugares pantanosos\nOlórìí: El vendedor de manteca de cacao o de\ncarnero\nÒkùràkùtà: Podría decirse que es un nombre o una\nllamada a las\n              Personas para que sirvan de testigo en\nun espectáculo Vergonzoso", "origen_id": "0814d3c46dee95f8f3c629ce"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku´Fuu advierte de inminente enfermedad y ofrece\n\nprotección contra ella.\n              WO – El cliente muestra un inesperado obstaculo cada día en su\n                                                         ambiente de negocios.\n\n\n46.1 · Adurogangan, el adivino del perchero (opa), Ayegiridanu, el\n           adivino del estante (ori pepe). Ambos adivinaron Ifá para Abaralile-\n              osise-osabo, quien nunca había tenido enfermedad alguna. Él fue\n               advertido de que venía una enfermedad inminente un repentino\n                   malestar que lo podía dejar lisiado. Él preguntó: ¿Cuál es el\n              sacrificio?, le fue dicho: 1 babosa, 1 pescado, manteca de corojo,\n                 20.000 cowrie, la medicina de Ifá. Él oyó el aviso y sacrificó.\n                    La enfermedad ocurrió, pero no fue severa. Él se recuperó.", "origen_id": "7deffd09cce01cbbce4e8ec9"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Abaralile: una babosa, un bagre, aceite de palma, 20,000 cauríes y medicina de Ifá.", "El ser humano: dieciséis ñames; el babaláwo raspa la cáscara durante la ofrenda.", "El jefe de la casa y sus hijos: ofrenda por larga vida."], "pasajes": [{"titulo": "Ofrenda en el verso 46.1", "texto": "Adurogangan el adivino del bastón (báculo),\nAyẹgiridanu el adivino de lo alto del estante:\nadivinaron Ifá para Abaralile-oṣiṣẹ-oṣabą,\nquien nunca había tenido enfermedad alguna.\nÉl fue advertido:\n\"La enfermedad está viniendo,\nuna enfermedad repentina está por ocurrir,\nes inminente un malestar\nque lo puede dejar lisiado\"\nEl preguntó: ¿Cuál es el sacrificio?\nLe dijeron: una babosa, un pescado (eja-aro), epo,\n20.000 cowries y medicina de Ifá.\nÉl oyó el aviso y sacrificó.\nLa enfermedad vino a toda costa (ocurrió),\nél tomó el antídoto, él se recuperó.\nlừ Odun\nÌwòrì", "origen_id": "7002c2aada2f1f5c9bdd0a0f"}]}, {"titulo": "Relaciones espirituales", "texto": "El destino (Ìpín) se trabaja desde el cielo con la ofrenda. Ifá da la medicina contra la enfermedad repentina."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame, babosa, bagre (ẹja aro), aceite de palma, manteca de òrí."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 46.1 (yorùbá): Adurogangan awo Ọpa, / Ayẹgiridanu awo orí pẹpẹ: / wọ̀n difá f'Abaralile-oṣiṣẹ-oṣabą, / eni àrùn kan koṣe ri, / Wọ̀n nì: / Àrùn kan nbọwa, àrùn öjiji, / àrùn naa yoo yeẹ ni'kun / Ó ni: kini ebọ? / A ni: igbin, eja-aro, epo, / ẹgbàáwa owó pelu ewé Ifá. / Ó gbọ̀ ó rú. / Àrùn naa de dandan, / ó mu qwó-ẹrọ, ó si sàn.", "REZO: OYEKUN BERDURA MAFUN ABA BARABA MAFUN ABA OFUN MAYEKUN FUN YANZAN LELE BERELE FOGUEREMALELE OYEKUN FUN MAFUN YEKU BERERE ORI OSHUN MERIYEYE MOLALA LALA YERI YALORDE MORIYEYEE LELE OSHUN BEBERE OKANA YELEGUE YELELE OYEKUN FUN YEYEBI OYA OMA YIRE AWO BADAWA. AWO OBA ERI IFA KAFEREFUN LERI IFA KAFEREFUN ELEGBARA.", "REZO: OYEKUN FUN IGUI AWO ILE ADO IRO AWO IKAURO AKOSHAMABA A OFE IBUNI ILE OYO SHANGO IBAURO ADIFAFUN OLOFIN UMBINA UNLO ARA OMODE LOMBO ADA ADIE IBUN EFUN EBEYI ORO AWO LOMBO EKU, EYA, EPO, EKO, OWO LAMEFA, OTUN, OSI.", "REZO: OYEKUN FUN OYEKUN BODURA IFA KUERIANO ODAFUN ORUNLA OLOKUN.", "REZO: BEBE AWO AFIBOYA LOGUE NITOSHE TOSHISHE BALERI YAGUN YAGUNANDIFAYESE KANFUN SHISHI LORAN OMO TINTUN MAFEREFUN OGGUN MAFEREFUN ARRIKUE OWA SHURIKUI UN SHOLA KOKO ARAYO ALA KAAKOLA AGUERE ALARA UNFUN BEROYANO ANDIFA FOYO LABEBE AFUN MUAA OLADE YOMOFUN MENI EYELE ADIFAFUN OSUN RONLORO INTORI OFO.", "REZO: KUKU ADIFAFUN AYO OKU TINSHOMA OLORDUMARE AKUKO LEBO IFA DE AROGIO.", "REZO: MAFUN AWO BABAGUA MAFUN AWO OFUN YANZA LELE BERELE FAGUERE MALELE OYEKUN FUN MAFUN YEKU BERERE ERI OSHUN MORI YEYEO MALEBE LALAYENI YALODE MORI YEYEO ABEJENA LELE OSHUN BIBERE OKANA YELEGUE YELELE OYEKUN FUN ESHU LARUFA OBA YEBE IKU, IKU OLORIN, AWO DAGUA NI OSHUN YEYEBI OYA OMAYIRE AWO MALAGUA AWO OBA ERI IFA KAFEREFUN LERI IFA KAFEREFUN ELEGBA.", "REZO: ESHU OWEREWI UNSHOLE KOKAROYO ALAGA OROKONLA AWERE ALOUN OFUN RERE YARU ADIFAYOKO OYETOURERE OFIN.", "SUYERE: OFUN MINI ALDEYANO (2 VECES)", "ADIFAFUN OSUN OLORUN (2 VECES)", "REZO: OYEKUN FUN IGUI AWO ILE ADO IRO AWO IKAURO AKOSHA MABA A OFE IBUNI ILE OYO SHANGO IBAURO ADIFAFUN OLOFIN UMBINA UNLO ARA OMODE LOMBO ADA ADIE IBUN EFUN EBEYI ORO AWO LOMBO EKU, EYA, EPO, EKO, OWO LAMEFA, OTUN, OSI.", "REZO: MAFUN AWO BABAGUA MAFUN AWO OFUN YANZA LELE BERELE FAGUERE MALELE OYEKUN FUN MAFUN YEKU BERERE ERI OSHUN MORI YEYEO MALEBE LALAYENI YALODE MORI YEYEO ABEJENA LELE OSHUN BIBERE OKANA YELEGUE YELELE OYEKUN FUN ESHU LARUFA OBA YEBE IKU, IKU OLORIN, AWO DAGUA NI OSHUN YEYEBI OYA OMAYIRE AWO MALAGUA AWO OBA ERI IFA KAFERE FUN LERI IFA KAFEREFUN ELEGBA.", "+++"], "pasajes": [{"titulo": "Suyere 8", "texto_ritual": "OFUN MINI ALDEYANO (2 VECES)\n\nADIFAFUN OSUN   OLORUN (2 VECES)", "origen_id": "515df6034c1d1595a5d1aa18"}]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from v where e.numero=v.numero and md5(e.secciones::text)=v.viejo and md5(v.sec::text)=v.nuevo returning e.numero;
